CREATE TABLE `knowledge_chunks` (
	`id` text PRIMARY KEY NOT NULL,
	`locale` text NOT NULL,
	`source_title` text NOT NULL,
	`title_path` text NOT NULL,
	`content` text NOT NULL,
	`search_text` text NOT NULL,
	`url` text NOT NULL,
	`evidence_level` text NOT NULL,
	`public` integer DEFAULT true NOT NULL,
	`index_version` text NOT NULL,
	`hash` text NOT NULL
);
--> statement-breakpoint
CREATE INDEX `knowledge_chunks_locale_idx` ON `knowledge_chunks` (`locale`);--> statement-breakpoint
CREATE TABLE `rag_usage` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`day` text NOT NULL,
	`created_at` text NOT NULL,
	`client_hash` text NOT NULL,
	`provider` text NOT NULL,
	`model` text NOT NULL,
	`mode` text NOT NULL,
	`status` text NOT NULL,
	`prompt_chars` integer DEFAULT 0 NOT NULL,
	`completion_chars` integer DEFAULT 0 NOT NULL
);
