	`source_title`,
	content=`knowledge_chunks`,
	content_rowid=`rowid`,
	tokenize='unicode61 remove_diacritics 2'
);--> statement-breakpoint
CREATE TRIGGER `knowledge_chunks_fts_ai` AFTER INSERT ON `knowledge_chunks` BEGIN
	INSERT INTO `knowledge_chunks_fts` (`rowid`, `search_text`, `title_path`, `source_title`)
	VALUES (new.`rowid`, new.`search_text`, new.`title_path`, new.`source_title`);
END;--> statement-breakpoint
CREATE TRIGGER `knowledge_chunks_fts_ad` AFTER DELETE ON `knowledge_chunks` BEGIN
	INSERT INTO `knowledge_chunks_fts` (`knowledge_chunks_fts`, `rowid`, `search_text`, `title_path`, `source_title`)
	VALUES ('delete', old.`rowid`, old.`search_text`, old.`title_path`, old.`source_title`);
END;--> statement-breakpoint
CREATE TRIGGER `knowledge_chunks_fts_au` AFTER UPDATE ON `knowledge_chunks` BEGIN
	INSERT INTO `knowledge_chunks_fts` (`knowledge_chunks_fts`, `rowid`, `search_text`, `title_path`, `source_title`)
	VALUES ('delete', old.`rowid`, old.`search_text`, old.`title_path`, old.`source_title`);
	INSERT INTO `knowledge_chunks_fts` (`rowid`, `search_text`, `title_path`, `source_title`)
