INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-profile', 'zh', '公开个人资料', '个人简介', '方子，英文名 Zi Fang，上海交通大学机械与动力工程学院机器人研究所机械工程直博生，预计 2026 年 12 月毕业。他目前正在求职、找工作，寻找算法/研究岗位，重点关注三维感知与具身智能，并希望将这些能力用于医疗机器人等真实物理系统。公开机构邮箱为 fangzi508@sjtu.edu.cn。', 'zi fang 2026 12 fangzi508 sjtu.edu.cn 个 人 简 介 个人 人简 简介 公 开 资 料 公开 开个 人资 资料 方 子 方子 英 文 名 英文 文名 上 海 交 通 大 学 机 械 动 力 工 程 院 器 研 究 所 直 博 生 上海 海交 交通 通大 大学 学机 机械 械与 与动 动力 力工 工程 程学 学院 院机 机器 器人 人研 研究 究所 所机 械工 程直 直博 博生 预 计 预计 年 月 毕 业 月毕 毕业 他 目 前 正 求 职 他目 目前 前正 正在 在求 求职 找 作 找工 工作 寻 算 法 寻找 找算 算法 岗 位 究岗 岗位 重 点 关 注 三 维 感 知 具 身 智 能 重点 点关 关注 注三 三维 维感 感知 知与 与具 具身 身智 智能 并 希 望 将 这 些 用 于 医 疗 等 真 实 物 理 系 统 并希 希望 望将 将这 这些 些能 能力 力用 用于 于医 医疗 疗机 人等 等真 真实 实物 物理 理系 系统 构 邮 箱 开机 机构 构邮 邮箱 箱为', '/#about', 'public-profile', 1, '2026-08-04', 'aeea0f1454a5b91467ff3ce9fde556f7522625b16698f8842a452d80bb950021') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-job-search', 'zh', '公开求职信息', '求职方向 / 工作意向', '方子目前正在求职、找工作，寻找算法或研究类岗位。他的求职方向和工作兴趣重点是三维感知与具身智能，也希望把这些能力用于医疗机器人等真实物理系统。预计毕业时间为 2026 年 12 月，可通过公开机构邮箱 fangzi508@sjtu.edu.cn 联系。', '2026 12 fangzi508 sjtu.edu.cn 求 职 方 向 求职 职方 方向 工 作 意 工作 作意 意向 公 开 信 息 公开 开求 职信 信息 子 目 前 正 方子 子目 目前 前正 正在 在求 找 找工 寻 算 法 或 研 究 类 岗 位 寻找 找算 算法 法或 或研 研究 究类 类岗 岗位 他 兴 趣 重 点 三 维 感 知 具 身 智 能 他的 的求 向和 和工 作兴 兴趣 趣重 重点 点是 是三 三维 维感 感知 知与 与具 具身 身智 智能 也 希 望 把 这 些 力 用 于 医 疗 机 器 人 等 真 实 物 理 系 统 也希 希望 望把 把这 这些 些能 能力 力用 用于 于医 医疗 疗机 机器 器人 人等 等真 真实 实物 物理 理系 系统 预 计 毕 业 时 间 预计 计毕 毕业 业时 时间 间为 年 月 可 通 过 构 邮 箱 可通 通过 过公 开机 机构 构邮 邮箱 联 联系', '/#about', 'public-profile', 1, '2026-08-04', 'b2a336c3435a1bf6d675b94ece633d8f90941a80afc9dc2748a055b13b3973e2') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-education', 'zh', '公开教育经历', '教育经历', '方子于 2017 年至 2021 年在上海交通大学机械与动力工程学院学习机械工程，参加试点班并获院优秀毕业生；2021 年起在上海交通大学机械与动力工程学院机器人所攻读机械工程博士学位。博士课题为甲状腺超声隐式三维重建与穿刺手术导航系统研究。', '2017 2021 教 育 经 历 教育 育经 经历 公 开 公开 开教 方 子 于 方子 子于 年 至 年至 上 海 交 通 大 学 机 械 动 力 工 程 院 习 年在 在上 上海 海交 交通 通大 大学 学机 机械 械与 与动 动力 力工 工程 程学 学院 院学 学习 习机 械工 参 加 试 点 班 并 获 优 秀 毕 业 生 参加 加试 试点 点班 班并 并获 获院 院优 优秀 秀毕 毕业 业生 起 器 人 所 攻 读 博 士 位 年起 起在 院机 机器 器人 人所 所攻 攻读 读机 程博 博士 士学 学位 课 题 甲 状 腺 超 声 隐 式 三 维 重 建 穿 刺 手 术 导 航 系 统 研 究 士课 课题 题为 为甲 甲状 状腺 腺超 超声 声隐 隐式 式三 三维 维重 重建 建与 与穿 穿刺 刺手 手术 术导 导航 航系 系统 统研 研究', '/#about', 'public-profile', 1, '2026-08-04', 'cb36ffa2a2550c678a5bc2e08680e548341455c9b64fa9dfe697f07b0b89f785') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-research-thread', 'zh', '博士研究主线', '研究主线', '博士研究沿可信观测、连续表征、空间统一、语义建模、物理坐标五步展开：先识别有效超声观测并规范输入域，再以神经场建立连续三维表征，随后联合优化多扫查位姿与形变，在规范空间中构建组织和针体语义，最后把图像、位姿、三维场和器械工作点连接到导航原理样机。', '研 究 主 线 研究 究主 主线 博 士 博士 士研 沿 可 信 观 测 究沿 沿可 可信 信观 观测 连 续 表 征 连续 续表 表征 空 间 统 一 空间 间统 统一 语 义 建 模 语义 义建 建模 物 理 坐 标 五 步 展 开 物理 理坐 坐标 标五 五步 步展 展开 先 识 别 有 效 超 声 并 规 范 输 入 域 先识 识别 别有 有效 效超 超声 声观 测并 并规 规范 范输 输入 入域 再 以 神 经 场 立 三 维 再以 以神 神经 经场 场建 建立 立连 续三 三维 维表 随 后 联 合 优 化 多 扫 查 位 姿 形 变 随后 后联 联合 合优 优化 化多 多扫 扫查 查位 位姿 姿与 与形 形变 构 组 织 针 体 在规 范空 间中 中构 构建 建组 组织 织和 和针 针体 体语 最 把 图 像 最后 后把 把图 图像 器 械 工 作 点 接 到 导 航 原 样 机 维场 场和 和器 器械 械工 工作 作点 点连 连接 接到 到导 导航 航原 原理 理样 样机', '/#research', 'thesis-synthesis', 1, '2026-08-04', '64ae7d78054e8fa0f414885e1c06cb3de9ab5a773e31820fcf3db99a378c024c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-evidence-boundary', 'zh', '博士论文证据边界', '结论适用范围', '当前结果支持方法、模块和假体原理样机层面的结论。针体几何只有单病例假体证据；成像平面条件场的二维优势不能外推为方向无关三维优势；分项标定残差不能外推为端到端穿刺精度；临床安全性不在现有实测范围内。', '结 论 适 用 范 围 结论 论适 适用 用范 范围 博 士 文 证 据 边 界 博士 士论 论文 文证 证据 据边 边界 当 前 果 支 持 方 法 当前 前结 结果 果支 支持 持方 方法 模 块 假 体 原 理 样 机 层 面 模块 块和 和假 假体 体原 原理 理样 样机 机层 层面 面的 的结 针 几 何 只 有 单 病 例 针体 体几 几何 何只 只有 有单 单病 病例 例假 体证 成 像 平 条 件 场 二 维 优 势 不 能 外 推 向 无 关 三 成像 像平 平面 面条 条件 件场 场的 的二 二维 维优 优势 势不 不能 能外 外推 推为 为方 方向 向无 无关 关三 三维 分 项 标 定 残 差 端 到 穿 刺 精 度 分项 项标 标定 定残 残差 差不 为端 端到 到端 端穿 穿刺 刺精 精度 临 床 安 全 性 现 实 测 内 临床 床安 安全 全性 性不 不在 在现 现有 有实 实测 测范 围内', '/#research', 'thesis-boundary', 1, '2026-08-04', 'c5f23b20cb9baaee965695b8f252d83c82d4869fc5817aeacfef43ea453e31c1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-neural-field', 'zh', '物理一致三维超声神经场', '代表项目', '物理一致三维超声神经场把列级有效接触筛选、连续神经场、瑞利背散射和方向参数化反射结合起来，在重建三维强度场的同时保留可解释的声学形成机制。该工作属于博士论文的方法研究，不在网站上表述为 Google Scholar 已收录论文。', 'google scholar 代 表 项 目 代表 表项 项目 物 理 一 致 三 维 超 声 神 经 场 物理 理一 一致 致三 三维 维超 超声 声神 神经 经场 把 列 级 有 效 接 触 筛 选 场把 把列 列级 级有 有效 效接 接触 触筛 筛选 连 续 连续 续神 瑞 利 背 散 射 方 向 参 数 化 反 结 合 起 来 瑞利 利背 背散 散射 射和 和方 方向 向参 参数 数化 化反 反射 射结 结合 合起 起来 重 建 强 度 同 时 保 留 可 解 释 学 形 成 机 制 在重 重建 建三 维强 强度 度场 场的 的同 同时 时保 保留 留可 可解 解释 释的 的声 声学 学形 形成 成机 机制 该 工 作 属 于 博 士 论 文 法 研 究 该工 工作 作属 属于 于博 博士 士论 论文 文的 的方 方法 法研 研究 不 网 站 上 述 不在 在网 网站 站上 上表 表述 述为 已 收 录 已收 收录 录论', '/#selected-work', 'doctoral-research', 1, '2026-08-04', '8e3edf2a2fd5e4073347cafd009f1f8ab3e1383469e4027b45bb88143d18c581') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-gla', 'zh', 'GLA-NeRF', '代表项目 / 多扫查配准', 'GLA-NeRF 面向多扫查自由手三维超声，把对齐偏差分为扫查级全局刚性偏差与帧级局部误差，通过外观检索、几何内点、不确定性加权和连续轨迹约束联合优化位姿与神经场，使多次扫查映射到规范空间。论文发表于 Physics in Medicine & Biology，年份为 2026。', 'gla-nerf physics in medicine biology 2026 代 表 项 目 代表 表项 项目 多 扫 查 配 准 多扫 扫查 查配 配准 面 向 自 由 手 三 维 超 声 面向 向多 查自 自由 由手 手三 三维 维超 超声 把 对 齐 偏 差 分 级 全 局 刚 性 帧 部 误 把对 对齐 齐偏 偏差 差分 分为 为扫 查级 级全 全局 局刚 刚性 性偏 差与 与帧 帧级 级局 局部 部误 误差 通 过 外 观 检 索 通过 过外 外观 观检 检索 几 何 内 点 几何 何内 内点 不 确 定 加 权 连 续 轨 迹 约 束 联 合 优 化 位 姿 神 经 场 不确 确定 定性 性加 加权 权和 和连 连续 续轨 轨迹 迹约 约束 束联 联合 合优 优化 化位 位姿 姿与 与神 神经 经场 使 次 映 射 到 规 范 空 间 使多 多次 次扫 查映 映射 射到 到规 规范 范空 空间 论 文 发 于 论文 文发 发表 表于 年 份 年份 份为', '/#selected-work', 'published-paper', 1, '2026-08-04', '879604863dab51563e27c3d30ec24700c4d21a11e60d773edd877c82be9ea351') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-semantics', 'zh', '组织语义与针体几何', '代表项目 / 语义建模', '组织语义与针体几何方法链包括输入域规范化、低标注多任务二维分割、连续多视角条件语义场和针体几何恢复。目标对象包括甲状腺、血管、结节和穿刺针，输出用于三维解剖表达、路径规划和导航定位。', '代 表 项 目 代表 表项 项目 语 义 建 模 语义 义建 建模 组 织 针 体 几 何 组织 织语 义与 与针 针体 体几 几何 方 法 链 包 括 输 入 域 规 范 化 何方 方法 法链 链包 包括 括输 输入 入域 域规 规范 范化 低 标 注 多 任 务 二 维 分 割 低标 标注 注多 多任 任务 务二 二维 维分 分割 连 续 视 角 条 件 场 恢 复 连续 续多 多视 视角 角条 条件 件语 义场 场和 和针 何恢 恢复 对 象 甲 状 腺 目标 标对 对象 象包 括甲 甲状 状腺 血 管 血管 结 节 穿 刺 结节 节和 和穿 穿刺 刺针 出 用 于 三 解 剖 达 输出 出用 用于 于三 三维 维解 解剖 剖表 表达 路 径 划 导 航 定 位 路径 径规 规划 划和 和导 导航 航定 定位', '/#selected-work', 'doctoral-research', 1, '2026-08-04', 'f44dee395299290105f5aa68ceceaa21f7998feaa2c8282f384fa29d9422befe') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-prototype', 'zh', '甲状腺超声穿刺导航原理样机', '代表项目 / 原理样机', '导航原理样机集成自由手超声采集、双目近红外外部定位、N 线探头标定、针尖枢轴标定、可重复甲状腺假体和四个软件工作台，建立图像、位姿、三维场、组织语义与器械工作点之间的物理坐标链。该系统的证据是原理样机和假体层级。', '代 表 项 目 代表 表项 项目 原 理 样 机 原理 理样 样机 甲 状 腺 超 声 穿 刺 导 航 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航原 集 成 自 由 手 采 机集 集成 成自 自由 由手 手超 声采 采集 双 近 红 外 部 定 位 双目 目近 近红 红外 外外 外部 部定 定位 线 探 头 标 线探 探头 头标 标定 针 尖 枢 轴 针尖 尖枢 枢轴 轴标 可 重 复 假 体 四 个 软 件 工 作 台 可重 重复 复甲 腺假 假体 体和 和四 四个 个软 软件 件工 工作 作台 建 立 图 像 建立 立图 图像 姿 位姿 三 维 场 三维 维场 组 织 语 义 器 械 点 之 间 物 坐 链 组织 织语 语义 义与 与器 器械 械工 作点 点之 之间 间的 的物 物理 理坐 坐标 标链 该 系 统 证 据 层 级 该系 系统 统的 的证 证据 据是 是原 机和 和假 体层 层级', '/#selected-work', 'prototype-evidence', 1, '2026-08-04', 'f10b2615a1fea17b636ec644c00153bd3c6814fe155356166bdb1ef0e347d8e9') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-publications', 'zh', 'Google Scholar 公开论文记录', '论文成果', '截至 2026 年 8 月 4 日，Zi Fang 的 Google Scholar 主页公开 11 篇论文，涵盖多扫查三维超声、可穿戴穿刺机器人、穿刺路径规划、冠脉介入与分割、多执行器容错控制、紧固件寿命预测和工业机器人故障诊断。其中已公开的一作论文是 GLA-NeRF（2026）、基于 IMU 与降维的螺栓松动寿命预测（2023）和基于降维与随机森林的工业机器人故障诊断（2021）。论文数量、题目、发表载体与年份以 Google Scholar 为唯一权威来源。', 'google scholar 2026 zi fang 11 gla-nerf imu 2023 2021 论 文 成 果 论文 文成 成果 公 开 记 录 公开 开论 文记 记录 截 至 截至 年 月 日 主 页 主页 页公 篇 篇论 涵 盖 多 扫 查 三 维 超 声 涵盖 盖多 多扫 扫查 查三 三维 维超 超声 可 穿 戴 刺 机 器 人 可穿 穿戴 戴穿 穿刺 刺机 机器 器人 路 径 规 划 刺路 路径 径规 规划 冠 脉 介 入 分 割 冠脉 脉介 介入 入与 与分 分割 执 行 容 错 控 制 多执 执行 行器 器容 容错 错控 控制 紧 固 件 寿 命 预 测 工 业 故 障 诊 断 紧固 固件 件寿 寿命 命预 预测 测和 和工 工业 业机 人故 故障 障诊 诊断 其 已 一 作 其中 中已 已公 开的 的一 一作 作论 文是 基 于 基于 降 螺 栓 松 动 与降 降维 维的 的螺 螺栓 栓松 松动 动寿 随 森 林 和基 于降 维与 与随 随机 机森 森林 林的 的工 数 量 文数 数量 题 目 题目 发 表 载 体 份 以 发表 表载 载体 体与 与年 年份 份以 唯 权 威 来 源 为唯 唯一 一权 权威 威来 来源', 'https://scholar.google.com.hk/citations?user=bEc7mGgAAAAJ&hl=zh-CN', 'google-scholar', 1, '2026-08-04', '329395d0fceca0dd713c1bcd2d06c0b2a0fcb8e4c5721642a6a3ff38b602fd43') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-profile-en', 'en', 'Public profile', 'Biography', 'Zi Fang is a direct-entry Ph.D. candidate in Mechanical Engineering at the Robotics Institute, School of Mechanical Engineering, Shanghai Jiao Tong University, expecting to graduate in December 2026. He is actively seeking research and algorithm roles in 3D perception and embodied intelligence, with medical robotics as a key application area. His public institutional email is fangzi508@sjtu.edu.cn.', 'biography public profile zi fang is direct-entry ph.d. candidate in mechanical engineering at the robotics institute school of shanghai jiao tong university expecting to graduate december 2026. he actively seeking research and algorithm roles 3d perception embodied intelligence with medical as key application area. his institutional email fangzi508 sjtu.edu.cn.', '/en/#about', 'public-profile', 1, '2026-08-04', '67194966a84df3efbce3361514b1ed0a61fe4d55db49d76e9b94a1f29dae5731') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-job-search-en', 'en', 'Public job-search information', 'Job search / career interests', 'Zi Fang is actively seeking research or algorithm roles. His main job-search and career interests are 3D perception and embodied intelligence, with medical robotics and other real-world physical systems as important application areas. He expects to graduate in December 2026 and can be contacted through his public institutional email, fangzi508@sjtu.edu.cn.', 'job search career interests public job-search information zi fang is actively seeking research or algorithm roles. his main and are 3d perception embodied intelligence with medical robotics other real-world physical systems as important application areas. he expects to graduate in december 2026 can be contacted through institutional email fangzi508 sjtu.edu.cn.', '/en/#about', 'public-profile', 1, '2026-08-04', 'd0577345f8b032494545546ba1242d7d3ccb9b7478f127c37e59772f1ac272c4') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-education-en', 'en', 'Public education record', 'Education', 'Zi Fang studied Mechanical Engineering at Shanghai Jiao Tong University from 2017 to 2021, joined the pilot honors program, and was named an outstanding graduate of the school. He began his Mechanical Engineering Ph.D. at the university''s Robotics Institute in 2021. His dissertation studies implicit 3D thyroid-ultrasound reconstruction and puncture-navigation systems.', 'education public record zi fang studied mechanical engineering at shanghai jiao tong university from 2017 to 2021 joined the pilot honors program and was named an outstanding graduate of school. he began his ph.d. robotics institute in 2021. dissertation studies implicit 3d thyroid-ultrasound reconstruction puncture-navigation systems.', '/en/#about', 'public-profile', 1, '2026-08-04', '6b0aa6d9be945cc6df2f317e81dfc370666685d6eeb1be9b76f550f52262bb98') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-research-thread-en', 'en', 'Doctoral research thread', 'Research thread', 'The doctoral research follows five stages: trustworthy observation, continuous representation, spatial unification, semantic modeling, and physical coordinates. It screens and normalizes ultrasound observations, builds continuous 3D neural-field representations, jointly optimizes multi-sweep poses and deformation, models tissue and needle semantics in canonical space, and connects images, poses, 3D fields, and instrument workpoints in a navigation prototype.', 'research thread doctoral the follows five stages trustworthy observation continuous representation spatial unification semantic modeling and physical coordinates. it screens normalizes ultrasound observations builds 3d neural-field representations jointly optimizes multi-sweep poses deformation models tissue needle semantics in canonical space connects images fields instrument workpoints navigation prototype.', '/en/#research', 'thesis-synthesis', 1, '2026-08-04', 'ebf7d531528036894931c125cdaf5a534c5dd9fe297e8559e006ce08fe9cd755') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-evidence-boundary-en', 'en', 'Dissertation evidence boundary', 'Scope of conclusions', 'Current evidence supports conclusions at method, module, and phantom proof-of-principle prototype levels. Needle geometry has single-case phantom evidence; 2D advantages of the imaging-plane conditional field cannot be generalized to a direction-independent 3D advantage; component calibration residuals are not end-to-end puncture accuracy; clinical safety has not been experimentally established.', 'scope of conclusions dissertation evidence boundary current supports at method module and phantom proof-of-principle prototype levels. needle geometry has single-case 2d advantages the imaging-plane conditional field cannot be generalized to direction-independent 3d advantage component calibration residuals are not end-to-end puncture accuracy clinical safety been experimentally established.', '/en/#research', 'thesis-boundary', 1, '2026-08-04', '3538d35b94b04d839464ec60a2e13049f46575864283be76ad0d3d310e926e1f') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-neural-field-en', 'en', 'Physics-consistent 3D ultrasound neural field', 'Representative project', 'The physics-consistent 3D ultrasound neural field combines column-level valid-contact screening, a continuous neural field, Rayleigh backscatter, and direction-parameterized reflection. It reconstructs a 3D intensity field while retaining interpretable acoustic image-formation mechanisms. This is doctoral method research and is not presented as a Google Scholar-indexed paper on the site.', 'representative project physics-consistent 3d ultrasound neural field the combines column-level valid-contact screening continuous rayleigh backscatter and direction-parameterized reflection. it reconstructs intensity while retaining interpretable acoustic image-formation mechanisms. this is doctoral method research not presented as google scholar-indexed paper on site.', '/en/#selected-work', 'doctoral-research', 1, '2026-08-04', '22d2114da41a37980a034a75bf87bf5361b3b871c4bf166f77903cd96efef43b') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-gla-en', 'en', 'GLA-NeRF', 'Representative project / Multi-sweep alignment', 'GLA-NeRF addresses multi-sweep freehand 3D ultrasound by separating alignment error into sweep-level global rigid bias and frame-level local error. Appearance retrieval, geometric inliers, uncertainty weighting, and continuous-trajectory constraints jointly optimize poses and the neural field in canonical space. The paper appeared in Physics in Medicine & Biology in 2026.', 'representative project multi-sweep alignment gla-nerf addresses freehand 3d ultrasound by separating error into sweep-level global rigid bias and frame-level local error. appearance retrieval geometric inliers uncertainty weighting continuous-trajectory constraints jointly optimize poses the neural field in canonical space. paper appeared physics medicine biology 2026.', '/en/#selected-work', 'published-paper', 1, '2026-08-04', 'a4a45e4defc368bf6b7e8333a95dd14d0574a84c1aa18940d5a6b76e7d4e3306') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-semantics-en', 'en', 'Tissue semantics and needle geometry', 'Representative project / Semantic modeling', 'The tissue-semantics and needle-geometry pipeline combines input-domain normalization, low-label multi-task 2D segmentation, a continuous multi-view conditional semantic field, and needle-geometry recovery. It models the thyroid, vessels, nodules, and puncture needle for 3D anatomy, path planning, and navigation localization.', 'representative project semantic modeling tissue semantics and needle geometry the tissue-semantics needle-geometry pipeline combines input-domain normalization low-label multi-task 2d segmentation continuous multi-view conditional field recovery. it models thyroid vessels nodules puncture for 3d anatomy path planning navigation localization.', '/en/#selected-work', 'doctoral-research', 1, '2026-08-04', '19b5620a8580511174a0f8491dca6069aea7288f48e97c6d467004ae9e2247ff') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-project-prototype-en', 'en', 'Thyroid-ultrasound puncture-navigation prototype', 'Representative project / Proof-of-principle prototype', 'The navigation prototype integrates freehand ultrasound, binocular near-infrared tracking, N-wire probe calibration, needle-tip pivot calibration, a repeatable thyroid phantom, and four software workbenches. It establishes a physical coordinate chain across images, poses, 3D fields, tissue semantics, and instrument workpoints. Its evidence remains at proof-of-principle and phantom level.', 'representative project proof-of-principle prototype thyroid-ultrasound puncture-navigation the navigation integrates freehand ultrasound binocular near-infrared tracking n-wire probe calibration needle-tip pivot repeatable thyroid phantom and four software workbenches. it establishes physical coordinate chain across images poses 3d fields tissue semantics instrument workpoints. its evidence remains at level.', '/en/#selected-work', 'prototype-evidence', 1, '2026-08-04', 'c836a6e0fd8cad95c017dbc1560a683a16c1de4d76a7421848be2072c59116bc') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('fact-publications-list', 'en', 'Google Scholar public record', 'Publications', 'As of 4 August 2026, Zi Fang''s Google Scholar profile lists 11 publications spanning multi-sweep 3D ultrasound, wearable puncture robots, puncture path planning, coronary intervention and segmentation, fault-tolerant control, bolted-joint life prediction, and industrial-robot fault diagnosis. His public first-author papers are GLA-NeRF (2026), Prediction for Loosening Life of Bolted Joints Using IMUs With Dimensionality Reduction (2023), and Fault Diagnosis Method for Industrial Robots based on Dimension Reduction and Random Forest (2021). Google Scholar is the authoritative source for titles, venues, years, and publication status.', 'publications google scholar public record as of august 2026 zi fang profile lists 11 spanning multi-sweep 3d ultrasound wearable puncture robots path planning coronary intervention and segmentation fault-tolerant control bolted-joint life prediction industrial-robot fault diagnosis. his first-author papers are gla-nerf for loosening bolted joints using imus with dimensionality reduction 2023 diagnosis method industrial based on dimension random forest 2021 is the authoritative source titles venues years publication status.', 'https://scholar.google.com.hk/citations?user=bEc7mGgAAAAJ&hl=zh-CN', 'google-scholar', 1, '2026-08-04', '5a97cad289a03e8ffd0b271da0400622ce9a8b9579038eca17e62a149302afa3') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-98f89a59f52c3f7a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 课题背景与意义', '甲状腺结节是临床常见的颈部疾病。随着超声检查普及和健康筛查频率提高，越来越多无明显症状的甲状腺结节在早期被发现。对于需要进一步判断性质或接受消融治疗的病例，超声引导下穿刺、活检和热消融已经成为重要的诊疗手段。二维超声具有实时、无辐射、成本较低和床旁可用等优势，但它本质上只提供当前探头切面内的信息。医生需要依靠经验在连续扫查过程中建立三维空间印象，并在这一空间印象中判断结节、甲状腺、颈部血管、气管以及穿刺针之间的相对关系。对于操作者经验不足、病灶位置复杂或穿刺路径受限的情况，单纯依靠二维切面进行空间判断仍存在困难。[1–3]
甲状腺穿刺导航的核心需求，是把超声图像中的组织结构、外部空间定位系统中的探头和器械位姿，以及穿刺针尖端位置统一到同一三维空间中。只有完成这一统一，系统才能在术前或术中给出可解释的空间结构、稳定的目标位置和可追溯的误差来源。然而，自由手超声并不天然具备这样的三维表达能力。探头扫查轨迹不规则，图像帧之间的重叠有限，组织受压会产生形变，超声图像又受到散斑、阴影、声束方向和设备后处理影响。若仅将二维图像按位姿粗略堆叠，容易出现结构断裂、边界模糊和空间错位；若只进行单帧图像分割或针体检测，则难以保证多视角结果在三维空间中的一致性。[4–6]', '第 章 绪 论 绪论 课 题 背 景 意 义 课题 题背 背景 景与 与意 意义 甲 状 腺 结 节 临 床 常 见 颈 部 疾 病 甲状 状腺 腺结 结节 节是 是临 临床 床常 常见 见的 的颈 颈部 部疾 疾病 随 着 超 声 检 查 普 健 康 筛 频 率 提 高 随着 着超 超声 声检 检查 查普 普及 及和 和健 健康 康筛 筛查 查频 频率 率提 提高 越 来 多 无 明 显 症 早 期 被 发 现 越来 来越 越多 多无 无明 明显 显症 症状 状的 的甲 节在 在早 早期 期被 被发 发现 对 于 需 要 进 一 步 判 断 性 质 或 接 受 消 融 治 疗 例 对于 于需 需要 要进 进一 一步 步判 判断 断性 性质 质或 或接 接受 受消 消融 融治 治疗 疗的 的病 病例 引 导 下 穿 刺 声引 引导 导下 下穿 穿刺 活 热 已 经 成 重 诊 手 段 活检 检和 和热 热消 融已 已经 经成 成为 为重 重要 要的 的诊 诊疗 疗手 手段 二 维 具 有 实 时 二维 维超 声具 具有 有实 实时 辐 射 无辐 辐射 本 较 低 旁 可 用 等 优 势 成本 本较 较低 低和 和床 床旁 旁可 可用 用等 等优 优势 但 它 上 只 供 当 前 探 头 切 面 内 信 息 但它 它本 本质 质上 上只 只提 提供 供当 当前 前探 探头 头切 切面 面内 内的 的信 信息 医 生 依 靠 验 连 续 扫 过 程 建 立 三 空 间 印 象 医生 生需 要依 依靠 靠经 经验 验在 在连 连续 续扫 扫查 查过 过程 程中 中建 建立 立三 三维 维空 空间 间印 印象 并 这 并在 在这 这一 一空 象中 中判 断结 血 管 部血 血管 气 以 针 之 相 关 系 气管 管以 以及 及穿 刺针 针之 之间 间的 的相 相对 对关 关系 操 作 者 不 足 于操 操作 作者 者经 验不 不足 灶 位 置 复 杂 路 径 限 情 况 病灶 灶位 位置 置复 复杂 杂或 或穿 刺路 路径 径受 受限 限的 的情 情况 单 纯 行 仍 存 困 难 单纯 纯依 靠二 维切 面进 进行 行空 间判 断仍 仍存 存在 在困 困难 航 核 心 求 腺穿 刺导 导航 航的 的核 核心 心需 需求 把 图 像 组 织 构 是把 把超 声图 图像 像中 中的 的组 组织 织结 结构 外 定 统 器 械 姿 外部 部空 间定 定位 位系 系统 统中 的探 头和 和器 器械 械位 位姿 尖 端 到 同 针尖 尖端 端位 置统 统一 一到 到同 同一 一三 间中 完 只有 有完 完成 成这 一统 才 能 术 给 出 解 释 统才 才能 能在 在术 术前 前或 或术 术中 中给 给出 出可 可解 解释 释的 的空 间结 稳 目 标 追 溯 误 差 源 稳定 定的 的目 目标 标位 置和 和可 可追 追溯 溯的 的误 误差 差来 来源 然 而 然而 自 由 天 备 样 表 达 力 自由 由手 手超 声并 并不 不天 天然 然具 具备 备这 这样 样的 的三 维表 表达 达能 能力 轨 迹 规 则 头扫 查轨 轨迹 迹不 不规 规则 帧 叠 像帧 帧之 的重 重叠 叠有 有限 压 会 产 形 变 织受 受压 压会 会产 产生 生形 形变 又 散 斑 像又 又受 受到 到散 散斑 阴 影 阴影 束 方 向 设 后 处 理 响 声束 束方 方向 向和 和设 设备 备后 后处 处理 理影 影响 若 仅 将 按 粗 略 堆 若仅 仅将 将二 维图 像按 按位 姿粗 粗略 略堆 堆叠 容 易 裂 容易 易出 出现 现结 构断 断裂 边 界 模 糊 错 边界 界模 模糊 糊和 和空 间错 错位 分 割 体 测 若只 只进 行单 单帧 帧图 像分 分割 割或 或针 针体 体检 检测 保 证 视 角 果 致 则难 难以 以保 保证 证多 多视 视角 角结 结果 果在 在三 的一 一致 致性', '/#research', 'doctoral-thesis', 1, '2026-08-04', '98f89a59f52c3f7af3a864b4d9532fddf8b9e52fdc51770fa7737c17046c0e55') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-53956f8b19a9fc62', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 课题背景与意义', '之间的重叠有限，组织受压会产生形变，超声图像又受到散斑、阴影、声束方向和设备后处理影响。若仅将二维图像按位姿粗略堆叠，容易出现结构断裂、边界模糊和空间错位；若只进行单帧图像分割或针体检测，则难以保证多视角结果在三维空间中的一致性。[4–6]
超声三维重建、连续神经场表征、超声扫查序列配准、医学图像分割和手术导航已分别形成较成熟的方法，但面向甲状腺穿刺仍缺少贯通这些环节的统一方案。光学场景中的神经辐射场难以直接表述超声背散射统计和方向相关反射；外部定位系统的位姿还包含扫查间整体偏移与帧级局部抖动。导航任务还要求在重建组织形态的同时识别甲状腺、结节、风险结构和穿刺针，并通过标定、同步与平台实验检验这些信息在统一空间链路中的可靠性。[7–10]
基于上述背景，本文围绕“甲状腺超声神经场三维重建与穿刺规划系统”展开研究，重点讨论自由手超声的数据采集、物理一致表征、超声扫查序列空间统一、三维语义理解以及实验平台几何标定。理论层面研究超声物理先验与连续神经场表征的结合，使三维建模不再依赖离散切片堆叠；方法层面将位姿修正、有效观测筛选、三维语义场和针体几何恢复纳入规范空间；实验平台层面建立空间定位、器械标定和甲状腺假体，为各坐标变换提供可追溯的误差统计。', '10 第 章 绪 论 绪论 课 题 背 景 意 义 课题 题背 背景 景与 与意 意义 之 间 重 叠 有 限 之间 间的 的重 重叠 叠有 有限 组 织 受 压 会 产 生 形 变 组织 织受 受压 压会 会产 产生 生形 形变 超 声 图 像 又 到 散 斑 超声 声图 图像 像又 又受 受到 到散 散斑 阴 影 阴影 束 方 向 设 备 后 处 理 响 声束 束方 方向 向和 和设 设备 备后 后处 处理 理影 影响 若 仅 将 二 维 按 位 姿 粗 略 堆 若仅 仅将 将二 二维 维图 像按 按位 位姿 姿粗 粗略 略堆 堆叠 容 易 出 现 结 构 断 裂 容易 易出 出现 现结 结构 构断 断裂 边 界 模 糊 空 错 边界 界模 模糊 糊和 和空 空间 间错 错位 只 进 行 单 帧 分 割 或 针 体 检 测 若只 只进 进行 行单 单帧 帧图 像分 分割 割或 或针 针体 体检 检测 则 难 以 保 证 多 视 角 果 三 一 致 性 则难 难以 以保 保证 证多 多视 视角 角结 结果 果在 在三 三维 维空 间中 中的 的一 一致 致性 建 声三 维重 重建 连 续 神 经 场 表 征 连续 续神 神经 经场 场表 表征 扫 查 序 列 配 准 声扫 扫查 查序 序列 列配 配准 医 学 手 术 导 航 已 别 成 较 熟 法 医学 学图 割和 和手 手术 术导 导航 航已 已分 分别 别形 形成 成较 较成 成熟 熟的 的方 方法 但 面 甲 状 腺 穿 刺 仍 缺 少 贯 通 这 些 环 节 统 案 但面 面向 向甲 甲状 状腺 腺穿 穿刺 刺仍 仍缺 缺少 少贯 贯通 通这 这些 些环 环节 节的 的统 统一 一方 方案 光 辐 射 直 接 述 计 相 关 反 光学 学场 场景 景中 的神 经辐 辐射 射场 场难 以直 直接 接表 表述 述超 声背 背散 散射 射统 统计 计和 和方 向相 相关 关反 反射 外 部 定 系 还 包 含 整 偏 移 级 局 抖 动 外部 部定 定位 位系 系统 统的 的位 姿还 还包 包含 含扫 查间 间整 整体 体偏 偏移 移与 与帧 帧级 级局 局部 部抖 抖动 任 务 要 求 态 同 时 识 航任 任务 务还 还要 要求 求在 在重 建组 织形 形态 态的 的同 同时 时识 识别 别甲 结节 风 险 风险 险结 构和 和穿 刺针 并 过 标 并通 通过 过标 标定 步 平 台 实 验 信 息 链 路 可 靠 同步 步与 与平 平台 台实 实验 验检 检验 验这 些信 信息 息在 在统 一空 间链 链路 路中 的可 可靠 靠性 基 于 上 基于 于上 上述 述背 本 文 围 绕 本文 文围 围绕 规 划 腺超 声神 场三 建与 与穿 刺规 规划 划系 展 开 研 究 展开 开研 研究 点 讨 自 由 数 据 采 集 重点 点讨 讨论 论自 自由 由手 手超 声的 的数 数据 据采 采集 物 物理 理一 致表 列空 间统 语 解 几 何 维语 语义 义理 理解 解以 以及 及实 验平 台几 几何 何标 层 先 合 理论 论层 层面 面研 究超 声物 理先 先验 验与 与连 征的 的结 结合 使 不 再 依 赖 离 切 片 使三 维建 建模 模不 不再 再依 依赖 赖离 离散 散切 切片 片堆 修 正 法层 面将 将位 姿修 修正 效 观 筛 选 有效 效观 观测 测筛 筛选 恢 复 纳 入 范 义场 场和 和针 体几 何恢 恢复 复纳 纳入 入规 规范 范空 立 台层 面建 建立 立空 间定 器 械 假 器械 械标 定和 和甲 腺假 假体 各 坐 换 提 供 追 溯 误 差 为各 各坐 坐标 标变 变换 换提 提供 供可 可追 追溯 溯的 的误 误差 差统', '/#research', 'doctoral-thesis', 1, '2026-08-04', '53956f8b19a9fc62244f126bf8f7ad25b52383c3b9c69e58f2b47f45258030e5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded