INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6b9ab56c86ce86e4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 课题来源', '本课题来源于国家自然科学基金面上项目"基于力觉感知的血管介入模块化机器人机电耦联建模与控制方法研究"(61973210)、上海交通大学医工交叉项目"远程甲状腺结节智能扫查及良恶性辅助诊断机器人关键技术研发"(YG2019ZDA17)、上海交通大学医工交叉项目"甲状腺结节智能扫查及良恶性辅助诊断机器人的研制"(ZH2018QNB23)。', '61973210 yg2019zda17 zh2018qnb23 第 章 绪 论 绪论 课 题 来 源 课题 题来 来源 本 于 国 家 自 然 科 学 基 金 面 上 项 目 本课 源于 于国 国家 家自 自然 然科 科学 学基 基金 金面 面上 上项 项目 力 觉 感 知 血 管 介 入 模 块 化 机 器 人 电 耦 联 建 控 制 方 法 研 究 基于 于力 力觉 觉感 感知 知的 的血 血管 管介 介入 入模 模块 块化 化机 机器 器人 人机 机电 电耦 耦联 联建 建模 模与 与控 控制 制方 方法 法研 研究 海 交 通 大 医 工 叉 上海 海交 交通 通大 大学 学医 医工 工交 交叉 叉项 远 程 甲 状 腺 结 节 智 能 扫 查 良 恶 性 辅 助 诊 断 关 键 技 术 发 远程 程甲 甲状 状腺 腺结 结节 节智 智能 能扫 扫查 查及 及良 良恶 恶性 性辅 辅助 助诊 诊断 断机 人关 关键 键技 技术 术研 研发 人的 的研 研制', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6b9ab56c86ce86e42e659b2bbff36b2c096a7f8f4305ac8522a1cc7fef913b1d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4b4bcb7389bf34f4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状', '甲状腺超声穿刺导航面对的是一条由二维图像、空间位姿、三维表征、组织语义和器械几何共同构成的空间证据链。二维 B-mode 图像提供局部组织观测，外部定位与标定链路给出探头和器械的空间关系，三维重建承接跨视角组织结构，语义模型进一步描述甲状腺、结节、风险结构和穿刺针之间的任务关系。因此，国内外研究现状不宜只按单个算法类别平铺，而应围绕二维观测如何进入三维导航空间这一主线展开。
本节围绕三条技术主线和一条实验平台支撑线梳理相关研究。第一条主线是超声三维重建与物理连续神经场表征，关注带位姿二维切片如何形成连续三维场景；第二条主线是空间标定约束下的超声扫查序列配准与规范空间，关注初始几何链路、残余位姿误差和超声扫查序列空间一致性；第三条主线是面向导航的超声语义理解与三维语义神经场，关注组织、病灶、风险结构和穿刺针的空间表达。实验平台支撑线则讨论可重复假体、外部定位和关键坐标标定。
其中，有效观测筛选和输入域稳定性是主线中的支撑环节。有效观测筛选决定进入三维重建训练的二维射线是否包含可信组织回波，输入域稳定性影响二维语义概率观测在不同设备、增益和后处理条件下的一致性。外部定位、探头标定与针尖标定进一步建立图像、探头、器械和世界坐标系之间的转换关系，用于界定几何误差来源。', 'b-mode 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 甲 腺 超 声 穿 刺 导 航 面 对 一 条 由 二 维 图 像 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航面 面对 对的 的是 是一 一条 条由 由二 二维 维图 图像 空 间 位 姿 空间 间位 位姿 三 表 征 三维 维表 表征 组 织 语 义 器 械 几 何 共 同 构 成 证 据 链 组织 织语 语义 义和 和器 器械 械几 几何 何共 共同 同构 构成 成的 的空 间证 证据 据链 提 供 局 部 观 测 像提 提供 供局 局部 部组 织观 观测 定 标 路 给 出 探 头 关 系 外部 部定 定位 位与 与标 标定 定链 链路 路给 给出 出探 探头 头和 械的 间关 关系 重 建 承 接 跨 视 角 结 维重 重建 建承 承接 接跨 跨视 视角 角组 织结 结构 模 型 进 步 描 述 义模 模型 型进 进一 一步 步描 描述 述甲 节 结节 风 险 针 之 任 务 风险 险结 构和 和穿 刺针 针之 之间 间的 的任 任务 务关 因 此 因此 不 宜 只 按 单 个 算 法 类 别 平 铺 状不 不宜 宜只 只按 按单 单个 个算 算法 法类 类别 别平 平铺 而 应 围 绕 如 入 这 主 线 展 开 而应 应围 围绕 绕二 维观 测如 如何 何进 进入 入三 维导 航空 间这 这一 一主 主线 线展 展开 本 技 术 实 验 台 支 撑 梳 理 相 本节 节围 绕三 三条 条技 技术 术主 线和 和一 条实 实验 验平 平台 台支 支撑 撑线 线梳 梳理 理相 相关 关研 物 连 续 神 经 场 第一 条主 线是 是超 声三 建与 与物 物理 理连 连续 续神 神经 经场 场表 注 带 切 片 形 景 关注 注带 带位 姿二 维切 切片 片如 何形 形成 成连 续三 维场 场景 约 束 下 扫 查 序 列 配 准 规 范 第二 二条 是空 间标 定约 约束 束下 下的 的超 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 初 始 注初 初始 始几 何链 残 余 误 差 致 性 残余 余位 姿误 误差 差和 和超 列空 间一 一致 致性 向 解 第三 是面 面向 向导 航的 声语 义理 理解 解与 与三 维语 义神 注组 病 灶 病灶 达 针的 间表 表达 则 讨 可 复 假 体 线则 则讨 讨论 论可 可重 重复 复假 假体 键 坐 位和 和关 关键 键坐 坐标 标标 其 其中 有 效 筛 选 输 域 稳 环 有效 效观 测筛 筛选 选和 和输 输入 入域 域稳 稳定 定性 性是 是主 线中 中的 的支 撑环 环节 决 训 练 射 否 包 含 信 回 波 选决 决定 定进 建训 训练 练的 的二 维射 射线 是否 否包 包含 含可 可信 信组 织回 回波 影 响 概 率 设 备 性影 影响 响二 义概 概率 率观 测在 在不 不同 同设 设备 增 益 后 处 件 增益 益和 和后 后处 处理 理条 条件 件下 的一 尖 立 头标 定与 与针 针尖 尖标 步建 建立 立图 世 界 转 换 械和 和世 世界 界坐 标系 系之 的转 转换 换关 用 于 来 源 用于 于界 界定 定几 何误 差来 来源', '/#research', 'doctoral-thesis', 1, '2026-08-04', '4b4bcb7389bf34f4a50be4a0f6bd16fad53ccc340cfd18fd18dbbec5c0399665') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_versio