INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-fb36b5b5b38aa9ff', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状', '有效观测筛选决定进入三维重建训练的二维射线是否包含可信组织回波，输入域稳定性影响二维语义概率观测在不同设备、增益和后处理条件下的一致性。外部定位、探头标定与针尖标定进一步建立图像、探头、器械和世界坐标系之间的转换关系，用于界定几何误差来源。
1.3　 节依据技术演进归纳本文所面对的条件缺口：自由手超声需要由离散切片转向物理一致的连续三维表示，多组超声扫查序列需要在初始标定基础上修正残余位姿误差，穿刺规划需要将二维语义观测转化为可查询的三维空间表示，实验平台还需要明确图像、探头、器械与外部定位坐标系之间的误差链路。本文第2—5章分别围绕这些问题展开。', '1.3 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 有 效 观 测 筛 选 决 定 进 入 三 维 重 建 训 练 二 射 线 否 包 含 可 信 组 织 回 波 有效 效观 观测 测筛 筛选 选决 决定 定进 进入 入三 三维 维重 重建 建训 训练 练的 的二 二维 维射 射线 线是 是否 否包 包含 含可 可信 信组 组织 织回 回波 输 域 稳 性 影 响 语 义 概 率 不 同 设 备 输入 入域 域稳 稳定 定性 性影 影响 响二 维语 语义 义概 概率 率观 测在 在不 不同 同设 设备 增 益 后 处 理 条 件 下 一 致 增益 益和 和后 后处 处理 理条 条件 件下 下的 的一 一致 致性 部 位 外部 部定 定位 探 头 标 针 尖 步 立 图 像 探头 头标 标定 定与 与针 针尖 尖标 进一 一步 步建 建立 立图 图像 器 械 世 界 坐 系 之 间 转 换 关 器械 械和 和世 世界 界坐 坐标 标系 系之 之间 间的 的转 转换 换关 关系 用 于 几 何 误 差 来 源 用于 于界 界定 定几 几何 何误 误差 差来 来源 节 依 据 技 术 演 归 纳 本 文 所 面 对 缺 口 节依 依据 据技 技术 术演 演进 进归 归纳 纳本 本文 文所 所面 面对 对的 的条 件缺 缺口 自 由 手 超 声 需 要 离 散 切 片 向 物 连 续 表 示 自由 由手 手超 超声 声需 需要 要由 由离 离散 散切 切片 片转 转向 向物 物理 理一 致的 的连 连续 续三 维表 表示 多 扫 查 序 列 初 始 基 础 上 修 正 残 余 姿 多组 组超 声扫 扫查 查序 序列 列需 要在 在初 初始 始标 定基 基础 础上 上修 修正 正残 残余 余位 位姿 姿误 穿 刺 规 划 将 化 询 空 穿刺 刺规 规划 划需 要将 将二 义观 测转 转化 化为 为可 可查 查询 询的 的三 维空 空间 间表 实 验 平 台 还 明 确 实验 验平 平台 台还 还需 要明 明确 确图 链 路 械与 与外 位坐 的误 差链 链路 文第 分 别 围 绕 这 些 问 题 展 开 章分 分别 别围 围绕 绕这 这些 些问 问题 题展 展开', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'fb36b5b5b38aa9ff6ed0e7eb3fce16a2ab124c1cd506399406c1fab51daa6c50') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e52b0bddd4c93b80', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 自由手超声采集与体素网格重建研究现状', '自由手超声采用常规二维探头连续扫查，并将每帧图像与对应空间位姿组织为三维数据。Mercier 等和 Hsu 等的综述指出[4,5]，超声三维重建至少需要解决两个基础问题：其一是如何获得二维切片在物理空间中的位置，其二是如何由不规则切片恢复连续体数据。Solberg 等进一步从重建角度将方法归纳为像素近邻、体素填充、函数插值和模型化重建等路线[6,11,12]；Huang 和 Zeng 则从实时三维超声成像技术角度总结了矩阵探头、机械扫描、自由手跟踪和高速体绘制等路线，说明三维超声的发展同时受到采集硬件、位姿获取、体数据重建和实时显示能力约束[13]。这些综述表明，超声三维重建的结果同时受采集几何、空间标定和重建表征约束，不能等同于二维图像的简单堆叠。
从采集方式看，自由手超声采集主要沿 tracked freehand、trackerless reconstruction 以及机器人或传感器辅助扫描等方向发展。Tracked 方法依赖光学、电磁、机械臂或惯性传感器提供切片位姿[14]，尺度明确、误差来源可追踪，适合需要物理坐标和器械关系的导航任务；trackerless 方法利用散斑去相关、图像配准或深度网络估计探头运动[15–20]，可以降低硬件依赖，但长序列漂移、跨扫查协议泛化和绝对尺度恢复仍然困难；机器人或传感器辅助扫描能够约束轨迹，但仍会受到探头压力、组织形变和系统误差影响。', 'mercier hsu solberg 11 12 huang zeng 13 tracked freehand trackerless reconstruction 14 15 20 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 自 由 手 采 集 体 素 网 格 自由 由手 手超 声采 采集 集与 与体 体素 素网 网格 格重 建研 用 常 规 二 探 头 扫 查 采用 用常 常规 规二 二维 维探 探头 头连 续扫 扫查 并 将 每 帧 图 像 对 应 空 间 位 姿 组 织 数 据 并将 将每 每帧 帧图 图像 像与 与对 对应 应空 空间 间位 位姿 姿组 组织 织为 为三 维数 数据 等 等和 综 述 指 出 等的 的综 综述 述指 指出 至 少 需 要 解 决 两 个 基 础 问 题 建至 至少 少需 需要 要解 解决 决两 两个 个基 基础 础问 问题 其 一 如 何 获 得 切 片 置 其一 一是 是如 如何 何获 获得 得二 维切 切片 片在 在物 理空 间中 中的 的位 位置 不 则 恢 复 其二 二是 何由 由不 不规 规则 则切 片恢 恢复 复连 续体 体数 进 步 从 角 度 方 法 归 纳 近 邻 等进 进一 一步 步从 从重 建角 角度 度将 将方 方法 法归 归纳 纳为 为像 像素 素近 近邻 填 充 素填 填充 函 插 值 模 型 化 路 线 函数 数插 插值 值和 和模 模型 型化 化重 建等 等路 路线 实 时 成 技 术 总 结 矩 阵 则从 从实 实时 时三 维超 声成 成像 像技 技术 术角 度总 总结 结了 了矩 矩阵 阵探 机 械 描 机械 械扫 扫描 跟 踪 高 速 绘 制 手跟 跟踪 踪和 和高 高速 速体 体绘 绘制 制等 说 明 发 展 同 受 到 硬 件 说明 明三 声的 的发 发展 展同 同时 时受 受到 到采 集硬 硬件 取 姿获 获取 显 示 能 力 据重 建和 和实 时显 显示 示能 能力 力约 这 些 表 这些 些综 述表 表明 果 几 建的 的结 结果 果同 受采 集几 几何 标 定 征 间标 标定 定和 和重 建表 表征 征约 于 简 单 堆 叠 不能 能等 等同 同于 于二 维图 像的 的简 简单 单堆 堆叠 式 看 从采 集方 方式 式看 主 沿 集主 主要 要沿 以 器 人 或 传 感 辅 助 向 以及 及机 机器 器人 人或 或传 传感 感器 器辅 辅助 助扫 描等 等方 方向 向发 依 赖 光 学 法依 依赖 赖光 光学 电 磁 电磁 臂 惯 性 提 供 械臂 臂或 或惯 惯性 性传 器提 提供 供切 片位 尺 确 尺度 度明 明确 误 差 来 源 可 追 误差 差来 来源 源可 可追 追踪 适 合 坐 关 系 导 航 任 务 适合 合需 要物 理坐 坐标 标和 和器 器械 械关 关系 系的 的导 导航 航任 任务 利 散 斑 去 相 法利 利用 用散 散斑 斑去 去相 相关 配 准 深 络 估 计 运 动 像配 配准 准或 或深 深度 度网 网络 络估 估计 计探 头运 运动 降 低 可以 以降 降低 低硬 件依 但 长 序 列 漂 移 但长 长序 序列 列漂 漂移 跨 协 议 泛 绝 仍 然 困 难 跨扫 查协 协议 议泛 泛化 化和 和绝 绝对 对尺 度恢 复仍 仍然 然困 困难 够 轨 迹 描能 能够 够约 束轨 轨迹 会 压 但仍 仍会 会受 到探 头压 压力 形 变 统 影 响 织形 形变 变和 和系 系统 统误 差影 影响', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e52b0bddd4c93b800903a8acefffd38805e9f9b78259cc427c2a546692d1092d') ON CONFLICT(`id`) DO