INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0b1434d6461133e8', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 自由手超声采集与体素网格重建研究现状', 'trackerless 方法利用散斑去相关、图像配准或深度网络估计探头运动[15–20]，可以降低硬件依赖，但长序列漂移、跨扫查协议泛化和绝对尺度恢复仍然困难；机器人或传感器辅助扫描能够约束轨迹，但仍会受到探头压力、组织形变和系统误差影响。
Trackerless 路线的重要贡献在于把部分自由手重建问题转化为序列运动估计和空间切片排序问题。相关 trackerless freehand ultrasound 综述指出，该方向已经从早期散斑去相关和传统配准，发展到基于 CNN、循环网络、Transformer、IMU 融合和连续神经场表征的多种路线，但绝对尺度、长序列漂移、跨器官泛化和缺少统一评测仍是主要瓶颈[15]。TUS-REC2024 挑战进一步把无外部跟踪超声三维重建放到公开基准中比较，说明该问题已经从单一算法验证走向数据集、协议和评价指标共同约束的阶段[21]。Prevost 等、Guo 等和 RecON 等工作通过学习相邻帧或序列的相对运动，表明在一定条件下，仅凭二维超声图像可以恢复局部空间关系[16,17,22]；ImplicitVol 以及 Yeung 等的二维到三维空间映射研究进一步说明，深度模型可以在少量标注或无需外部跟踪条件下弥合二维采集与三维空间之间的映射缺口[18,23]。不过，对于穿刺导航而言，系统仍需要可追溯的物理坐标、器械位姿和误差链路，因此可标定自由手采集仍是更适合导航任务的几何基础。', 'trackerless 15 20 freehand ultrasound cnn transformer imu tus-rec2024 21 prevost guo recon 16 17 22 implicitvol yeung 18 23 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 自 由 手 采 集 体 素 网 格 自由 由手 手超 声采 采集 集与 与体 体素 素网 网格 格重 建研 方 法 利 用 散 斑 去 相 关 方法 法利 利用 用散 散斑 斑去 去相 相关 图 像 配 准 或 深 度 络 估 计 探 头 运 动 图像 像配 配准 准或 或深 深度 度网 网络 络估 估计 计探 探头 头运 运动 可 以 降 低 硬 件 依 赖 可以 以降 降低 低硬 硬件 件依 依赖 但 长 序 列 漂 移 但长 长序 序列 列漂 漂移 跨 扫 查 协 议 泛 化 绝 对 尺 恢 复 仍 然 困 难 跨扫 扫查 查协 协议 议泛 泛化 化和 和绝 绝对 对尺 尺度 度恢 恢复 复仍 仍然 然困 困难 机 器 人 传 感 辅 助 描 能 够 轨 迹 机器 器人 人或 或传 传感 感器 器辅 辅助 助扫 扫描 描能 能够 够约 束轨 轨迹 会 受 到 压 力 但仍 仍会 会受 受到 到探 头压 压力 组 织 形 变 系 统 误 差 影 响 组织 织形 形变 变和 和系 系统 统误 误差 差影 影响 路 线 要 贡 献 于 把 部 分 问 题 转 空 间 切 片 排 路线 线的 的重 重要 要贡 贡献 献在 在于 于把 把部 部分 分自 手重 建问 问题 题转 转化 化为 为序 列运 动估 计和 和空 空间 间切 切片 片排 排序 序问 综 述 指 出 综述 述指 指出 该 向 已 从 早 期 该方 方向 向已 已经 经从 从早 早期 期散 关和 和传 传统 统配 发 展 基 发展 展到 到基 基于 循 环 循环 环网 融 合 表 征 多 种 融合 合和 和连 场表 表征 征的 的多 多种 种路 但绝 官 缺 少 一 评 测 主 瓶 颈 跨器 器官 官泛 和缺 缺少 少统 统一 一评 评测 测仍 仍是 是主 主要 要瓶 瓶颈 挑 战 进 步 无 跟 踪 放 公 开 比 较 挑战 战进 进一 一步 步把 把无 无外 外部 部跟 跟踪 踪超 建放 放到 到公 公开 开基 基准 准中 中比 比较 说 明 单 算 验 证 走 数 据 说明 明该 该问 题已 从单 单一 一算 算法 法验 验证 证走 走向 向数 数据 据集 价 标 共 同 阶 段 议和 和评 评价 价指 指标 标共 共同 同约 束的 的阶 阶段 等 等和 工 作 通 过 学 习 邻 帧 等工 工作 作通 通过 过学 学习 习相 相邻 邻帧 帧或 或序 列的 的相 相对 对运 定 条 下 表明 明在 在一 一定 定条 条件 件下 仅 凭 二 局 仅凭 凭二 二维 维超 声图 像可 以恢 复局 局部 部空 间关 关系 以及 映 射 等的 的二 维到 到三 维空 间映 映射 射研 究进 步说 模 型 量 注 需 弥 之 口 度模 模型 型可 以在 在少 少量 量标 标注 注或 或无 无需 需外 踪条 下弥 弥合 合二 维采 与三 间之 之间 间的 的映 射缺 缺口 不 不过 穿 刺 导 航 而 言 对