INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-105143a1943cea7d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 自由手超声采集与体素网格重建研究现状', '空间映射研究进一步说明，深度模型可以在少量标注或无需外部跟踪条件下弥合二维采集与三维空间之间的映射缺口[18,23]。不过，对于穿刺导航而言，系统仍需要可追溯的物理坐标、器械位姿和误差链路，因此可标定自由手采集仍是更适合导航任务的几何基础。
图 1.1展示了自由手超声系统中的基本坐标链。B-scan 图像平面中的像素点首先位于图像坐标系 P，再通过安装在探头上的接收器坐标系 R、外部定位发射器坐标系 T，最终转换到三维体坐标系 C[4,5]。自由手超声由此形成“图像切片 + 空间位姿”的基本数据形式；无论采用离散体素重建还是连续神经场建模，都必须首先回答这些二维切片如何进入统一三维空间的问题。
图 .1 自由手超声系统中图像平面到体坐标系的坐标链[4,5]
Figure . Freehand 3D ultrasound coordinate chain. [4,5]
在重建表示方面，传统体素网格方法通常将带位姿二维切片映射到离散体素网格，再通过最近邻、距离加权、归一化卷积、核函数插值、局部拟合、贝叶斯非局部重建或四面体插值完成体数据填充[24–30]。Wang 等提出的自适应四面体插值是其中具有代表性的改进[31]，如图 1.2所示，该方法依据非均匀切片分布构造四面体单元并在单元内部插值，以缓解自由手采样不规则导致的局部空洞。体素网格方法几何含义直观、实现成熟，结果也容易进入常规体数据可视化流程。', '18 23 1.1 b-scan figure freehand 3d ultrasound coordinate chain. 24 30 wang 31 1.2 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 自 由 手 采 集 体 素 网 格 自由 由手 手超 声采 采集 集与 与体 体素 素网 网格 格重 建研 空 间 映 射 进 一 步 说 明 空间 间映 映射 射研 究进 进一 一步 步说 说明 深 度 模 型 可 以 少 量 标 注 或 无 需 部 跟 踪 条 件 下 弥 合 二 之 缺 口 深度 度模 模型 型可 可以 以在 在少 少量 量标 标注 注或 或无 无需 需外 外部 部跟 跟踪 踪条 条件 件下 下弥 弥合 合二 二维 维采 与三 维空 间之 之间 间的 的映 射缺 缺口 不 过 不过 对 于 穿 刺 导 航 而 言 对于 于穿 穿刺 刺导 导航 航而 而言 系 统 仍 要 追 溯 坐 系统 统仍 仍需 需要 要可 可追 追溯 溯的 的物 理坐 坐标 器 械 位 姿 误 差 链 路 器械 械位 位姿 姿和 和误 误差 差链 链路 因 此 定 更 适 任 务 几 何 基 础 因此 此可 可标 标定 定自 手采 集仍 仍是 是更 更适 适合 合导 航任 任务 务的 的几 几何 何基 基础 图 展 示 本 展示 示了 了自 声系 统中 中的 的基 基本 本坐 标链 像 平 面 点 首 先 图像 像平 平面 面中 的像 像素 素点 点首 首先 先位 位于 于图 像坐 标系 再 通 安 装 探 头 上 接 收 再通 通过 过安 安装 装在 在探 探头 头上 上的 的接 接收 收器 器坐 发 部定 定位 位发 发射 射器 最 终 转 换 到 最终 终转 转换 换到 到三 维体 体坐 形 成 声由 由此 此形 形成 切 片 像切 切片 间位 数 据 式 本数 数据 据形 形式 用 离 散 还 无论 论采 采用 用离 离散 散体 素重 建还 还是 是连 场建 建模 都 必 须 回 答 这 些 如 入 问 题 都必 必须 须首 先回 回答 答这 这些 些二 维切 片如 如何 何进 进入 入统 统一 一三 的问 问题 中图 面到 到体 系的 的坐 表 方 在重 建表 表示 示方 方面 传 法 常 将 带 传统 统体 格方 方法 法通 通常 常将 将带 带位 姿二 片映 射到 到离 近 邻 过最 最近 近邻 距 加 权 距离 离加 加权 归 化 卷 积 归一 一化 化卷 卷积 核 函 插 值 核函 函数 数插 插值 局 拟 局部 部拟 拟合 贝 叶 斯 非 四 完 填 充 贝叶 叶斯 斯非 非局 部重 建或 或四 四面 面体 体插 值完 完成 成体 体数 据填 填充 等 提 出 应 其 具 有 代 性 改 等提 提出 出的 的自 自适 适应 应四 值是 是其 其中 中具 具有 有代 代表 表性 性的 的改 改进 如图 所 所示 该 依 均 匀 分 布 构 造 单 元 并 该方 法依 依据 据非 非均 均匀 匀切 片分 分布 布构 构造 造四 体单 单元 元并 并在 在单 元内 内部 部插 缓 解 样 规 则 致 洞 以缓 缓解 解自 采样 样不 不规 规则 则导 导致 致的 的局 部空 空洞 含 义 直 观 法几 何含 含义 义直 直观 实 熟 实现 现成 成熟 结 果 也 容 易 视 流 程 结果 果也 也容 容易 易进 入常 常规 规体 据可 可视 视化 化流 流程', '/#research', 'doctoral-thesis', 1, '2026-08-04', '105143a1943cea7d083a2bbbe5d577c7f77fddccde23b81f62990992a95d0a95') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e1c3871a1df2a985', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 自由手超声采集与体素网格重建研究现状', '等提出的自适应四面体插值是其中具有代表性的改进[31]，如图 1.2所示，该方法依据非均匀切片分布构造四面体单元并在单元内部插值，以缓解自由手采样不规则导致的局部空洞。体素网格方法几何含义直观、实现成熟，结果也容易进入常规体数据可视化流程。
体素网格重建内部也形成了由简单填充到结构化插值的演进。像素驱动方法从输入像素出发写入邻近体素，速度较快但容易留下空洞；体素驱动方法从目标体素反查附近切片，重建更规则但计算开销更高；距离加权、归一化卷积和核插值利用局部邻域补偿不规则采样；贝叶斯非局部和马尔可夫随机场方法进一步利用图像块相似性或空间先验抑制噪声[29,30]。这些改进说明体素网格方法并非简单切片堆叠，但其主要能力仍集中在离散采样与局部插值层面。
随着超声三维重建从离线可视化走向术中导航，评价重点也发生了变化。早期研究更关注体素填充完整性、插值平滑性和实时性；导航任务则进一步要求组织边界、病灶位置、器械位姿和风险结构能够在同一物理空间中被量化。对于甲状腺穿刺导航而言，视觉上连续的体数据并不足够，系统还需要表达针尖、结节、甲状腺包膜和邻近风险结构之间的空间关系。离散体素表征可以作为重要基线，但较难自然整合配准、语义概率和针体几何约束。', '31 1.2 29 30 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 自 由 手 采 集 体 素 网 格 自由 由手 手超 声采 采集 集与 与体 体素 素网 网格 格重 建研 等 提 出 适 应 四 面 插 值 其 具 有 代 表 性 改 进 等提 提出 出的 的自 自适 适应 应四 四面 面体 体插 插值 值是 是其 其中 中具 具有 有代 代表 表性 性的 的改 改进 如 图 如图 所 示 所示 该 方 法 依 据 非 均 匀 切 片 分 布 构 造 单 元 并 部 该方 方法 法依 依据 据非 非均 均匀 匀切 切片 片分 分布 布构 构造 造四 体单 单元 元并 并在 在单 元内 内部 部插 以 缓 解 样 不 规 则 导 致 局 空 洞 以缓 缓解 解自 手采 采样 样不 不规 规则 则导 导致 致的 的局 局部 部空 空洞 几 何 含 义 直 观 格方 法几 几何 何含 含义 义直 直观 实 成 熟 实现 现成 成熟 结 果 也 容 易 入 常 数 可 视 化 流 程 结果 果也 也容 容易 易进 进入 入常 常规 规体 体数 数据 据可 可视 视化 化流 流程 形 简 填 充 到 演 建内 部也 也形 形成 成了 了由 由简 简单 单填 填充 充到 到结 结构 构化 化插 值的 的演 演进 像 驱 动 从 输 发 写 邻 近 像素 素驱 驱动 动方 法从 从输 输入 入像 素出 出发 发写 写入 入邻 邻近 近体 速 度 较 快 但 留 下 速度 度较 较快 快但 但容 易留 留下 下空 目 标 反 查 附 从目 目标 标体 素反 反查 查附 附近 近切 更 计 算 开 销 高 建更 更规 则但 但计 计算 算开 开销 销更 更高 距 离 加 权 距离 离加 加权 归 一 卷 积 核 利 用 域 补 偿 归一 一化 化卷 卷积 积和 和核 核插 值利 利用 用局 部邻 邻域 域补 补偿 偿不 则采 贝 叶 斯 马 尔 夫 随 机 步 块 相 似 或 间 先 验 抑 制 噪 贝叶 叶斯 斯非 非局 部和 和马 马尔 尔可 可夫 夫随 随机 机场 场方 法进 进一 一步 步利 用图 图像 像块 块相 相似 似性 性或 或空 空间 间先 先验 验抑 抑制 制噪 噪声 这 些 说 明 堆 叠 这些 些改 进说 说明 明体 法并 并非 非简 单切 片堆 堆叠 主 要 能 力 仍 散 层 但其 其主 主要 要能 能力 力仍 仍集 集中 中在 在离 离散 散采 样与 与局 值层 层面 着 线 走 向 术 航 随着 着超 建从 从离 离线 线可 化走 走向 向术 术中 中导 导航 评 价 点 生 变 评价 价重 重点 点也 也发 发生 生了 了变 变化 早 期 关 注 完 整 早期 期研 究更 更关 关注 注体 素填 充完 完整 整性 平 滑 时 值平 平滑 滑性 性和 和实 实时 时性 任 务 求 组 织 边 界 航任 任务 务则 则进 步要 要求 求组 组织 织边 边界 病 灶 位 置 病灶 灶位 位置 器 械 姿 风 险 够 同 被 量 器械 械位 位姿 姿和 和风 风险 险结 构能 能够 够在 在同 同一 一物 理空 间中 中被 被量 量化 对 于 甲 腺 穿 刺 而 言 对于 于甲 甲状 状腺 腺穿 穿刺 刺导 航而 而言 觉 上 足 视觉 觉上 上连 续的 的体 据并 并不 不足 足够 系 统 还 需 达 针 尖 系统 统还 还需 需要 要表 表达 达针 针尖 节 结节 包 膜 之 腺包 包膜 膜和 和邻 近风 构之 之间 间的 的空 间关 关系 征 作 基 散体 素表 表征 征可 可以 以作 作为 为重 重要 要基 基线 难 然 合 配 准 但较 较难 难自 自然 然整 整合 合配 配准 语 概 率 语义 义概 概率 率和 和针 针体 体几 何约', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e1c3871a1df2a9857e01315e01efd6493cd68f