INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-08d877ead7a9be51', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 自由手超声采集与体素网格重建研究现状', '、器械位姿和风险结构能够在同一物理空间中被量化。对于甲状腺穿刺导航而言，视觉上连续的体数据并不足够，系统还需要表达针尖、结节、甲状腺包膜和邻近风险结构之间的空间关系。离散体素表征可以作为重要基线，但较难自然整合配准、语义概率和针体几何约束。
综上，自由手超声采集与体素网格重建已经形成从外部跟踪、无跟踪运动估计到体素插值和结构化插值的技术链条。其优势在于几何关系直观、实现成熟、便于体数据可视化；困难在于稀疏非均匀扫查、探头压力变化、接触状态变化和位姿误差会共同破坏局部插值假设，且离散体素难以自然表达方向相关回波、散斑统计和多源语义约束。因此，面向颈部自由手扫查的三维重建需要在体素网格重建基础上进一步研究连续表征和物理成像约束。
图 .2 非均匀自由手超声数据的四面体插值重建流程[31]
