INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3ad3da0fc43beb85', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 超声物理约束下的连续神经场三维重建研究现状', '连续神经场表征为超声三维重建提供了不同于离散体素网格的建模方式：空间属性不再存储在固定分辨率网格中，而由坐标条件神经函数连续表示[32–34]。神经场表面重建、Geometry-aware ultrasound NeRF、Continuous Bernoulli ultrasound NeRF 以及 Representing 3D Ultrasound with Neural Fields 等工作表明，不规则二维切片可以作为监督信号约束连续三维函数，使超声三维重建从离散体素插值进一步走向连续场建模[35–37]。这一路线的意义在于，它不必先把所有切片重采样到固定网格，而是直接在坐标空间中表达可查询的组织强度、结构或语义属性。
连续神经场表征最初在医学图像中主要服务连续形状建模、稀疏视角重建和新视角合成[33,38–41]；迁移到超声后，问题的性质发生了变化。Ultra-NeRF 将神经渲染与超声传播联系起来，指出 B-mode 外观具有明显的入射方向依赖[7]；UlRe-NeRF 通过反射方向参数化和谐波编码描述高频反射强度[42]；Continuous Bernoulli ultrasound NeRF 从概率分布角度处理回波强度；Geometry-aware 方法则强调几何一致性约束。这些研究共同说明，连续场表示需要进一步适配超声成像机制，而不能只沿用光学图像中的 NeRF 假设。', '32 34 geometry-aware ultrasound nerf continuous bernoulli representing 3d with neural fields 35 37 33 38 41 ultra-nerf b-mode ulre-nerf 42 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 下 声物 束下 下的 的连 场三 建研 表 征 提 供 不 同 于 离 散 体 素 网 格 模 方 式 场表 表征 征为 为超 建提 提供 供了 了不 不同 同于 于离 离散 散体 体素 素网 网格 格的 的建 建模 模方 方式 空 间 属 性 再 存 储 固 定 分 辨 率 空间 间属 属性 性不 不再 再存 存储 储在 在固 固定 定分 分辨 辨率 率网 格中 而 由 坐 标 条 件 函 数 示 而由 由坐 坐标 标条 条件 件神 经函 函数 数连 续表 表示 面 表面 面重 以 以及 等 工 作 明 等工 工作 作表 表明 规 则 二 切 片 可 监 督 信 号 不规 规则 则二 二维 维切 切片 片可 可以 以作 作为 为监 监督 督信 信号 号约 续三 维函 使 从 插 值 进 一 步 走 向 使超 建从 从离 素插 插值 值进 进一 一步 步走 走向 向连 续场 场建 这 路 线 意 义 这一 一路 路线 线的 的意 意义 义在 在于 它 必 先 把 所 有 采 样 到 它不 不必 必先 先把 把所 所有 有切 片重 重采 采样 样到 到固 定网 直 接 达 查 询 组 织 强 度 而是 是直 直接 接在 在坐 标空 间中 中表 表达 达可 可查 查询 询的 的组 组织 织强 强度 结 构 或 语 结构 构或 或语 语义 义属 最 初 医 学 图 像 主 要 服 务 形 征最 最初 初在 在医 医学 学图 图像 像中 中主 主要 要服 服务 务连 续形 形状 状建 稀 疏 视 角 新 合 成 稀疏 疏视 视角 角重 建和 和新 新视 角合 合成 迁 移 后 迁移 移到 到超 声后 问 题 质 发 生 变 化 问题 题的 的性 性质 质发 发生 生了 了变 变化 将 渲 染 传 播 联 系 起 来 将神 经渲 渲染 染与 与超 声传 传播 播联 联系 系起 起来 指 出 指出 观 具 显 入 射 依 赖 外观 观具 具有 有明 明显 显的 的入 入射 射方 方向 向依 依赖 通 过 反 参 谐 波 编 码 描 述 高 频 通过 过反 反射 向参 参数 数化 化和 和谐 谐波 波编 编码 码描 描述 述高 高频 频反 射强 概 布 处 回 从概 概率 率分 分布 布角 角度 度处 处理 理回 回波 波强 法 调 几 何 致 方法 法则 则强 强调 调几 几何 何一 一致 致性 性约 些 共 说 这些 些研 究共 共同 同说 说明 需 适 配 机 制 示需 需要 要进 步适 适配 配超 声成 成像 像机 机制 能 只 沿 用 光 而不 不能 能只 只沿 沿用 用光 光学 中的 假 设 假设', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3ad3da0fc43beb85b774bc47d9e3bc1f8b3f05197ff38457beb97d72a36f2b72') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5a5ceec7b60bc6fd', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 超声物理约束下的连续神经场三维重建研究现状', 'us Bernoulli ultrasound NeRF 从概率分布角度处理回波强度；Geometry-aware 方法则强调几何一致性约束。这些研究共同说明，连续场表示需要进一步适配超声成像机制，而不能只沿用光学图像中的 NeRF 假设。
坐标网络的表示能力也是神经场重建能否适用于超声的重要因素。SIREN 证明周期激活函数更适合表示高频信号及其导数[43]；FINER 和 Beyond Periodicity 进一步讨论可变周期、初始化敏感性和谱偏置问题[44,45]；Instant-NGP、DONeRF 和 Mip-NeRF 等工作则分别从多分辨率编码、实时查询和抗混叠采样角度缓解神经场在多尺度表达、查询效率与采样混叠方面的局限[46–48]。这些工作并非专门的超声重建算法，但提示超声神经场需要同时处理高频散斑、组织界面、连续导数、采样尺度和训练效率。
从问题表述看，自由手超声神经场重建可以理解为正问题和逆问题的耦合：正问题是由三维介质场和成像配置生成二维超声观测，逆问题是由多帧观测反推三维介质场或其参数化表示。在这一框架下，神经场网络不应仅学习坐标到灰度的黑盒映射，而应表达与声束传播、介质散射和界面反射相关的场属性；渲染算子也不能简单沿用光学体渲染，而需要结合超声图像形成过程。[49–52]', 'us bernoulli ultrasound nerf geometry-aware siren 43 finer beyond periodicity 44 45 instant-ngp donerf mip-nerf 46 48 49 52 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 下 声物 束下 下的 的连 场三 建研 从 概 率 分 布 角 度 处 回 波 强 从概 概率 率分 分布 布角 角度 度处 处理 理回 回波 波强 强度 方 法 则 调 几 何 一 致 性 方法 法则 则强 强调 调几 几何 何一 一致 致性 性约 这 些 共 同 说 明 这些 些研 究共 共同 同说 说明 表 示 需 要 进 步 适 配 成 像 机 制 续场 场表 表示 示需 需要 要进 进一 一步 步适 适配 配超 声成 成像 像机 机制 而 不 能 只 沿 用 光 学 图 而不 不能 能只 只沿 沿用 用光 光学 学图 图像 像中 中的 假 设 假设 坐 标 网 络 力 也 否 于 因 素 坐标 标网 网络 络的 的表 示能 能力 力也 也是 是神 场重 建能 能否 否适 适用 用于 于超 声的 的重 重要 要因 因素 证 周 期 激 活 函 数 更 合 高 频 信 号 其 导 证明 明周 周期 期激 激活 活函 函数 数更 更适 适合 合表 示高 高频 频信 信号 号及 及其 其导 导数 讨 可 变 步讨 讨论 论可 可变 变周 初 始 化 敏 感 谱 偏 置 问 题 初始 始化 化敏 敏感 感性 性和 和谱 谱偏 偏置 置问 问题 等 工 作 别 多 辨 编 码 等工 工作 作则 则分 分别 别从 从多 多分 分辨 辨率 率编 编码 实 时 查 询 抗 混 叠 采 样 缓 解 尺 达 实时 时查 查询 询和 和抗 抗混 混叠 叠采 采样 样角 度缓 缓解 解神 场在 在多 多尺 尺度 度表 表达 效 面 局 限 询效 效率 率与 与采 样混 叠方 方面 面的 的局 局限 并 非 专 门 算 些工 作并 并非 非专 专门 门的 的超 声重 建算 算法 但 提 散 斑 但提 提示 示超 声神 场需 要同 同时 时处 理高 频散 散斑 组 织 界 组织 织界 界面 续导 训 练 样尺 度和 和训 训练 练效 述 看 从问 题表 表述 述看 自 由 手 以 正 逆 耦 自由 由手 手超 建可 可以 以理 理解 解为 为正 正问 题和 和逆 逆问 题的 的耦 耦合 介 质 生 二 观 测 题是 是由 由三 维介 介质 质场 场和 和成 像配 配置 置生 生成 成二 二维 维超 声观 观测 帧 反 推 或 参 由多 多帧 帧观 测反 反推 推三 场或 或其 其参 参数 数化 化表 框 架 在这 这一 一框 框架 架下 应 仅 习 到 灰 黑 盒 映 射 场网 络不 不应 应仅 仅学 学习 习坐 标到 到灰 灰度 度的 的黑 黑盒 盒映 映射 传 播 而应 应表 达与 与声 声束 束传 传播 相 关 属 质散 散射 射和 和界 面反 反射 射相 相关 关的 的场 场属 属性 渲 染 子 简 单 体 渲染 染算 算子 子也 也不 能简 简单 单沿 学体 体渲 结 形 过 程 而需 要结 结合 合超 声图 像形 形成 成过 过程', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5a5ceec7b60bc6fd97992a8ed76d457513d3c35e0664f9df8359a997fea0dd97') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`