INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5f69764d79d0f207', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 超声物理约束下的连续神经场三维重建研究现状', '声观测，逆问题是由多帧观测反推三维介质场或其参数化表示。在这一框架下，神经场网络不应仅学习坐标到灰度的黑盒映射，而应表达与声束传播、介质散射和界面反射相关的场属性；渲染算子也不能简单沿用光学体渲染，而需要结合超声图像形成过程。[49–52]
图 .3 Ultra-NeRF 中面向超声物理的神经渲染框架[7]
Figure . Ultrasound-physics-aware neural rendering framework in Ultra-NeRF. [7]
图 1.3表明，现有超声 NeRF 研究已经暴露出直接套用光学 NeRF 的局限。探头压力变化会导致不同扫查在同一空间位置对应的像素强度不一致，位姿误差会破坏多视角监督，B-mode 图像中的散斑和声影也不满足自然图像的颜色一致性假设。Continuous Bernoulli ultrasound NeRF 尝试从概率建模角度提高回波重建真实性，Geometry-aware 方法强调几何约束，这些探索都指向同一问题：超声神经场必须同时处理连续空间表示、自由手位姿误差和声学成像机制。', '49 52 ultra-nerf figure ultrasound-physics-aware neural rendering framework in ultra-nerf. 1.3 nerf b-mode continuous bernoulli ultrasound geometry-aware 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 下 声物 束下 下的 的连 场三 建研 观 测 声观 观测 逆 问 题 由 多 帧 反 推 介 质 或 其 参 数 化 表 示 逆问 问题 题是 是由 由多 多帧 帧观 测反 反推 推三 维介 介质 质场 场或 或其 其参 参数 数化 化表 表示 这 一 框 架 在这 这一 一框 框架 架下 网 络 不 应 仅 学 习 坐 标 到 灰 度 黑 盒 映 射 场网 网络 络不 不应 应仅 仅学 学习 习坐 坐标 标到 到灰 灰度 度的 的黑 黑盒 盒映 映射 而 达 传 播 而应 应表 表达 达与 与声 声束 束传 传播 散 界 面 相 关 属 性 质散 散射 射和 和界 界面 面反 反射 射相 相关 关的 的场 场属 属性 渲 染 算 子 也 能 简 单 沿 用 光 体 渲染 染算 算子 子也 也不 不能 能简 简单 单沿 沿用 用光 光学 学体 体渲 需 要 结 合 图 像 形 成 过 程 而需 需要 要结 结合 合超 声图 图像 像形 形成 成过 过程 向 中面 面向 向超 理的 的神 经渲 染框 明 表明 有 现有 有超 已 暴 露 出 直 接 套 究已 已经 经暴 暴露 露出 出直 直接 接套 套用 局 限 的局 局限 探 头 压 力 变 会 导 致 同 扫 查 空 间 位 置 对 素 强 探头 头压 压力 力变 变化 化会 会导 导致 致不 不同 同扫 扫查 查在 在同 同一 一空 空间 间位 位置 置对 对应 应的 的像 像素 素强 强度 度不 不一 一致 姿 误 差 破 坏 视 角 监 督 位姿 姿误 误差 差会 会破 破坏 坏多 多视 视角 角监 监督 斑 影 满 足 自 然 颜 色 假 设 像中 中的 的散 散斑 斑和 和声 声影 影也 不满 满足 足自 自然 然图 像的 的颜 颜色 色一 致性 性假 假设 尝 试 从 概 率 模 提 高 回 波 真 实 尝试 试从 从概 概率 率建 建模 模角 角度 度提 提高 高回 回波 波重 建真 真实 实性 方 法 调 几 何 方法 法强 强调 调几 几何 何约 些 索 都 指 这些 些探 探索 索都 都指 指向 向同 一问 必 须 时 处 声神 场必 必须 须同 同时 时处 处理 理连 续空 间表 手 机 制 自由 由手 手位 差和 声学 学成 成像 像机 机制', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5f69764d79d0f20775dd8543839fa889827e75c5da9417de88059b7053f49363') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-05e3f2b618d19e9f', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 超声物理约束下的连续神经场三维重建研究现状', 'nuous Bernoulli ultrasound NeRF 尝试从概率建模角度提高回波重建真实性，Geometry-aware 方法强调几何约束，这些探索都指向同一问题：超声神经场必须同时处理连续空间表示、自由手位姿误差和声学成像机制。
超声仿真和定量超声研究为这种物理约束提供了基础。Field II、k-Wave、SIMUS、卷积射线追踪和 Monte Carlo 超声仿真分别从声场传播、波动方程、点扩散函数、散射体分布和交互式渲染等角度解释超声图像形成[61–64]。这些方法不直接求解自由手逆重建问题，却说明 B-mode 灰度是声束传播、介质散射、接收孔径、系统响应和显示后处理共同作用的结果。图 1.4 UltraRay 的射线追踪过程可视化为例，展示了主射线传播以及界面交互后二次射线向换能器采样的机制；这类可视化说明，B-mode 观测应被理解为物理成像过程的结果，而不仅是普通灰度图像。
图 .4 UltraRay 中超声主射线与二次射线追踪过程示意[64]
Figure . Primary and secondary ray-tracing process in UltraRay. [64]
散斑统计进一步说明，超声图像中的纹理不能简单视作应被去除的噪声。Oelze 与 Mamou、Cloutier 等以及 Tsui 等的研究表明，散斑与组织微结构、散射体分布和系统响应密切相关；甲状腺超声中的散斑特征还可能有助于区分甲状腺、气管、颈动脉和肌肉等结构。这类认识提示，三维重建方法不宜用过强逐像素约束把随机散斑误当成确定性灰度，而应把散斑视为亚分辨散射体和系统响应共同形成的统计纹理。', 'nuous bernoulli ultrasound nerf geometry-aware field ii k-wave simus monte carlo 61 64 b-mode 1.4 ultraray figure primary and secondary ray-tracing process in ultraray. oelze mamou cloutier tsui 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 下 声物 束下 下的 的连 场三 建研 尝 试 从 概 率 模 角 度 提 高 回 波 真 实 性 尝试 试从 从概 概率 率建 建模 模角 角度 度提 提高 高回 回波 波重 建真 真实 实性 方 法 强 调 几 何 方法 法强 强调 调几 几何 何约 这 些 探 索 都 指 向 同 一 问 题 这些 些探 探索 索都 都指 指向 向同 同一 一问 问题 必 须 时 处 空 间 表 示 声神 场必 必须 须同 同时 时处 处理 理连 续空 空间 间表 表示 自 由 手 位 姿 误 差 学 成 像 机 制 自由 由手 手位 位姿 姿误 误差 差和 和声 声学 学成 成像 像机 机制 仿 定 量 种 供 基 础 声仿 仿真 真和 和定 定量 量超 声研 究为 为这 这种 种物 束提 提供 供了 了基 基础 卷 积 射 线 追 踪 卷积 积射 射线 线追 追踪 踪和 分 别 传 播 真分 分别 别从 从声 声场 场传 传播 动 程 波动 动方 方程 点 扩 散 函 数 点扩 扩散 散函 函数 体 布 交 互 式 渲 染 等 解 释 图 形 散射 射体 体分 分布 布和 和交 交互 互式 式渲 渲染 染等 等角 度解 解释 释超 声图 图像 像形 形成 不 直 接 求 逆 些方 法不 不直 直接 接求 求解 解自 手逆 逆重 建问 却 说 明 却说 说明 灰 灰度 度是 是声 声束 束传 介 质 介质 质散 收 孔 径 接收 收孔 孔径 系 统 响 应 显 后 共 作 用 结 果 系统 统响 响应 应和 和显 显示 示后 后处 理共 共同 同作 作用 用的 的结 结果 过 可 视 化 例 的射 踪过 过程 程可 可视 视化 化为 为例 展 主 以 界 面 二 次 换 能 器 采 样 展示 示了 了主 主射 线传 播以 以及 及界 界面 面交 互后 后二 二次 次射 线向 向换 换能 能器 器采 采样 样的 的机 类 这类 类可 化说 观 测 被 观测 测应 应被 被理 理解 解为 为物 理成 像过 程的 而 仅 普 通 而不 不仅 仅是 是普 普通 通灰 度图 意 中超 声主 线与 与二 程示 示意 斑 计 进 步 散斑 斑统 统计 计进 进一 一步 步说 纹 简 单 去 除 噪 像中 中的 的纹 纹理 理不 不能 能简 简单 单视 视作 作应 被去 去除 除的 的噪 噪声 等以 等的 的研 究表 表明 组 织 微 构 斑与 与组 组织 织微 微结 结构 密 切 相 关 和系 应密 密切 切相 相关 甲 腺 特 征 还 有 助 于 区 甲状 状腺 腺超 声中 的散 斑特 特征 征还 还可 可能 能有 有助 助于 于区 区分 分甲 气 管 气管 颈 脉 肌 肉 颈动 动脉 脉和 和肌 肌肉 肉等 等结 认 识 类认 认识 识提 提示 宜 逐 素 把 随 当 确 建方 不宜 宜用 用过 过强 强逐 逐像 像素 素约 束把 把随 随机 机散 斑误 误当 当成 成确 确定 定性 性灰 亚 辨 而应 应把 把散 斑视 视为 为亚 亚分 分辨 辨散 体和 应共 同形 成的 的统 计纹', '/#research', 'doctoral-thesis', 1, '2026-08-04', '05e3f2b618d19e9f2fa88db4f6c24778704d85756ab482c55ccabcb3dfb297fe') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d2065f320f3098a3', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 超声三维重建与物理约束连续神经场研究现状 / 超声物理约束下的连续神经场三维重建研究现状', '微结构、散射体分布和系统响应密切相关；甲状腺超声中的散斑特征还可能有助于区分甲状腺、气管、颈动脉和肌肉等结构。这类认识提示，三维重建方法不宜用过强逐像素约束把随机散斑误当成确定性灰度，而应把散斑视为亚分辨散射体和系统响应共同形成的统计纹理。
真实自由手超声采集中仍存在接触不良、声影、深度衰减、局部无效列和设备后处理差异等观测质量问题。NeRF-US、无监督超声图像质量评估和标准切面检测等研究表明，超声图像的可用性与采集质量、切面标准性和局部可见性密切相关[73–75]，因此进入三维神经场重建的像素或射线不宜默认全部有效。近年来 USF-MAE、OpenUS、USFM 和 UltraSam 等超声基础模型通过自监督预训练、对比学习或大规模分割数据学习通用声像表征[76–80]；UMAP 和随机森林则分别提供非线性特征压缩与稳健判别边界[81,82]。在自由手重建任务中，这类方法更适合作为输入侧的列级观测可信度控制，用于降低低可信射线对三维重建的干扰，而不应被拔高为独立主线。
综上，超声神经场重建的技术脉络已经从通用坐标网络和医学神经场，逐步发展到面向 B-mode 成像机制的方向相关反射、概率回波建模、几何一致性约束和超声仿真启发。现有研究仍常把连续场表示、自由手位姿误差、局部观测质量和声学成像机制分开处理，在颈部自由手扫查中难以同时应对稀疏多视角、接触不稳定和强界面反射。因此，本文围绕物理约束连续神经场表征开展相应研究，并将有效观测筛选定位为输入侧质量控制，而非独立研究主线。[83]', 'nerf-us 73 75 usf-mae openus usfm ultrasam 76 80 umap 81 82 b-mode 83 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 超 声 三 维 重 建 物 理 约 束 连 续 神 经 场 超声 声三 三维 维重 重建 建与 与物 物理 理约 约束 束连 连续 续神 神经 经场 场研 下 声物 束下 下的 的连 场三 建研 微 结 构 微结 结构 散 射 体 分 布 系 统 响 应 密 切 相 关 散射 射体 体分 分布 布和 和系 系统 统响 响应 应密 密切 切相 相关 甲 腺 斑 特 征 还 可 能 有 助 于 区 甲状 状腺 腺超 声中 中的 的散 散斑 斑特 特征 征还 还可 可能 能有 有助 助于 于区 区分 分甲 气 管 气管 颈 动 脉 肌 肉 等 颈动 动脉 脉和 和肌 肌肉 肉等 等结 这 类 认 识 提 示 这类 类认 认识 识提 提示 方 法 不 宜 用 过 强 逐 像 素 把 随 机 误 当 成 确 定 性 灰 度 建方 方法 法不 不宜 宜用 用过 过强 强逐 逐像 像素 素约 束把 把随 随机 机散 斑误 误当 当成 成确 确定 定性 性灰 灰度 而 视 亚 辨 共 同 形 计 纹 而应 应把 把散 斑视 视为 为亚 亚分 分辨 辨散 体和 应共 共同 同形 形成 成的 的统 统计 计纹 纹理 真 实 自 由 手 采 集 仍 存 接 触 良 真实 实自 自由 由手 手超 声采 采集 集中 中仍 仍存 存在 在接 接触 触不 不良 影 声影 深 衰 减 深度 度衰 衰减 局 部 无 效 列 设 备 后 处 差 异 观 测 质 量 问 题 局部 部无 无效 效列 列和 和设 设备 备后 后处 处理 理差 差异 异等 等观 观测 测质 质量 量问 问题 监 督 图 评 估 标 准 面 检 表 明 无监 监督 督超 声图 图像 像质 量评 评估 估和 和标 标准 准切 切面 面检 检测 测等 等研 究表 表明 像的 的可 可用 用性 性与 与采 集质 见 面标 准性 性和 和局 部可 可见 见性 性密 因 此 进 入 或 线 默 全 因此 此进 进入 入三 维神 场重 建的 的像 素或 或射 射线 线不 宜默 默认 认全 全部 部有 有效 近 年 来 近年 年来 基 础 模 型 通 预 训 练 等超 声基 基础 础模 模型 型通 通过 过自 自监 督预 预训 训练 对 比 学 习 大 规 割 数 据 对比 比学 学习 习或 或大 大规 规模 模分 分割 割数 数据 据学 习通 通用 用声 声像 像表 表征 森 林 则 别 供 非 压 缩 稳 健 判 边 界 和随 机森 森林 林则 则分 分别 别提 提供 供非 非线 线性 性特 征压 压缩 缩与 与稳 稳健 健判 判别 别边 边界 任 务 在自 手重 建任 任务 务中 更 适 合 作 输 侧 级 信 控 制 类方 法更 更适 适合 合作 作为 为输 输入 入侧 侧的 的列 列级 级观 测可 可信 信度 度控 控制 降 低 干 扰 用于 于降 降低 低低 低可 信射 线对 对三 的干 干扰 被 拔 高 独 立 主 而不 不应 应被 被拔 拔高 高为 为独 独立 立主 主线 综 上 综上 技 术 络 已 从 坐 网 医 声神 的技 技术 术脉 脉络 络已 已经 经从 从通 用坐 坐标 标网 网络 络和 和医 医学 学神 步 发 展 到 向 逐步 步发 发展 展到 到面 面向 反 成像 像机 机制 制的 的方 方向 向相 关反 反射 概 率 回 波 概率 率回 回波 波建 建模 几 何 一 致 仿 启 几何 何一 一致 致性 性约 束和 和超 声仿 仿真 真启 启发 常 现有 有研 究仍 仍常 常把 把连 续场 场表 表示 位 姿 手位 位姿 姿误 误差 开 部观 量和 和声 声学 学成 制分 分开 开处 扫 查 难 以 时 稀 疏 多 角 在颈 颈部 部自 手扫 扫查 查中 中难 难以 以同 同时 时应 应对 对稀 稀疏 疏多 多视 视角 不稳 稳定 定和 和强 强界 界面 面反 本 文 围 绕 本文 文围 围绕 绕物 征开 开展 展相 相应 应研 并 将 筛 选 并将 将有 效观 测筛 筛选 选定 定位 位为 侧质 量控 而非 非独 立研 究主', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd2065f320f3098a3346f5b43bc3dcde79f40ca6eaeb30153f2c7a585a96acbde') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-c5575283741bbb1c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '超声扫查序列配准首先要回答一个几何问题：不同扫查、不同切片和不同器械观测如何进入同一物理空间。自由手超声的坐标链通常包括图像坐标、图像物理尺度、探头坐标、跟踪器坐标和世界坐标；穿刺导航还需要把器械参考架和真实针尖位置纳入同一链路。Mercier 等和 Hsu 等关于自由手超声标定的综述将这一问题界定为超声三维重建的前提条件[4,5]。若坐标链本身不闭合，后续配准和导航只能在错误初值上局部补偿。
探头标定研究围绕如何把二维图像平面可靠放入三维空间展开。点靶、平面靶、交叉线和N线模体都将图像中可见结构转换为空间中的已知几何约束；其中N线模体由于交点清晰、冗余约束较多，被广泛用于自由手超声标定。Carbajal 等指出，只使用中间线位置会浪费N线结构中的其他几何信息[84]；Chen 等的实时标定系统进一步将交点自动提取、闭式求解、精度反馈和采样控制结合起来，使标定从一次性矩阵估计转向带质量反馈的采样过程[85]。任意线模体、多层N线和共面约束算法则进一步提高了自动识别、外点抑制和鲁棒优化能力[86,87]。
图 1.5给出了N线模体中超声图像平面与三层N线交点之间的几何对应关系[84]。该图同时呈现三层N线的空间布置、单个N线与图像平面的交点关系，以及实际超声图像中交点自动分割后的对应点。对于多次扫查重建与导航任务，N线标定提供的是初始几何可信度：它不能消除所有扫查级偏差和帧级抖动，却决定了后续规范空间优化是否具有可靠起点。', 'mercier hsu carbajal 84 chen 85 86 87 1.5 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 首 先 要 回 答 一 个 几 何 问 题 准首 首先 先要 要回 回答 答一 一个 个几 几何 何问 问题 不 同 不同 同扫 切 片 器 械 观 测 如 进 入 物 理 同切 切片 片和 和不 同器 器械 械观 观测 测如 如何 何进 进入 入同 同一 一物 物理 理空 自 由 手 坐 链 通 常 包 括 图 像 自由 由手 手超 声的 的坐 坐标 标链 链通 通常 常包 包括 括图 图像 像坐 尺 度 像物 理尺 尺度 探 头 探头 头坐 跟 踪 世 界 跟踪 踪器 器坐 标和 和世 世界 界坐 穿 刺 导 航 还 需 把 参 考 架 真 实 针 尖 位 置 纳 路 穿刺 刺导 导航 航还 还需 需要 要把 把器 械参 参考 考架 架和 和真 真实 实针 针尖 尖位 位置 置纳 纳入 一链 链路 等 等和 关 于 综 述 将 这 三 维 重 建 前 提 条 件 等关 关于 于自 声标 定的 的综 综述 述将 将这 这一 一问 题界 界定 定为 为超 声三 三维 维重 重建 建的 的前 前提 提条 条件 若 本 身 闭 合 若坐 链本 本身 身不 不闭 闭合 后 续 只 能 错 误 初 值 上 局 部 补 偿 后续 续配 准和 和导 航只 只能 能在 在错 错误 误初 初值 值上 上局 局部 部补 补偿 围 绕 二 平 面 可 靠 放 展 开 头标 定研 究围 围绕 绕如 何把 把二 二维 维图 像平 平面 面可 可靠 靠放 放入 入三 维空 间展 展开 点 靶 点靶 面靶 交 叉 线 交叉 叉线 线和 模 体 都 见 结 构 转 换 已 知 线模 模体 体都 都将 将图 像中 中可 可见 见结 结构 构转 转换 换为 为空 间中 中的 的已 已知 知几 何约 其 其中 清 晰 体由 由于 于交 交点 点清 清晰 冗 余 较 多 冗余 余约 束较 较多 被 广 泛 用 被广 广泛 泛用 用于 指 出 等指 指出 使 会 浪 费 只使 使用 用中 中间 间线 线位 置会 会浪 浪费 他 信 息 线结 构中 的其 其他 他几 何信 信息 时 系 统 步 动 取 等的 的实 实时 时标 定系 系统 统进 进一 一步 步将 将交 点自 自动 动提 提取 式 求 解 闭式 式求 求解 精 反 馈 采 样 控 制 起 来 精度 度反 反馈 馈和 和采 采样 样控 控制 制结 结合 合起 起来 从 次 性 矩 阵 估 计 向 带 质 量 过 程 使标 定从 从一 一次 次性 性矩 矩阵 阵估 估计 计转 转向 向带 带质 质量 量反 馈的 的采 样过 过程 任 意 任意 意线 层 多层 共 算 法 则 高 识 别 和共 共面 面约 束算 算法 法则 则进 步提 提高 高了 了自 动识 识别 抑 鲁 棒 优 化 力 外点 点抑 抑制 制和 和鲁 鲁棒 棒优 优化 化能 能力 给 给出 出了 体中 中超 声图 面与 与三 三层 之 对 应 线交 点之 之间 间的 的几 何对 对应 应关 关系 该 呈 该图 图同 同时 时呈 呈现 现三 布 线的 的空 间布 布置 单 单个 线与 与图 面的 的交 点关 以 际 分 割 以及 及实 实际 际超 中交 动分 分割 割后 后的 的对 应点 务 对于 于多 多次 次扫 查重 建与 与导 航任 任务 供 始 线标 定提 提供 供的 的是 是初 初始 始几 何可 可信 信度 它 消 除 所 有 级 偏 差 帧 抖 它不 不能 能消 消除 除所 所有 有扫 查级 级偏 偏差 差和 和帧 帧级 级抖 抖动 却 决 否 具 却决 决定 定了 了后 续规 间优 化是 是否 否具 具有 有可 靠起 起点', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'c5575283741bbb1cf459445d64dbb84410cf86d00c01b6e2fec72f246bfdb0a0')