INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-efd8f932e7d8bf0d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '图同时呈现三层N线的空间布置、单个N线与图像平面的交点关系，以及实际超声图像中交点自动分割后的对应点。对于多次扫查重建与导航任务，N线标定提供的是初始几何可信度：它不能消除所有扫查级偏差和帧级抖动，却决定了后续规范空间优化是否具有可靠起点。
图 .5 N线模体中图像平面与三层N线交点的几何对应关系[84]
Figure . N-wire phantom geometric correspondences. [84]
综上，空间标定研究已经从单一几何模型求解，发展到模体设计、自动交点识别、闭式或鲁棒求解和质量反馈共同约束的流程化标定。其局限在于，标定主要确定图像平面与探头坐标系的初始关系，难以吸收后续扫查中的同步误差、探头压力、遮挡和轨迹抖动。因此，多组超声扫查序列还需要在标定基础上进一步研究残余位姿误差的建模与修正。[88–91]
在标定链路给出初始空间关系后，超声扫查序列配准需要处理残余系统偏差和局部位姿抖动。单次自由手扫查视野有限，甲状腺及其周围结构通常需要多次扫查才能覆盖；不同扫查的起止位置、入射角、探头压力和接触状态不同，外部定位系统还会带入同步误差或短时遮挡。超声扫查序列配准因此不能简化为两幅图像刚性对齐，而应被视为观测、轨迹和三维表征在规范空间中的联合估计。', '84 figure n-wire phantom geometric correspondences. 88 91 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 图 同 时 呈 三 层 图同 同时 时呈 呈现 现三 三层 线 布 置 线的 的空 间布 布置 单 个 单个 像 平 面 交 点 关 系 线与 与图 图像 像平 平面 面的 的交 交点 点关 关系 以 实 际 自 动 分 割 后 对 应 以及 及实 实际 际超 声图 像中 中交 点自 自动 动分 分割 割后 后的 的对 对应 应点 于 多 次 重 建 导 航 任 务 对于 于多 多次 次扫 查重 重建 建与 与导 导航 航任 任务 提 供 初 始 几 何 可 信 度 线标 定提 提供 供的 的是 是初 初始 始几 几何 何可 可信 信度 它 不 能 消 除 所 有 级 偏 差 帧 抖 它不 不能 能消 消除 除所 所有 有扫 查级 级偏 偏差 差和 和帧 帧级 级抖 抖动 却 决 续 优 化 否 具 靠 起 却决 决定 定了 了后 后续 续规 间优 优化 化是 是否 否具 具有 有可 可靠 靠起 起点 模 体 线模 模体 体中 中图 面与 与三 线交 点的 的几 何对 应关 综 上 综上 已 经 从 一 型 求 解 定研 究已 已经 经从 从单 单一 一几 何模 模型 型求 求解 发 展 到 设 计 发展 展到 到模 体设 设计 识 别 动交 点识 识别 闭 式 或 鲁 棒 质 量 反 馈 共 流 程 闭式 式或 或鲁 鲁棒 棒求 解和 和质 质量 量反 反馈 馈共 共同 同约 束的 的流 流程 程化 化标 其 局 限 其局 局限 限在 在于 主 要 确 探 头 坐 定主 主要 要确 确定 定图 与探 探头 头坐 坐标 标系 系的 的初 始关 难 吸 收 步 误 难以 以吸 吸收 收后 续扫 查中 中的 的同 同步 步误 误差 压 力 头压 压力 遮 挡 轨 迹 遮挡 挡和 和轨 轨迹 迹抖 因 此 因此 组 还 需 基 础 进 残 余 位 姿 修 正 多组 组超 列还 还需 需要 要在 在标 定基 基础 础上 上进 进一 一步 步研 究残 残余 余位 位姿 姿误 差的 的建 建模 模与 与修 修正 链 路 给 出 定链 链路 路给 给出 出初 始空 间关 系后 处 理 统 部 准需 要处 处理 理残 余系 系统 统偏 和局 局部 部位 姿抖 由 手 视 野 单次 次自 自由 由手 手扫 查视 视野 野有 有限 甲 腺 周 围 结 构 通 常 才 覆 盖 甲状 状腺 腺及 及其 其周 周围 围结 结构 构通 通常 常需 要多 查才 才能 能覆 覆盖 止 不同 同扫 查的 的起 起止 止位 位置 入 射 角 入射 射角 接 触 态 力和 和接 接触 触状 状态 态不 会 带 短 外部 部定 定位 位系 统还 还会 会带 带入 入同 差或 或短 短时 时遮 简 两 幅 刚 性 齐 准因 此不 能简 简化 化为 为两 两幅 幅图 像刚 刚性 性对 对齐 而 被 观 测 而应 应被 被视 视为 为观 观测 维 表 征 联 合 估 迹和 和三 三维 维表 表征 征在 在规 间中 的联 联合 合估 估计', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'efd8f932e7d8bf0d64e7b0cc956552552ccb198b11d0e7dd8dd7fbdbd06e173e') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1b5b026cba45fd11', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '，甲状腺及其周围结构通常需要多次扫查才能覆盖；不同扫查的起止位置、入射角、探头压力和接触状态不同，外部定位系统还会带入同步误差或短时遮挡。超声扫查序列配准因此不能简化为两幅图像刚性对齐，而应被视为观测、轨迹和三维表征在规范空间中的联合估计。
医学图像配准领域已经形成了从强度相似性、局部特征、传统优化到学习式配准的技术脉络。CT-US 自动配准、实时 slice-to-volume 配准、标签驱动弱监督 MRI-TRUS 配准以及沿轨迹的 2D/3D 深度配准等研究说明，介入超声配准正在从单次图像对齐转向连续导航过程中的空间一致性维护[92–96]。ANTs/SyN 和 VoxelMorph 分别代表了经典可微变形配准与学习式密集形变配准的重要路线，提示医学配准评价不能只看局部相似度，还要关注变换正则性、模板偏置和跨病例泛化[97,98]。这些工作提供了医学配准问题背景，但跨模态术前影像融合与同一对象多次自由手超声扫查之间的空间统一仍属于不同任务形态。
按任务形态划分，超声配准主要包括术前CT/MRI与术中超声的跨模态配准、2D/3D切片到体数据配准，以及同一对象多次自由手扫查之间的同模态配准。前两类通常依赖互信息、解剖标签、器官边界或三维先验体；超声扫查序列配准则要求多条不规则扫查轨迹在共同三维表示中相互解释。其任务是在初始标定存在残余误差时建立规范空间，而非在既有三维先验体中定位单张切片。', 'ct-us slice-to-volume mri-trus 2d 3d 92 96 ants syn voxelmorph 97 98 ct mri 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 甲 腺 其 周 围 结 构 通 常 需 要 多 次 才 能 覆 盖 甲状 状腺 腺及 及其 其周 周围 围结 结构 构通 通常 常需 需要 要多 多次 次扫 查才 才能 能覆 覆盖 不 同 起 止 位 置 不同 同扫 查的 的起 起止 止位 位置 入 射 角 入射 射角 探 头 压 力 接 触 态 探头 头压 压力 力和 和接 接触 触状 状态 态不 部 系 统 还 会 带 步 误 差 或 短 时 遮 挡 外部 部定 定位 位系 系统 统还 还会 会带 带入 入同 同步 步误 误差 差或 或短 短时 时遮 遮挡 因 此 简 化 两 幅 图 像 刚 性 对 齐 准因 因此 此不 不能 能简 简化 化为 为两 两幅 幅图 图像 像刚 刚性 性对 对齐 而 应 被 视 观 测 而应 应被 被视 视为 为观 观测 轨 迹 三 维 表 征 联 合 估 计 轨迹 迹和 和三 三维 维表 表征 征在 在规 间中 中的 的联 联合 合估 估计 医 学 领 域 已 经 形 成 从 强 度 相 似 医学 学图 像配 准领 领域 域已 已经 经形 形成 成了 了从 从强 强度 度相 相似 似性 局 特 局部 部特 特征 传 优 到 习 式 技 术 脉 络 传统 统优 优化 化到 到学 学习 习式 式配 准的 的技 技术 术脉 脉络 自 动 自动 动配 实 实时 签 驱 弱 监 督 标签 签驱 驱动 动弱 弱监 监督 以 沿 准以 以及 及沿 沿轨 迹的 深 等 说 明 深度 度配 准等 等研 究说 说明 介 正 单 转 向 连 续 导 航 过 程 一 致 护 介入 入超 声配 准正 正在 在从 从单 单次 次图 像对 齐转 转向 向连 连续 续导 导航 航过 过程 程中 的空 间一 一致 致性 性维 维护 分 别 代 典 可 微 变 密 集 重 路 线 分别 别代 代表 表了 了经 经典 典可 可微 微变 变形 形配 与学 式密 密集 集形 形变 变配 的重 重要 要路 路线 提 示 评 价 只 看 提示 示医 学配 准评 评价 价不 能只 只看 看局 部相 似度 关 注 换 则 还要 要关 关注 注变 变换 换正 正则 则性 模 板 偏 跨 病 例 泛 模板 板偏 偏置 置和 和跨 跨病 病例 例泛 泛化 这 些 工 作 供 问 题 背 景 这些 些工 工作 作提 提供 供了 了医 准问 问题 题背 背景 但 前 影 融 象 由 手 之 仍 属 于 任 务 但跨 跨模 模态 态术 术前 前影 影像 像融 融合 合与 与同 同一 一对 对象 象多 次自 自由 由手 手超 查之 之间 间的 间统 统一 一仍 仍属 属于 于不 同任 任务 务形 形态 按 划 按任 态划 划分 主 包 括 准主 主要 要包 包括 括术 与术 术中 中超 声的 的跨 态配 切 片 体 数 据 切片 片到 到体 体数 数据 据配 及同 手扫 的同 同模 类 依 赖 互 信 息 前两 两类 类通 常依 依赖 赖互 互信 信息 解 剖 解剖 剖标 器 官 边 界 先 验 器官 官边 边界 界或 或三 维先 先验 验体 求 条 共 释 准则 则要 要求 求多 多条 条不 不规 规则 则扫 查轨 迹在 在共 共同 同三 表示 示中 中相 相互 互解 解释 初 始 存 残 余 建 立 其任 务是 是在 在初 初始 始标 定存 存在 在残 残余 余误 差时 时建 建立 立规 非 既 有 张 而非 非在 在既 既有 有三 体中 中定 位单 单张 张切', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1b5b026cba45fd11d727f2e17a6d91ba2edd58969a6334d066b1665da66bd819') ON CONFLICT(`id`) 