INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ef758cfd08d1f33a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '一对象多次自由手扫查之间的同模态配准。前两类通常依赖互信息、解剖标签、器官边界或三维先验体；超声扫查序列配准则要求多条不规则扫查轨迹在共同三维表示中相互解释。其任务是在初始标定存在残余误差时建立规范空间，而非在既有三维先验体中定位单张切片。
多组超声扫查序列通常具有两个层次的位姿误差：不同扫查之间存在整体刚性偏差，单次扫查内部还存在逐帧局部高频抖动。图 1.6所示的规范空间映射体现了这一类问题的基本形式：每一帧二维图像先通过修正后的位姿映射到共同空间，再由同一个连续三维神经场解释其观测。配准目标由局部图像相似度最大化扩展为多组超声扫查序列在同一三维场中的共同可解释性。
图 .6 多组超声扫查序列中的位姿修正与规范空间映射示意
Figure . Pose correction and canonical-coordinate mapping for multi-sweep ultrasound registration.
神经场位姿优化研究为这一思路提供了直接参照。BARF、RPE-BARF、CorresNeRF 和 TrackNeRF 等工作表明，在视角稀疏或位姿带噪时，将位姿修正和场表示学习放入同一可微目标，通常比固定外参后单独训练场更稳健。其思想接近结构光束平差：三维场不被动接受错误位姿，而是通过多视角一致残差反向约束位姿。区别在于，超声没有稳定光学纹理，也没有真正的透视投影，因此不能直接照搬光学 NeRF 的位姿优化假设。[8,99–101]', '1.6 figure pose correction and canonical-coordinate mapping for multi-sweep ultrasound registration. barf rpe-barf corresnerf tracknerf nerf 99 101 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 一 对 象 多 次 自 由 手 之 同 模 态 一对 对象 象多 多次 次自 自由 由手 手扫 查之 之间 间的 的同 同模 模态 态配 前 两 类 通 常 依 赖 互 信 息 前两 两类 类通 通常 常依 依赖 赖互 互信 信息 解 剖 签 解剖 剖标 标签 器 官 边 界 或 三 维 先 验 体 器官 官边 边界 界或 或三 三维 维先 先验 验体 则 要 求 条 不 轨 迹 共 表 示 相 释 准则 则要 要求 求多 多条 条不 不规 规则 则扫 查轨 轨迹 迹在 在共 共同 同三 维表 表示 示中 中相 相互 互解 解释 其 任 务 初 始 存 残 余 误 差 时 建 立 其任 任务 务是 是在 在初 初始 始标 定存 存在 在残 残余 余误 误差 差时 时建 建立 立规 而 非 既 有 位 单 张 切 片 而非 非在 在既 既有 有三 体中 中定 定位 位单 单张 张切 切片 组 具 个 层 姿 多组 组超 列通 常具 具有 有两 两个 个层 层次 次的 的位 位姿 姿误 整 刚 性 偏 不同 同扫 间存 在整 整体 体刚 刚性 性偏 偏差 部 还 逐 帧 局 高 频 抖 动 单次 次扫 查内 内部 部还 还存 在逐 逐帧 帧局 局部 部高 高频 频抖 抖动 图 所 映 射 这 问 题 基 本 形 式 所示 示的 的规 间映 映射 射体 体现 现了 了这 这一 一类 类问 问题 题的 的基 基本 本形 形式 每 二 像 过 修 正 后 到 每一 一帧 帧二 二维 维图 图像 像先 先通 通过 过修 修正 正后 后的 姿映 射到 到共 同空 再 连 续 神 经 场 观 测 再由 由同 同一 一个 个连 连续 续三 维神 神经 经场 场解 释其 其观 观测 目 似 度 最 大 化 扩 展 可 准目 目标 标由 由局 部图 像相 相似 似度 度最 最大 大化 化扩 扩展 展为 为多 列在 在同 一三 维场 场中 中的 的共 同可 可解 释性 意 列中 姿修 正与 射示 示意 优 思 路 提 供 直 接 参 照 场位 姿优 优化 化研 究为 为这 一思 思路 路提 提供 供了 了直 直接 接参 参照 等 工 作 明 等工 工作 作表 表明 视 角 稀 疏 带 噪 在视 视角 角稀 稀疏 疏或 或位 姿带 带噪 噪时 将 学 习 放 入 微 将位 正和 和场 场表 示学 学习 习放 放入 入同 一可 可微 微目 比 固 独 训 练 更 稳 健 常比 比固 固定 定外 外参 参后 后单 单独 独训 训练 练场 场更 更稳 稳健 想 近 结 构 光 平 其思 思想 想接 接近 近结 结构 构光 光束 束平 平差 被 受 错 场不 不被 被动 动接 接受 受错 错误 误位 致 反 向 而是 是通 过多 多视 角一 一致 致残 残差 差反 反向 向约 束位 区 别 于 区别 别在 在于 没 纹 理 声没 没有 有稳 稳定 定光 光学 学纹 纹理 也 真 透 投 影 也没 有真 真正 正的 的透 透视 视投 投影 因 此 能 搬 因此 此不 不能 能直 接照 照搬 搬光 假 设 化假 假设', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ef758cfd08d1f33a84246c2da85699d3dee92e2fc52d5dde597ee37ad180fbe7') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`,