INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2ed330f9ebceb8da', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '常比固定外参后单独训练场更稳健。其思想接近结构光束平差：三维场不被动接受错误位姿，而是通过多视角一致残差反向约束位姿。区别在于，超声没有稳定光学纹理，也没有真正的透视投影，因此不能直接照搬光学 NeRF 的位姿优化假设。[8,99–101]
这些方法的限制对自由手超声同样重要。BARF 类方法多依赖光学图像的外观一致性、可追踪纹理或可靠对应关系；自由手超声中的散斑、声影、出平面运动和接触变化会削弱这些假设。因此，超声位姿优化不宜被简单写成光度一致性损失 下的外参微调，而需要结合外观检索、几何内点验证、不确定性加权和轨迹连续性等多种证据。
图像检索和局部跟踪研究为超声扫查序列配准的前端证据提供了支撑。医学图像中的全局检索常用于为配准提供初值，超声标准切面导航以及 USPoint、PIPsUS 等自监督点跟踪工作说明，在散斑和低纹理条件下仍然能够提取一定运动线索[102,103]。但图像检索容易受到相似切面和伪重复纹理干扰，局部点跟踪也会在弱纹理、声影或接触变化时漂移。因此，这类证据更适合作为候选生成和置信度估计，而不应直接决定最终位姿。
Sarlin 等提出的 From Coarse to Fine 将定位组织为“全局检索—局部匹配—PnP/RANSAC 几何验证”的层次化流程[104]，如图 1.7所示。HF-Net 通过共享编码器同时输出全局描述子、局部关键点和局部描述子，使粗检索与精匹配共享计算。该框架说明，外观相似性只应缩小候选空间，位姿约束仍需来自几何验证后的局部对应。', 'nerf 99 101 barf uspoint pipsus 102 103 sarlin from coarse to fine pnp ransac 104 1.7 hf-net 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 常 比 固 参 后 单 独 训 练 场 更 稳 健 常比 比固 固定 定外 外参 参后 后单 单独 独训 训练 练场 场更 更稳 稳健 其 思 想 接 近 结 构 光 平 差 其思 思想 想接 接近 近结 结构 构光 光束 束平 平差 三 维 不 被 动 受 错 误 位 姿 三维 维场 场不 不被 被动 动接 接受 受错 错误 误位 位姿 而 通 过 多 视 角 一 致 残 反 向 而是 是通 通过 过多 多视 视角 角一 一致 致残 残差 差反 反向 向约 束位 区 别 于 区别 别在 在于 没 有 学 纹 理 声没 没有 有稳 稳定 定光 光学 学纹 纹理 也 真 正 透 投 影 也没 有真 真正 正的 的透 透视 视投 投影 因 此 能 直 照 搬 因此 此不 不能 能直 直接 接照 照搬 搬光 优 化 假 设 的位 姿优 优化 化假 假设 这 些 方 法 限 制 对 自 由 手 同 样 重 要 这些 些方 方法 法的 的限 限制 制对 对自 自由 由手 手超 声同 同样 样重 重要 类 依 赖 图 像 观 性 类方 法多 多依 依赖 赖光 学图 图像 像的 的外 外观 观一 致性 可 追 踪 或 靠 应 关 系 可追 追踪 踪纹 理或 或可 可靠 靠对 对应 应关 关系 散 斑 声中 中的 的散 散斑 声影 出 面 运 触 变 会 削 弱 出平 平面 面运 运动 动和 和接 接触 触变 变化 化会 会削 削弱 弱这 些假 宜 简 写 成 度 损 失 声位 化不 不宜 宜被 被简 简单 单写 写成 成光 光度 度一 性损 损失 微 调 参微 微调 需 合 检 索 而需 需要 要结 结合 合外 观检 检索 几 何 点 验 证 几何 何内 内点 点验 验证 确 加 权 轨 迹 连 续 等 种 据 不确 确定 定性 性加 加权 权和 和轨 轨迹 迹连 连续 续性 性等 等多 多种 种证 证据 局 部 跟 前 端 提 供 支 撑 像检 索和 和局 局部 部跟 跟踪 踪研 究为 为超 准的 的前 前端 端证 据提 提供 供了 了支 支撑 医 全 用 初 值 医学 像中 的全 全局 局检 索常 常用 用于 于为 为配 准提 供初 初值 切 导 航 以 声标 标准 准切 切面 面导 导航 航以 以及 监 督 工 作 说 明 等自 自监 监督 督点 点跟 踪工 工作 作说 说明 低 条 件 仍 然 够 取 线 在散 斑和 和低 低纹 理条 条件 件下 下仍 仍然 然能 能够 够提 提取 取一 一定 定运 动线 线索 但 容 易 到 相 似 伪 复 干 扰 但图 索容 容易 易受 受到 到相 相似 似切 面和 和伪 伪重 重复 复纹 理干 干扰 部点 踪也 也会 会在 在弱 弱纹 时 漂 移 影或 或接 化时 时漂 漂移 适 候 选 生 置 信 估 计 这类 类证 据更 更适 适合 合作 作为 为候 候选 选生 生成 成和 和置 置信 信度 度估 估计 决 最 终 而不 不应 应直 接决 决定 定最 最终 终位 等提 提出 出的 将 组 织 将定 定位 位组 组织 织为 匹 部匹 匹配 何验 层 次 流 程 的层 层次 次化 化流 流程 如 如图 所 示 所示 共 享 编 码 器 输 描 述 子 过共 共享 享编 编码 码器 器同 同时 时输 输出 出全 局描 描述 述子 键 部关 关键 键点 点和 部描 使 粗 精 算 使粗 粗检 索与 与精 精匹 配共 享计 计算 该 框 架 该框 框架 架说 只 缩 小 观相 似性 性只 只应 应缩 缩小 小候 选空 来 姿约 束仍 仍需 需来 来自 自几 证后 后的 的局 部对', '/#research', 'doctoral-thesis', 1, '2026-08-04', '2ed330f