INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b5a228de26576261', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', 'ANSAC 几何验证”的层次化流程[104]，如图 1.7所示。HF-Net 通过共享编码器同时输出全局描述子、局部关键点和局部描述子，使粗检索与精匹配共享计算。该框架说明，外观相似性只应缩小候选空间，位姿约束仍需来自几何验证后的局部对应。
图 .7 HF-Net 由粗到细的层次化定位流程[104]
Figure . HF-Net hierarchical localization pipeline in From Coarse to Fine. [104]
在图像索引方面，NetVLAD 将传统 VLAD 聚合改造成可端到端训练的 CNN 全局描述子[105]，Patch-NetVLAD 进一步结合局部和全局描述以提高视角变化下的检索稳健性[106]。超声扫查引导中的 landmark retrieval 和 Transformer-VLAD 将类似思想迁移到医学场景[107]。这些全局描述子适合快速召回可能重叠的图像，但同一器官中的相似切面、重复纹理和局部声影也可能产生高相似度伪候选。
在局部匹配方面，SuperGlue、LoFTR 和 LightGlue 代表了深度特征匹配的不同路线[108–110]。它们延续了“候选召回后再做局部对应和几何验证”的证据组织方式，但超声图像并不满足自然图像中稳定角点和纹理描述子的假设，散斑还会随探头角度、压力和声束方向改变。因此，局部匹配结果必须经过适合三维几何关系的验证和加权，才能进入超声扫查序列位姿优化。', 'ansac 104 1.7 hf-net figure hierarchical localization pipeline in from coarse to fine. netvlad vlad cnn 105 patch-netvlad 106 landmark retrieval transformer-vlad 107 superglue loftr lightglue 108 110 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 几 何 验 证 几何 何验 验证 层 次 化 流 程 的层 层次 次化 化流 流程 如 图 如图 所 示 所示 通 过 共 享 编 码 器 同 时 输 出 全 局 描 述 子 通过 过共 共享 享编 编码 码器 器同 同时 时输 输出 出全 全局 局描 描述 述子 部 关 键 点 局部 部关 关键 键点 点和 和局 部描 使 粗 检 索 精 匹 计 算 使粗 粗检 检索 索与 与精 精匹 匹配 配共 享计 计算 该 框 架 说 明 该框 框架 架说 说明 观 相 似 性 只 应 缩 小 候 选 外观 观相 相似 似性 性只 只应 应缩 缩小 小候 候选 选空 位 姿 仍 需 来 自 后 对 位姿 姿约 束仍 仍需 需来 来自 自几 证后 后的 的局 部对 对应 由 到 细 由粗 粗到 到细 细的 化定 定位 位流 像 引 方 面 在图 图像 像索 索引 引方 方面 将 传 统 将传 传统 聚 合 改 造 成 可 端 训 练 聚合 合改 改造 造成 成可 可端 端到 到端 端训 训练 练的 进 一 步 结 以 提 高 视 角 变 稳 健 进一 一步 步结 结合 合局 部和 和全 述以 以提 提高 高视 视角 角变 变化 化下 的检 索稳 稳健 健性 导 查引 引导 导中 中的 类 思 想 迁 移 医 学 场 景 将类 类似 似思 思想 想迁 迁移 移到 到医 医学 学场 场景 这 些 适 快 速 召 回 能 重 叠 这些 些全 子适 适合 合快 快速 速召 召回 回可 可能 能重 重叠 叠的 的图 但 官 切 但同 同一 一器 器官 官中 的相 似切 切面 复 纹 理 影 也 产 生 度 伪 重复 复纹 纹理 理和 部声 声影 影也 也可 能产 产生 生高 高相 似度 度伪 伪候 在局 部匹 配方 代 表 深 特 征 不 路 线 代表 表了 了深 深度 度特 特征 征匹 配的 的不 不同 同路 路线 它 们 延 续 它们 们延 延续 续了 再 做 选召 回后 后再 再做 做局 应和 和几 据 组 织 式 的证 证据 据组 组织 织方 方式 并 满 足 然 假 设 但超 声图 像并 并不 不满 满足 足自 自然 然图 像中 中稳 稳定 定角 角点 和纹 理描 子的 的假 假设 散 斑 还 会 随 探 头 散斑 斑还 还会 会随 随探 探头 头角 角度 压 力 向 压力 力和 和声 声束 束方 方向 向改 改变 因 此 因此 果 必 须 经 三 维 系 加 权 配结 结果 果必 必须 须经 经过 过适 合三 三维 维几 何关 关系 系的 的验 证和 和加 加权 才 入 优 才能 能进 进入 入超 列位 姿优 优化', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b5a228de26576261e11d4baf9acc91bd88c20bb8b6e32a0c2aeaed0a112328b4') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `eviden