INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0fa7eae03fa1faeb', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '延续了“候选召回后再做局部对应和几何验证”的证据组织方式，但超声图像并不满足自然图像中稳定角点和纹理描述子的假设，散斑还会随探头角度、压力和声束方向改变。因此，局部匹配结果必须经过适合三维几何关系的验证和加权，才能进入超声扫查序列位姿优化。
匹配后的外点剔除需要几何验证。RANSAC 及其改进方法从随机采样、局部优化、鲁棒估计和高外点率场景下的模型筛选等角度提高几何估计稳定性[111–114]。这些方法提供的核心原则是：图像相似性只能生成候选，对应关系必须经几何内点筛选后才能约束规范空间，否则相似切面和伪重复纹理会把配准拉向错误位置。
宽基线图像匹配基准还提示，匹配算法的评价不能只看特征数量或表观匹配分数，而要看最终相机位姿或几何模型是否正确[115,116]。这一思想可迁移到多组超声扫查序列：两帧图像相似，并不意味着它们在三维组织中对应同一切面；局部散斑或腺体纹理相似，也未必能够约束全局规范空间。因此，外观检索、几何验证和不确定性估计需要共同工作。
综上，粗到细定位、图像检索、局部匹配和 RANSAC 类几何验证形成了从外观相似到几何一致的证据链。其不足在于，这些方法多建立在自然图像或刚性多视角几何假设上，面对超声散斑、相似切面和接触变化时容易产生高置信伪匹配。因此，超声扫查序列配准需要把候选生成视为前端证据，而把最终位姿约束交给三维几何、轨迹连续性和不确定性加权共同决定。', 'ransac 111 114 115 116 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 延 续 延续 续了 候 选 召 回 后 再 做 局 部 对 应 几 何 验 证 候选 选召 召回 回后 后再 再做 做局 局部 部对 对应 应和 和几 几何 何验 验证 据 组 织 方 式 的证 证据 据组 组织 织方 方式 但 图 像 并 不 满 足 自 然 稳 角 点 纹 理 描 述 子 假 设 但超 声图 图像 像并 并不 不满 满足 足自 自然 然图 像中 中稳 稳定 定角 角点 点和 和纹 纹理 理描 描述 述子 子的 的假 假设 散 斑 还 会 随 探 头 度 散斑 斑还 还会 会随 随探 探头 头角 角度 压 力 向 改 变 压力 力和 和声 声束 束方 方向 向改 改变 因 此 因此 匹 结 果 必 须 经 过 适 合 三 维 关 系 加 权 部匹 匹配 配结 结果 果必 必须 须经 经过 过适 适合 合三 三维 维几 何关 关系 系的 的验 证和 和加 加权 才 能 进 入 位 姿 优 化 才能 能进 进入 入超 列位 位姿 姿优 优化 剔 除 需 要 配后 后的 的外 外点 点剔 剔除 除需 需要 要几 其 法 从 机 采 样 及其 其改 改进 进方 方法 法从 从随 随机 机采 采样 部优 鲁 棒 估 计 高 率 场 景 模 型 筛 等 提 性 鲁棒 棒估 估计 计和 和高 高外 点率 率场 场景 景下 的模 模型 型筛 筛选 选等 等角 度提 提高 高几 何估 计稳 定性 这 些 供 核 心 原 则 这些 些方 法提 提供 供的 的核 核心 心原 原则 则是 相 似 只 生 成 像相 相似 似性 性只 只能 能生 生成 成候 应关 系必 经几 何内 内点 点筛 选后 后才 能约 束规 否 切 面 伪 重 复 把 拉 错 误 置 否则 则相 似切 切面 面和 和伪 伪重 重复 复纹 理会 会把 把配 准拉 拉向 向错 错误 误位 位置 宽 基 线 示 宽基 基线 线图 像匹 配基 基准 准还 还提 提示 算 评 价 看 特 征 数 量 或 表 观 分 配算 算法 法的 的评 评价 价不 不能 能只 只看 看特 特征 征数 数量 量或 或表 表观 观匹 配分 分数 而 最 终 正 确 而要 要看 看最 最终 终相 相机 机位 姿或 或几 何模 型是 是否 否正 正确 一 思 想 可 迁 移 到 多 这一 一思 思想 想可 可迁 迁移 移到 到多 多组 组超 两 帧 两帧 帧图 意 味 着 它 们 同 不意 意味 味着 着它 它们 们在 在三 维组 织中 中对 应同 同一 一切 腺 体 部散 斑或 或腺 腺体 体纹 理相 也 未 够 全 也未 未必 必能 能够 够约 束全 全局 局规 检 索 外观 观检 检索 共 工 作 和不 不确 确定 性估 计需 要共 共同 同工 工作 综 上 综上 粗 细 粗到 到细 细定 定位 像检 配和 类 形 致 链 类几 证形 形成 成了 了从 从外 观相 似到 到几 何一 一致 致的 据链 于 其不 不足 足在 在于 建 立 刚 视 法多 多建 建立 立在 在自 像或 或刚 刚性 性多 多视 视角 角几 何假 设上 面对 对超 声散 接 触 时 容 易 产 信 和接 接触 触变 变化 化时 时容 容易 易产 产生 生高 高置 置信 信伪 伪匹 前 端 准需 要把 把候 选生 成视 视为 为前 前端 端证 交 给 而把 把最 终位 姿约 束交 交给 给三 轨 迹 连 决 轨迹 迹连 连续 续性 性和 性加 权共 同决 决定', '/#research', 'doctoral-thesis', 1, '2026-08-04', '0fa7eae03fa1faebdab128447403a0541a52efadf5ea0c86b00faa5e0bda4c5e') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-47b53faf26ce4f77', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '的证据链。其不足在于，这些方法多建立在自然图像或刚性多视角几何假设上，面对超声散斑、相似切面和接触变化时容易产生高置信伪匹配。因此，超声扫查序列配准需要把候选生成视为前端证据，而把最终位姿约束交给三维几何、轨迹连续性和不确定性加权共同决定。
连续时间轨迹建模和多图像联合优化研究进一步说明，位姿修正不能只依赖离散帧之间的局部残差。GroupRegNet 等方法用共享参数化模板把多时相医学图像共同配准到无偏空间，避免选择单一参考图像带来的偏置和误差累积[117]；NeRF-SLAM 以及带轨迹平滑约束的 NeRF-SLAM 优化研究将位姿、深度、不确定性和轨迹连续性输入神经辐射场，使地图和轨迹相互约束[118,119]；Lie群上的累积 B样条则为连续位姿轨迹提供了可微、可求导且适合刚体运动链的运动表示[120]。这些研究共同提示，超声扫查序列配准应同时考虑扫查间整体一致性和单次扫查内连续运动规律。
综上，超声扫查序列配准研究已经从单次图像对齐，发展到标定链路、外观检索、局部匹配、几何内点验证、神经场位姿优化和连续轨迹建模共同参与的多证据问题。其核心困难在于，超声图像缺少稳定光学纹理，相似切面和重复散斑容易产生伪对应，外部定位又会带来扫查间系统偏差和单次扫查内的帧级抖动。因此，超声扫查序列配准需要把外观证据、几何验证、不确定性估计和连续运动先验组织到规范空间中，而不能仅依赖局部图像相似性或初始跟踪位姿。', 'groupregnet 117 nerf-slam 118 119 lie 120 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 证 据 链 的证 证据 据链 其 不 足 于 其不 不足 足在 在于 这 些 方 法 多 建 立 自 然 图 像 或 刚 性 视 角 几 何 假 设 上 这些 些方 方法 法多 多建 建立 立在 在自 自然 然图 图像 像或 或刚 刚性 性多 多视 视角 角几 几何 何假 假设 设上 面 对 散 斑 面对 对超 声散 散斑 相 似 切 接 触 变 化 时 容 易 产 生 高 置 信 伪 匹 相似 似切 切面 面和 和接 接触 触变 变化 化时 时容 容易 易产 产生 生高 高置 置信 信伪 伪匹 匹配 因 此 因此 需 要 把 候 选 成 前 端 准需 需要 要把 把候 候选 选生 生成 成视 视为 为前 前端 端证 而 最 终 位 姿 交 给 三 维 而把 把最 最终 终位 位姿 姿约 束交 交给 给三 三维 维几 轨 迹 连 续 确 加 权 共 同 决 轨迹 迹连 连续 续性 性和 和不 不确 确定 定性 性加 加权 权共 共同 同决 决定 模 联 合 优 进 一 步 说 明 续时 时间 间轨 迹建 建模 模和 和多 多图 像联 联合 合优 优化 化研 究进 进一 一步 步说 说明 修 正 能 只 依 赖 离 帧 之 局 部 残 差 姿修 修正 正不 不能 能只 只依 依赖 赖离 离散 散帧 帧之 之间 间的 的局 局部 部残 残差 等 用 享 参 数 板 医 学 到 无 偏 等方 法用 用共 共享 享参 参数 数化 化模 模板 板把 把多 多时 时相 相医 医学 学图 像共 同配 准到 到无 无偏 偏空 避 免 择 单 考 带 来 误 累 积 避免 免选 选择 择单 单一 一参 参考 考图 像带 带来 来的 的偏 偏置 置和 和误 误差 差累 累积 以 平 滑 以及 及带 带轨 迹平 平滑 滑约 束的 将 究将 将位 深 度 深度 输 入 神 经 辐 射 场 和轨 性输 输入 入神 神经 经辐 辐射 射场 使 地 互 使地 地图 图和 迹相 相互 互约 群 群上 上的 的累 样 条 则 提 供 可 微 样条 条则 则为 为连 续位 姿轨 迹提 提供 供了 了可 可微 求 导 且 适 体 运 动 表 示 可求 求导 导且 且适 适合 合刚 刚体 体运 运动 动链 链的 的运 动表 表示 些研 究共 同提 提示 应 虑 整 致 次 律 准应 应同 同时 时考 考虑 虑扫 查间 间整 整体 体一 一致 致性 和单 单次 次扫 查内 内连 续运 动规 规律 综 综上 已 从 齐 准研 究已 已经 经从 从单 次图 像对 对齐 发 展 路 发展 展到 到标 定链 链路 观 检 索 外观 观检 检索 部匹 点 验 何内 内点 点验 验证 问 题 经场 场位 姿优 化和 和连 续轨 模共 同参 参与 与的 的多 多证 据问 问题 核 心 困 难 其核 核心 心困 困难 难在 缺 少 稳 光 纹 理 声图 像缺 缺少 少稳 稳定 定光 光学 学纹 纹理 重 复 和重 重复 复散 斑容 生伪 伪对 对应 又 会 系 统 级 抖 外部 部定 定位 位又 又会 会带 来扫 间系 系统 统偏 偏差 差和 内的 的帧 帧级 级抖 抖动 把外 观证 何验 估 计 先 组 织 性估 估计 计和 动先 先验 验组 组织 织到 到规 间中 仅 初 始 跟 踪 而不 能仅 仅依 赖局 部图 像相 似性 性或 或初 初始 始跟 跟踪 踪位', '/#research', 'doctoral-thesis', 1, '2026-08-04', '47b53faf26ce4f77a4eb5eb3b7ab9a6e7d96512c904c7dccb1889092ff5d6f46') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `s