INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4e92ca567d81e1c4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 空间标定约束下的超声扫查序列配准与规范空间研究现状', '缺少稳定光学纹理，相似切面和重复散斑容易产生伪对应，外部定位又会带来扫查间系统偏差和单次扫查内的帧级抖动。因此，超声扫查序列配准需要把外观证据、几何验证、不确定性估计和连续运动先验组织到规范空间中，而不能仅依赖局部图像相似性或初始跟踪位姿。
基于上述困难，本文在空间标定提供初始几何链路的基础上，面向颈部自由手超声的多组超声扫查序列开展规范空间构建研究，使整体扫查偏差和局部轨迹噪声能够在同一三维表示中被约束和评估。[121]', '121 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 空 间 标 定 约 束 下 超 声 扫 查 序 列 配 准 规 范 空间 间标 标定 定约 约束 束下 下的 的超 超声 声扫 扫查 查序 序列 列配 配准 准与 与规 规范 范空 间研 缺 少 稳 光 学 纹 理 缺少 少稳 稳定 定光 光学 学纹 纹理 相 似 切 面 重 复 散 斑 容 易 产 生 伪 对 应 相似 似切 切面 面和 和重 重复 复散 散斑 斑容 容易 易产 产生 生伪 伪对 对应 部 位 又 会 带 来 系 统 偏 差 单 次 帧 级 抖 动 外部 部定 定位 位又 又会 会带 带来 来扫 查间 间系 系统 统偏 偏差 差和 和单 单次 次扫 查内 内的 的帧 帧级 级抖 抖动 因 此 因此 需 要 把 观 证 据 准需 需要 要把 把外 外观 观证 证据 几 何 验 几何 何验 验证 不 确 性 估 计 连 续 运 先 组 织 到 不确 确定 定性 性估 估计 计和 和连 连续 续运 运动 动先 先验 验组 组织 织到 到规 间中 而 能 仅 依 赖 局 图 像 或 初 始 跟 踪 姿 而不 不能 能仅 仅依 依赖 赖局 局部 部图 图像 像相 似性 性或 或初 初始 始跟 跟踪 踪位 位姿 基 于 上 述 困 难 基于 于上 上述 述困 困难 本 文 提 供 链 路 础 本文 文在 在空 定提 提供 供初 始几 何链 链路 路的 的基 基础 础上 向 颈 自 由 手 多 开 展 构 建 面向 向颈 颈部 部自 自由 由手 手超 声的 的多 多组 组超 列开 开展 展规 间构 构建 建研 使 整 体 轨 迹 噪 够 同 一 三 维 表 示 被 评 使整 整体 体扫 查偏 和局 部轨 轨迹 迹噪 噪声 声能 能够 够在 在同 同一 一三 三维 维表 表示 示中 中被 被约 束和 和评 评估', '/#research', 'doctoral-thesis', 1, '2026-08-04', '4e92ca567d81e1c42619f7e73496d390fb2b3ad477af5a2fef494a62e712c7ba') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6477c7abcab1d3ce', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向导航的二维超声语义理解与多任务概率观测研究现状', '三维重建和超声扫查序列配准建立统一空间后，导航系统还需要回答临床任务问题：甲状腺、结节、风险结构、针体和针尖分别在哪里，它们之间的空间关系是否满足安全穿刺要求。二维超声语义理解是这一问题的局部观测入口。U-Net、U-Net++、Attention U-Net 和 DeepLabV3+ 等通用网络推动了医学图像像素级分割[122–127]，但甲状腺超声存在低对比度、散斑、声影、边界模糊和甲状腺外相似纹理，通用网络容易产生结构性误检。
从通用语义分割的发展看，FCN 将分类网络改造为端到端像素预测框架，U-Net 通过编码器—解码器和跳跃连接适配小样本医学图像，UNet++ 通过嵌套跳连缩小编码器和解码器之间的语义差距，Attention U-Net、CBAM、DANet 等注意力机制则增强目标区域和长程依赖建模，DeepLabV3+ 和 nnU-Net 又分别代表了空洞卷积多尺度上下文建模与自配置医学分割框架的发展[122–128]。这一脉络为甲状腺、结节和针体分割提供了通用方法基础，但通用结构改造不能自动解决甲状腺超声中的解剖先验、设备域偏移和针体可见性问题。', 'u-net u-net++ attention deeplabv3+ 122 127 fcn unet++ cbam danet nnu-net 128 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 二 多 任 务 概 率 观 测 的二 二维 维超 与多 多任 任务 务概 概率 率观 观测 测研 重 建 扫 查 序 列 配 准 立 统 一 空 间 后 维重 重建 建和 和超 声扫 扫查 查序 序列 列配 配准 准建 建立 立统 统一 一空 空间 间后 系 还 需 要 回 答 临 床 问 题 航系 系统 统还 还需 需要 要回 回答 答临 临床 床任 务问 问题 甲 腺 甲状 状腺 结 节 结节 风 险 构 风险 险结 结构 针 体 尖 分 别 哪 里 针体 体和 和针 针尖 尖分 分别 别在 在哪 哪里 它 们 之 关 否 满 足 安 全 穿 刺 求 它们 们之 之间 间的 的空 间关 关系 系是 是否 否满 满足 足安 安全 全穿 穿刺 刺要 要求 这 局 部 入 口 解是 是这 这一 一问 题的 的局 局部 部观 测入 入口 等 通 用 网 络 推 动 医 学 图 像 素 级 割 等通 通用 用网 网络 络推 推动 动了 了医 医学 学图 图像 像像 像素 素级 级分 分割 但 存 低 对 比 度 但甲 腺超 声存 存在 在低 低对 对比 比度 散 斑 散斑 影 声影 边 界 模 糊 相 似 纹 边界 界模 模糊 糊和 和甲 腺外 外相 相似 似纹 纹理 容 易 产 生 性 误 检 络容 容易 易产 产生 生结 构性 性误 误检 从 发 展 看 从通 用语 义分 割的 的发 发展 展看 将 类 改 造 端 到 预 框 架 将分 分类 类网 络改 改造 造为 为端 端到 到端 端像 素预 预测 测框 框架 过 编 码 器 通过 过编 编码 码器 跳 跃 连 接 适 小 样 本 解码 器和 和跳 跳跃 跃连 连接 接适 适配 配小 小样 样本 本医 嵌 套 缩 差 距 过嵌 嵌套 套跳 跳连 连缩 缩小 小编 和解 器之 的语 义差 差距 注 意 力 机 制 则 增 强 目 标 区 域 长 程 依 赖 等注 注意 意力 力机 机制 制则 则增 增强 强目 目标 标区 区域 域和 和长 长程 程依 依赖 赖建 建模 又 代 表 洞 卷 积 尺 上 下 文 自 置 又分 别代 代表 表了 了空 空洞 洞卷 卷积 积多 多尺 尺度 度上 上下 下文 文建 模与 与自 自配 配置 置医 学分 割框 架的 脉 一脉 脉络 络为 为甲 提 供 方 法 基 础 节和 体分 割提 提供 供了 了通 用方 方法 法基 基础 不 能 决 剖 先 验 但通 用结 构改 造不 不能 能自 自动 动解 解决 决甲 声中 中的 的解 解剖 剖先 先验 设 备 偏 移 可 见 设备 备域 域偏 偏移 移和 体可 可见 见性 性问', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6477c7abcab1d3ceac904f2837983e43aa2c212a19c583319789d74e7733b91c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=ex