INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-004a1a2b40171f4d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向导航的二维超声语义理解与多任务概率观测研究现状', 'V3+ 和 nnU-Net 又分别代表了空洞卷积多尺度上下文建模与自配置医学分割框架的发展[122–128]。这一脉络为甲状腺、结节和针体分割提供了通用方法基础，但通用结构改造不能自动解决甲状腺超声中的解剖先验、设备域偏移和针体可见性问题。
甲状腺超声分割研究也经历了从传统图像处理到任务先验学习的转变。早期方法依赖活动轮廓、区域生长、K-means、纹理建模和多层滤波，适合边界较清晰或规则的图像，但对低对比、声影和伪影敏感。随后 CNN、U-Net、ASPP、多尺度特征融合和迁移学习成为主流，DDTI、TN3K、TN5000 等公开数据集推动了可复现实验[129–134]，同时也暴露了跨设备、跨中心和跨标注规范的差异。TRFE 系列的价值在于将“结节应当位于甲状腺区域内”这一解剖事实转化为可学习的区域先验，而不仅是修改网络结构。
TRFE-Net 和 TRFE+ 将甲状腺结节分割从局部外观分类推进到器官区域先验约束下的多任务概率估计[135,136]。TRFE-Net 通过甲状腺区域分支增强结节分支，使网络直接感知结节的器官归属；TRFE+ 进一步引入结节尺寸、甲状腺区域和结节位置等多任务信息，并通过 Adaptive Region Prior Guidance 在通道和空间维度上调制结节特征。图 1.8 展示了 TRFE+ 的核心架构，其意义在于说明解剖先验可以进入网络内部的软特征引导，而不必退化为后处理阶段的硬规则。', 'v3+ nnu-net 122 128 k-means cnn u-net aspp ddti tn3k tn5000 129 134 trfe trfe-net trfe+ 135 136 adaptive region prior guidance 1.8 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 二 多 任 务 概 率 观 测 的二 二维 维超 与多 多任 任务 务概 概率 率观 观测 测研 又 分 别 代 表 空 洞 卷 积 尺 度 上 下 文 建 模 自 配 置 医 学 割 框 架 发 展 又分 分别 别代 代表 表了 了空 空洞 洞卷 卷积 积多 多尺 尺度 度上 上下 下文 文建 建模 模与 与自 自配 配置 置医 医学 学分 分割 割框 框架 架的 的发 发展 这 一 脉 络 甲 腺 这一 一脉 脉络 络为 为甲 甲状 状腺 结 节 针 体 提 供 通 用 方 法 基 础 结节 节和 和针 针体 体分 割提 提供 供了 了通 通用 用方 方法 法基 基础 但 构 改 造 不 能 动 决 剖 先 验 但通 用结 结构 构改 改造 造不 不能 能自 自动 动解 解决 决甲 腺超 声中 中的 的解 解剖 剖先 先验 设 备 域 偏 移 可 见 性 问 题 设备 备域 域偏 偏移 移和 体可 可见 见性 性问 问题 也 历 从 传 统 图 像 处 到 习 转 变 声分 割研 究也 也经 经历 历了 了从 从传 传统 统图 图像 像处 处理 理到 到任 务先 验学 学习 习的 的转 转变 早 期 依 赖 活 轮 廓 早期 期方 法依 依赖 赖活 活动 动轮 轮廓 区 生 长 区域 域生 生长 纹 层 滤 波 纹理 理建 模和 和多 多层 层滤 滤波 适 合 边 界 较 清 晰 或 规 则 适合 合边 边界 界较 较清 清晰 晰或 或规 规则 则的 的图 对 低 比 但对 对低 低对 对比 影 伪 敏 感 声影 影和 和伪 伪影 影敏 敏感 随 后 随后 特 征 融 迁 成 主 流 度特 特征 征融 融合 合和 和迁 迁移 移学 习成 成为 为主 主流 等 公 开 数 据 集 推 复 实 等公 公开 开数 数据 据集 集推 推动 动了 了可 可复 复现 现实 实验 同 时 暴 露 跨 同时 时也 也暴 暴露 露了 了跨 跨设 心 标 注 范 差 异 跨中 中心 心和 和跨 跨标 标注 注规 规范 范的 的差 差异 系 列 价 值 于 将 系列 列的 的价 价值 值在 在于 于将 应 当 位 节应 应当 当位 位于 于甲 腺区 域内 事 化 一解 剖事 事实 实转 转化 化为 为可 可学 的区 域先 而 仅 修 网 而不 不仅 仅是 是修 修改 改网 网络 络结 局 部 类 进 器 官 约 束 估 计 将甲 腺结 节分 割从 从局 局部 部外 外观 观分 分类 类推 推进 进到 到器 器官 官区 验约 约束 束下 下的 的多 率估 估计 过 支 增 强 通过 过甲 域分 分支 支增 增强 强结 使 直 接 知 归 属 使网 络直 直接 接感 感知 知结 节的 的器 官归 归属 步 引 入 寸 进一 一步 步引 引入 入结 节尺 尺寸 信 息 域和 和结 节位 位置 置等 等多 务信 信息 并 并通 道 间 调 制 在通 通道 道和 和空 空间 间维 维度 上调 调制 制结 节特 示 展示 示了 核 的核 核心 心架 架构 其 意 说 明 以 软 其意 意义 义在 于说 说明 明解 验可 可以 以进 进入 入网 络内 内部 部的 的软 软特 征引 引导 必 退 阶 段 硬 不必 必退 退化 为后 后处 理阶 阶段 段的 的硬 硬规', '/#research', 'doctoral-thesis', 1, '2026-08-04', '004a1a2b40171f4d7240b463a4e3f3811afc563d54b