INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-63e0ab12b4a48cdd', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向导航的二维超声语义理解与多任务概率观测研究现状', '任务信息，并通过 Adaptive Region Prior Guidance 在通道和空间维度上调制结节特征。图 1.8 展示了 TRFE+ 的核心架构，其意义在于说明解剖先验可以进入网络内部的软特征引导，而不必退化为后处理阶段的硬规则。
二维语义观测的稳定性还受到输入域差异影响。公开 B-mode 图像通常缺少 RF 数据、通道数据、完整设备参数和统一后处理记录，灰度外观会受到增益、动态范围、TGC、设备厂商后处理和导出格式影响。若直接把显示域图像作为唯一输入，网络可能同时学习组织语义和设备风格。现有输入规范化、域适应和超声基础模型研究说明，二维分割的泛化问题不能只依靠网络结构堆叠解决，还需要在输入表征、任务先验和数据域差异之间建立更稳定的联系。
图 .8 TRFE+ 中甲状腺区域先验引导的多任务分割架构[135,136]
Figure . Thyroid-region-prior-guided multi-task segmentation architecture in TRFE+. [135,136]
面向穿刺导航的二维语义观测需要同时提供甲状腺、结节、风险血管和可见针体的概率证据。任务扩展涉及多源数据集、部分标注和任务相关性的共同组织：公开甲状腺数据集多聚焦结节或腺体边界，针体和风险结构标注通常来自不同采集条件或自建数据，直接合并训练容易造成任务缺失、标签语义不一致和数据域偏移。因此，二维语义理解正在由单任务分割转向多任务概率观测，以及不完整标注条件下的任务协同。', 'adaptive region prior guidance 1.8 trfe+ b-mode rf tgc 135 136 figure thyroid-region-prior-guided multi-task segmentation architecture in trfe+. 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 二 多 任 务 概 率 观 测 的二 二维 维超 与多 多任 任务 务概 概率 率观 观测 测研 信 息 务信 信息 并 通 过 并通 通过 道 空 间 度 上 调 制 结 节 特 征 在通 通道 道和 和空 空间 间维 维度 度上 上调 调制 制结 结节 节特 特征 图 展 示 展示 示了 核 心 架 构 的核 核心 心架 架构 其 意 于 说 明 剖 先 验 可 以 进 入 网 络 部 软 引 其意 意义 义在 在于 于说 说明 明解 解剖 剖先 先验 验可 可以 以进 进入 入网 网络 络内 内部 部的 的软 软特 征引 引导 而 不 必 退 化 后 处 阶 段 硬 规 则 而不 不必 必退 退化 化为 为后 后处 处理 理阶 阶段 段的 的硬 硬规 规则 稳 定 性 还 受 到 输 域 差 异 影 响 义观 测的 的稳 稳定 定性 性还 还受 受到 到输 输入 入域 域差 差异 异影 影响 公 开 公开 像 常 缺 少 图像 像通 通常 常缺 缺少 数 据 数据 道数 完 整 设 备 参 统 一 记 录 完整 整设 设备 备参 参数 数和 和统 统一 一后 理记 记录 灰 会 增 益 灰度 度外 外观 观会 会受 到增 增益 动 态 范 围 动态 态范 范围 厂 商 出 格 式 备厂 厂商 商后 理和 和导 导出 出格 格式 式影 若 直 接 把 显 作 唯 若直 直接 接把 把显 显示 示域 域图 像作 作为 为唯 唯一 一输 能 同 时 学 习 组 织 风 络可 可能 能同 同时 时学 学习 习组 组织 织语 义和 和设 备风 风格 有 现有 有输 入规 规范 范化 适 应 基 础 模 型 域适 适应 应和 和超 声基 基础 础模 模型 型研 究说 分 割 泛 问 题 只 依 靠 堆 叠 决 维分 分割 割的 的泛 泛化 化问 问题 题不 不能 能只 只依 依靠 靠网 络结 结构 构堆 堆叠 叠解 解决 需 要 表 还需 需要 要在 在输 入表 表征 之 建 立 更 联 系 务先 验和 和数 据域 异之 之间 间建 建立 立更 更稳 定的 的联 联系 甲 腺 区 中甲 甲状 状腺 腺区 区域 域先 验引 导的 的多 务分 割架 穿 刺 提 供 向穿 穿刺 刺导 测需 要同 时提 提供 供甲 险 血 管 见 针 体 证 风险 险血 血管 管和 和可 可见 见针 针体 体的 的概 率证 证据 扩 涉 源 集 务扩 扩展 展涉 涉及 及多 多源 源数 据集 标 注 相 关 共 部分 分标 标注 注和 和任 务相 相关 关性 性的 的共 共同 同组 聚 焦 或 边 界 开甲 腺数 集多 多聚 聚焦 焦结 节或 或腺 腺体 体边 边界 来 自 采 条 件 体和 和风 险结 构标 注通 常来 来自 自不 不同 同采 采集 集条 条件 件或 或自 自建 建数 合 训 练 容 易 造 成 失 接合 合并 并训 训练 练容 容易 易造 造成 成任 务缺 缺失 签 致 偏 移 标签 签语 义不 不一 一致 致和 域偏 偏移 因 此 因此 正 由 单 转 解正 正在 在由 由单 单任 割转 转向 向多 下 协 以及 及不 不完 整标 注条 件下 下的 的任 务协 协同', '/#research', 'doctoral-thesis', 1, '2026-08-04', '63e0ab12b4a48cddaf470828be3110e2c8d850e2eee23434b575ea0ba4d6aaa1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f9d13ba3e2b3ae24', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向导航的二维超声语义理解与多任务概率观测研究现状', '同组织：公开甲状腺数据集多聚焦结节或腺体边界，针体和风险结构标注通常来自不同采集条件或自建数据，直接合并训练容易造成任务缺失、标签语义不一致和数据域偏移。因此，二维语义理解正在由单任务分割转向多任务概率观测，以及不完整标注条件下的任务协同。
同时，超声基础模型和大规模分割预训练正在改变二维语义观测的构建方式。USFM、OpenUS、UltraSam 等工作表明，跨器官预训练和开放数据汇聚可以提升超声模型的标签效率和任务迁移能力[77,79,80]；但这些模型多以二维分类、检测或分割性能为主要目标，尚不能直接给出甲状腺穿刺所需的三维空间关系。由此，二维基础模型更适合作为稳定局部表征来源，而不是完整导航系统本身。
甲状腺导航还受到临床语义约束。ACR TI-RADS、ATA指南、AACE/ACE/AME指南以及韩国和欧洲甲状腺射频消融指南均表明，结节处置取决于分割结果、结节大小、可疑声像图特征、症状、治疗目的和邻近风险结构。图像引导穿刺或消融还需考虑危险三角区、喉返神经、迷走神经、颈动脉、气管、食管和皮肤入路等空间关系。这些临床约束要求二维分割结果进一步转化为可进入三维导航空间的概率观测。
穿刺针定位研究也表明，二维图像证据本身并不充分。传统 Hough/Radon 直线检测和亮线增强依赖针体在 B-mode 中的高回声线状外观，容易受角度、阴影和组织纹理影响。深度学习方法可以预测针体掩膜或针尖热图[137,138]，但真值标注和跨场景泛化仍然困难。Hui 等使用光声图像提供针体真值[139]，如图 1.9 所示，说明可靠标签本身就是针跟踪的难点。', 'usfm openus ultrasam 77 79 80 acr ti-rads ata aace ace ame hough radon b-mode 137 138 hui 139 1.9 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 二 多 任 务 概 率 观 测 的二 二维 维超 与多 多任 任务 务概 概率 率观 观测 测研 同 组 织 同组 组织 公 开 甲 腺 数 据 集 聚 焦 结 节 或 体 边 界 公开 开甲 甲状 状腺 腺数 数据 据集 集多 多聚 聚焦 焦结 结节 节或 或腺 腺体 体边 边界 针 风 险 构 标 注 通 常 来 自 不 采 条 件 建 针体 体和 和风 风险 险结 结构 构标 标注 注通 通常 常来 来自 自不 不同 同采 采集 集条 条件 件或 或自 自建 建数 直 接 合 并 训 练 容 易 造 成 缺 失 直接 接合 合并 并训 训练 练容 容易 易造 造成 成任 务缺 缺失 签 一 致 域 偏 移 标签 签语 义不 不一 一致 致和 和数 据域 域偏 偏移 因 此 因此 正 由 单 分 割 转 解正 正在 在由 由单 单任 务分 分割 割转 转向 向多 以 完 整 下 协 以及 及不 不完 完整 整标 注条 件下 下的 的任 务协 协同 时 同时 基 础 模 型 大 规 预 改 变 方 式 声基 基础 础模 模型 型和 和大 大规 规模 模分 割预 预训 练正 在改 改变 变二 义观 测的 的构 构建 建方 方式 等 工 作 表 明 等工 工作 作表 表明 跨 器 官 放 汇 可 提 升 效 迁 能 力 跨器 器官 官预 练和 和开 开放 放数 据汇 汇聚 聚可 可以 以提 提升 升超 声模 型的 的标 签效 效率 率和 和任 务迁 迁移 移能 能力 但 这 些 类 但这 这些 些模 型多 多以 以二 维分 分类 检 性 主 要 目 检测 测或 或分 割性 性能 能为 为主 主要 要目 目标 尚 给 出 穿 刺 所 需 空 间 关 系 尚不 不能 能直 接给 给出 出甲 腺穿 穿刺 刺所 所需 需的 的三 维空 空间 间关 关系 由此 更 适 稳 定 局 部 征 源 维基 型更 更适 适合 合作 作为 为稳 稳定 定局 局部 部表 表征 征来 来源 而 统 本 身 而不 不是 是完 整导 航系 系统 统本 本身 还 受 到 临 床 约 束 腺导 航还 还受 受到 到临 临床 床语 义约 约束 指 南 指南 韩 欧 洲 射 频 消 融 均 南以 及韩 韩国 国和 和欧 欧洲 洲甲 腺射 射频 频消 消融 融指 南均 均表 处 置 取 决 于 果 节处 处置 置取 取决 决于 于分 割结 结果 小 节大 大小 疑 像 图 特 可疑 疑声 声像 像图 图特 特征 症 症状 治 疗 邻 近 治疗 疗目 目的 的和 和邻 邻近 近风 引 考 虑 危 角 区 图像 像引 引导 导穿 刺或 或消 融还 还需 需考 考虑 虑危 危险 险三 三角 角区 喉 返 喉返 返神 迷 走 迷走 走神 颈 动 脉 颈动 动脉 气 管 气管 食 皮 肤 入 路 食管 管和 和皮 皮肤 肤入 入路 路等 等空 求 进 步 化 些临 床约 束要 要求 求二 果进 进一 一步 步转 转化 化为 为可 可进 进入 入三 维导 航空 间的 的概 位 也 刺针 针定 定位 位研 究也 也表 证 充 维图 像证 证据 据本 身并 并不 不充 充分 传 传统 线 亮 增 强 依 赖 直线 线检 测和 和亮 亮线 线增 增强 强依 依赖 赖针 体在 高 回 中的 的高 高回 回声 声线 线状 状外 外观 度 易受 受角 角度 阴 影 纹 响 阴影 影和 和组 织纹 纹理 理影 影响 深 学 习 法 掩 膜 尖 热 深度 度学 学习 习方 方法 法可 以预 预测 测针 体掩 掩膜 膜或 或针 针尖 尖热 热图 真 值 景 泛 仍 然 困 难 但真 真值 值标 注和 和跨 跨场 场景 景泛 泛化 化仍 仍然 然困 困难 使 用 光 供 等使 使用 用光 光声 声图 像提 提供 供针 体真 如 如图 示 所示 说 靠 就 跟 踪 点 说明 明可 可靠 靠标 签本 身就 就是 是针 针跟 跟踪 踪的 的难 难点', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f9d13ba3e2b3ae24a092b1dc21b0a0fe790de6d5e3375bfdf3efdf65065b13ac') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-7cd92fd94e471ab4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向导航的二维超声语义理解与多任务概率观测研究现状', '的高回声线状外观，容易受角度、阴影和组织纹理影响。深度学习方法可以预测针体掩膜或针尖热图[137,138]，但真值标注和跨场景泛化仍然困难。Hui 等使用光声图像提供针体真值[139]，如图 1.9 所示，说明可靠标签本身就是针跟踪的难点。
面向导航的针体理解需要区分“看见针体”和“知道针尖位置”。二维图像中的强回声线段只代表针体与当前声束切面的可见交互；针尖可能因入射角、局部散射或遮挡而不可见。外部参考架提供的是针具整体刚体位姿，枢轴标定给出参考架到针尖的固定几何偏移，但二者都不能替代超声图像中的局部可见性证据。因此，二维语义观测研究需要与器械标定和多视角几何恢复相衔接，才能服务于后续三维导航判断。
图 .9 基于光声真值的超声针跟踪实验与标签生成示意[139]
Figure . Ultrasound needle-tracking experiment and label generation using photoacoustic ground truth. [139]
综上，面向导航的二维超声语义理解已经从通用分割网络发展到解剖先验、多任务概率观测、输入域稳定性和针体可见性建模。其主要困难在于，甲状腺、结节、风险结构和针体证据来源不同、标注完整性不同、设备域差异明显，单帧二维输出难以直接承担导航决策。因此，本文在二维端围绕规范化输入、多任务概率观测和任务先验开展相应研究，为后续三维语义场提供更稳定的局部证据。', '137 138 hui 139 1.9 figure ultrasound needle-tracking experiment and label generation using photoacoustic ground truth. 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 二 多 任 务 概 率 观 测 的二 二维 维超 与多 多任 任务 务概 概率 率观 观测 测研 高 回 线 的高 高回 回声 声线 线状 状外 外观 容 易 受 角 度 容易 易受 受角 角度 阴 影 组 织 纹 响 阴影 影和 和组 组织 织纹 纹理 理影 影响 深 学 习 方 法 可 以 预 针 体 掩 膜 或 尖 热 图 深度 度学 学习 习方 方法 法可 可以 以预 预测 测针 针体 体掩 掩膜 膜或 或针 针尖 尖热 热图 但 真 值 标 注 跨 景 泛 化 仍 然 困 难 但真 真值 值标 标注 注和 和跨 跨场 场景 景泛 泛化 化仍 仍然 然困 困难 等 使 用 光 像 提 供 等使 使用 用光 光声 声图 图像 像提 提供 供针 体真 如 如图 所 示 所示 说 明 靠 签 本 身 就 跟 踪 点 说明 明可 可靠 靠标 标签 签本 本身 身就 就是 是针 针跟 跟踪 踪的 的难 难点 需 要 区 分 的针 体理 解需 需要 要区 区分 看 见 看见 见针 知 道 位 置 知道 道针 尖位 位置 强 段 只 代 表 当 前 束 切 交 互 维图 像中 中的 的强 强回 线段 段只 只代 代表 表针 体与 与当 当前 前声 声束 束切 切面 面的 的可 可见 见交 交互 能 因 入 射 尖可 可能 能因 因入 入射 射角 局 部 散 遮 挡 而 不 局部 部散 散射 射或 或遮 遮挡 挡而 而不 不可 参 考 架 具 整 刚 姿 外部 部参 参考 考架 架提 供的 的是 针具 具整 整体 体刚 刚体 体位 位姿 枢 轴 定 给 出 到 固 几 何 偏 移 枢轴 轴标 标定 定给 给出 出参 架到 到针 尖的 的固 固定 定几 几何 何偏 偏移 者 都 替 性 证 据 但二 二者 者都 都不 不能 能替 替代 代超 的局 部可 见性 性证 证据 此 因此 器 械 视 恢 复 相 衔 接 义观 究需 要与 与器 器械 械标 定和 和多 多视 视角 角几 何恢 恢复 复相 相衔 衔接 才 服 于 后 续 判 断 才能 能服 服务 务于 于后 后续 续三 维导 航判 判断 基 实 验 生 成 意 基于 于光 声真 值的 声针 踪实 实验 验与 与标 签生 生成 成示 示意 综 上 综上 已 从 通 割 网 络 发 展 剖 先 解已 已经 经从 从通 通用 用分 分割 割网 网络 络发 发展 展到 到解 解剖 剖先 先验 输 域 稳 建 模 输入 入域 域稳 稳定 定性 性和 和针 体可 性建 建模 其 主 其主 主要 要困 难在 在于 甲 腺 甲状 状腺 结 节 结节 风 险 构 来 源 同 风险 险结 结构 构和 体证 据来 来源 源不 不同 完 注完 完整 整性 性不 设 备 差 异 显 设备 备域 域差 差异 异明 明显 单 帧 直 承 担 决 策 单帧 帧二 维输 输出 出难 难以 以直 直接 接承 承担 担导 航决 决策 文 端 围 绕 规 范 本文 文在 在二 维端 端围 围绕 绕规 规范 范化 化输 开 应 测和 和任 务先 验开 开展 展相 相应 应研 更 为后 义场 场提 供更 更稳 定的 部证', '/#research', 'doctoral-thesis', 1, '2026-08-04', '7cd92fd94e471ab415b2efd0c0a418cea41034bb0e3eeeef4e85b4647ab9ac0d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3e7e0e0ae6708df7', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 三维语义分割与三维语义神经场研究现状', '二维概率观测进入导航任务后，需要在统一空间中恢复连续语义结构；简单的体素投票难以完成这一任务。传统三维医学分割在 CT/MRI 等规则体数据上可以利用 3D U-Net、V-Net 和 nnU-Net 等三维卷积或自配置框架学习体素级语义[128,140,141]；自由手超声则由带位姿的二维切片组成，切片间距、方向和重叠区域都不规则。若把二维概率图按位姿直接累积到体素网格，多视角重叠只能简单加权，位姿噪声会造成概率场撕裂，未覆盖区域会产生空洞，细长针体也容易呈锯齿状离散结构。
如图 1.10 所示，语义神经场提供了更适合不规则多视角观测的表示方式。NeSF 从带位姿二维语义监督中学习三维语义场，使任意空间位置都可查询语义属性[9]；Panoptic Neural Fields 和 Panoptic Lifting 等工作进一步将对象级、实例级和场景级语义引入神经场[142,143]；语义感知 NeRF 相关综述也说明，语义可以作为视角相对稳定的空间函数，与几何和外观共同优化[144]。迁移到超声时，这一思想需要被改写为二维概率观测、探头位姿、有效观测掩膜和切片厚度之间的一致性约束。
相较规则体数据上的三维卷积或点云网络，语义神经场将语义写成可在任意分辨率查询的空间坐标函数，避免固定体素网格的存储与量化限制。它能够直接适配不规则视角和稀疏观测，并把像素概率、局部方向、点线约束和几何先验纳入同一优化框架。迁移到甲状腺超声后，其任务是使组织语义、针体几何和针尖位置在同一规范空间中可查询、可评价并可用于导航约束，而非追求通用三维场景理解。', 'ct mri 3d u-net v-net nnu-net 128 140 141 1.10 nesf panoptic neural fields lifting 142 143 nerf 144 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 分 割 义分 分割 割与 二 概 率 观 测 进 入 任 务 后 二维 维概 概率 率观 观测 测进 进入 入导 航任 任务 务后 需 要 统 一 空 间 恢 复 连 续 结 构 需要 要在 在统 统一 一空 空间 间中 中恢 恢复 复连 连续 续语 义结 结构 简 单 体 素 投 票 难 以 完 成 这 简单 单的 的体 体素 素投 投票 票难 难以 以完 完成 成这 这一 一任 传 医 学 传统 统三 维医 医学 学分 割在 等 规 则 数 据 上 可 利 用 等规 规则 则体 体数 数据 据上 上可 可以 以利 利用 卷 积 或 自 配 置 框 架 习 级 等三 维卷 卷积 积或 或自 自配 配置 置框 框架 架学 学习 习体 素级 级语 由 手 带 位 姿 切 片 组 自由 由手 手超 声则 则由 由带 带位 位姿 姿的 的二 维切 切片 片组 组成 距 片间 间距 方 重 叠 区 域 都 不 方向 向和 和重 重叠 叠区 区域 域都 都不 不规 若 把 图 按 直 接 累 到 网 格 若把 把二 率图 图按 按位 姿直 直接 接累 累积 积到 到体 素网 网格 多 视 角 只 能 加 权 多视 视角 角重 叠只 只能 能简 单加 加权 噪 会 造 撕 裂 姿噪 噪声 声会 会造 造成 成概 率场 场撕 撕裂 未 覆 盖 产 生 洞 未覆 覆盖 盖区 域会 会产 产生 生空 空洞 细 长 针 也 容 易 呈 锯 齿 离 散 细长 长针 针体 体也 也容 容易 易呈 呈锯 锯齿 齿状 状离 离散 散结 如 如图 所 示 所示 提 供 更 适 合 表 式 场提 提供 供了 了更 更适 适合 合不 则多 角观 测的 的表 表示 示方 方式 从 监 督 从带 姿二 义监 监督 督中 中学 习三 义场 使 意 查 询 属 性 使任 任意 意空 间位 位置 置都 都可 可查 查询 询语 义属 属性 工 作 步 将 对 象 等工 工作 作进 进一 一步 步将 将对 对象 象级 实 例 景 引 实例 例级 级和 和场 场景 景级 义引 引入 入神 感 知 义感 感知 相 关 综 述 说 明 相关 关综 综述 述也 也说 说明 稳 定 函 义可 以作 作为 为视 角相 相对 对稳 稳定 定的 的空 间函 函数 几 何 共 同 优 化 与几 几何 何和 和外 外观 观共 共同 同优 优化 迁 移 时 迁移 移到 到超 声时 思 想 被 改 写 一思 思想 想需 要被 被改 改写 写为 为二 探 头 探头 头位 有 效 掩 膜 厚 度 之 致 约 束 有效 效观 测掩 掩膜 膜和 和切 片厚 厚度 度之 之间 间的 的一 一致 致性 性约 约束 较 点 云 络 相较 较规 上的 的三 或点 点云 云网 网络 辨 坐 标 场将 将语 义写 写成 成可 可在 在任 意分 分辨 辨率 率查 询的 间坐 坐标 标函 避 免 固 存 储 量 限 制 避免 免固 固定 定体 格的 的存 存储 储与 与量 量化 化限 限制 它 够 稀 疏 它能 能够 够直 接适 适配 配不 则视 角和 和稀 稀疏 疏观 并 像 并把 把像 像素 素概 局 部 局部 部方 线 先 验 纳 点线 线约 束和 和几 何先 先验 验纳 纳入 入同 同一 一优 化框 甲 腺 到甲 甲状 状腺 腺超 声后 其 织 其任 务是 是使 使组 组织 织语 尖 范 体几 和针 针尖 尖位 置在 在同 一规 规范 范空 中可 评 价 于 可评 评价 价并 并可 可用 用于 于导 航约 而 非 追 求 通 而非 非追 追求 求通 通用 用三 维场 景理', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3e7e0e0ae6708df704