INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-90b2107e68aa3bdc', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 三维语义分割与三维语义神经场研究现状', '与量化限制。它能够直接适配不规则视角和稀疏观测，并把像素概率、局部方向、点线约束和几何先验纳入同一优化框架。迁移到甲状腺超声后，其任务是使组织语义、针体几何和针尖位置在同一规范空间中可查询、可评价并可用于导航约束，而非追求通用三维场景理解。
体素概率融合和语义神经场对应两种三维语义观。前者把二维像素按位姿投影到体素网格，并在重叠区域做加权平均，方法直接且可解释，但会把位姿噪声表现为空间重影，把局部缺扫表现为空洞，把细长针体表现为离散折线。后者把二维概率图看作连续语义函数的稀疏观测，用同一函数解释来自不同方向、不同扫查和不同置信度的证据。这一发展趋势说明，三维语义表示的重点正在从规则体数据上的标签预测，转向不规则多视角观测下的连续空间语义恢复。
图 .10 NeSF 从多视角观测学习三维语义场的代表性架构[9]
Figure . Representative NeSF architecture for learning 3D semantic fields from multi-view observations. [9]
在三维体超声中，器械定位需要从体数据的高回声响应或候选点中恢复穿刺针轴线及其工作平面。现有方法通常结合投影、PCA、RANSAC或概率融合估计针体的空间方向和位置[145]。相较于二维切面内的线段检测，三维定位能够直接给出针轴与针尖的空间参数，但其实时性仍受体数据分辨率、计算开销和低对比针体可见性限制。', '10 nesf figure representative architecture for learning 3d semantic fields from multi-view observations. pca ransac 145 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 分 割 义分 分割 割与 量 化 限 制 与量 量化 化限 限制 它 能 够 直 接 适 配 不 规 则 视 角 稀 疏 观 测 它能 能够 够直 直接 接适 适配 配不 不规 规则 则视 视角 角和 和稀 稀疏 疏观 观测 并 把 像 素 概 率 并把 把像 像素 素概 概率 局 部 方 局部 部方 方向 点 线 约 束 几 何 先 验 纳 入 同 一 优 框 架 点线 线约 约束 束和 和几 几何 何先 先验 验纳 纳入 入同 同一 一优 优化 化框 框架 迁 移 到 甲 腺 后 迁移 移到 到甲 甲状 状腺 腺超 声后 其 任 务 使 组 织 其任 任务 务是 是使 使组 组织 织语 针 体 尖 位 置 范 空 间 可 查 询 针体 体几 何和 和针 针尖 尖位 位置 置在 在同 一规 规范 范空 空间 间中 中可 可查 查询 评 价 用 于 可评 评价 价并 并可 可用 用于 于导 航约 而 非 追 求 通 景 而非 非追 追求 求通 通用 用三 维场 场景 景理 融 合 对 应 两 种 体素 率融 融合 合和 和语 场对 对应 应两 两种 种三 义观 前 者 二 按 姿 投 影 网 格 前者 者把 把二 二维 维像 素按 按位 位姿 姿投 投影 影到 到体 素网 网格 重 叠 区 域 做 加 权 平 均 并在 在重 重叠 叠区 区域 域做 做加 加权 权平 平均 法 且 释 方法 法直 接且 且可 可解 解释 但 会 噪 表 但会 会把 把位 姿噪 噪声 声表 表现 现为 为空 间重 重影 缺 扫 洞 把局 部缺 缺扫 扫表 空洞 细 长 离 散 折 把细 细长 长针 体表 为离 离散 散折 折线 图 看 作 连 续 函 数 后者 维概 率图 图看 看作 作连 连续 续语 义函 函数 数的 的稀 来 自 用同 一函 数解 释来 来自 自不 不同 同方 信 度 证 据 同扫 扫查 查和 和不 同置 置信 信度 度的 的证 证据 这 发 展 趋 势 说 明 这一 一发 发展 展趋 趋势 势说 说明 示 正 从 上 标 签 预 义表 表示 示的 的重 重点 点正 正在 在从 从规 则体 体数 数据 据上 上的 的标 标签 签预 预测 转 多 下 恢 复 转向 向不 则多 多视 角观 测下 下的 的连 续空 间语 义恢 恢复 学 习 代 性 构 从多 测学 学习 习三 义场 场的 的代 代表 表性 性架 架构 在三 维体 体超 声中 器 械 定 需 要 高 回 响 或 候 选 穿 刺 轴 工 器械 械定 定位 位需 需要 要从 从体 据的 的高 高回 回声 声响 响应 应或 或候 候选 选点 点中 中恢 复穿 穿刺 刺针 针轴 轴线 线及 及其 其工 工作 作平 平面 有 常 结 现有 有方 法通 通常 常结 结合 合投 估 计 或概 合估 估计 计针 体的 的空 间方 向和 和位 相 较 切 段 检 相较 较于 于二 维切 切面 面内 内的 的线 线段 段检 检测 给 出 参 维定 位能 接给 给出 出针 轴与 与针 尖的 间参 参数 实 时 仍 受 辨 但其 其实 实时 时性 性仍 仍受 受体 据分 分辨 辨率 算 开 销 低 比 见 计算 算开 开销 销和 和低 低对 对比 比针 体可 可见 见性 性限', '/#research', 'doctoral-thesis', 1, '2026-08-04', '90b2107e68aa3bdc34cd6e46779e7b03b10e33f3c73c16f46c23f00fcb7734f1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-811286b5c03371d3', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 三维语义分割与三维语义神经场研究现状', '刺针轴线及其工作平面。现有方法通常结合投影、PCA、RANSAC或概率融合估计针体的空间方向和位置[145]。相较于二维切面内的线段检测，三维定位能够直接给出针轴与针尖的空间参数，但其实时性仍受体数据分辨率、计算开销和低对比针体可见性限制。
针体导航研究也从几何检测逐渐转向任务闭环。Zhao 等在 3D/4D 超声中比较 PCA、随机 Hough、积分投影和 RANSAC-Kalman 等针定位方法，说明传统方法在实时性和三维精度之间存在取舍[145]；Tyagi 等面向自主机器人区域麻醉，将神经分割、针尖定位和针轨迹外推结合到实时视觉伺服中[146]；基于光声真值的深度网络则降低了人工针体标注偏差[139]。相应地，针体检测的评价应转向三维针轴、针尖、目标和风险结构之间的空间误差，而不能停留在线段像素重合。
综上，三维语义分割与语义神经场研究已经形成从规则体素分割、体素概率融合到连续语义场和三维器械定位的发展脉络。其困难在于，自由手超声观测稀疏且不规则，二维概率图存在误差，位姿噪声会在三维空间中累积，细长针体和小体积风险结构又对空间连续性和几何精度要求较高。因此，本文围绕三维语义神经场开展相应研究，使组织语义、风险结构和针体候选能够在统一空间中被查询和评价。', 'pca ransac 145 zhao 3d 4d hough ransac-kalman tyagi 146 139 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 分 割 义分 分割 割与 刺 针 轴 线 其 工 作 平 刺针 针轴 轴线 线及 及其 其工 工作 作平 平面 有 方 法 通 常 结 合 投 影 现有 有方 方法 法通 通常 常结 结合 合投 投影 或 概 率 融 估 计 体 空 间 位 置 或概 概率 率融 融合 合估 估计 计针 针体 体的 的空 空间 间方 方向 向和 和位 位置 相 较 于 二 切 段 检 测 相较 较于 于二 二维 维切 切面 面内 内的 的线 线段 段检 检测 定 能 够 直 接 给 出 尖 参 数 维定 定位 位能 能够 够直 直接 接给 给出 出针 轴与 与针 针尖 尖的 间参 参数 但 实 时 性 仍 受 据 辨 但其 其实 实时 时性 性仍 仍受 受体 体数 数据 据分 分辨 辨率 算 开 销 低 对 比 可 见 限 制 计算 算开 开销 销和 和低 低对 对比 比针 体可 可见 见性 性限 限制 也 从 几 何 逐 渐 转 任 务 闭 环 体导 航研 究也 也从 从几 几何 何检 测逐 逐渐 渐转 转向 向任 任务 务闭 闭环 等 等在 声中 中比 比较 随 机 随机 积 积分 分投 影和 等针 针定 位方 说 明 传 统 精 度 之 存 取 舍 说明 明传 传统 统方 法在 在实 性和 和三 维精 精度 度之 之间 间存 存在 在取 取舍 自 主 器 人 区 域 麻 醉 等面 向自 自主 主机 机器 器人 人区 区域 域麻 麻醉 将 将神 经分 轨 迹 推 到 视 觉 伺 服 尖定 位和 和针 针轨 轨迹 迹外 外推 推结 合到 到实 时视 视觉 觉伺 伺服 服中 基 光 真 值 深 网 络 则 降 标 注 偏 差 基于 于光 光声 声真 真值 值的 的深 深度 度网 网络 络则 则降 降低 低了 了人 人工 工针 体标 标注 注偏 偏差 应 地 相应 应地 评 价 体检 测的 的评 评价 价应 应转 向三 维针 目 风 险 构 误 目标 标和 和风 风险 险结 结构 构之 间的 间误 误差 而 不 停 留 像 素 重 而不 不能 能停 停留 留在 在线 段像 像素 素重 重合 综 上 综上 已 形 成 规 与语 究已 已经 经形 形成 成从 从规 规则 则体 体素 素分 连 续 械 发 展 脉 素概 到连 连续 续语 义场 场和 维器 器械 械定 位的 的发 发展 展脉 脉络 困 难 其困 困难 难在 在于 由 手 观 稀 疏 且 自由 由手 手超 声观 观测 测稀 稀疏 疏且 且不 不规 图 维概 率图 图存 在误 姿 噪 会 累 位姿 姿噪 噪声 声会 会在 在三 维空 间中 中累 累积 细 长 小 又 要 求 高 细长 长针 体和 和小 小体 体积 积风 构又 又对 对空 间连 续性 和几 何精 度要 要求 求较 较高 因 此 因此 本 文 围 绕 本文 文围 围绕 绕三 场开 开展 展相 应研 使 组 织 使组 组织 织语 候 选 一 被 查 询 构和 体候 候选 选能 够在 在统 统一 一空 中被 被查 查询 询和 和评', '/#research', 'doctoral-thesis', 1, '2026-08-04', '811286b5c03371d3f3a23fb1279ea0c8c3b91d5e5b9dfbdde747d8ee8b0c26f4') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2944c07d57cf3791', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向穿刺导航的针体定位与空间关系分析研究现状', '当针体和针尖被可靠定位后，导航系统还需要回答入针方向、靶区接近性、风险结构距离和针尖偏离量等问题。韩国甲状腺放射学会 RFA 指南、欧洲甲状腺协会关于良性结节图像引导消融的指南以及 ATA/AACE 等甲状腺结节诊疗指南均强调，超声引导干预需要结合结节位置、靶区大小、邻近血管和神经、气管食管关系、患者症状和治疗目的。trans-isthmic approach、moving-shot technique、hydrodissection 和危险三角区避让等临床技术也说明，导航输出不能只给出单个分割掩膜，而应把目标、针体和风险结构之间的空间关系转化为可度量约束。
从针体定位研究看，早期方法多把穿刺针视作二维 B-mode 图像中的高亮直线结构，通过 Hough/Radon 变换、线增强滤波、模板匹配或基于概率投票的方式估计针轴方向。这类方法实现简洁，适用于针体在当前切面内连续可见、背景纹理较弱的场景，但对入射角、针体弯曲、局部遮挡、声影和组织散斑高度敏感。深度学习方法进一步将针体定位转化为掩膜分割、目标检测或针尖热图回归问题[137,138]，能够利用上下文纹理和形状先验，但仍依赖可靠标注，并且难以保证跨探头、跨组织和不同针体入射角下的稳定泛化。', 'rfa ata aace trans-isthmic approach moving-shot technique hydrodissection b-mode hough radon 137 138 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 穿 刺 针 体 定 位 空 间 关 系 分 析 向穿 穿刺 刺导 的针 针体 体定 定位 位与 与空 空间 间关 关系 系分 分析 析研 当 尖 被 可 靠 后 当针 体和 和针 针尖 尖被 被可 可靠 靠定 位后 统 还 需 要 回 答 入 方 航系 系统 统还 还需 需要 要回 回答 答入 入针 针方 方向 靶 区 接 近 性 靶区 区接 接近 近性 风 险 结 构 距 离 偏 量 等 问 题 风险 险结 结构 构距 距离 离和 尖偏 偏离 离量 量等 等问 问题 韩 甲 腺 放 射 学 会 韩国 国甲 甲状 状腺 腺放 放射 射学 学会 指 南 指南 欧 洲 协 于 良 节 图 像 引 消 融 以 欧洲 洲甲 腺协 协会 会关 关于 于良 良性 性结 结节 节图 图像 像引 引导 导消 消融 融的 的指 南以 以及 诊 疗 均 强 调 等甲 腺结 节诊 诊疗 疗指 南均 均强 强调 干 预 合 置 声引 导干 干预 预需 要结 结合 合结 节位 位置 大 小 区大 大小 邻 血 管 邻近 近血 血管 管和 和神 气 食 气管 管食 食管 管关 患 者 症 治 目 患者 者症 症状 状和 和治 治疗 疗目 目的 危 角 避 让 临 床 技 术 也 说 明 和危 危险 险三 三角 角区 区避 避让 让等 等临 临床 床技 技术 术也 也说 说明 输 出 不 能 只 给 单 个 割 掩 膜 航输 输出 出不 不能 能只 只给 给出 出单 单个 个分 分割 割掩 掩膜 而 应 把 标 而应 应把 把目 目标 之 转 化 度 约 束 和风 构之 之间 间的 的空 系转 转化 化为 为可 可度 度量 量约 约束 从 看 从针 位研 究看 早 期 法 多 视 作 二 早期 期方 方法 法多 多把 把穿 刺针 针视 视作 作二 二维 高 亮 直 线 像中 中的 的高 高亮 亮直 直线 线结 通 过 通过 变 换 变换 增 滤 波 线增 增强 强滤 滤波 模 板 匹 配 或 基 概 率 投 票 式 估 计 轴 模板 板匹 匹配 配或 或基 基于 于概 概率 率投 投票 票的 的方 方式 式估 估计 计针 针轴 轴方 这 类 实 简 洁 这类 类方 法实 实现 现简 简洁 适 用 前 切 连 续 见 适用 用于 于针 体在 在当 当前 前切 切面 面内 内连 连续 续可 可见 背 景 纹 较 弱 背景 景纹 纹理 理较 较弱 弱的 的场 场景 但 对 但对 对入 入射 射角 弯 曲 体弯 弯曲 局 部 遮 挡 局部 部遮 遮挡 影 组 织 散 斑 敏 感 声影 影和 和组 组织 织散 散斑 斑高 高度 度敏 敏感 深 习 进 一 步 将 深度 度学 学习 习方 法进 进一 一步 步将 将针 位转 为掩 膜分 检 测 热 归 标检 检测 测或 或针 尖热 热图 图回 回归 归问 够 利 上 下 文 形 先 验 能够 够利 利用 用上 上下 下文 文纹 理和 和形 形状 状先 先验 仍 依 赖 注 但仍 仍依 依赖 赖可 靠标 标注 并 且 难 保 证 跨 探 头 并且 且难 难以 以保 保证 证跨 跨探 探头 同 稳 泛 跨组 织和 和不 不同 同针 体入 角下 下的 的稳 稳定 定泛 泛化', '/#research', 'doctoral-thesis', 1, '2026-08-04', '2944c07d57cf379115ca266a4f7dae7a0719a4744ba6387d274f2007cc2d48f8') ON CONFLICT(`id`) DO UPDATE SET `locale