INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-63c49cbf436d12f0', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向穿刺导航的针体定位与空间关系分析研究现状', '、针体弯曲、局部遮挡、声影和组织散斑高度敏感。深度学习方法进一步将针体定位转化为掩膜分割、目标检测或针尖热图回归问题[137,138]，能够利用上下文纹理和形状先验，但仍依赖可靠标注，并且难以保证跨探头、跨组织和不同针体入射角下的稳定泛化。
因此，近年来的研究逐渐从单帧二维检测转向三维/四维超声、外部定位和多源真值结合。Zhao 等在 3D/4D 超声中系统比较 PCA、随机 Hough、积分投影和 RANSAC-Kalman 等针定位方法，说明传统几何方法在实时性、鲁棒性和三维精度之间存在明显权衡[145]。Hui 等利用光声图像提供针体真值，降低了人工标注对针体可见性和端点位置的主观偏差[139]。Tyagi 等面向机器人超声区域麻醉，将神经目标定位、针尖定位和针轨迹外推结合，用实时视觉伺服支持自主针引导[146]。这些工作共同表明，针体定位的研究重点已经从“图像中是否检测到亮线”转向“针轴、针尖、目标和风险结构在三维空间中的相对误差是否可量化”。', '137 138 zhao 3d 4d pca hough ransac-kalman 145 hui 139 tyagi 146 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 穿 刺 针 体 定 位 空 间 关 系 分 析 向穿 穿刺 刺导 的针 针体 体定 定位 位与 与空 空间 间关 关系 系分 分析 析研 弯 曲 体弯 弯曲 局 部 遮 挡 局部 部遮 遮挡 影 组 织 散 斑 高 度 敏 感 声影 影和 和组 组织 织散 散斑 斑高 高度 度敏 敏感 深 学 习 方 法 进 一 步 将 转 化 掩 膜 割 深度 度学 学习 习方 方法 法进 进一 一步 步将 将针 位转 转化 化为 为掩 掩膜 膜分 分割 目 标 检 测 或 尖 热 图 回 归 问 题 目标 标检 检测 测或 或针 针尖 尖热 热图 图回 回归 归问 问题 能 够 利 用 上 下 文 纹 形 先 验 能够 够利 利用 用上 上下 下文 文纹 纹理 理和 和形 形状 状先 先验 但 仍 依 赖 可 靠 注 但仍 仍依 依赖 赖可 可靠 靠标 标注 并 且 难 以 保 证 跨 探 头 并且 且难 难以 以保 保证 证跨 跨探 探头 不 同 入 射 角 稳 泛 跨组 织和 和不 不同 同针 体入 入射 射角 角下 下的 的稳 稳定 定泛 泛化 因 此 因此 近 年 来 逐 渐 从 单 帧 二 近年 年来 来的 的研 究逐 逐渐 渐从 从单 单帧 帧二 二维 维检 测转 转向 向三 四 四维 维超 多 源 真 值 结 合 外部 部定 位和 和多 多源 源真 真值 值结 结合 等 等在 统 比 较 声中 中系 系统 统比 比较 随 机 随机 积 投 积分 分投 投影 等针 针定 位方 说 明 传 几 何 实 时 性 说明 明传 传统 统几 几何 何方 法在 在实 实时 时性 鲁 棒 精 之 存 显 权 衡 鲁棒 棒性 性和 和三 维精 精度 度之 之间 间存 存在 在明 明显 显权 权衡 光 像 提 供 等利 用光 光声 声图 图像 像提 提供 供针 体真 降 低 人 工 对 见 端 点 置 主 观 偏 差 降低 低了 了人 人工 工标 注对 对针 体可 可见 见性 和端 端点 点位 位置 置的 的主 主观 观偏 偏差 器 区 域 麻 醉 等面 向机 机器 器人 人超 声区 区域 域麻 麻醉 将神 经目 标定 轨 迹 推 尖定 和针 针轨 轨迹 迹外 外推 推结 视 觉 伺 服 支 持 自 引 用实 时视 视觉 觉伺 伺服 服支 支持 持自 自主 主针 针引 引导 这 些 作 共 表 这些 些工 工作 作共 共同 同表 表明 重 已 位的 究重 重点 点已 已经 经从 否 到 亮 线 像中 中是 是否 否检 测到 到亮 亮线 轴 针轴 风 险 构 相 误 量 标和 和风 风险 险结 结构 构在 在三 维空 间中 中的 的相 相对 对误 误差 差是 否可 可量 量化', '/#research', 'doctoral-thesis', 1, '2026-08-04', '63c49cbf436d12f013404879f2cbd1526f8003800058610319e5999c5c545d1e') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b3d48980e543d389', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向穿刺导航的针体定位与空间关系分析研究现状', '面向机器人超声区域麻醉，将神经目标定位、针尖定位和针轨迹外推结合，用实时视觉伺服支持自主针引导[146]。这些工作共同表明，针体定位的研究重点已经从“图像中是否检测到亮线”转向“针轴、针尖、目标和风险结构在三维空间中的相对误差是否可量化”。
面向穿刺导航的空间关系分析也不再只是路径显示问题。临床指南和消融技术强调，穿刺或消融操作需要同时考虑结节位置、靶区范围、皮肤入路、trans-isthmic approach、moving-shot technique、hydrodissection、危险三角区以及喉返神经、迷走神经、颈动脉、气管和食管等邻近风险结构。相应地，导航系统的评价指标应包括针尖到靶点距离、针轴与期望入路夹角、针尖到风险结构的最小距离、针体可见段与外部跟踪位姿的一致性，以及不同观测来源之间的时空同步误差。只有当这些指标被定义为可计算的空间量，二维超声分割、三维重建、外部定位和器械标定才能共同服务于导航决策。
现有工作为这一方向提供了三类基础：二维端提供针体和组织的局部语义证据，三维/四维超声或自由手重建提供切面外空间背景，外部定位和枢轴标定提供器械参考架到针尖的几何约束。然而，这些证据在真实自由手扫查中往往并不完全一致：二维图像中的针体可能间断可见，外部跟踪给出的针尖位置可能受标定误差影响，三维语义场也可能因扫查覆盖不足或位姿噪声出现空洞和重影。因此，面向导航的研究现状正在从单一图像算法评价转向多源空间证据的一致性评价。', '146 trans-isthmic approach moving-shot technique hydrodissection 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 穿 刺 针 体 定 位 空 间 关 系 分 析 向穿 穿刺 刺导 的针 针体 体定 定位 位与 与空 空间 间关 关系 系分 分析 析研 机 器 人 区 域 麻 醉 向机 机器 器人 人超 声区 区域 域麻 麻醉 将 目 标 将神 经目 目标 标定 尖 轨 迹 推 结 合 针尖 尖定 位和 和针 针轨 轨迹 迹外 外推 推结 结合 用 实 时 视 觉 伺 服 支 持 自 主 引 用实 实时 时视 视觉 觉伺 伺服 服支 支持 持自 自主 主针 针引 引导 这 些 工 作 共 同 表 明 这些 些工 工作 作共 共同 同表 表明 重 点 已 从 位的 的研 究重 重点 点已 已经 经从 图 像 否 检 测 到 亮 线 图像 像中 中是 是否 否检 检测 测到 到亮 亮线 转 转向 轴 针轴 风 险 构 相 对 误 差 可 量 化 标和 和风 风险 险结 结构 构在 在三 维空 间中 中的 的相 相对 对误 误差 差是 否可 可量 量化 也 不 再 只 路 径 显 示 问 题 的空 析也 也不 不再 再只 只是 是路 路径 径显 显示 示问 问题 临 床 指 南 消 融 技 术 强 调 临床 床指 指南 南和 和消 消融 融技 技术 术强 强调 或 操 需 要 考 虑 节 置 刺或 或消 融操 操作 作需 需要 要同 同时 时考 考虑 虑结 结节 节位 位置 靶 范 围 靶区 区范 范围 皮 肤 入 皮肤 肤入 入路 危 角 以 喉 返 危险 险三 三角 角区 区以 以及 及喉 喉返 返神 迷 走 迷走 走神 颈 动 脉 颈动 动脉 气 管 食 等 邻 近 气管 管和 和食 食管 管等 等邻 邻近 近风 应 地 相应 应地 统 评 价 包 括 距 离 航系 系统 统的 的评 评价 价指 指标 标应 应包 包括 括针 尖到 到靶 靶点 点距 距离 期 望 夹 轴与 与期 期望 望入 路夹 夹角 最 小 到风 构的 的最 最小 小距 见 段 部 跟 踪 姿 一 致 性 体可 可见 见段 段与 与外 外部 部跟 跟踪 踪位 位姿 姿的 的一 一致 致性 观 来 源 之 步 及不 不同 同观 观测 测来 来源 源之 之间 间的 的时 时空 空同 同步 步误 有 当 被 计 算 只有 有当 当这 些指 标被 被定 定义 义为 为可 可计 计算 算的 间量 二 割 二维 维超 声分 分割 建 维重 重建 械 才 能 务 于 决 策 部定 和器 器械 械标 定才 才能 能共 同服 服务 务于 于导 航决 决策 方 提 供 类 基 础 现有 有工 作为 为这 这一 一方 方向 向提 提供 供了 了三 三类 类基 基础 端 组 织 局 证 据 维端 端提 供针 体和 和组 组织 织的 的局 局部 部语 义证 证据 四 由 手 切 背 景 四维 声或 或自 自由 由手 手重 建提 供切 切面 面外 外空 间背 背景 枢 参 架 几 何 约 束 和枢 枢轴 轴标 定提 供器 械参 参考 考架 架到 到针 尖的 的几 几何 何约 约束 然 而 然而 真 扫 查 往 并 完 全 些证 据在 在真 真实 实自 手扫 扫查 查中 中往 往往 往并 并不 不完 完全 全一 断 维图 可能 能间 间断 断可 给 出 受 影 响 踪给 给出 出的 尖位 置可 能受 受标 定误 差影 影响 因 覆 盖 足 噪 洞 义场 场也 也可 能因 因扫 查覆 覆盖 盖不 不足 足或 或位 姿噪 噪声 声出 出现 现空 空洞 洞和 和重 重影 此 因此 正 单 法 多 状正 正在 在从 从单 单一 一图 像算 算法 法评 价转 向多 多源 源空 间证 据的 性评', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b3d48980e543d3890bb093161bf1d120c6beed79289c9b2296062f1e7e130768') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-7d92041a052941d2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向导航的超声语义理解与三维语义神经场研究现状 / 面向穿刺导航的针体定位与空间关系分析研究现状', '在真实自由手扫查中往往并不完全一致：二维图像中的针体可能间断可见，外部跟踪给出的针尖位置可能受标定误差影响，三维语义场也可能因扫查覆盖不足或位姿噪声出现空洞和重影。因此，面向导航的研究现状正在从单一图像算法评价转向多源空间证据的一致性评价。
综上，穿刺导航相关研究已经形成从二维针体检测、三维/四维针跟踪、机器人超声引导到空间误差评价的技术链条。其共同趋势是将针体、靶区和风险结构放在同一可度量空间中分析，而不是仅报告二维分割精度或单帧检测准确率。对于甲状腺自由手超声场景，如何在稀疏多视角观测、外部定位误差和组织语义不确定性共同存在的条件下获得稳定的三维空间关系，仍是相关研究需要进一步解决的问题。', '第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 导 航 超 声 语 义 理 解 三 维 神 经 场 面向 向导 导航 航的 的超 超声 声语 语义 义理 理解 解与 与三 三维 维语 义神 神经 经场 场研 穿 刺 针 体 定 位 空 间 关 系 分 析 向穿 穿刺 刺导 的针 针体 体定 定位 位与 与空 空间 间关 关系 系分 分析 析研 真 实 自 由 手 扫 查 往 并 不 完 全 一 致 在真 真实 实自 自由 由手 手扫 扫查 查中 中往 往往 往并 并不 不完 完全 全一 一致 二 图 像 可 能 断 见 二维 维图 图像 像中 中的 体可 可能 能间 间断 断可 可见 部 跟 踪 给 出 尖 置 受 标 误 差 影 响 外部 部跟 跟踪 踪给 给出 出的 针尖 尖位 位置 置可 能受 受标 标定 定误 误差 差影 影响 也 因 覆 盖 足 或 姿 噪 洞 重 义场 场也 也可 能因 因扫 查覆 覆盖 盖不 不足 足或 或位 位姿 姿噪 噪声 声出 出现 现空 空洞 洞和 和重 重影 此 因此 正 从 单 算 法 评 价 转 多 源 证 据 性 的研 状正 正在 在从 从单 单一 一图 像算 算法 法评 评价 价转 转向 向多 多源 源空 间证 证据 据的 的一 致性 性评 综 上 综上 相 已 形 成 检 测 航相 相关 关研 究已 已经 经形 形成 成从 从二 维针 体检 检测 四 四维 针跟 机 器 人 引 到 技 术 链 条 机器 器人 人超 声引 引导 导到 到空 间误 差评 价的 的技 技术 术链 链条 其 共 同 趋 势 将 其共 共同 同趋 趋势 势是 是将 将针 靶 区 风 险 结 构 放 度 量 靶区 区和 和风 风险 险结 结构 构放 放在 在同 同一 一可 可度 度量 量空 间中 中分 而 仅 报 告 割 精 帧 准 确 率 而不 不是 是仅 仅报 报告 告二 维分 分割 割精 精度 度或 或单 单帧 帧检 测准 准确 确率 对 于 甲 腺 景 对于 于甲 甲状 状腺 腺自 手超 声场 场景 如 何 稀 疏 视 角 观 如何 何在 在稀 稀疏 疏多 多视 视角 角观 观测 组 织 存 件 下 获 得 稳 部定 位误 差和 和组 组织 织语 义不 不确 确定 定性 性共 同存 存在 在的 的条 条件 件下 下获 获得 得稳 稳定 定的 的三 维空 仍 需 要 进 步 决 问 题 仍是 是相 究需 需要 要进 进一 一步 步解 解决 决的 的问 问题', '/#research', 'doctoral-thesis', 1, '2026-08-04', '7d92041a052941d21da57a084beea857d807c8d8f8e58d265756acc9d5cdf643') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1e02ec69dd1bbbf9', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向穿刺导航的系统集成与假体验证研究现状', '算法链路若要服务于穿刺导航，最终必须回到可标定、可重复、可量化的系统平台中接受检验。三维重建、配准、语义场和针体定位分别解决不同层级的问题，但系统误差往往来自模块之间的耦合：探头标定误差会传递到三维重建和语义融合，针尖标定误差会影响空间关系评价，假体结构和材料稳定性又决定实验是否具有可重复性。已有 3D 超声引导靶向穿刺系统的 phantom validation 研究也表明，系统级评价需要同时关注影像引导、空间定位、靶点命中和平台误差来源[147]。系统集成与假体验证据此用于检查导航证据链在物理平台上能否闭合。
甲状腺及颈部超声假体研究为这种验证提供了物理基础。现有工作大体可分为训练型假体、介入操作假体和系统验证假体：训练型假体强调穿刺入路和操作手感，适合 FNA 或住院医师训练[148,149]；RFA 相关甲状腺假体进一步关注结节、血管、颈部解剖和热消融操作的综合逼真度[150,151]；系统验证型平台则更强调可重复的靶点、可量化的空间误差和影像—定位链路闭合[147]。对于导航验证任务而言，假体不需要完整复制人体颈部全部细节，但必须稳定呈现甲状腺、结节、血管、气管、肌肉和浅层软组织之间的空间关系，并在超声图像中形成可用于重建、分割和针体定位的可观测边界。', '3d phantom validation 147 fna 148 149 rfa 150 151 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 穿 刺 导 航 系 统 集 成 假 体 验 证 面向 向穿 穿刺 刺导 导航 航的 的系 系统 统集 集成 成与 与假 假体 体验 验证 证研 算 法 链 路 若 要 服 务 于 算法 法链 链路 路若 若要 要服 服务 务于 于穿 最 终 必 须 回 到 可 标 定 最终 终必 必须 须回 回到 到可 可标 标定 重 复 可重 重复 量 化 平 台 接 受 检 可量 量化 化的 统平 平台 台中 中接 接受 受检 检验 三 维 建 三维 维重 重建 配 准 配准 语 义 场 针 位 分 别 解 决 不 同 层 级 问 题 语义 义场 场和 和针 针体 体定 定位 位分 分别 别解 解决 决不 不同 同层 层级 级的 的问 问题 但 误 差 往 来 自 模 块 之 间 耦 合 但系 统误 误差 差往 往往 往来 来自 自模 模块 块之 之间 间的 的耦 耦合 探 头 会 传 递 融 探头 头标 定误 差会 会传 传递 递到 到三 建和 和语 义融 融合 尖 影 响 空 关 评 价 针尖 尖标 会影 影响 响空 空间 间关 关系 系评 评价 结 构 材 料 稳 性 又 实 否 具 有 体结 结构 构和 和材 材料 料稳 稳定 定性 性又 又决 决定 定实 实验 验是 是否 否具 具有 有可 复性 已 已有 超 声 引 靶 超声 声引 引导 导靶 靶向 刺系 统的 也 表 明 究也 也表 表明 需 时 注 像 统级 级评 价需 需要 要同 同时 时关 关注 注影 影像 像引 间定 点 命 源 靶点 点命 命中 中和 和平 台误 差来 来源 据 此 用 查 物 理 上 能 闭 证据 据此 此用 用于 于检 检查 查导 航证 据链 链在 在物 物理 理平 台上 上能 能否 否闭 闭合 甲 腺 颈 部 这 种 提 供 基 础 甲状 状腺 腺及 及颈 颈部 部超 声假 体研 究为 为这 这种 种验 证提 提供 供了 了物 理基 基础 工 作 大 训 练 型 现有 有工 工作 作大 大体 体可 可分 分为 为训 训练 练型 型假 介 入 操 介入 入操 操作 作假 体和 和系 统验 证假 强 调 手 感 体强 强调 调穿 刺入 入路 路和 和操 作手 手感 适 适合 或 住 院 医 师 或住 住院 院医 医师 师训 相 进 一 步 节 相关 关甲 腺假 体进 进一 一步 步关 注结 结节 血 管 血管 剖 热 消 综 逼 真 度 部解 解剖 剖和 和热 热消 消融 融操 作的 的综 综合 合逼 逼真 真度 则 更 证型 型平 台则 则更 更强 调可 复的 的靶 的空 间误 差和 和影 位链 路闭 对 任 而 言 对于 于导 航验 证任 任务 务而 而言 完 整 制 人 全 细 体不 不需 要完 完整 整复 复制 制人 人体 体颈 部全 全部 部细 细节 呈 但必 须稳 定呈 呈现 现甲 气 气管 肌 肉 浅 软 组 织 肌肉 肉和 和浅 浅层 层软 软组 组织 织之 并 图 形 并在 在超 声图 图像 像中 中形 形成 成可 可用 于重 割 观 测 边 界 分割 割和 位的 的可 可观 观测 测边 边界', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1e02ec69dd1bbbf9474006bfed075f7965783216cc12bbeec18e91e881d7ce25') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-8e9eefc29b276340', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向穿刺导航的系统集成与假体验证研究现状', '点、可量化的空间误差和影像—定位链路闭合[147]。对于导航验证任务而言，假体不需要完整复制人体颈部全部细节，但必须稳定呈现甲状腺、结节、血管、气管、肌肉和浅层软组织之间的空间关系，并在超声图像中形成可用于重建、分割和针体定位的可观测边界。
组织模拟材料的选择直接影响超声回声、衰减、散斑纹理、针刺反馈和长期稳定性。组织模拟材料综述表明，明胶、琼脂、PVA、水凝胶、聚丙烯酰胺凝胶以及含石墨、玻璃珠或二氧化硅等散射颗粒的复合材料，常用于调节声速、衰减、回声强度和机械刚度[152]；可重复使用水凝胶和 3D 打印模具则分别服务于耐久性与复杂解剖结构成形[148,153]。BDAM 等双网络材料进一步尝试在形状保持、成像稳定性和针刺反馈之间取得平衡[150]。因此，面向导航的甲状腺假体不能只追求视觉外形，还需要在材料分层、结节回声、血管腔性结构、强回声/声影边界和长期稳定性之间形成可重复设计。
定位与标定链路是系统验证的另一核心。自由手超声系统通常需要外部光学或近红外定位提供探头位姿，通过N线、交叉线或点靶模型完成图像平面到探头坐标系的标定，并通过枢轴标定建立工具参考架与针尖之间的几何关系[4,5,84,85]。这些步骤分别给出图像、探头、世界坐标、器械参考架和针尖之间的转换关系，也决定后续三维重建、针体几何恢复和空间关系评价的误差边界。', '147 pva 152 3d 148 153 bdam 150 84 85 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 穿 刺 导 航 系 统 集 成 假 体 验 证 面向 向穿 穿刺 刺导 导航 航的 的系 系统 统集 集成 成与 与假 假体 体验 验证 证研 点 可 量 化 空 间 误 差 影 像 可量 量化 化的 的空 空间 间误 误差 差和 和影 影像 定 位 链 路 闭 合 定位 位链 链路 路闭 闭合 对 于 任 务 而 言 对于 于导 航验 证任 任务 务而 而言 不 需 要 完 整 复 制 人 颈 部 全 细 节 体不 不需 需要 要完 完整 整复 复制 制人 人体 体颈 颈部 部全 全部 部细 细节 但 必 须 稳 呈 甲 腺 但必 必须 须稳 稳定 定呈 呈现 现甲 甲状 状腺 结 结节 血 管 血管 气 气管 肌 肉 浅 层 软 组 织 之 关 肌肉 肉和 和浅 浅层 层软 软组 组织 织之 之间 间的 间关 关系 并 超 声 图 形 用 重 建 并在 在超 超声 声图 图像 像中 中形 形成 成可 可用 用于 于重 重建 分 割 针 观 测 边 界 分割 割和 和针 针体 体定 位的 的可 可观 观测 测边 边界 模 拟 材 料 选 择 直 接 响 回 织模 模拟 拟材 材料 料的 的选 选择 择直 直接 接影 影响 响超 声回 回声 衰 减 衰减 散 斑 纹 理 散斑 斑纹 纹理 反 馈 长 期 性 针刺 刺反 反馈 馈和 和长 长期 期稳 定性 综 述 表 明 料综 综述 述表 表明 胶 明胶 琼 脂 琼脂 水 凝 水凝 凝胶 聚 丙 烯 酰 胺 以 含 石 墨 聚丙 丙烯 烯酰 酰胺 胺凝 胶以 以及 及含 含石 石墨 玻 璃 珠 或 二 氧 硅 等 射 颗 粒 玻璃 璃珠 珠或 或二 二氧 氧化 化硅 硅等 等散 散射 射颗 颗粒 粒的 的复 复合 合材 常 调 速 常用 于调 调节 节声 声速 强 度 机 械 刚 声强 强度 度和 和机 机械 械刚 刚度 使 可重 重复 复使 使用 用水 胶和 打 印 具 则 别 服 耐 久 杂 解 剖 构 打印 印模 模具 具则 则分 分别 别服 服务 务于 于耐 耐久 久性 性与 与复 复杂 杂解 解剖 剖结 结构 构成 成形 双 网 络 进 一 步 尝 试 保 持 等双 双网 网络 络材 料进 进一 一步 步尝 尝试 试在 在形 形状 状保 保持 取 得 平 衡 成像 像稳 性和 馈之 间取 取得 得平 平衡 因 此 因此 能 只 追 求 视 觉 向导 的甲 腺假 不能 能只 只追 追求 求视 视觉 觉外 外形 还 还需 要在 在材 料分 分层 节回 腔 管腔 腔性 性结 强回 设 计 声影 影边 界和 性之 间形 复设 设计 标 另 核 心 位与 与标 标定 定链 路是 是系 统验 证的 的另 另一 一核 核心 自 由 手 通 光 学 近 红 提 供 探 头 姿 自由 由手 手超 声系 统通 通常 常需 要外 外部 部光 光学 学或 或近 近红 红外 外定 位提 提供 供探 探头 头位 位姿 过 通过 线 交 叉 靶 型 到 坐 交叉 叉线 线或 或点 点靶 靶模 模型 型完 完成 成图 像平 平面 面到 到探 头坐 坐标 标系 系的 的标 枢 轴 立 工 参 考 架 尖 几 何 并通 过枢 枢轴 轴标 定建 建立 立工 工具 具参 参考 考架 架与 与针 针尖 尖之 的几 几何 何关 这 些 骤 给 出 这些 些步 步骤 骤分 别给 给出 出图 世 世界 界坐 器 转 换 器械 械参 架和 的转 转换 换关 也 决 后 续 三 维 也决 决定 定后 后续 续三 三维 维重 恢 评 价 体几 何恢 恢复 复和 和空 系评 评价 价的 的误 差边', '/#research', 'doctoral-thesis', 1, '2026-08-04', '8e9eefc29b276340a761448490c0a80fa014b0451add17d3dfc9d2d4e03286c2') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`so