INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ff5aacc82ab03d86', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 国内外研究现状 / 面向穿刺导航的系统集成与假体验证研究现状', '点靶模型完成图像平面到探头坐标系的标定，并通过枢轴标定建立工具参考架与针尖之间的几何关系[4,5,84,85]。这些步骤分别给出图像、探头、世界坐标、器械参考架和针尖之间的转换关系，也决定后续三维重建、针体几何恢复和空间关系评价的误差边界。
综上，系统集成与假体验证研究已由单一训练模型或演示平台，发展到材料声学特性、解剖结构可重复性、定位标定链路和误差传播的联合分析。算法指标只有在影像、定位、器械和假体结构均可量化时才具有明确的导航含义。基于这一认识，本文构建可重复的甲状腺假体实验平台，并通过双目标定、轨迹跟踪、探头标定和针尖标定评价关键坐标链路的几何一致性。', '84 85 第 章 绪 论 绪论 国 内 外 研 究 现 状 国内 内外 外研 研究 究现 现状 面 向 穿 刺 导 航 系 统 集 成 假 体 验 证 面向 向穿 穿刺 刺导 导航 航的 的系 系统 统集 集成 成与 与假 假体 体验 验证 证研 点 靶 模 型 完 图 像 平 到 探 头 坐 标 定 点靶 靶模 模型 型完 完成 成图 图像 像平 平面 面到 到探 探头 头坐 坐标 标系 系的 的标 标定 并 通 过 枢 轴 建 立 工 具 参 考 架 针 尖 之 间 几 何 关 并通 通过 过枢 枢轴 轴标 定建 建立 立工 工具 具参 参考 考架 架与 与针 针尖 尖之 之间 间的 的几 几何 何关 关系 这 些 步 骤 分 别 给 出 这些 些步 步骤 骤分 分别 别给 给出 出图 世 界 世界 界坐 器 械 转 换 器械 械参 架和 和针 的转 转换 换关 也 决 后 续 三 维 重 也决 决定 定后 后续 续三 三维 维重 重建 恢 复 空 评 价 误 差 边 针体 体几 何恢 恢复 复和 和空 空间 间关 系评 评价 价的 的误 误差 差边 边界 综 上 综上 已 由 单 一 训 练 或 演 示 台 究已 已由 由单 单一 一训 训练 练模 型或 或演 演示 示平 平台 发 展 材 料 声 学 特 性 发展 展到 到材 材料 料声 声学 学特 特性 解 剖 结 构 可 解剖 剖结 结构 构可 可重 重复 复性 位 链 路 传 播 联 合 析 定位 位标 定链 链路 路和 和误 差传 传播 播的 的联 联合 合分 分析 算 法 指 只 有 影 算法 法指 指标 标只 只有 有在 在影 影像 均 量 化 时 才 明 确 含 义 械和 和假 体结 构均 均可 可量 量化 化时 时才 才具 具有 有明 明确 确的 的导 航含 含义 基 于 认 识 基于 于这 这一 一认 认识 本 文 甲 腺 实 本文 文构 构建 建可 复的 的甲 甲状 状腺 腺假 体实 实验 验平 双 目 过双 双目 目标 轨 迹 跟 踪 轨迹 迹跟 跟踪 键 致 头标 定和 尖标 定评 价关 关键 键坐 标链 路的 何一 一致 致性', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ff5aacc82ab03d8682bc35aca5c0840e53693fdb2a6c3aec60eb860a22fdef4f') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b9a4db18d93ac063', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 研究内容与章节安排 / 研究内容', '本文从甲状腺穿刺规划对连续三维场景、多次扫查空间一致性、组织—器械关系和物理坐标可追溯性的实际需求出发，将需求分解为四个递进研究问题。第2章建立可信连续表征，第3章修正多次扫查空间关系，第4章估计组织与器械的三维语义，第5章在假体、定位和标定平台中检验坐标链与模块接口。各部分均先由任务约束导出数学模型和方法假设，再以理论分析给出可检验预期，最后由现有实验结果验证预期并限定结论范围。
（1）物理一致的超声三维重建。针对非均匀采样、局部弱接触以及散斑与方向相关回波造成的重建不稳定，建立B-scan、探头位姿、像素尺度和规范空间之间的映射，并以列级有效接触筛选约束训练观测。在连续神经场表征中引入高频表达增强、瑞利背散射和方向参数化反射，理论上分别缓解离散插值、散斑统计失配和界面视角依赖；实验通过接触判别、离散体素表征与连续神经场表征对比和物理组件消融检验这些预测。
（2）面向多组超声扫查序列的位姿—表征联合优化。针对扫查间整体错位和帧内高频抖动，将全局刚性偏差、局部位姿扰动与神经场共同置于规范空间优化。外观检索提供候选可辨识性，几何内点与不确定性加权抑制错误对应，统计先验和Lie群B样条约束连续轨迹；理论分析预期这些约束在误差尺度和作用阶段上互补，实验分别在随机扰动、冷启动和局部抖动条件下验证位姿与渲染质量。', 'b-scan lie 第 章 绪 论 绪论 研 究 内 容 节 安 排 研究 究内 内容 容与 与章 章节 节安 安排 本 文 从 甲 状 腺 穿 刺 规 划 对 连 续 三 维 场 景 本文 文从 从甲 甲状 状腺 腺穿 穿刺 刺规 规划 划对 对连 连续 续三 三维 维场 场景 多 次 扫 查 空 间 一 致 性 多次 次扫 扫查 查空 空间 间一 一致 致性 组 织 组织 器 械 关 系 物 理 坐 标 可 追 溯 实 际 需 求 出 发 器械 械关 关系 系和 和物 物理 理坐 坐标 标可 可追 追溯 溯性 性的 的实 实际 际需 需求 求出 出发 将 分 解 四 个 递 进 问 题 将需 求分 分解 解为 为四 四个 个递 递进 进研 究问 问题 建 立 信 表 征 章建 建立 立可 可信 信连 续表 表征 修 正 章修 修正 正多 间关 估 计 语 义 章估 估计 计组 织与 与器 械的 的三 维语 语义 假 体 章在 在假 假体 定 位 平 台 检 验 链 模 块 接 口 定位 位和 和标 标定 定平 平台 台中 中检 检验 验坐 标链 链与 与模 模块 块接 接口 各 部 均 先 由 任 务 约 束 导 数 学 型 方 法 设 各部 部分 分均 均先 先由 由任 任务 务约 约束 束导 导出 出数 数学 学模 模型 型和 和方 方法 法假 假设 再 以 析 给 预 期 再以 以理 理论 论分 分析 析给 给出 出可 可检 验预 预期 最 后 现 有 结 果 证 并 限 范 围 最后 后由 由现 现有 有实 实验 验结 结果 果验 验证 证预 期并 并限 限定 定结 结论 论范 范围 超 声 重 理一 致的 的超 超声 声三 维重 重建 针 非 匀 采 样 针对 对非 非均 均匀 匀采 采样 局 弱 触 散 斑 向 相 回 波 造 成 不 稳 局部 部弱 弱接 接触 触以 以及 及散 散斑 斑与 与方 方向 向相 相关 关回 回波 波造 造成 成的 的重 建不 不稳 稳定 探 头 姿 探头 头位 位姿 像 素 尺 度 之 映 射 像素 素尺 尺度 度和 和规 规范 范空 间之 之间 间的 的映 映射 列 级 效 筛 选 训 练 观 测 并以 以列 列级 级有 有效 效接 触筛 筛选 选约 束训 训练 练观 观测 神 经 引 入 高 频 达 增 强 在连 续神 神经 经场 场表 征中 中引 引入 入高 高频 频表 表达 达增 增强 瑞 利 背 参 化 反 瑞利 利背 背散 散射 射和 向参 参数 数化 化反 反射 上 别 缓 离 插 值 论上 上分 分别 别缓 缓解 解离 离散 散插 插值 统 失 配 界 面 视 角 依 赖 斑统 统计 计失 失配 配和 和界 界面 面视 视角 角依 依赖 通 过 判 验通 通过 过接 触判 判别 比 件 消 融 这 些 散体 体素 素表 征与 与连 征对 对比 比和 理组 组件 件消 消融 融检 验这 这些 些预 预测 序 面向 向多 多组 组超 声扫 查序 序列 列的 的位 联 合 优 征联 联合 合优 优化 整 错 帧 抖 动 对扫 查间 间整 整体 体错 错位 和帧 帧内 内高 频抖 抖动 全 刚 偏 差 将全 全局 局刚 刚性 性偏 偏差 扰 共 同 置 于 部位 姿扰 扰动 动与 与神 场共 共同 同置 置于 于规 间优 外 索 提 供 候 辨 识 外观 观检 检索 索提 提供 供候 候选 选可 可辨 辨识 识性 几 何 点 确 加 权 抑 制 误 应 几何 何内 内点 点与 与不 不确 确定 定性 性加 加权 权抑 抑制 制错 错误 误对 对应 计先 先验 验和 群 条 轨 迹 样条 条约 束连 续轨 轨迹 作 用 阶 段 互 补 析预 期这 些约 束在 在误 误差 差尺 和作 作用 用阶 阶段 段上 上互 互补 随 机 验分 别在 在随 随机 机扰 冷 启 下 渲 染 质 量 冷启 启动 动和 和局 部抖 动条 条件 件下 下验 证位 姿与 与渲 渲染 染质 质量', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b9a4db18d93ac06304c9b33e3ddce63fcf8f2475c98289dd164f2e8a7a330d4a') ON CONF