INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b7d0749b625ec259', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 研究内容与章节安排 / 研究内容', '与神经场共同置于规范空间优化。外观检索提供候选可辨识性，几何内点与不确定性加权抑制错误对应，统计先验和Lie群B样条约束连续轨迹；理论分析预期这些约束在误差尺度和作用阶段上互补，实验分别在随机扰动、冷启动和局部抖动条件下验证位姿与渲染质量。
（3）面向导航的二维语义观测、三维语义场与针体几何。针对设备域差异、低标注、组织与针体重叠及细长结构易断裂，依次研究输入域规范化、多任务二维观测、连续位置场、成像平面条件场、解剖—器械双分支和距离—拓扑约束。理论上，连续坐标共享应减弱体素量化，方向条件应解释切面相关观测，但方向无关三维输出仍依赖可靠边缘化；因此实验同时报告二维观测域和三维组织GT，并以单病例针体结果限定几何结论。
（4）甲状腺穿刺导航原理样机与几何链路。围绕算法进入物理平台所需的可重复实验对象和坐标变换，构建多组织假体、双目近红外定位、探头N线标定和针尖枢轴标定链路。通过重投影、连续轨迹、成像平面和针尖偏移实验给出分项误差边界，并在统一数据与坐标语义下连接二维语义、三维语义和针体几何。原理样机以模块结果和几何链路为评价对象，不以分项残差推算未直接测量的端到端穿刺精度。', 'lie gt 第 章 绪 论 绪论 研 究 内 容 节 安 排 研究 究内 内容 容与 与章 章节 节安 安排 神 经 场 共 同 置 于 规 范 空 间 优 化 与神 神经 经场 场共 共同 同置 置于 于规 规范 范空 空间 间优 优化 外 观 检 索 提 供 候 选 可 辨 识 性 外观 观检 检索 索提 提供 供候 候选 选可 可辨 辨识 识性 几 何 点 不 确 定 加 权 抑 制 错 误 对 应 几何 何内 内点 点与 与不 不确 确定 定性 性加 加权 权抑 抑制 制错 错误 误对 对应 统 计 先 验 统计 计先 先验 验和 群 样 条 约 束 连 续 轨 迹 样条 条约 约束 束连 连续 续轨 轨迹 理 分 析 预 期 这 些 差 尺 度 作 用 阶 段 上 互 补 理论 论分 分析 析预 预期 期这 这些 些约 束在 在误 误差 差尺 尺度 度和 和作 作用 用阶 阶段 段上 上互 互补 实 别 随 机 扰 动 实验 验分 分别 别在 在随 随机 机扰 扰动 冷 启 局 部 抖 件 下 证 位 姿 渲 染 质 量 冷启 启动 动和 和局 局部 部抖 抖动 动条 条件 件下 下验 验证 证位 位姿 姿与 与渲 渲染 染质 质量 面 向 导 航 二 维 语 义 测 面向 向导 导航 航的 的二 二维 维语 语义 义观 观测 三 针 体 三维 义场 场与 与针 针体 体几 设 备 域 异 针对 对设 设备 备域 域差 差异 低 标 注 低标 标注 组 织 重 叠 细 长 结 构 易 断 裂 组织 织与 体重 重叠 叠及 及细 细长 长结 结构 构易 易断 断裂 依 次 输 入 依次 次研 究输 输入 入域 域规 范化 多 任 务 多任 任务 务二 维观 续位 位置 置场 成 像 平 成像 像平 平面 面条 件场 解 剖 解剖 器 械 双 支 距 离 器械 械双 双分 分支 支和 和距 距离 拓 扑 拓扑 扑约 论上 坐 享 减 弱 素 续坐 坐标 标共 共享 享应 应减 减弱 弱体 体素 素量 量化 方 释 切 相 关 方向 向条 件应 应解 解释 释切 切面 面相 相关 关观 但 无 出 仍 赖 靠 边 缘 但方 向无 无关 关三 维输 输出 出仍 仍依 依赖 赖可 可靠 靠边 边缘 缘化 因 此 时 报 告 因此 此实 验同 同时 时报 报告 告二 测域 域和 和三 维组 并 以 单 病 例 果 限 并以 以单 单病 病例 例针 体结 结果 果限 限定 定几 何结 结论 甲 状 腺 穿 刺 原 链 路 甲状 状腺 腺穿 穿刺 刺导 航原 原理 理样 样机 机与 与几 何链 链路 围 绕 算 法 进 物 台 所 需 复 象 变 换 围绕 绕算 算法 法进 进入 入物 物理 理平 平台 台所 所需 需的 的可 可重 重复 复实 验对 对象 象和 和坐 标变 变换 建 假 构建 建多 多组 织假 假体 目 近 红 双目 目近 近红 红外 外定 定位 探 头 探头 线 尖 枢 轴 线标 标定 定和 和针 针尖 尖枢 枢轴 轴标 定链 通 过 投 影 通过 过重 重投 投影 偏 移 给 项 界 面和 尖偏 偏移 移实 验给 给出 出分 分项 项误 差边 边界 一 数 据 接 并在 在统 统一 一数 数据 据与 与坐 标语 义下 下连 连接 接二 义和 模 块 评 价 机以 以模 模块 块结 果和 和几 路为 为评 评价 价对 残 推 未 直 端 到 精 不以 以分 项残 残差 差推 推算 算未 未直 直接 接测 测量 量的 的端 端到 到端 端穿 刺精 精度', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b7d0749b625ec259bcbc07f307802aeb98667e90913c3f38bf8c7194e445a535') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f670d68531ffb2c2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 研究内容与章节安排 / 章节安排', '全文共分为六章。第1章提出需求与科学问题，第2—5章按照“基础表征—空间统一—语义理解—系统实现”的顺序展开，第6章总结结论、创新与研究边界。章节关系如图 1.11所示，具体安排如下。
第1章为绪论。介绍甲状腺结节诊疗与超声穿刺规划的研究背景，梳理超声三维重建、超声扫查序列配准、超声语义理解、介入器械定位和系统集成的研究现状，归纳观测质量、空间一致性、语义融合与系统验证方面的不足，并提出全文研究内容与技术路线。
第2章研究基于超声物理与连续神经场表征的三维重建。建立自由手超声的空间映射和有效观测筛选方法，比较离散体素表征与连续神经场表征，构建融合表达增强、瑞利背散射和方向参数化反射的重建框架，并通过有效接触、表征方式、网络结构和物理渲染实验验证各组成环节。
第3章研究多组超声扫查序列的位姿—表征联合优化。面向扫查级整体扰动与帧级局部抖动，建立规范空间下的联合模型；分别研究基于外观与几何一致性的全局配准，以及融合统计噪声先验、Lie群B样条和运动学约束的局部降噪，并评价不同初始化条件下的位姿恢复与重建质量。
第4章研究多视角三维超声语义场与针体几何。依次研究输入域规范化、低数据多任务二维语义观测、连续位置场与成像平面条件场、解剖—器械双分支与针体中心线几何；通过二维观测域、三维组织GT和几何诊断指标区分不同层级的证据。', '1.11 lie gt 第 章 绪 论 绪论 研 究 内 容 节 安 排 研究 究内 内容 容与 与章 章节 节安 安排 全 文 共 分 六 全文 文共 共分 分为 为六 六章 提 出 需 求 科 学 问 题 章提 提出 出需 需求 求与 与科 科学 学问 问题 按 照 章按 按照 基 础 表 征 基础 础表 表征 空 间 统 一 空间 间统 统一 语 义 理 解 语义 义理 理解 系 实 现 系统 统实 实现 顺 序 展 开 的顺 顺序 序展 展开 总 结 章总 总结 结结 结论 创 新 边 界 创新 新与 与研 究边 边界 关 如 图 节关 关系 系如 如图 所 示 所示 具 体 下 具体 体安 排如 如下 章为 为绪 介 绍 甲 状 腺 诊 疗 超 声 穿 刺 规 划 背 景 介绍 绍甲 甲状 状腺 腺结 结节 节诊 诊疗 疗与 与超 超声 声穿 穿刺 刺规 规划 划的 的研 究背 背景 梳 三 维 重 建 梳理 理超 声三 三维 维重 重建 扫 查 列 配 准 声扫 扫查 查序 序列 列配 配准 声语 入 器 械 定 位 集 成 介入 入器 器械 械定 定位 位和 和系 统集 集成 成的 究现 现状 归 纳 观 测 质 量 归纳 纳观 观测 测质 质量 致 性 间一 一致 致性 融 合 验 证 方 面 不 足 义融 融合 合与 与系 统验 验证 证方 方面 面的 的不 不足 并 技 术 路 线 并提 出全 文研 与技 技术 术路 路线 于 物 连 续 神 经 场 章研 究基 基于 于超 声物 物理 理与 与连 连续 续神 神经 经场 场表 征的 的三 立 自 由 手 映 射 有 效 筛 选 法 建立 立自 自由 由手 手超 声的 的空 间映 映射 射和 和有 有效 效观 测筛 筛选 选方 方法 比 较 离 散 素 比较 较离 离散 散体 体素 素表 征与 构 达 增 强 构建 建融 合表 表达 达增 增强 瑞 利 向 参 数 化 反 框 架 瑞利 利背 背散 散射 和方 方向 向参 参数 数化 化反 反射 射的 的重 建框 框架 通 过 接 触 并通 通过 过有 效接 接触 式 征方 方式 网 络 渲 染 各 组 环 网络 络结 结构 构和 和物 理渲 渲染 染实 实验 验验 证各 各组 组成 成环 环节 多 姿 究多 多组 组超 列的 的位 位姿 联 优 征联 联合 合优 优化 级 整 扰 动 帧 局 部 抖 面向 向扫 查级 级整 整体 体扰 扰动 动与 与帧 帧级 级局 局部 部抖 抖动 范 模 型 立规 规范 范空 间下 下的 的联 合模 模型 别 外 几 何 分别 别研 于外 外观 观与 与几 几何 何一 性的 的全 全局 局配 以 计 噪 先 以及 及融 合统 统计 计噪 噪声 声先 先验 群 样 条 运 约 束 降 样条 条和 和运 运动 动学 学约 约束 束的 的局 部降 降噪 评 价 同 初 始 件 恢 复 并评 评价 价不 不同 同初 初始 始化 化条 条件 件下 姿恢 恢复 复与 与重 建质 视 角 针 多视 视角 角三 维超 义场 场与 与针 针体 体几 依 次 输 域 依次 次研 究输 输入 入域 域规 范化 低 据 任 务 二 低数 数据 据多 多任 任务 务二 二维 维语 义观 置 像 平 续位 位置 置场 与成 成像 像平 平面 面条 件场 剖 解剖 双 支 心 械双 双分 分支 支与 体中 中心 心线 线几 过二 维观 测域 织 维组 组织 断 指 标 区 层 和几 何诊 诊断 断指 指标 标区 区分 分不 同层 层级 级的 的证 证据', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f670d68531ffb2c2d00ee9e922c19311818ef670b0d3db8f1d0439ed3b9b0653') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.