INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-7264bb8452b0cbaf', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第1章 绪论 / 研究内容与章节安排 / 章节安排', '下的位姿恢复与重建质量。
第4章研究多视角三维超声语义场与针体几何。依次研究输入域规范化、低数据多任务二维语义观测、连续位置场与成像平面条件场、解剖—器械双分支与针体中心线几何；通过二维观测域、三维组织GT和几何诊断指标区分不同层级的证据。
第5章研究甲状腺穿刺导航原理样机。构建多组织甲状腺假体与双目近红外定位平台，完成探头和针尖标定，分析关键几何链路误差；在统一数据、坐标和证据接口下连接重建、配准、组织语义与针体几何模块，并依据已有实验界定原理样机的功能范围和结论边界。
第6章为总结与展望。在区分方法实验、三维组织GT评价、几何标定和系统集成证据的基础上，总结全文主要结论与创新点，并讨论组织形变、不确定性表达、在线计算和多中心临床应用等超出本文评价范围的研究方向。
