INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-a5de270fcbe9d33d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 引言', '甲状腺穿刺规划首先需要把离散二维超声观测转化为具有统一物理尺度和连续查询能力的三维场景。第1章的需求分析表明，自由手超声虽兼具实时性与灵活性，但采样轨迹不规则、有效观测分布不均，并受到位姿误差、散斑噪声和方向相关回波影响。若仅堆叠切片或进行局部体素插值，欠采样区域容易出现空洞、撕裂和边界模糊，难以支撑后续超声扫查序列配准与语义建模。
本章从观测几何和场景表征两个层面设计方法。首先建立B-scan、探头位姿、像素尺度和规范空间之间的映射，并通过外部定位、探头标定与列级有效接触筛选，使训练图像同时具备空间和质量约束。随后比较离散体素表征与连续神经场表征，分析连续坐标共享对非均匀采样的适应性，并引入位置-方向编码、分层采样和周期激活增强高频表达。在成像模型方面，瑞利背散射用于描述散斑统计，方向参数化反射用于描述界面角度响应，超声适应性损失用于协调观测与物理分量。由此可先验预期：有效观测筛选减少错误射线，连续神经场表征减弱网格量化，散射与反射机制分别改善纹理统计和界面结构。本章实验按照这一预测组织逐层对比与消融，并为第3章的超声扫查序列空间统一提供底层表征。', 'b-scan 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 引 言 引言 甲 状 腺 穿 刺 规 划 首 先 需 要 把 离 散 二 观 测 转 化 具 有 统 一 尺 度 查 询 能 力 景 甲状 状腺 腺穿 穿刺 刺规 规划 划首 首先 先需 需要 要把 把离 离散 散二 二维 维超 声观 观测 测转 转化 化为 为具 具有 有统 统一 一物 理尺 尺度 度和 和连 续查 查询 询能 能力 力的 的三 维场 场景 求 分 析 表 明 章的 的需 需求 求分 分析 析表 表明 自 由 手 虽 兼 实 时 性 灵 活 自由 由手 手超 声虽 虽兼 兼具 具实 实时 时性 性与 与灵 灵活 活性 但 采 样 轨 迹 不 则 但采 采样 样轨 轨迹 迹不 不规 规则 效 布 均 有效 效观 测分 分布 布不 不均 并 受 到 位 姿 误 差 并受 受到 到位 位姿 姿误 误差 斑 噪 方 向 相 关 回 波 影 响 散斑 斑噪 噪声 声和 和方 方向 向相 相关 关回 回波 波影 影响 若 仅 堆 叠 切 片 或 进 行 局 部 体 素 插 值 若仅 仅堆 堆叠 叠切 切片 片或 或进 进行 行局 局部 部体 体素 素插 插值 欠 区 域 容 易 出 现 空 洞 欠采 样区 区域 域容 容易 易出 出现 现空 空洞 撕 裂 边 界 模 糊 撕裂 裂和 和边 边界 界模 模糊 难 以 支 撑 后 扫 序 列 配 准 语 义 难以 以支 支撑 撑后 后续 续超 声扫 扫查 查序 序列 列配 配准 准与 与语 语义 义建 建模 本 从 几 何 征 两 个 层 面 设 计 法 本章 章从 从观 测几 几何 何和 和场 景表 表征 征两 两个 个层 层面 面设 设计 计方 方法 立 先建 建立 探 头 探头 头位 像 范 间 之 映 射 像素 素尺 和规 规范 范空 空间 间之 之间 间的 的映 映射 通 过 外 定 并通 通过 过外 外部 部定 定位 标 级 接 触 筛 选 头标 标定 定与 与列 列级 级有 效接 接触 触筛 筛选 使 训 练 图 同 备 质 量 约 束 使训 训练 练图 图像 像同 同时 时具 具备 备空 间和 和质 质量 量约 约束 随 比 较 随后 后比 比较 较离 散体 素表 征与 场表 坐 共 享 对 非 匀 适 应 析连 续坐 坐标 标共 共享 享对 对非 非均 均匀 匀采 样的 的适 适应 应性 入 置 并引 引入 入位 位置 编 码 向编 编码 周 期 激 增 强 高 频 达 分层 层采 样和 和周 周期 期激 激活 活增 增强 强高 高频 频表 表达 成 型 在成 成像 像模 模型 型方 方面 瑞 利 背 用 描 述 瑞利 利背 背散 散射 射用 用于 于描 描述 述散 斑统 统计 参 数 反 角 向参 参数 数化 化反 反射 述界 界面 面角 角度 度响 响应 损 失 协 调 声适 性损 损失 失用 于协 协调 调观 测与 与物 理分 分量 此 可 验 预 由此 此可 可先 先验 验预 预期 减 少 错 线 测筛 选减 减少 少错 错误 误射 射线 弱 网 格 征减 减弱 弱网 网格 格量 量化 机 制 别 改 善 纹 结 构 射与 与反 射机 机制 制分 分别 别改 改善 善纹 纹理 理统 计和 和界 面结 结构 按 照 这 组 织 逐 消 融 章实 实验 验按 按照 照这 这一 一预 预测 测组 组织 织逐 逐层 层对 对比 比与 与消 消融 并为 为第 提 供 底 列空 间统 一提 提供 供底 底层 层表', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'a5de270fcbe9d33d930b3063e30690138443f5b565c61eab697f29cba9590e3c') ON C