INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3c0f4c9d5ff18ff7', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建流程', '超声三维重建首先需要回答二维B-mode观测如何进入统一三维空间。图像采集与位姿同步确定观测来源，像素物理映射和声学传播描述空间位置及回波形成；二者共同规定本章重建问题的输入、输出与约束。', 'b-mode 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 流 程 建流 流程 首 先 需 要 回 答 二 建首 首先 先需 需要 要回 回答 答二 二维 观 测 如 何 进 入 统 一 空 间 观测 测如 如何 何进 进入 入统 统一 一三 维空 空间 图 像 采 集 位 姿 同 步 确 定 来 源 图像 像采 采集 集与 与位 位姿 姿同 同步 步确 确定 定观 测来 来源 素 映 射 学 传 播 描 述 置 波 形 成 像素 素物 理映 映射 射和 和声 声学 学传 传播 播描 描述 述空 间位 位置 置及 及回 回波 波形 形成 者 共 规 本 问 题 输 二者 者共 共同 同规 规定 定本 本章 章重 建问 问题 题的 的输 输入 出 约 束 输出 出与 与约 约束', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3c0f4c9d5ff18ff73c44cf03cd4a1c7e4989cdbff06f6ce400e723457891c837') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-36506cd4f2b79419', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建流程 / 超声三维重建的正逆问题', '从更一般的成像与反演角度看，超声三维重建可以统一表述为一个由正问题与逆问题构成的过程。其核心并不在于将二维图像简单堆叠为三维体数据，而在于围绕同一前向成像模型，建立三维介质场、成像配置与二维观测结果之间的对应关系。[6,11,12,32]
Figure . Schematic illustration of 3D ultrasound reconstruction
Figure . The forward and inverse problems of 3D reconstruction
如图 2.1与图 2.2所示，自由手超声的三维重建过程可统一建模为一个由正问题（Forward Problem）与逆问题（Inverse Problem）耦合的空间求解系统。三维重建中的正问题与逆问题可以在统一框架下理解：正向过程由“介质场+边界/成像条件”出发，经过前向成像模型得到观测结果；逆向过程则由观测结果反推介质场或其参数化表示。
具体而言，超声三维重建中的正问题是指：在已知三维介质场及成像配置的前提下，计算对应视角下的二维超声图像。这里，三维介质场 用于描述三维空间中与超声成像相关的物理属性分布，例如反射率、声速、衰减系数及其他介质参数；成像配置 则表示探头位姿与成像参数的集合，包括阵元结构、聚焦方式、发射脉冲、增益、时间增益补偿、动态范围压缩等。若记超声前向成像算子为 ，则正问题可抽象表示为', '11 12 32 figure schematic illustration of 3d ultrasound reconstruction the forward and inverse problems 2.1 2.2 problem 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 流 程 建流 流程 正 逆 问 题 建的 的正 正逆 逆问 问题 从 更 一 般 成 像 反 演 角 度 看 从更 更一 一般 般的 的成 成像 像与 与反 反演 演角 角度 度看 可 以 统 表 述 个 由 构 过 建可 可以 以统 统一 一表 表述 述为 为一 一个 个由 由正 正问 题与 与逆 题构 构成 成的 的过 过程 其 核 心 并 不 将 二 图 简 单 堆 叠 体 数 据 其核 核心 心并 并不 不在 在于 于将 将二 二维 维图 图像 像简 简单 单堆 堆叠 叠为 为三 维体 体数 数据 而 围 绕 同 前 向 模 型 而在 于围 围绕 绕同 同一 一前 前向 向成 像模 模型 立 介 质 建立 立三 维介 介质 质场 配 置 观 测 结 果 之 间 对 应 关 系 像配 配置 置与 与二 维观 观测 测结 结果 果之 之间 间的 的对 对应 应关 关系 如 如图 与图 所 示 所示 自 手 自由 由手 手超 声的 的三 建过 程可 可统 一建 建模 模为 耦 合 空 求 解 耦合 合的 的空 空间 间求 求解 解系 系统 框 架 下 建中 中的 题可 以在 在统 一框 框架 架下 下理 理解 正向 向过 程由 边 界 边界 条 件 像条 条件 出 发 出发 得 到 经过 过前 型得 得到 到观 则 推 或 参 化 逆向 程则 则由 由观 果反 反推 推介 场或 或其 其参 参数 数化 化表 表示 具 言 具体 体而 而言 指 题是 是指 已 知 提 在已 已知 知三 场及 及成 置的 的前 前提 提下 计 算 视 计算 算对 应视 视角 角下 下的 的二 维超 声图 这 里 这里 用 描 相 属 性 分 布 用于 于描 描述 述三 维空 间中 中与 与超 声成 像相 相关 关的 的物 理属 属性 性分 分布 例 射 率 例如 如反 反射 射率 速 声速 衰 减 他 衰减 减系 系数 数及 及其 其他 他介 质参 探 头 位 姿 集 则表 示探 探头 头位 位姿 姿与 与成 像参 数的 的集 集合 包 括 阵 元 包括 括阵 阵元 元结 结构 聚 焦 方 式 聚焦 焦方 方式 脉 冲 发射 射脉 脉冲 增 益 增益 时 补 偿 时间 间增 益补 补偿 动 态 范 压 缩 等 动态 态范 范围 围压 压缩 缩等 若 记 子 若记 记超 声前 像算 算子 子为 抽 象 则正 可抽 抽象 象表 示为', '/#research', 'doctoral-thesis', 1, '2026-08-04', '36506cd4f2b79419ff913e805b09837f175301d8f4cbce6448982571d988527e') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-97fac36d51ce4557', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建流程 / 超声三维重建的正逆问题', '三维空间中与超声成像相关的物理属性分布，例如反射率、声速、衰减系数及其他介质参数；成像配置 则表示探头位姿与成像参数的集合，包括阵元结构、聚焦方式、发射脉冲、增益、时间增益补偿、动态范围压缩等。若记超声前向成像算子为 ，则正问题可抽象表示为
在这一框架下，正问题的输入是三维介质场 与成像配置 ；其计算过程依赖于所选定的声学前向模型，用以完成波在介质中的传播、散射、接收、束形成，以及后续的包络检波与压缩；其输出则是在该位姿与成像条件下得到的二维合成超声切片。前向模型可按精度分为不同层级，例如快速的各向异性点扩散函数卷积模型、基于射线或束线的传播模型，乃至更高保真的全波仿真模型。尽管模型复杂度不同，但它们在问题定义上是一致的，即：从三维介质场出发，通过成像物理生成二维观测结果。[38–41]
与之对应，超声三维重建中的逆问题是指：在给定多视角二维观测及其对应位姿与成像参数的条件下，估计最能解释这些观测数据的三维介质场，或其某种参数化表示。设共有二维观测结果集合与成像配置集合，则逆问题可写为
其中， 表示第 个视角下的真实二维超声图像， 表示其对应的探头位姿与成像配置， 表示观测图像与前向渲染图像之间的一致性损失， 表示对三维表示施加的先验或正则化约束，例如平滑性、边缘保持或解剖一致性， 为权衡系数。逆问题的目标是寻找一个三维表示，使其通过正问题模型生成的二维图像能够在已知视角下与观测图像匹配，并在未见视角下保持合理的一致性。', '38 41 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 流 程 建流 流程 正 逆 问 题 建的 的正 正逆 逆问 问题 空 间 成 像 相 关 属 性 分 布 维空 空间 间中 中与 与超 声成 成像 像相 相关 关的 的物 理属 属性 性分 分布 例 如 反 射 率 例如 如反 反射 射率 速 声速 衰 减 系 数 其 他 介 质 参 衰减 减系 系数 数及 及其 其他 他介 介质 质参 参数 配 置 像配 配置 则 表 示 探 头 位 姿 集 合 则表 表示 示探 探头 头位 位姿 姿与 与成 像参 数的 的集 集合 包 括 阵 元 结 构 包括 括阵 阵元 元结 结构 聚 焦 方 式 聚焦 焦方 方式 发 脉 冲 发射 射脉 脉冲 增 益 增益 时 补 偿 时间 间增 益补 补偿 动 态 范 围 压 缩 等 动态 态范 范围 围压 压缩 缩等 若 记 前 向 算 子 若记 记超 声前 前向 向成 像算 算子 子为 可 抽 象 则正 正问 题可 可抽 抽象 象表 示为 这 一 框 架 下 在这 这一 一框 框架 架下 输 入 题的 的输 输入 入是 是三 维介 质场 计 过 依 赖 所 选 定 学 模 型 其计 计算 算过 过程 程依 依赖 赖于 于所 所选 选定 定的 的声 声学 学前 向模 模型 用 以 完 波 传 播 用以 以完 完成 成波 波在 在介 质中 中的 的传 传播 散 散射 接 收 接收 束 形 束形 形成 后 络 检 以及 及后 后续 续的 的包 包络 络检 检波 波与 与压 出 该 条 件 得 到 二 切 片 其输 输出 出则 则是 是在 在该 该位 像条 条件 件下 下得 得到 到的 的二 二维 维合 合成 成超 声切 切片 按 精 度 不 同 层 级 型可 可按 按精 精度 度分 分为 为不 不同 同层 层级 快 各 异 点 扩 函 卷 积 如快 快速 速的 的各 各向 向异 异性 性点 点扩 扩散 散函 函数 数卷 卷积 积模 线 或 于射 射线 线或 或束 束线 线的 播模 乃 至 更 高 保 真 全 仿 乃至 至更 更高 高保 保真 真的 的全 全波 波仿 仿真 真模 尽 管 复 杂 尽管 管模 型复 复杂 杂度 度不 但 它 们 义 上 致 但它 它们 们在 在问 题定 定义 义上 上是 是一 一致 致的 即 从 从三 场出 出发 通 生 观 测 果 通过 过成 像物 理生 生成 成二 维观 观测 测结 结果 之 对 应 与之 之对 对应 指 建中 的逆 题是 是指 给 多 视 角 在给 给定 定多 多视 视角 角二 测及 其对 应位 的条 估 最 能 解 释 些 据 估计 计最 最能 能解 解释 释这 这些 些观 测数 数据 据的 的三 某 种 化 或其 其某 某种 种参 数化 化表 设 共 有 设共 共有 有二 果集 合与 置集 写 则逆 可写 写为 其中 示第 个 实 图 个视 角下 下的 的真 真实 实二 维超 声图 图像 示其 应的 的探 渲 染 损 失 示观 测图 像与 与前 向渲 渲染 染图 像之 之间 间的 的一 致性 性损 损失 施 加 先 验 约 示对 对三 维表 示施 施加 加的 的先 先验 验或 或正 正则 则化 化约 约束 平 滑 如平 平滑 滑性 边 缘 持 剖 边缘 缘保 保持 持或 或解 解剖 剖一 权 衡 为权 权衡 衡系 目 标 寻 找 的目 目标 标是 是寻 寻找 找一 一个 个三 使 够 已 知 匹 使其 其通 过正 题模 型生 成的 维图 像能 能够 够在 在已 已知 知视 下与 与观 像匹 匹配 并 未 见 并在 在未 未见 见视 下保 持合 合理 理的', '/#research', 'doctoral-thesis', 1, '2026-08-04', '97fac36d51ce45571189377cf71c8f0424b180678bc73e352c0ed1c9191968fd') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_titl