INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1e7b712b4d885e52', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建流程 / 超声射线传播模型', '表示中的第四个坐标参数从根本上将空间位置（1）与不具有平移性质的方向向量（0）区分开来。该映射保证了随着位姿参数更新，二维图像中的空间位置、射线方向以及沿射线采样得到的三维点能够同步变化，从而为统一三维重建和后续联合优化提供一致的坐标基础。
在超声成像中，每一列像素可视为一条声学扫描线。因而在二维 B-scan 图像中，一条二维射线 可由其起点 与方向 表示。对该射线按距离参数 进行采样，可得到二维图像中的采样点 与方向：
通过映射算子 ，可将二维采样点与方向映射到三维规范空间中，得到对应的三维采样位置与传播方向：
如图 2.3所示，在二维 B-scan 图像中，每一列像素都可以理解为一条由换能器发射的声学扫描线，沿该扫描线在深度方向进行采样即可得到一系列二维采样点。图中不仅展示了扫描线的方向性，也直观说明了二维图像中的深度坐标并非普通的平面坐标，而对应超声波沿传播方向逐步返回的回波路径。这一过程构成了二维超声图像到三维空间建模的起点。图 2.4 则进一步展示了从二维切片采样到三维规范空间映射的过程。二维图像中的采样点和方向，经过像素物理间距矩阵 与位姿变换 的联合映射后，被嵌入到统一三维规范空间中。这样，不同时间、不同位姿下采集的二维图像便可在同一个三维坐标系中建立对应关系，从而为后续连续神经场建模和新视角重投影提供统一空间基础。', 'b-scan 2.3 2.4 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 流 程 建流 流程 射 线 传 播 模 型 声射 射线 线传 传播 播模 模型 表 示 四 个 坐 标 参 数 从 根 本 上 将 空 间 位 置 表示 示中 中的 的第 第四 四个 个坐 坐标 标参 参数 数从 从根 根本 本上 上将 将空 空间 间位 位置 不 具 有 平 移 性 质 方 向 量 与不 不具 具有 有平 平移 移性 性质 质的 的方 方向 向向 向量 区 分 开 来 区分 分开 开来 该 映 保 证 随 着 姿 更 新 该映 映射 射保 保证 证了 了随 随着 着位 位姿 姿参 数更 更新 二 图 像 二维 维图 图像 像中 的空 以 沿 采 样 得 到 点 能 够 同 步 变 化 线方 向以 以及 及沿 沿射 线采 采样 样得 得到 到的 的三 维点 点能 能够 够同 同步 步变 变化 而 统 一 后 联 合 优 提 供 致 础 从而 而为 为统 统一 一三 建和 和后 后续 续联 联合 合优 优化 化提 提供 供一 一致 致的 的坐 标基 基础 成 在超 声成 成像 每 列 素 可 视 条 学 扫 描 每一 一列 列像 像素 素可 可视 视为 为一 一条 条声 声学 学扫 扫描 描线 因 因而 而在 在二 条二 维射 由 其 起 可由 由其 其起 起点 与方 对 按 距 离 对该 该射 线按 按距 距离 离参 进 行 进行 行采 可得 到二 的采 样点 通 过 算 子 通过 过映 射算 算子 规 范 可将 将二 维采 点与 向映 射到 到三 维规 规范 范空 间中 应 到对 对应 应的 样位 置与 与传 播方 如 如图 所 所示 都 解 换 器 发 素都 都可 可以 以理 理解 解为 条由 由换 换能 能器 器发 发射 射的 的声 深 度 即 系 沿该 该扫 线在 在深 深度 度方 向进 样即 即可 到一 一系 系列 列二 仅 展 图中 中不 不仅 仅展 展示 示了 了扫 线的 向性 也 直 观 说 明 并 非 普 面 也直 直观 观说 说明 明了 了二 的深 度坐 标并 并非 非普 普通 通的 的平 平面 面坐 波 逐 返 回 路 径 而对 应超 声波 波沿 沿传 向逐 逐步 步返 返回 回的 的回 回波 波路 路径 这 构 这一 一过 过程 程构 构成 成了 维超 声图 像到 维空 间建 建模 模的 的起 则 切 片 则进 进一 一步 步展 了从 从二 维切 切片 片采 样到 间映 的过 点和 和方 矩 阵 经过 过像 素物 理间 间距 距矩 矩阵 与位 姿变 变换 的联 合映 射后 被 嵌 入 被嵌 嵌入 入到 到统 这样 时 不同 同时 时间 下 集 便 立 关 同位 姿下 下采 采集 集的 的二 像便 便可 可在 在同 同一 一个 个三 维坐 标系 系中 中建 建立 立对 应关 关系 角 投 影 为后 续连 场建 模和 和新 新视 视角 角重 重投 投影 影提 供统 一空 间基', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1e7b712b4d885e524a6b00ab87d769d96ab1bf969c77c1565b9085d405eb0ae7') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidenc