INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0dbf15ea0bee5111', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建流程 / 超声射线传播模型', '程。二维图像中的采样点和方向，经过像素物理间距矩阵 与位姿变换 的联合映射后，被嵌入到统一三维规范空间中。这样，不同时间、不同位姿下采集的二维图像便可在同一个三维坐标系中建立对应关系，从而为后续连续神经场建模和新视角重投影提供统一空间基础。
图 .3 B-scan图像中的声学扫描线与深度采样示意
Figure . Acoustic scan line and depth sampling in a B-scan image
图 .4 不同探头位姿下二维超声切片向三维规范空间的映射示意
Figure . Mapping of 2D ultrasound slices acquired at different probe poses into the 3D canonical space
于是，二维图像中的每一列像素都不再仅仅是一个平面上的离散灰度序列，而对应为规范三维空间中一条带有明确物理尺度和位姿信息的声学采样轨迹。由所有图像帧、所有扫描线及其采样点共同构成的观测集合，最终形成对三维介质场的离散约束。
本节据此将超声三维重建统一表述为受成像几何与声学传播约束的逆问题，并明确了二维扫描线对三维介质场的离散观测关系。下一节进一步说明可靠位姿与有效回波观测的获取条件。', 'b-scan figure acoustic scan line and depth sampling in image mapping of 2d ultrasound slices acquired at different probe poses into the 3d canonical space 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 流 程 建流 流程 射 线 传 播 模 型 声射 射线 线传 传播 播模 模型 二 图 像 采 样 点 方 向 二维 维图 图像 像中 中的 的采 采样 样点 点和 和方 方向 过 素 间 距 矩 阵 经过 过像 像素 素物 理间 间距 距矩 矩阵 位 姿 变 换 与位 位姿 姿变 变换 联 合 映 后 的联 联合 合映 映射 射后 被 嵌 入 到 统 一 规 范 空 被嵌 嵌入 入到 到统 统一 一三 维规 规范 范空 空间 间中 这 这样 不 同 时 不同 同时 时间 下 集 便 可 个 坐 标 系 立 对 应 关 同位 姿下 下采 采集 集的 的二 像便 便可 可在 在同 同一 一个 个三 维坐 坐标 标系 系中 中建 建立 立对 对应 应关 关系 从 而 新 视 角 投 影 提 供 础 从而 而为 为后 后续 续连 场建 建模 模和 和新 新视 视角 角重 重投 投影 影提 提供 供统 一空 间基 基础 学 扫 描 深 度 示 意 的声 声学 学扫 扫描 描线 线与 与深 深度 度采 样示 示意 探 头 切 片 同探 探头 头位 下二 维超 声切 切片 片向 向三 间的 的映 射示 于是 每 列 都 再 仅 平 面 上 离 散 灰 序 的每 每一 一列 列像 素都 都不 不再 再仅 仅仅 仅是 是一 个平 平面 面上 上的 的离 离散 散灰 灰度 度序 序列 条 带 有 明 确 尺 信 息 轨 迹 而对 应为 为规 范三 维空 中一 一条 条带 带有 有明 明确 确物 理尺 尺度 度和 和位 姿信 信息 息的 学采 样轨 轨迹 由 所 帧 由所 所有 有图 像帧 其 共 构 成 观 测 有扫 线及 及其 其采 点共 共同 同构 构成 成的 的观 观测 测集 集合 最 终 形 介 质 约 束 最终 终形 形成 成对 对三 维介 介质 质场 散约 约束 本 节 据 此 将 表 述 受 几 何 逆 问 题 本节 节据 据此 此将 将超 建统 一表 表述 述为 为受 受成 成像 像几 几何 何与 与声 学传 播约 束的 的逆 逆问 问题 并 并明 确了 了二 维扫 线对 散观 测关 进 步 说 靠 效 回 波 获 取 件 下一 一节 节进 进一 一步 步说 说明 明可 可靠 靠位 姿与 与有 有效 效回 回波 波观 测的 的获 获取 取条 条件', '/#research', 'doctoral-thesis', 1, '2026-08-04', '0dbf15ea0bee5111c47b1ae66ca6fff22b3ac2d1b83f2044c376409e9f9208b0') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e51b586d1b1899f4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统', '二维超声帧进入三维建模前，必须同时具备可信位姿和有效回波。本节分别建立外部近红外视觉定位与列级有效接触筛选模型：前者恢复探头和器械的六自由度位姿，后者剔除缺乏可靠组织回波的成像列，从几何和观测两方面约束后续重建、语义建模与导航分析。[157,158]', '157 158 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 二 帧 进 入 模 前 二维 维超 声帧 帧进 进入 入三 维建 建模 模前 必 须 同 时 具 备 可 信 姿 有 效 回 波 必须 须同 同时 时具 具备 备可 可信 信位 位姿 姿和 和有 有效 效回 回波 本 节 分 别 立 外 部 近 红 视 觉 列 级 接 触 筛 选 型 本节 节分 分别 别建 建立 立外 外部 部近 近红 红外 外视 视觉 觉定 与列 列级 级有 效接 接触 触筛 筛选 选模 模型 者 恢 复 探 头 器 械 六 自 由 度 前者 者恢 恢复 复探 探头 头和 和器 器械 械的 的六 六自 自由 由度 度位 后 剔 除 缺 乏 靠 组 织 成 像 后者 者剔 剔除 除缺 缺乏 乏可 可靠 靠组 组织 织回 波的 的成 成像 像列 从 几 何 观 测 两 方 面 约 束 从几 几何 何和 和观 观测 测两 两方 方面 面约 约束 束后 后续 续重 语 义 导 航 析 语义 义建 模与 与导 导航 航分 分析', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e51b586d1b1899f47ae77cb3180dab5c2b9e72efaac50df2c9cc7a63921dbb3b') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-96dfefea23a93f11', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 外部近红外视觉定位系统', '双目近红外定位系统为自由手甲状腺超声提供外部六自由度位姿输入。本文将该系统作为二维超声帧进入三维空间的几何入口，不单独提出硬件创新。其基本链路包括相机标定、近红外光斑提取、左右视图匹配、三角测量和刚体位姿求解；双目相机内参、畸变系数、左右相机相对位姿和标定精度由 5.3.1　 节实验给出，本节说明位姿输入与三维重建、配准和导航分析之间的关系。', '5.3.1 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 外 部 近 红 视 觉 外部 部近 近红 红外 外视 视觉 觉定 位系 双 目 自 由 手 甲 状 腺 提 供 六 度 姿 输 入 双目 目近 外定 统为 为自 自由 由手 手甲 甲状 状腺 腺超 声提 提供 供外 部六 六自 由度 度位 位姿 姿输 输入 本 文 将 该 作 二 帧 进 空 间 几 何 口 本文 文将 将该 该系 统作 作为 为二 二维 维超 声帧 帧进 进入 入三 维空 空间 间的 的几 几何 何入 入口 不 单 独 出 硬 件 创 新 不单 单独 独提 提出 出硬 硬件 件创 创新 其 链 路 包 括 相 机 标 其基 基本 本链 链路 路包 包括 括相 相机 机标 标定 光 斑 取 外光 光斑 斑提 提取 左 右 图 匹 配 左右 右视 视图 图匹 匹配 角 测 量 刚 体 求 解 三角 角测 测量 量和 和刚 刚体 体位 姿求 求解 内 参 目相 机内 内参 畸 变 数 畸变 变系 系数 对 精 右相 机相 相对 对位 姿和 和标 定精 精度 度由 节 实 验 给 节实 实验 验给 给出 说 明 本节 节说 说明 明位 入与 与三 准 导 航 分 析 之 关 配准 准和 和导 导航 航分 分析 析之 之间 的关 关系', '/#research', 'doctoral-thesis', 1, '2026-08-04', '96dfefea23a93f11193326fb07ba01582b4120f7d5aebae977ad0be24f42c3e0') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-8a1596a51511c571', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 外部近红外视觉定位系统 / 双目相机三角测量定位模型', '双目近红外定位系统的核心是把左右相机中的二维观测恢复为空间三维点。单相机投影给出空间点到像素平面的映射，双目立体几何则利用左右同名点约束恢复其三维坐标。5.3.1.1　 节通过双目标定与轨迹跟踪实验给出参数稳定性和实际误差。5.3
