INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0fcfb2d0ffb65495', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 外部近红外视觉定位系统 / 近红外标志点提取与配对', '完成相机几何建模后，定位链路需要从左右图像中提取近红外标志点并建立正确配对。中心提取误差会影响三角测量精度，误匹配则会造成三维点跳变，因此该步骤直接决定外部位姿输入的稳定性。[159]
近红外主动光斑通常表现为局部高亮、形状近圆且纹理较弱的连通区域。本文采用“阈值分割 + 连通域筛选 + 灰度加权中心”的方式提取亚像素中心，该表达利用光斑内部灰度分布估计能量中心，比单纯几何中心更适合主动近红外光源。图 2.10 展示了阈值分割后近红外标志点及其中心位置。
