INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2c7340362465218e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 外部近红外视觉定位系统 / 目标位姿计算与物体注册识别', '双目三角测量输出的是当前视野内的无序三维近红外标志点集合，其本身不包含目标身份和点序关系。在导航场景中，探头、穿刺针、患者参考架和标定工具可能同时进入视野，因此系统需要在无序光点中识别刚体模板，恢复模板点与观测点的对应关系，并进一步求解带目标身份的六自由度位姿。[160]
