INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b7232503e6b3cfeb', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 外部近红外视觉定位系统 / 目标位姿计算与物体注册识别', '帧，双目视觉系统得到的全部可见三维光点构成无序集合，可能混合来自多个刚体目标。本文将目标识别与位姿估计统一表述为：在观测集合中搜索与模板几何结构相容的候选子集，恢复一一对应关系，并通过刚体配准求解目标位姿。其空间变换关系如图 2.13所示。
上述变量若直接联合搜索，计算量不适合在线导航。本文采用分层求解流程：先利用刚体距离不变量筛选候选子集，再利用局部几何签名恢复点对应，最后通过 SVD 刚体配准得到位姿，整体流程如图 2.14 所示。
对观测集合中的任一候选子集 ，计算同构的全局无序距离签名。当该签名与模板 的几何一致性误差不超过阈值 时，认为该候选子集的整体几何结构与模板 相容。
对候选集合中的任一子集 ，需要确定与模板局部有序几何签名相一致的点排列。模板点与子集点之间的一一对应关系可写为标准线性指派问题，即在约束条件下最小化总代价：
该线性指派问题采用匈牙利算法求解，其时间复杂度为 ，可得到模板点与候选观测点之间的最优对应关系，避免阶乘级排列枚举，适合在线目标识别。
随后构造协方差矩阵并进行奇异值分解，由此得到最优旋转矩阵和平移向量，其中修正项用于避免反射解，保证旋转矩阵属于 SO(3)。
经过上述步骤，系统即可将无序三维光点转换为带身份标签的刚体位姿。该位姿为超声图像空间定位、三维重建、器械标定和导航显示提供外部几何约束；5.3.1.1　 节通过定位系统、标定与动态跟踪实验给出相应误差边界。5.3', '2.13 svd 2.14 so 5.3.1.1 5.3 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 外 部 近 红 视 觉 外部 部近 近红 红外 外视 视觉 觉定 位系 目 标 姿 计 算 体 注 册 识 别 目标 标位 位姿 姿计 计算 算与 与物 物体 体注 注册 册识 识别 帧 双 得 到 全 可 见 光 点 构 成 无 序 集 合 双目 目视 觉系 统得 得到 到的 的全 全部 部可 可见 见三 维光 光点 点构 构成 成无 无序 序集 集合 能 混 来 自 多 个 刚 可能 能混 混合 合来 来自 自多 多个 个刚 刚体 体目 本 文 将 估 一 表 述 本文 文将 将目 标识 别与 与位 姿估 估计 计统 统一 一表 表述 述为 观 测 搜 索 模 板 几 何 结 相 容 候 选 子 在观 观测 测集 合中 中搜 搜索 索与 与模 模板 板几 几何 何结 结构 构相 相容 容的 的候 候选 选子 子集 恢 复 对 应 关 恢复 复一 一一 一对 对应 应关 关系 并 通 过 配 准 求 解 并通 通过 过刚 体配 配准 准求 求解 解目 其 空 间 变 换 如 图 其空 空间 间变 变换 换关 系如 如图 所 示 所示 上 量 若 直 接 联 上述 述变 变量 量若 若直 直接 接联 联合 合搜 不 适 线 导 航 算量 量不 不适 适合 合在 在线 线导 导航 采 用 分 层 流 程 文采 采用 用分 分层 层求 解流 流程 先 利 距 离 筛 先利 利用 用刚 体距 距离 离不 不变 量筛 筛选 选候 再 局 签 名 再利 用局 局部 部几 何签 签名 名恢 复点 点对 最 后 最后 后通 准得 到位 整 整体 体流 程如 任 对观 中的 的任 任一 一候 同 算同 同构 构的 全局 局无 序距 离签 当 该 当该 该签 名与 致 性 误 差 阈 值 的几 何一 一致 致性 性误 误差 差不 不超 超过 过阈 阈值 时 认 认为 为该 该候 集的 的整 体几 构与 对候 选集 一子 需 要 确 有 排 列 需要 要确 确定 定与 板局 部有 有序 序几 名相 相一 致的 的点 点排 排列 之 写 指 派 问 题 板点 点与 与子 集点 点之 之间 间的 的一 系可 可写 写为 为标 标准 准线 线性 性指 指派 派问 问题 即 约 束 条 件 下 小 化 总 代 价 即在 在约 约束 束条 条件 件下 下最 最小 小化 化总 总代 代价 匈 牙 法 该线 题采 用匈 匈牙 牙利 利算 算法 法求 杂 度 其时 时间 间复 复杂 杂度 度为 优 可得 到模 与候 选观 测点 的最 最优 优对 避 免 阶 乘 级 枚 举 避免 免阶 阶乘 乘级 级排 列枚 枚举 线目 随 造 协 方 矩 阵 进 行 奇 异 随后 后构 构造 造协 协方 方差 差矩 矩阵 阵并 并进 进行 行奇 奇异 异值 值分 分解 由 此 旋 转 平 移 向 由此 此得 到最 优旋 旋转 转矩 阵和 和平 平移 移向 向量 修 正 项 反 射 其中 中修 修正 正项 项用 用于 于避 免反 反射 射解 保 证 属 保证 证旋 阵属 属于 步 骤 经过 过上 述步 步骤 带 身 份 统即 即可 可将 将无 序三 点转 转换 换为 为带 带身 身份 份标 标签 签的 的刚 体位 像 该位 姿为 为超 声图 图像 像空 间定 器 械 显 提 供 器械 械标 标定 定和 和导 航显 显示 示提 提供 供外 何约 节 节通 过定 动 态 跟 踪 实 验 给 出 边 界 与动 动态 态跟 跟踪 踪实 实验 验给 给出 出相 相应 应误 差边 边界', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b7232503e6b3cfeb9eba05ce0841e2585ff337e33c00d4101ea9e40fcd72b7f3') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`,