INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6738fa9f3aa2c99a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 手术器械标定', '双目近红外定位系统输出的是参考架位姿，导航计算需要的是超声成像平面、针尖和目标组织在同一坐标系中的关系。因此，器械标定主要解决两类固定几何映射：超声图像坐标系到探头参考架坐标系的变换，以及针尖相对于针体参考架的偏移。前者决定二维超声切片如何进入三维空间，后者决定视觉测得的针体位姿如何转化为针尖位置。本节给出这两类映射的几何约束和优化目标；第5.3.2　 节报告具体采样、误差统计和重复性分析。', '5.3.2 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 手 术 器 械 标 手术 术器 器械 械标 标定 双 目 近 红 外 输 出 参 考 架 姿 双目 目近 近红 红外 外定 位系 统输 输出 出的 的是 是参 参考 考架 架位 位姿 导 航 计 算 需 要 成 像 平 面 导航 航计 计算 算需 需要 要的 是超 声成 成像 像平 平面 针 尖 组 织 同 一 坐 关 针尖 尖和 和目 目标 标组 组织 织在 在同 同一 一坐 坐标 标系 系中 中的 的关 关系 因 此 因此 主 解 决 两 类 固 几 何 映 射 定主 主要 要解 解决 决两 两类 类固 固定 定几 几何 何映 映射 图 到 探 头 变 换 声图 图像 像坐 系到 到探 探头 头参 架坐 系的 的变 变换 以 相 对 体 偏 移 以及 及针 尖相 相对 对于 于针 针体 体参 架的 的偏 偏移 前 者 二 切 片 如 进 入 空 间 前者 者决 决定 定二 二维 维超 声切 切片 片如 如何 何进 进入 入三 维空 空间 后 视 觉 测 得 转 化 置 后者 定视 视觉 觉测 测得 得的 的针 体位 姿如 何转 转化 化为 为针 尖位 位置 本 节 给 这 约 束 优 本节 节给 给出 出这 这两 类映 射的 的几 何约 约束 束和 和优 优化 化目 报 告 具 采 样 节报 报告 告具 具体 体采 采样 误 差 复 性 分 析 误差 差统 统计 计和 和重 重复 复性 性分 分析', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6738fa9f3aa2c99aacfb4e6c35aaefa478c4912882011e075921b3afc6afb281') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-49c5167eb94ccd3d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 手术器械标定 / 基于N线模型的超声探头空间标定', 'N线探头标定用于求解超声图像坐标系到探头参考架坐标系的标定矩阵。其基本思想是利用标定块中已知几何关系的N线与二维超声平面相交，在图像中形成可标注亮点，并由这些亮点恢复标定块坐标系中的三维点，从而建立空间点与像素点之间的对应。与普通点靶或平面靶相比，N线结构的优势在于交点深度由线组几何关系约束，不依赖人工测量成像平面位置。多姿态采样后，空间—像素对应点共同约束超声图像平面在探头参考架中的位置和方向。[161–163]
Figure . 3D structure of the N-wire calibration phantom
图 .16 N线探头标定中的图像平面、探头参考架与标定块坐标关系
Figure . Coordinate relationship among the image plane, probe reference frame, and N-wire phantom in ultrasound probe calibration.
图 .17 N线相似三角形约束与空间交点恢复原理
