INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ca37b4fa47d031c3', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 手术器械标定 / 穿刺针尖端空间标定', '双目近红外定位系统实时测得的是穿刺针参考架位姿，导航计算需要的是针尖位置。因此，针尖端空间标定需要求解针尖在参考架坐标系下的固定偏移，使参考架位姿能够转换为针尖工作点。该问题可用枢轴标定建模：针尖接触固定支点，器械围绕该点进行多姿态旋转。
图 2.18 穿刺针尖端旋转标定原理示意图
Figure . Schematic of pivot calibration for the puncture needle tip
如图 2.18 所示，多姿态采样提供同一针尖固定点在不同参考架姿态下的约束，既可以求解针尖偏移，也可以通过残差分布评估采样质量和异常姿态影响。设穿刺针参考架坐标系为 ，相机坐标系为 ；第 次采样时参考架姿态由 表示；针尖在参考架中的固定坐标为 ，固定支点在相机坐标系中的坐标为 。当针尖始终接触同一支点时，对任意采样时刻联立，可形成超定线性方程组
于是，可采用最小二乘法同时求得针尖在参考架坐标系下的偏移 与固定支点在世界坐标系下的位置 。', '2.18 figure schematic of pivot calibration for the puncture needle tip 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 手 术 器 械 标 手术 术器 器械 械标 标定 穿 刺 针 尖 端 空 间 穿刺 刺针 针尖 尖端 端空 空间 间标 双 目 近 红 外 实 时 测 得 参 考 架 姿 双目 目近 近红 红外 外定 位系 统实 实时 时测 测得 得的 的是 是穿 针参 参考 考架 架位 位姿 导 航 计 算 需 要 置 导航 航计 计算 算需 需要 要的 是针 尖位 位置 因 此 因此 求 解 坐 下 固 偏 移 定需 要求 求解 解针 尖在 在参 架坐 坐标 标系 系下 下的 的固 固定 定偏 偏移 使 能 够 转 换 工 作 点 使参 姿能 能够 够转 转换 换为 为针 尖工 工作 作点 该 问 题 可 用 枢 轴 模 该问 问题 题可 可用 用枢 枢轴 轴标 定建 建模 接 触 支 尖接 接触 触固 定支 支点 围 绕 进 行 多 态 旋 械围 围绕 绕该 该点 点进 进行 行多 多姿 姿态 态旋 旋转 图 原 示 意 端旋 转标 定原 原理 理示 示意 意图 如 如图 所 所示 采 样 提 供 同 一 不 约 束 态采 采样 样提 提供 供同 同一 一针 尖固 定点 点在 在不 不同 同参 架姿 态下 的约 约束 既 以 既可 可以 以求 尖偏 也 通 过 残 差 分 布 评 估 质 量 异 常 影 响 也可 以通 通过 过残 残差 差分 分布 布评 评估 估采 样质 质量 量和 和异 异常 常姿 态影 影响 设 设穿 系为 相 机 相机 机坐 次 由 次采 样时 时参 态由 表 表示 架中 中的 定坐 标为 在相 系中 的坐 当 始 终 当针 尖始 始终 终接 触同 一支 点时 对 任 刻 联 立 对任 任意 意采 时刻 刻联 联立 形 成 线 性 方 程 组 可形 形成 成超 超定 定线 线性 性方 方程 程组 于是 最 小 二 乘 法 可采 采用 用最 最小 小二 二乘 乘法 法同 同时 时求 求得 得针 的偏 世 界 与固 在世 世界 界坐 的位', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ca37b4fa47d031c3fa46fbb50aa2058e0359bbf602f150eae7692ccebe0bf393') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1d3c7fc29221477a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / 任务定义与列级筛选流程', '三维重建和语义神经场训练依赖可靠的二维观测。自由扫查得到的 B-mode 图像并不总是整帧有效：探头一侧可能保持连续组织回波，另一侧却因局部脱耦、声束遮挡或边缘压迫形成低信噪比黑区。若这类无效列直接参与三维优化，模型容易把缺失观测解释为空洞、伪影或不连续结构。本文因此将有效接触筛选定义为三维建模前的列级观测质量控制任务[74–76,81,82]，致力于实现列级/射线级细粒度的有效接触观测掩膜。从每帧图像中估计连续列级有效概率，从而判断各列附近的成像射线是否包含可信组织回波。设第 i 帧 B-mode 图像为 I_i，图像宽度为 W，第 j 个列锚点的有效接触标签为 y_(i,j)，则列级概率估计与二值判别写为：
其中， 表示第 j 列包含可信组织回波的条件概率，τ 为判别阈值。该定义把帧级质量判断转化为可直接约束三维射线的列级二元观测。
图 2.19 给出了列级有效接触筛选的数据流。系统首先以 B-mode 超声帧为输入，围绕列锚点构造局部多尺度上下文，并同步引入整帧全局上下文；随后将列级观测单元转化为可学习表征，经过 UMAP 流形降维和随机森林判别后得到有效接触概率；最后，后处理模块将离散列级概率转换为连续有效列掩膜。该流程输出观测可信度约束，用于决定哪些二维射线可以进入后续三维重建。列级筛选与三维建模由此形成明确分工：筛选模块在输入侧排除明显失效观测，降低三维模型用结构连续性去解释缺失回波的压力；三维重建模块则只在相对可信的观测区域内学习连续空间表示。', 'b-mode 74 76 81 82 2.19 umap 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 表 征 流 形 降 随 机 森 林 验 证 有 效 接 触 筛 选 于表 表征 征流 流形 形降 降维 维与 与随 随机 机森 森林 林验 验证 证的 的有 有效 效接 接触 触筛 筛选 任 务 义 列 级 程 任务 务定 定义 义与 与列 列级 级筛 选流 流程 语 训 练 依 赖 可 靠 二 观 测 建和 和语 语义 义神 场训 训练 练依 依赖 赖可 可靠 靠的 的二 二维 维观 观测 自 由 得 到 自由 由扫 查得 得到 到的 图 像 并 不 总 整 帧 图像 像并 并不 不总 总是 是整 整帧 帧有 探 头 一 侧 能 保 持 组 织 回 波 探头 头一 一侧 侧可 可能 能保 保持 持连 续组 组织 织回 回波 另 却 因 局 部 脱 耦 另一 侧却 却因 因局 局部 部脱 脱耦 束 遮 挡 或 边 缘 压 迫 成 低 信 噪 比 黑 区 声束 束遮 遮挡 挡或 或边 边缘 缘压 压迫 迫形 形成 成低 低信 信噪 噪比 比黑 黑区 若 这 类 无 直 参 优 化 若这 这类 类无 无效 效列 列直 直接 接参 参与 与三 维优 优化 模 型 容 易 把 缺 失 解 释 空 洞 模型 型容 容易 易把 把缺 缺失 失观 测解 解释 释为 为空 空洞 伪 影 结 构 伪影 影或 或不 不连 续结 结构 本 文 此 将 前 质 量 控 制 本文 文因 因此 此将 将有 选定 义为 为三 维建 建模 模前 前的 的列 级观 测质 质量 量控 控制 制任 致 力 实 现 致力 力于 于实 实现 现列 射 线 细 粒 度 掩 膜 射线 线级 级细 细粒 粒度 度的 触观 测掩 掩膜 从 每 估 计 概 率 从每 每帧 帧图 像中 中估 估计 计连 续列 级有 效概 概率 而 判 断 各 附 近 否 包 含 从而 而判 判断 断各 各列 列附 附近 近的 的成 成像 像射 线是 是否 否包 包含 含可 可信 信组 设 设第 像为 宽 像宽 宽度 度为 个 锚 点 标 签 个列 列锚 锚点 点的 触标 标签 签为 则 值 别 写 则列 级概 率估 计与 与二 二值 值判 判别 别写 写为 其 其中 示 表示 示第 条 件 列包 波的 的条 条件 件概 阈 为判 别阈 阈值 该 转 约 元 该定 义把 把帧 帧级 级质 量判 断转 转化 化为 为可 可直 接约 约束 束三 维射 线的 级二 二元 元观 给 出 数 据 给出 出了 了列 选的 的数 数据 据流 首 先 以 统首 首先 先以 输 入 声帧 帧为 为输 输入 围 绕 造 多 尺 上 下 围绕 绕列 点构 构造 造局 部多 多尺 尺度 度上 上下 下文 同 步 引 全 并同 同步 步引 引入 入整 帧全 全局 局上 后 单 学 习 随后 后将 将列 测单 单元 元转 可学 学习 习表 过 经过 维和 和随 林判 别后 后得 到有 触概 最 最后 处 块 离 散 换 后处 处理 理模 模块 块将 将离 离散 散列 率转 转换 换为 为连 续有 列掩 该流 程输 输出 出观 测可 信度 度约 用 决 哪 些 进 用于 于决 决定 定哪 哪些 些二 线可 可以 以进 进入 入后 后续 续三 明 确 分 工 选与 模由 由此 此形 成明 明确 确分 分工 排 除 显 选模 块在 在输 入侧 侧排 排除 除明 明显 显失 失效 效观 性 去 降低 低三 维模 型用 用结 构连 续性 性去 去解 释缺 失回 的压 压力 只 相 对 域 内 间 块则 则只 只在 在相 相对 对可 信的 的观 测区 区域 域内 内学 习连 续空 空间 间表', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1d3c7fc29221