INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-9ed7fa41f53fbc38', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / 任务定义与列级筛选流程', '该流程输出观测可信度约束，用于决定哪些二维射线可以进入后续三维重建。列级筛选与三维建模由此形成明确分工：筛选模块在输入侧排除明显失效观测，降低三维模型用结构连续性去解释缺失回波的压力；三维重建模块则只在相对可信的观测区域内学习连续空间表示。
