INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f885aae0df3d6f1c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / USF-MAE 表征与 UMAP 流形降维假设', '列级筛选需要能够同时感知局部纹理、阴影衰减、边界连续性和整帧上下文的表征。USFM[79]、USF-MAE[76]、OpenUS[77] 等超声基础模型通过多器官、多中心和多设备数据学习通用声像特征，为弱接触识别提供了比自然图像预训练更贴近超声成像机制的编码器。本文选择 USF-MAE 作为列级特征编码器，是因为 masked autoencoding[78] 任务与局部缺失回波、斑点纹理恢复和上下文一致性判断更为接近，其有效性由本章降维和判别器对比实验共同评价。
具体而言，局部多尺度窗口经过 USF-MAE 编码后提供列邻域的纹理与边界线索，整帧 USF-MAE 描述子提供全局成像上下文，位置编码则把归一化横坐标、周期编码和边缘距离作为软空间先验加入特征。三者共同构成最终列级特征：局部窗口负责回答“这一列附近是否存在有效回波”，全局描述子负责回答“当前帧整体成像状态如何”，位置编码负责补充“失效是否位于常见边缘或横向连续区域”[76,78]。
设 为以第列为中心、尺度为 的局部窗口， 为共享的USF-MAE 编码器， 为位置编码，则融合列级特征表示为：
该式将局部尺度描述子、整帧全局描述子与归一化横向位置连接到统一特征空间。局部项刻画散斑与边界回波，全局项提供成像状态参照，位置项补充边缘失效的空间先验。', 'usf-mae umap usfm 79 76 openus 77 masked autoencoding 78 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 表 征 流 形 降 随 机 森 林 验 证 有 效 接 触 筛 选 于表 表征 征流 流形 形降 降维 维与 与随 随机 机森 森林 林验 验证 证的 的有 有效 效接 接触 触筛 筛选 征与 假 设 维假 假设 列 级 需 要 能 够 同 时 感 知 局 部 纹 列级 级筛 选需 需要 要能 能够 够同 同时 时感 感知 知局 局部 部纹 纹理 阴 影 衰 减 阴影 影衰 衰减 边 界 性 整 帧 上 下 文 边界 界连 续性 性和 和整 整帧 帧上 上下 下文 文的 的表 等 础 模 型 通 过 多 器 官 等超 声基 基础 础模 模型 型通 通过 过多 多器 器官 心 备 数 据 学 习 用 像 特 多中 中心 心和 和多 多设 设备 备数 数据 据学 学习 习通 通用 用声 声像 像特 特征 弱 识 别 提 供 比 自 然 图 预 训 练 更 贴 近 成 制 编 码 为弱 弱接 触识 识别 别提 提供 供了 了比 比自 自然 然图 图像 像预 预训 训练 练更 更贴 贴近 近超 声成 成像 像机 机制 制的 的编 编码 码器 本 择 本文 文选 选择 作 作为 为列 级特 征编 因 是因 因为 任 务 缺 失 回 波 任务 务与 与局 部缺 缺失 失回 回波 斑 点 恢 复 一 致 判 断 斑点 点纹 理恢 恢复 复和 和上 文一 一致 致性 性判 判断 断更 更为 为接 接近 其 由 对 实 共 评 价 其有 效性 性由 由本 本章 章降 维和 和判 判别 别器 器对 对比 比实 实验 验共 共同 同评 评价 具 体 而 言 具体 体而 而言 尺 度 窗 口 部多 多尺 尺度 度窗 窗口 口经 经过 后 邻 域 线 索 码后 后提 供列 列邻 邻域 域的 的纹 与边 界线 线索 描 述 子 全 描述 述子 子提 供全 全局 局成 像上 置 则 把 归 化 横 坐 标 位置 置编 码则 则把 把归 归一 一化 化横 横坐 坐标 周 期 缘 距 离 软 空 间 先 加 入 周期 期编 码和 和边 边缘 缘距 距离 离作 为软 软空 空间 间先 先验 验加 加入 入特 者 构 最 终 三者 者共 同构 构成 成最 最终 终列 负 责 答 部窗 口负 负责 责回 回答 这 附 否 存 这一 一列 列附 附近 近是 是否 否存 存在 在有 效回 局描 子负 当 前 状 态 如 何 当前 前帧 帧整 整体 体成 像状 状态 态如 如何 补 充 码负 责补 补充 常 见 或 向 区 失效 效是 否位 位于 于常 常见 见边 缘或 或横 横向 向连 续区 区域 以 为以 以第 第列 列为 为中 度为 的局 享 为共 共享 享的 为位 融 合 示 则融 融合 合列 征表 表示 示为 该 式 将 该式 式将 将局 部尺 度描 到 帧全 子与 与归 向位 置连 连接 接到 到统 统一 一特 征空 项 刻 画 散 部项 项刻 刻画 画散 散斑 斑与 界回 参 照 局项 项提 供成 态参 参照 置项 项补 充边 缘失 效的 的空', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f885aae0df3d6f1cd0ecbbcad616fa7dd4ae0037a14800cf775aed1086ab40b1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash