INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1c70df1f98894da5', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / USF-MAE 表征与 UMAP 流形降维假设', '为 的局部窗口， 为共享的USF-MAE 编码器， 为位置编码，则融合列级特征表示为：
该式将局部尺度描述子、整帧全局描述子与归一化横向位置连接到统一特征空间。局部项刻画散斑与边界回波，全局项提供成像状态参照，位置项补充边缘失效的空间先验。
图 .21 局部弱接触样本中 USF-MAE 描述子的二维嵌入可视化
Figure . 2D embedding of USF-MAE descriptors for partial weak-contact samples.
图 .22 局部弱接触样本中 USF-MAE 描述子的三维嵌入可视化
Figure . 3D embedding of USF-MAE descriptors for partial weak-contact samples.
在此基础上，UMAP通过近邻图保持局部拓扑，以提取USF-MAE表征中与接触状态相关的非线性结构[81]。若该表征包含有效接触信息，不同有效列比例的样本应在低维空间连续分布；相较于随机投影和线性PCA，UMAP预期能够更好地维持边界样本的邻域关系，从而改善列IoU、无效列F1和边界MAE。图 2.21 和图 2.22 分别从二维和三维嵌入角度验证上述假设。二维嵌入中，真实有效列比例沿嵌入空间呈现连续变化，说明接触质量与超声域自监督特征之间存在可学习关系；三维嵌入进一步保留了邻域展开关系。与 PCA 的线性带状分布相比，UMAP 更容易把接触状态相近的局部弱接触样本组织为邻近簇，从而为后续列级判别提供更合适的低维表征。', 'usf-mae umap 21 figure 2d embedding of descriptors for partial weak-contact samples. 22 3d 81 pca iou f1 mae 2.21 2.22 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 表 征 流 形 降 随 机 森 林 验 证 有 效 接 触 筛 选 于表 表征 征流 流形 形降 降维 维与 与随 随机 机森 森林 林验 验证 证的 的有 有效 效接 接触 触筛 筛选 征与 假 设 维假 假设 局 部 窗 口 的局 局部 部窗 窗口 共 享 为共 共享 享的 编 码 器 编码 码器 置 为位 位置 置编 则 融 合 列 级 特 示 则融 融合 合列 列级 级特 特征 征表 表示 示为 该 式 将 尺 度 描 述 子 该式 式将 将局 部尺 尺度 度描 描述 述子 整 帧 全 归 一 化 横 向 到 空 间 整帧 帧全 全局 局描 子与 与归 归一 一化 化横 横向 向位 置连 连接 接到 到统 统一 一特 征空 空间 项 刻 画 散 斑 边 界 回 波 部项 项刻 刻画 画散 散斑 斑与 与边 边界 界回 回波 提 供 成 像 状 态 参 照 局项 项提 提供 供成 成像 像状 状态 态参 参照 补 充 缘 失 先 置项 项补 补充 充边 边缘 缘失 失效 效的 的空 间先 先验 图 弱 样 本 部弱 弱接 触样 样本 本中 二 嵌 入 可 视 子的 的二 二维 维嵌 嵌入 入可 可视 视化 的三 此 础 上 在此 此基 基础 础上 通 过 近 邻 保 持 拓 扑 通过 过近 近邻 邻图 图保 保持 持局 部拓 拓扑 以 取 以提 提取 相 关 非 线 性 结 构 征中 中与 与接 触状 态相 相关 关的 的非 非线 线性 性结 结构 若 包 含 信 息 若该 该表 征包 包含 含有 触信 信息 不 同 比 例 应 低 分 布 不同 同有 效列 列比 比例 例的 的样 本应 应在 在低 低维 维空 间连 续分 分布 较 投 影 相较 较于 于随 机投 投影 影和 和线 预 期 能 够 更 好 地 域 预期 期能 能够 够更 更好 好地 地维 维持 持边 界样 本的 的邻 邻域 域关 关系 从 而 改 善 从而 而改 改善 善列 无 无效 和边 和图 别 角 分别 别从 从二 维和 和三 入角 角度 度验 证上 上述 述假 入中 真 实 沿 呈 现 变 真实 实有 例沿 沿嵌 入空 间呈 呈现 现连 续变 变化 说 明 质 量 自 监 督 之 存 学 习 说明 明接 触质 质量 量与 与超 声域 域自 自监 监督 督特 征之 之间 间存 存在 在可 可学 学习 习关 进 步 留 展 开 入进 进一 一步 步保 保留 留了 了邻 域展 展开 开关 带 的线 性带 带状 状分 布相 相比 容 易 把 组 织 簇 更容 容易 易把 把接 相近 近的 本组 组织 织为 为邻 邻近 近簇 后 判 适 而为 为后 后续 续列 级判 判别 别提 供更 更合 合适 适的 的低 维表', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1c70df1f98894da5d993e81995cfeedfbdd080533e337f37738f52a2b5db06e6') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`