INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-18ddedf510542d01', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / 随机森林判别与后处理', 'UMAP降维后的列级表征需由分类器估计有效接触概率。为检验其在不同判别假设下的可分性，本文比较KNN、ElasticNet、SVC、XGBoost和随机森林：KNN 侧重局部邻域一致性，ElasticNet 和 SVC 提供线性或间隔型基线，XGBoost 与 Random Forest 则利用树模型刻画非线性特征组合。随机森林利用自助采样和特征随机子空间降低模型方差与树间相关性，从而减弱噪声列和局部伪影的影响，更适合处理由USF-MAE描述子、位置编码及多尺度上下文构成的混合特征[82]。据此，本文将随机森林作为主要判别器，其余模型作为对照。
设 维映射，h_t(·) 为第 t 棵决策为树的数量， 为包含阈值化与最短连续区间约束的一维后处理算子，则降维表征、集成概率与连续掩膜分别写为：
其中，为低，为树集成后的有效接触概率， 为允许保留的最短连续列区间。两式明确区分表征压缩、概率判别和空间连续性约束三个环节。判别器输出的是离散列锚点上的有效接触概率，后处理模块进一步将概率序列转换为连续列掩膜，并抑制孤立误判列对射线筛选的影响。', 'umap knn elasticnet svc xgboost random forest usf-mae 82 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 表 征 流 形 降 随 机 森 林 验 证 有 效 接 触 筛 选 于表 表征 征流 流形 形降 降维 维与 与随 随机 机森 森林 林验 验证 证的 的有 有效 效接 接触 触筛 筛选 判 别 后 处 林判 判别 别与 与后 后处 处理 列 级 需 由 分 类 器 估 计 概 率 维后 后的 的列 列级 级表 征需 需由 由分 分类 类器 器估 估计 计有 触概 概率 检 其 不 同 假 设 下 可 性 为检 检验 验其 其在 在不 不同 同判 别假 假设 设下 下的 的可 可分 分性 本 文 比 较 本文 文比 比较 和随 侧 局 部 邻 域 一 致 侧重 重局 局部 部邻 邻域 域一 一致 致性 提 供 线 或 间 隔 型 提供 供线 线性 性或 或间 间隔 隔型 型基 基线 则 利 用 树 模 刻 画 非 特 组 合 则利 利用 用树 树模 模型 型刻 刻画 画非 非线 性特 特征 征组 组合 自 助 采 样 子 空 低 方 差 相 关 林利 用自 自助 助采 采样 样和 和特 征随 机子 子空 空间 间降 降低 低模 型方 方差 差与 与树 树间 间相 相关 关性 从 而 减 弱 噪 伪 影 响 从而 而减 减弱 弱噪 噪声 声列 列和 和局 部伪 伪影 影的 的影 影响 更 适 更适 适合 合处 理由 描 述 描述 述子 置 编 码 多 尺 度 上 构 成 混 位置 置编 编码 码及 及多 多尺 尺度 度上 上下 下文 文构 构成 成的 的混 混合 合特 据 此 据此 将 作 主 要 文将 将随 林作 作为 为主 主要 要判 别器 余 对 照 其余 余模 型作 为对 对照 映 射 维映 映射 为第 棵 决 策 数 量 棵决 决策 策为 为树 树的 的数 数量 包 含 阈 值 化 最 短 区 约 束 算 为包 包含 含阈 阈值 值化 化与 与最 最短 短连 续区 区间 间约 约束 束的 的一 一维 理算 算子 则降 维表 集 掩 膜 写 集成 成概 率与 续掩 掩膜 膜分 分别 别写 写为 其中 为低 树集 成后 允 许 保 留 为允 允许 许保 保留 留的 的最 续列 列区 两 式 明 确 压 缩 两式 式明 明确 确区 区分 分表 征压 压缩 个 环 节 率判 别和 和空 间连 续性 性约 束三 三个 个环 环节 输 出 离 散 锚 点 器输 输出 出的 的是 是离 离散 散列 列锚 锚点 点上 上的 块 进 步 序 转 换 理模 模块 块进 进一 一步 步将 将概 率序 序列 列转 转换 换为 为连 列掩 并 抑 制 孤 立 误 并抑 抑制 制孤 孤立 立误 误判 判列 列对 对射 射线 线筛 选的', '/#research', 'doctoral-thesis', 1, '2026-08-04', '18ddedf510542d016df3ef52fa21039e216823e8469755f83c0a109c31a8cf2a') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0e7f10da5c71092e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / 实验结果与分析', '实验评价采用统一图像划分、统一列锚点、统一局部弱接触标注和统一后处理规则。指标分为两类：列 IoU、无效列 F1 和边界 MAE 评价掩膜质量；输入维度和平均耗时评价计算代价。这样的设计可以同时回答三个问题：USF-MAE 表征是否能够提供有效接触信息，UMAP 是否能在压缩后保留关键流形结构，以及随机森林是否能把低维表征转化为稳定的有效列掩膜[76,78,81,82]。
