INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ba5de18d687ae577', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声定位与扫查系统 / 基于表征流形降维与随机森林验证的有效接触筛选 / 实验结果与分析', '经UMAP压缩后较随机投影和PCA更好地保持边界样本的邻域关系；随机森林进一步将该表征转化为稳定的列级有效概率。表 2.1中，UMAP+Random Forest取得当前验证集的最佳综合结果，因而被选为有效接触筛选组合。[76,81,82]
本节形成了由外部位姿测量、探头与器械标定以及列级有效接触筛选组成的观测获取链。前两者建立二维图像与世界坐标系的几何关系，后者限定可参与优化的可靠成像列；2.5　 节据此比较离散与连续三维表征。', 'umap pca 2.1 umap+random forest 76 81 82 2.5 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 定 位 扫 查 系 统 声定 定位 位与 与扫 扫查 查系 系统 表 征 流 形 降 随 机 森 林 验 证 有 效 接 触 筛 选 于表 表征 征流 流形 形降 降维 维与 与随 随机 机森 森林 林验 验证 证的 的有 有效 效接 接触 触筛 筛选 实 结 果 分 析 实验 验结 结果 果与 与分 分析 压 缩 后 较 投 影 压缩 缩后 后较 较随 机投 投影 影和 更 好 地 保 持 边 界 样 本 邻 域 关 更好 好地 地保 保持 持边 边界 界样 样本 本的 的邻 邻域 域关 关系 进 一 步 将 该 转 化 稳 列 级 概 率 林进 进一 一步 步将 将该 该表 征转 转化 化为 为稳 稳定 定的 的列 列级 级有 效概 概率 取 得 当 前 集 最 佳 综 合 取得 得当 当前 前验 证集 集的 的最 最佳 佳综 综合 合结 因 而 被 组 因而 而被 被选 选为 为有 选组 组合 节 成 由 外 部 姿 测 量 本节 节形 形成 成了 了由 由外 外部 部位 位姿 姿测 测量 探 头 器 械 标 以 观 获 链 探头 头与 与器 器械 械标 标定 定以 以及 及列 组成 成的 的观 观测 测获 获取 取链 两 者 立 二 图 像 世 坐 几 何 前两 两者 者建 建立 立二 二维 维图 图像 像与 与世 世界 界坐 坐标 标系 系的 的几 几何 何关 限 可 参 优 靠 后者 者限 限定 定可 可参 参与 与优 优化 化的 的可 可靠 靠成 成像 像列 据 此 比 离 散 节据 据此 此比 比较 较离 离散 散与 续三 维表', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ba5de18d687ae57781637f799a56df8caffc81c8db2ad28ed4a9ec7834f104ee') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3b4d59b171140f16', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征', '完成二维超声图像向三维规范空间的映射后，重建的关键转向三维场景表征。该表征既需整合不规则采样数据，保留解剖结构与声学纹理，又需支持任意视角下的图像合成。现有方法主要分为离散体素表征与连续神经场表征两类：前者以离散三维网格直接存储体素值，后者通过参数化连续函数隐式编码场景，并依据空间坐标与视角方向查询场值，结合成像模型生成目标视角的图像响应[33,34]。鉴于二者在空间连续性、存储形式、查询机制和跨视角合成能力方面存在差异，下文将对其进行系统比较，并据此说明本文选择连续神经场作为主要表征的依据。', '33 34 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 完 成 二 图 像 向 规 范 空 间 映 射 后 完成 成二 二维 维超 声图 图像 像向 向三 维规 规范 范空 空间 间的 的映 映射 射后 关 键 转 景 建的 的关 关键 键转 转向 维场 场景 景表 该 既 需 整 合 不 则 采 样 数 据 该表 征既 既需 需整 整合 合不 不规 规则 则采 采样 样数 数据 保 留 解 剖 结 构 学 纹 保留 留解 解剖 剖结 结构 构与 与声 声学 学纹 纹理 又 支 持 任 意 视 角 下 又需 需支 支持 持任 任意 意视 视角 角下 下的 的图 像合 合成 现 有 方 法 主 要 分 两 类 现有 有方 方法 法主 主要 要分 分为 为离 征两 两类 前 者 以 网 格 直 接 存 储 值 前者 者以 以离 散三 维网 网格 格直 直接 接存 存储 储体 素值 通 过 参 化 函 隐 式 编 码 后者 者通 通过 过参 参数 数化 化连 续函 函数 数隐 隐式 式编 编码 码场 并 依 坐 标 查 询 并依 依据 据空 间坐 坐标 标与 与视 角方 方向 向查 查询 询场 场值 模 型 生 目 响 应 结合 成像 像模 模型 型生 生成 成目 目标 标视 角的 像响 响应 鉴 性 鉴于 于二 二者 者在 在空 间连 续性 形 储形 形式 机 制 跨 能 力 面 差 异 询机 机制 制和 和跨 跨视 角合 成能 能力 力方 方面 面存 存在 在差 差异 文 将 对 其 进 行 系 统 比 较 下文 文将 将对 对其 其进 进行 行系 系统 统比 比较 此 说 明 本 选 择 作 并据 据此 此说 说明 明本 本文 文选 选择 择连 场作 作为 为主 要表 征的 的依', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3b4d59b171140f16ef5c6458144ca298e247669ef07522b57b2600ddd812e22e') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d10bd13d2e69d526', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / 传统体素网格三维重建方法', '传统超声三维重建方法通常采用离散体素表征，即在离散三维网格中保存空间位置对应的超声强度。其共同机制是：根据每帧二维超声图像的空间位姿将像素映射到三维规范空间，再通过重采样或插值算子把离散观测累积到体素网格中；当需要任意切面显示或体渲染时，再从该网格中进行邻域查询。
从形式上看，每一帧二维超声图像可视为带有空间位姿的切片点云。设第 k 帧图像经位姿映射后形成点集，其中每个点包含三维坐标及对应图像强度；体素网格重建的目标是在体素网格中汇聚邻域切片观测，得到每个体素的重建强度值
其中，局部邻域和重采样算子可由最近邻、距离加权、核函数加权或局部拟合等策略实现[24–28]。这类方法的差异主要体现在“由体素寻找邻近像素”还是“由像素填充邻近体素”，但最终都依赖离散网格和局部插值完成空间查询。
围绕上述体素网格，体素网格重建主要包含体素驱动和像素驱动两类路线。
图 .24 三维体素网格 VNN 重建 [13]
Figure . Voxel-nearest-neighbor reconstruction based on a 3D voxel grid.
图 .25 三维体素网格的相邻切片插值 [13]
Figure . Voxel-based interpolation from two surrounding images.', '24 28 vnn 13 figure voxel-nearest-neighbor reconstruction based on 3d voxel grid. 25 voxel-based interpolation from two surrounding images. 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 传 统 网 格 方 法 传统 统体 素网 网格 格三 建方 方法 通 常 采 用 统超 法通 通常 常采 采用 用离 即 保 存 空 间 位 置 对 应 强 度 即在 在离 散三 维网 格中 中保 保存 存空 空间 间位 位置 置对 对应 应的 声强 强度 其 共 同 机 制 其共 共同 同机 机制 制是 根 据 每 帧 二 图 像 姿 将 映 射 到 规 范 根据 据每 每帧 帧二 二维 维超 声图 图像 像的 的空 位姿 姿将 将像 像素 素映 映射 射到 到三 维规 规范 范空 再 过 样 或 插 值 算 子 把 观 测 累 积 再通 通过 过重 重采 采样 样或 或插 插值 值算 算子 子把 把离 散观 观测 测累 累积 积到 到体 当 需 要 任 意 切 面 显 示 渲 染 时 当需 需要 要任 任意 意切 切面 面显 显示 示或 或体 体渲 渲染 染时 从 该 进 行 邻 域 查 询 再从 从该 该网 中进 进行 行邻 邻域 域查 查询 形 式 上 看 从形 形式 式上 上看 一 可 视 带 有 片 点 云 每一 一帧 像可 可视 视为 为带 带有 有空 姿的 的切 切片 片点 点云 设 设第 后 成 集 帧图 像经 经位 姿映 射后 后形 形成 成点 点集 个 包 含 坐 标 其中 中每 每个 个点 点包 包含 含三 维坐 坐标 标及 及对 应图 像强 目 汇 聚 格重 建的 的目 目标 标是 是在 在体 中汇 汇聚 聚邻 域切 片观 得 得到 到每 个体 素的 的重 建强 度值 局 部 由 最 近 局部 部邻 域和 和重 样算 子可 可由 由最 最近 近邻 距 加 权 距离 离加 加权 核 函 数 拟 合 等 策 略 实 现 核函 函数 数加 权或 或局 部拟 拟合 合等 等策 策略 略实 实现 这 类 差 异 主 这类 类方 法的 的差 差异 异主 主要 要体 体现 现在 寻 找 由体 素寻 寻找 找邻 邻近 近像 还 还是 填 充 由像 素填 填充 充邻 近体 但 终 都 依 赖 完 但最 最终 终都 都依 依赖 赖离 散网 格和 和局 部插 值完 完成 成空 间查 围 绕 述 围绕 绕上 上述 述体 驱 动 两 路 线 建主 要包 含体 素驱 驱动 动和 和像 动两 两类 类路 路线 维体 相 格的 的相 相邻 邻切 片插', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd10bd13d2e69d526d35e91e867a7252627690ff33d2c5e7b820a8990a9019db6') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
