INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5fa5c457ea67a212', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / 传统体素网格三维重建方法', '锯齿和过度平滑问题。
图 .28 三维超声体数据的切面与整体渲染[13]
Figure . Slice interrogation and global volume rendering of ultrasound volume data.
图 .29 直接光线投射体渲染 [13]
Figure . Direct ray-casting volume rendering.
如图 2.30 所示，基于体素网格的三维重建方法在三维表征阶段先将二维超声切片点云重采样到离散体素网格中；在新视角渲染阶段，再对查询位置附近的体素值进行局部插值，以获得对应图像强度。该图直观体现了体素网格方法“先离散存储、后邻域查询”的基本思路[24–28]。
图 2.30 基于体素网格的三维重建方法的表征与查询机制示意图
Figure . Representation and querying in voxel-grid 3D reconstruction.
基于体素网格的三维重建方法的瓶颈在于先将观测压缩到离散网格，再依赖邻域插值完成查询，因此难以表达方向相关的超声回波特征，并且在高分辨率体数据中面临显著的内存与计算开销。此外其离散存储和局部插值机制决定了它对采样密度、扫查轨迹和位姿精度较为敏感。第2.7.2　 节的稀疏视图实验进一步表明：当训练视图数量减少时，离散体素方法更容易出现撕裂和模糊，而连续神经场表征能够在多视角一致性约束下获得更稳定的结构表达[13,29,30,37]。', '28 13 figure slice interrogation and global volume rendering of ultrasound data. 29 direct ray-casting rendering. 2.30 24 representation querying in voxel-grid 3d reconstruction. 2.7.2 30 37 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 传 统 网 格 方 法 传统 统体 素网 网格 格三 建方 方法 锯 齿 过 度 平 滑 问 题 锯齿 齿和 和过 过度 度平 平滑 滑问 问题 图 数 据 切 面 整 渲 染 维超 声体 体数 数据 据的 的切 切面 面与 与整 整体 体渲 渲染 直 接 光 线 投 射 直接 接光 光线 线投 投射 射体 如 如图 所 示 所示 阶 段 先 将 二 片 点 云 采 样 到 于体 格的 的三 法在 在三 维表 征阶 阶段 段先 先将 将二 二维 声切 切片 片点 点云 云重 重采 采样 样到 到离 格中 新 视 角 在新 新视 视角 角渲 染阶 再 对 查 询 位 置 附 近 值 进 行 局 部 插 再对 对查 查询 询位 位置 置附 附近 近的 的体 素值 值进 进行 行局 局部 部插 插值 以 获 得 应 像 强 以获 获得 得对 对应 应图 图像 像强 强度 该 观 现 该图 图直 直观 观体 体现 现了 了体 格方 存 储 先离 散存 存储 后 邻 域 后邻 邻域 域查 本 思 路 的基 基本 本思 思路 机 制 意 法的 的表 与查 询机 机制 制示 示意 意图 瓶 颈 测 压 缩 的瓶 瓶颈 颈在 在于 于先 将观 观测 测压 压缩 缩到 散网 依 赖 完 成 再依 依赖 赖邻 域插 值完 完成 成查 因 此 难 达 向 相 关 回 波 特 因此 此难 难以 以表 表达 达方 方向 向相 相关 关的 声回 回波 波特 特征 并 且 高 分 辨 率 临 显 著 内 计 算 开 销 并且 且在 在高 高分 分辨 辨率 率体 据中 中面 面临 临显 显著 著的 的内 内存 存与 与计 计算 算开 开销 外 其 决 定 它 密 此外 外其 其离 储和 和局 值机 制决 决定 定了 了它 它对 对采 样密 密度 扫 轨 迹 姿 精 较 敏 感 扫查 查轨 轨迹 迹和 和位 位姿 姿精 精度 度较 较为 为敏 敏感 节 稀 疏 实 验 一 步 明 节的 的稀 稀疏 疏视 视图 图实 实验 验进 进一 一步 步表 表明 当 训 练 量 减 少 时 当训 训练 练视 图数 数量 量减 减少 少时 更 容 易 出 撕 裂 模 糊 素方 法更 更容 容易 易出 出现 现撕 撕裂 裂和 和模 模糊 而 能 够 多 致 性 约 束 下 稳 结 构 而连 征能 能够 够在 在多 多视 角一 一致 致性 性约 约束 束下 下获 得更 更稳 稳定 定的 的结 结构 构表', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5fa5c457ea67a2122935f7dfd5ce2d6166ee32a080ae5cea21ce4be6d81a7753') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_v