INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-c87d333b631c2076', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / 基于NeRF的连续神经场三维重建方法', '传统体素网格方法为超声三维重建提供了直观而成熟的实现路径，但其在连续表达与高质量视图合成方面仍存在局限，因此有必要进一步引入以神经场为代表的连续神经场表征方法[23,32,38,39]。连续神经场通过坐标驱动的多层感知机建立查询坐标到场景属性的映射，无需在三维空间保存逐体素离散强度。设查询位置与方向分别为 和 ，则神经场网络 可以直接对该位置处的场景属性进行预测：
其中， 表示该位置局部三维场属性的参数化结果。随后通过参数化成像或渲染算子 ，将其转换为最终图像响应：
与离散体素表征相比，神经场通过连续函数计算任意空间位置与方向上的中间属性和图像响应，无需在体素网格中查询离散强度。三维信息编码于网络参数 中，形成一个全局共享、连续可查询的三维场景表示。
在训练阶段，连续神经场表征通常采用多视图二维图像作为监督信号，在已知位姿条件下，通过最小化合成图像与真实图像之间的差异，学习一个能够同时解释所有视角观测的统一三维场景表示：
其中， 表示在成像配置 下，通过神经场与渲染算子生成的合成图像。由于所有训练视角共享同一组网络参数，这一优化过程实际上等价于寻找一个统一的连续三维表示，使其能够同时解释所有视角下的观测图像，从而天然引入多视角一致性约束。', 'nerf 23 32 38 39 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 方 法 的连 场三 建方 方法 传 统 网 格 提 供 直 观 而 成 熟 实 现 路 径 传统 统体 素网 网格 格方 法为 为超 建提 提供 供了 了直 直观 观而 而成 成熟 熟的 的实 实现 现路 路径 但 其 达 高 质 量 视 图 合 面 仍 存 局 限 但其 其在 在连 续表 表达 达与 与高 高质 质量 量视 视图 图合 合成 成方 方面 面仍 仍存 存在 在局 局限 因 此 有 必 要 进 一 步 引 入 以 代 因此 此有 有必 必要 要进 进一 一步 步引 引入 入以 以神 场为 为代 代表 表的 征方 通 过 坐 标 驱 动 多 层 感 知 机 立 查 询 到 景 属 性 映 射 场通 通过 过坐 坐标 标驱 驱动 动的 的多 多层 层感 感知 知机 机建 建立 立查 查询 询坐 标到 到场 场景 景属 属性 性的 的映 映射 无 需 空 间 保 逐 强 度 无需 需在 在三 维空 空间 间保 保存 存逐 逐体 素离 散强 强度 设 位 置 向 分 别 设查 询位 位置 置与 与方 方向 向分 分别 别为 则 络 则神 场网 网络 可 接 对 该 处 行 预 测 可以 以直 直接 接对 对该 该位 置处 处的 的场 性进 进行 行预 预测 其中 示 部 参 数 化 结 果 表示 示该 置局 局部 部三 维场 场属 的参 参数 数化 化结 结果 随 后 像 或 渲 染 算 子 随后 后通 过参 化成 成像 像或 或渲 渲染 染算 算子 将 转 换 最 终 响 应 将其 其转 转换 换为 为最 最终 终图 图像 像响 响应 相 比 与离 征相 相比 函 计 任 意 上 过连 续函 函数 数计 计算 算任 任意 意空 间位 向上 上的 的中 中间 间属 性和 和图 在体 格中 中查 询离 信 息 编 码 维信 信息 息编 编码 码于 于网 络参 形 个 全 共 享 形成 成一 一个 个全 全局 局共 共享 续可 可查 询的 的三 景表 训 练 阶 段 在训 训练 练阶 阶段 常 采 用 二 作 监 督 号 征通 通常 常采 采用 用多 多视 图二 二维 维图 像作 作为 为监 监督 督信 信号 已 姿 条 件 下 在已 已知 知位 位姿 姿条 条件 件下 小 真 之 差 异 过最 最小 小化 化合 成图 像与 与真 真实 实图 像之 之间 间的 的差 差异 学 习 能 够 同 时 解 释 所 角 学习 习一 个能 能够 够同 同时 时解 解释 释所 所有 有视 视角 角观 观测 测的 的统 统一 一三 配 示在 在成 像配 配置 生 过神 场与 与渲 子生 生成 成的 的合 由 组 由于 于所 有训 练视 角共 享同 同一 一组 组网 这 优 程 际 等 价 寻 找 这一 一优 优化 化过 过程 程实 实际 际上 上等 等价 价于 于寻 寻找 找一 个统 一的 续三 维表 使 使其 其能 角下 下的 的观 测图 从 天 然 致 约 束 从而 而天 天然 然引 入多 角一 一致 致性 性约 约束', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'c87d333b631c2076313996189bc916816528e64d4d134a84674fda824e60c623') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=exclu