INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e0199454cde6675b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / 基于NeRF的连续神经场三维重建方法', '统一三维场景表示：
其中， 表示在成像配置 下，通过神经场与渲染算子生成的合成图像。由于所有训练视角共享同一组网络参数，这一优化过程实际上等价于寻找一个统一的连续三维表示，使其能够同时解释所有视角下的观测图像，从而天然引入多视角一致性约束。
图 2.31 基于连续神经场的三维重建方法的表征与渲染机制示意图
Figure . Representation and rendering in continuous neural-field reconstruction.
为了克服离散体素网格的固有缺陷，连续神经场表征提供了连续空间建模范式。如图 2.31所示，与离散体素网格直接存储空间灰度值不同，神经场方法通过坐标驱动的 MLP 对规范空间中的连续三维场进行参数化表示，再结合参数化渲染模型生成最终二维超声图像。与图 2.30的离散体素表征机制形成对照后，可以更清晰地看出：体素网格方法强调“离散网格存储”，而神经场方法强调“连续函数表示”。由此，神经场方法将三维重建转化为一个连续场表示学习与可微渲染联合优化的问题。由于所有观测图像共享同一组网络参数，因此多视图之间天然存在全局一致性约束。这一点与体素网格方法中“每个体素局部插值、局部更新”的机制有本质不同。据此可提出先验预测：当训练视图减少时，连续神经场表征应比传统离散体素方法更好地保持结构精度与纹理质量；第2.7.2　 节的稀疏视图实验据此检验该先验预测。[33,34,40,41]', 'nerf 2.31 figure representation and rendering in continuous neural-field reconstruction. mlp 2.30 2.7.2 33 34 40 41 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 方 法 的连 场三 建方 方法 统 一 景 示 统一 一三 维场 场景 景表 表示 其 其中 成 像 配 置 示在 在成 成像 像配 配置 下 通 过 渲 染 算 子 生 合 图 通过 过神 场与 与渲 渲染 染算 算子 子生 生成 成的 的合 合成 成图 图像 由 所 有 训 练 视 角 共 享 同 组 网 络 参 数 由于 于所 所有 有训 训练 练视 视角 角共 共享 享同 同一 一组 组网 网络 络参 参数 这 优 化 程 实 际 上 等 价 寻 找 个 这一 一优 优化 化过 过程 程实 实际 际上 上等 等价 价于 于寻 寻找 找一 一个 个统 一的 续三 维表 使 能 够 时 解 释 观 测 使其 其能 能够 够同 同时 时解 解释 释所 有视 角下 下的 的观 观测 测图 从 而 天 然 引 入 多 致 性 约 束 从而 而天 天然 然引 引入 入多 多视 角一 一致 致性 性约 约束 机 制 意 于连 的三 法的 的表 染机 机制 制示 示意 意图 克 服 格 固 缺 陷 为了 了克 克服 服离 素网 网格 格的 的固 固有 有缺 缺陷 提 供 空 间 模 范 式 征提 提供 供了 了连 续空 空间 间建 建模 模范 范式 如 如图 所示 直 接 存 储 灰 度 值 不 与离 格直 直接 接存 存储 储空 间灰 灰度 度值 值不 不同 坐 标 驱 动 场方 法通 过坐 坐标 标驱 驱动 动的 对 规 进 行 对规 规范 范空 间中 中的 场进 进行 行参 数化 化表 再 结 型 最 终 二 再结 结合 合参 化渲 染模 模型 型生 成最 最终 终二 二维 维超 声图 与图 形 照 后 的离 征机 制形 形成 成对 对照 照后 可 以 更 清 晰 地 看 出 可以 以更 更清 清晰 晰地 地看 看出 强 调 格方 法强 强调 散网 格存 而神 函 续函 函数 数表 此 由此 将 转 学 习 微 联 问 题 法将 将三 建转 转化 化为 为一 个连 续场 示学 学习 习与 与可 可微 微渲 染联 联合 合优 化的 的问 问题 有观 像共 因 之 全 局 因此 此多 视图 图之 之间 间天 然存 存在 在全 全局 局一 点 一点 点与 与体 法中 每 部 插 每个 个体 素局 局部 部插 插值 新 部更 更新 本 质 的机 制有 有本 本质 质不 据 先 验 预 据此 此可 可提 提出 出先 先验 验预 预测 当 减 少 当训 图减 减少 少时 应 比 传 好 保 持 构 精 纹 量 征应 应比 比传 传统 统离 素方 法更 更好 好地 地保 保持 持结 结构 构精 精度 度与 与纹 纹理 理质 质量 节 稀 疏 检 该 节的 的稀 稀疏 疏视 图实 实验 验据 此检 检验 验该 该先', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e0199454cde6675b4cc701b4c2965075ab919e986f94b81aeb290e3842b168ae') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`