INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4115dee31120eef0', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / NeRF用于超声影像', '在2.4.1　 节中，已经讨论了传统离散体素重建方法在采样稀疏、轨迹不均或位姿误差存在时容易出现空洞、撕裂与模糊等局限；在2.4.2　 节中，则说明了采用连续神经场表征进行三维重建的必要性。然而，标准 NeRF 主要面向光学场景设计[32,33,38–41]，其成像基础是透视投影与体渲染，而自由手超声的图像形成机理与之存在本质差异。超声图像由声波传播、衰减、散射、反射和成像系统响应共同形成，不能按表面颜色投影建模[50–52,57]。因此，若连续神经场表征仅直接回归灰度值，虽然可能在训练视角下拟合图像，但往往难以充分体现超声物理机制，也不利于在未见视角下获得稳定、真实的重建结果。
基于这一认识，本文针对超声影像的图像模态，提出了 Ultrasonic-physics-informed Neural Radiance Fields for Freehand 3D Ultrasound（UPI-NeRF）。该方法的核心思想是：在保持 NeRF 连续神经场表征优势的同时，将超声物理机制直接引入神经渲染过程[7,35,36,42,64,73,165]，将三维重建由单纯图像拟合扩展为连续神经场表征与超声前向成像模型共同驱动的物理约束重建。UPI-NeRF 据此依据超声成像机理重构适用于超声三维重建的神经辐射场框架。', 'nerf 2.4.1 2.4.2 32 33 38 41 50 52 57 ultrasonic-physics-informed neural radiance fields for freehand 3d ultrasound upi-nerf 35 36 42 64 73 165 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 用 影 像 用于 声影 影像 节 节中 已 讨 论 传 统 方 法 采 样 稀 疏 已经 经讨 讨论 论了 了传 传统 统离 素重 建方 方法 法在 在采 采样 样稀 稀疏 轨 迹 不 均 或 位 姿 误 差 存 时 容 易 出 现 空 洞 轨迹 迹不 不均 均或 或位 位姿 姿误 误差 差存 存在 在时 时容 容易 易出 出现 现空 空洞 撕 裂 模 糊 等 局 限 撕裂 裂与 与模 模糊 糊等 等局 局限 则 说 明 进 行 必 要 性 则说 说明 明了 了采 采用 用连 征进 进行 行三 建的 的必 必要 要性 然 而 然而 标 准 标准 主 面 向 光 学 景 设 计 主要 要面 面向 向光 光学 学场 场景 景设 设计 其 成 础 透 视 投 渲 染 其成 成像 像基 基础 础是 是透 透视 视投 投影 影与 与体 体渲 渲染 自 由 手 图 形 机 之 本 质 异 而自 自由 由手 手超 声的 的图 图像 像形 形成 成机 机理 与之 之存 在本 本质 质差 差异 波 播 声图 像由 由声 声波 波传 传播 衰 减 衰减 射 散射 反 系 响 应 共 同 反射 射和 和成 像系 系统 统响 响应 应共 共同 同形 能 按 颜 色 不能 能按 按表 表面 面颜 颜色 色投 影建 建模 因 此 因此 若 仅 直 接 回 归 灰 度 值 若连 征仅 仅直 直接 接回 回归 归灰 灰度 度值 虽 可 训 练 角 下 拟 合 虽然 然可 可能 能在 在训 训练 练视 视角 角下 下拟 拟合 合图 但 往 难 以 充 分 制 但往 往往 往难 难以 以充 充分 分体 体现 现超 理机 机制 也 利 未 见 获 得 稳 定 也不 不利 利于 于在 在未 未见 见视 下获 获得 得稳 稳定 真 实 结 果 真实 实的 的重 建结 结果 这 一 认 识 于这 这一 一认 认识 文 针 对 态 本文 文针 针对 对超 像的 像模 模态 提 提出 出了 该 核 心 思 想 该方 法的 的核 核心 心思 思想 想是 保 持 在保 保持 优 势 征优 优势 势的 的同 同时 将 引 入 过 程 将超 制直 接引 引入 入神 经渲 染过 过程 单 纯 扩 展 前 型 驱 动 约 束 将三 建由 由单 单纯 纯图 像拟 合扩 扩展 展为 为连 与超 声前 前向 向成 模型 型共 同驱 驱动 动的 的物 理约 约束 束重 据 依 构 适 辐 框 架 据此 此依 依据 据超 声成 像机 理重 重构 构适 适用 的神 经辐 辐射 射场 场框 框架', '/#research', 'doctoral-thesis', 1, '2026-08-04', '4115dee31120eef024685b5068ae9d001605c9baeef4ac6279da6cfed5de003f') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_leve