INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-a8acd8d42e22fb8b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / NeRF用于超声影像', '声物理机制直接引入神经渲染过程[7,35,36,42,64,73,165]，将三维重建由单纯图像拟合扩展为连续神经场表征与超声前向成像模型共同驱动的物理约束重建。UPI-NeRF 据此依据超声成像机理重构适用于超声三维重建的神经辐射场框架。
图 2.32 UPI-NeRF用于超声神经渲染总览图
Figure . Overview of UPI-NeRF for ultrasound neural rendering.
如图 2.32所示，UPI-NeRF 可以概括为四个连续阶段：
其中表示局部衰减系数，表示背散射幅度参数，表示宏观界面法向，表示法向集中参数或界面粗糙度参数， 表示声阻抗失配比例。后续2.5　 节将具体展开引入更强的采样组织方式、位置/方向编码与周期激活函数，以提升神经场网络 对细小解剖结构和强方向依赖变化的建模能力。
这里基于超声波的物理特性，将回波解耦为 表示的由亚分辨散射体产生的背散射项以及 表示的由宏观界面产生的反射项，为超声成像系统的点扩散函数以实现从回波强度到图像像素的成像过程映射。 表示剩余波强，其通过 Beer–Lambert 型衰减关系随深度递减。后续2.6　 节将具体展开参数化物理渲染建模，包括：基于瑞利分布的散射机制从而根据背散射幅度参数生成符合 散斑统计规律的纹理；基于方向参数化的反射机制从而根据界面法向、粗糙度和阻抗失配生成具有入射角依赖性的界面回波[53,58–60]。', 'nerf 35 36 42 64 73 165 upi-nerf 2.32 figure overview of for ultrasound neural rendering. 2.5 beer lambert 2.6 53 58 60 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 用 影 像 用于 声影 影像 机 制 直 接 引 入 渲 染 过 程 理机 机制 制直 直接 接引 引入 入神 经渲 渲染 染过 过程 将 由 单 纯 图 拟 合 扩 展 前 向 成 模 型 共 同 驱 动 约 束 将三 建由 由单 单纯 纯图 图像 像拟 拟合 合扩 扩展 展为 为连 与超 声前 前向 向成 成像 像模 模型 型共 共同 同驱 驱动 动的 的物 理约 约束 束重 据 此 依 构 适 辐 射 框 架 据此 此依 依据 据超 声成 像机 机理 理重 重构 构适 适用 建的 的神 经辐 辐射 射场 场框 框架 总 览 声神 染总 总览 览图 如 如图 所 示 所示 可 以 概 括 四 个 阶 段 可以 以概 概括 括为 为四 四个 个连 续阶 阶段 其 局 部 衰 减 系 数 其中 中表 表示 示局 局部 部衰 衰减 减系 系数 背 幅 度 参 示背 背散 散射 射幅 幅度 度参 参数 宏 观 界 面 法 示宏 宏观 观界 界面 面法 法向 集 或 粗 糙 示法 向集 集中 中参 数或 或界 面粗 粗糙 糙度 阻 抗 失 配 比 例 示声 声阻 阻抗 抗失 失配 配比 比例 后 后续 节 具 开 更 强 采 样 组 织 方 式 节将 将具 具体 体展 展开 开引 入更 更强 强的 的采 采样 样组 组织 织方 方式 位 置 位置 编 码 周 期 激 活 函 方向 向编 编码 码与 与周 周期 期激 激活 活函 函数 提 升 网 络 以提 提升 升神 场网 网络 对 细 小 解 剖 结 赖 变 化 能 力 对细 细小 小解 解剖 剖结 结构 构和 和强 强方 向依 依赖 赖变 变化 化的 的建 建模 模能 能力 这 里 波 特 性 这里 里基 声波 波的 理特 特性 回 耦 将回 回波 波解 解耦 耦为 亚 分 辨 产 生 项 示的 的由 由亚 亚分 分辨 辨散 射体 体产 产生 生的 的背 射项 项以 以及 反 由宏 面产 的反 反射 统 点 实 现 从 到 映 为超 像系 系统 统的 的点 点扩 扩散 散函 数以 以实 实现 现从 从回 波强 强度 度到 到图 像像 像素 素的 的成 像过 程映 映射 剩 余 示剩 剩余 余波 通 其通 通过 关 随 深 递 型衰 减关 关系 系随 随深 深度 度递 递减 开参 数化 化物 理渲 染建 包 包括 瑞 利 布 而 根 符 于瑞 瑞利 利分 分布 布的 的散 射机 制从 从而 而根 根据 据背 数生 生成 成符 符合 斑 计 规 律 纹 散斑 斑统 统计 计规 规律 律的 的纹 纹理 于方 向参 据界 有 角 度和 和阻 配生 成具 具有 有入 入射 射角 角依 赖性 性的 的界 面回', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'a8acd8d42e22fb8ba865df18353e9f7029af8b34fe5854181cc7eafd7c392285') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.