INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-12d5feb2296951f1', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 离散体素表征与连续神经场表征 / NeRF用于超声影像', '减。后续2.6　 节将具体展开参数化物理渲染建模，包括：基于瑞利分布的散射机制从而根据背散射幅度参数生成符合 散斑统计规律的纹理；基于方向参数化的反射机制从而根据界面法向、粗糙度和阻抗失配生成具有入射角依赖性的界面回波[53,58–60]。
本节比较了离散体素与连续神经场两类三维表征。体素网格便于直接写入观测，但在不规则采样下受分辨率、空洞和插值误差限制；连续神经场支持连续查询与新视角合成，但通用NeRF缺少超声成像约束。基于这一比较，后续方法以连续神经场为主体，并分别改进其属性表达与物理渲染机制。[7,35,36,42,64,73,165]', 'nerf 2.6 53 58 60 35 36 42 64 73 165 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 离 散 体 素 表 征 离散 散体 体素 素表 表征 征与 场表 用 影 像 用于 声影 影像 减 后 后续 节 将 具 展 开 参 数 化 渲 染 模 节将 将具 具体 体展 展开 开参 参数 数化 化物 理渲 渲染 染建 建模 包 括 包括 瑞 利 分 布 射 机 制 从 而 根 据 背 幅 度 生 成 符 合 于瑞 瑞利 利分 分布 布的 的散 散射 射机 机制 制从 从而 而根 根据 据背 背散 射幅 幅度 度参 数生 生成 成符 符合 斑 统 计 规 律 纹 散斑 斑统 统计 计规 规律 律的 的纹 纹理 方 向 反 界 面 法 于方 方向 向参 化的 的反 反射 据界 界面 面法 法向 粗 糙 阻 抗 失 配 有 入 角 依 赖 性 回 波 粗糙 糙度 度和 和阻 阻抗 抗失 失配 配生 成具 具有 有入 入射 射角 角依 依赖 赖性 性的 的界 面回 回波 本 比 较 两 类 本节 节比 比较 较了 了离 素与 场两 两类 类三 维表 网 格 便 直 接 写 观 测 素网 网格 格便 便于 于直 直接 接写 写入 入观 观测 但 不 则 采 样 下 受 辨 率 但在 在不 不规 规则 则采 采样 样下 下受 受分 分辨 辨率 空 洞 插 值 误 差 限 空洞 洞和 和插 插值 值误 误差 差限 限制 支 持 查 询 新 视 场支 支持 持连 续查 查询 询与 与新 新视 视角 角合 合成 通 但通 通用 缺 少 约 束 缺少 少超 声成 成像 像约 约束 这 一 于这 这一 一比 以 主 续方 方法 法以 以连 场为 为主 主体 并 别 改 进 其 属 达 并分 分别 别改 改进 进其 其属 属性 性表 表达 达与 与物 染机', '/#research', 'doctoral-thesis', 1, '2026-08-04', '12d5feb2296951f1cd71cf3184afbdb9e87846f6ebc2057b83a993cde1394da5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-54e383ded7762c8b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 物理属性预测网络表达能力增强', '完成二维像素坐标向三维规范空间的映射后，三维重建的核心在于构建能够整合不规则二维超声切片的连续神经场，并准确表征高频边界、复杂纹理和方向相关信息[32,38-41,43-45]。根据2.4.3　 节的定义，本文采用神经场网络 对规范空间中的局部场属性进行建模。对于任意射线上的采样位置 与方向 ，网络输出相应的中间物理表征 用于描述该位置处与超声成像相关的局部属性，例如衰减、散射、界面法向、粗糙度以及阻抗失配等。随后，参数化渲染算子 根据这些中间物理属性生成对应的图像响应。UPI-NeRF物理属性预测网络表达能力增强的设计目标，就是提升神经场网络 对细小解剖结构和强方向依赖变化的建模能力。[33,34,166,167]
普通多层感知器对高频和强方向依赖变化的表达有限。为此，本节分别采用高频位置与方向编码（2.5.1　节）、改进射线采样（2.5.2　节）和周期激活函数（2.5.3　节），对应增强特征带宽、聚焦组织界面和改善连续场拟合。三者构成图 2.33所示的物理属性预测网络；2.6　节再以参数化物理渲染约束属性到图像响应的转换。
图 2.33 物理属性预测网络表达能力增强模块总览图
