INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f047fbe252a5dfd7', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 物理属性预测网络表达能力增强 / 位置编码与方向编码', '虽然规范空间中的采样方式能够保留超声图像的几何结构，但若直接将坐标 与方向 输入普通多层感知机，网络仍然容易受到谱偏置影响，只优先拟合低频平滑结构，而难以表达组织边界、细粒度散斑和尖锐方向变化等高频特征。对于超声重建而言，这一问题尤为突出，因为组织界面、散斑纹理和视角相关回波往往都含有明显高频成分。为缓解这一问题，本章在空间分支采用正弦位置编码，将原始空间坐标映射到多频基函数空间。[46,168,169]其表达式为：
其中，为人为设定的最高频带超参数。通过引入不同尺度的正弦与余弦基函数，网络在输入层即可获得对多尺度空间变化的感知能力，从而更容易表达高频空间结构。
仅对位置进行编码仍不足以适应超声场景，因为超声图像中的许多结构不仅与空间位置有关，还与入射方向密切相关。尤其在组织界面处，当波束方向与界面法向夹角发生变化时，回波强度往往会呈现明显的非线性变化。在超声成像中，随着探头旋转，界面法向与入射方向的夹角发生变化，回波强度可能出现快速下降或急剧增强，这种变化往往比空间纹理本身更具非线性。因此，除了位置编码外，还需要对传播方向 进行方向编码。已有工作常直接对方向向量沿用与位置相同的正弦编码，但有限频带的三角基很难充分表达这种突变的角度依赖关系。为此，本章引入由粗糙度参数 调制的球谐方向编码。其形式可写为：', '46 168 169 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 属 性 预 测 网 络 表 达 能 力 增 强 理属 属性 性预 预测 测网 网络 络表 表达 达能 能力 力增 增强 位 置 编 码 方 向 位置 置编 编码 码与 与方 方向 向编 虽 然 规 范 空 间 采 样 式 够 保 留 图 像 几 何 结 构 虽然 然规 规范 范空 空间 间中 中的 的采 采样 样方 方式 式能 能够 够保 保留 留超 声图 图像 像的 的几 几何 何结 结构 但 若 直 接 将 坐 标 但若 若直 直接 接将 将坐 坐标 输 入 普 通 多 层 感 知 机 输入 入普 普通 通多 多层 层感 感知 知机 仍 容 易 受 到 谱 偏 影 响 络仍 仍然 然容 容易 易受 受到 到谱 谱偏 偏置 置影 影响 只 优 先 拟 合 低 频 平 滑 只优 优先 先拟 拟合 合低 低频 频平 平滑 滑结 而 难 以 组 织 边 界 而难 难以 以表 达组 组织 织边 边界 细 粒 度 散 斑 尖 锐 变 化 等 高 特 征 细粒 粒度 度散 散斑 斑和 和尖 尖锐 锐方 向变 变化 化等 等高 高频 频特 特征 对 言 对于 声重 建而 而言 这 一 问 题 尤 突 出 这一 一问 问题 题尤 尤为 为突 突出 因 面 因为 为组 织界 界面 纹 视 角 相 关 回 波 往 都 含 有 明 显 成 分 斑纹 纹理 理和 和视 视角 角相 相关 关回 回波 波往 往往 往都 都含 含有 有明 明显 显高 频成 成分 缓 解 为缓 缓解 解这 本 支 用 正 弦 本章 章在 在空 间分 分支 支采 采用 用正 正弦 弦位 原 始 映 射 函 数 将原 原始 始空 间坐 标映 映射 射到 到多 多频 频基 基函 函数 数空 其 其表 达式 式为 其中 人 设 定 最 带 参 为人 人为 为设 设定 定的 的最 最高 频带 带超 超参 参数 过 引 不 同 尺 余 通过 过引 引入 入不 不同 同尺 尺度 度的 的正 弦与 与余 余弦 弦基 即 可 获 得 络在 在输 入层 层即 即可 可获 获得 得对 对多 多尺 度空 间变 化的 的感 知能 从 更 从而 而更 更容 易表 达高 频空 间结 仅 进 行 足 适 应 景 仅对 对位 置进 进行 行编 码仍 仍不 不足 足以 以适 适应 应超 声场 场景 许 为超 像中 的许 许多 多结 构不 不仅 仅与 与空 间位 置有 有关 还 密 切 还与 与入 入射 射方 向密 密切 切相 处 尤其 其在 在组 面处 当 束 法 夹 发 生 时 当波 波束 束方 向与 与界 面法 法向 向夹 夹角 角发 发生 生变 化时 会 呈 现 非 线 波强 强度 度往 往会 会呈 呈现 现明 显的 的非 非线 线性 性变 在超 声成 成像 随 着 探 头 旋 转 随着 着探 探头 头旋 旋转 向的 的夹 快 速 下 降 或 急 剧 度可 可能 能出 出现 现快 快速 速下 下降 降或 或急 急剧 剧增 种 比 身 具 这种 种变 化往 往比 比空 间纹 理本 本身 身更 更具 具非 此 因此 除 外 除了 了位 码外 需 要 传 播 还需 需要 要对 对传 传播 播方 行方 已 工 作 常 量 沿 已有 有工 工作 作常 常直 接对 对方 向向 向量 量沿 沿用 用与 与位 置相 相同 同的 弦编 限 很 充 依 赖 系 但有 有限 限频 带的 的三 三角 角基 基很 很难 难充 充分 分表 达这 种突 突变 变的 的角 角度 度依 依赖 赖关 关系 为此 由 粗 糙 章引 入由 由粗 粗糙 糙度 度参 调 制 球 谐 调制 制的 的球 球谐 谐方 形 写 其形 形式 式可 可写 写为', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f047fbe252a5dfd7b5d77e809cfb