INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-37856fbf052f143a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 物理属性预测网络表达能力增强 / 位置编码与方向编码', '纹理本身更具非线性。因此，除了位置编码外，还需要对传播方向 进行方向编码。已有工作常直接对方向向量沿用与位置相同的正弦编码，但有限频带的三角基很难充分表达这种突变的角度依赖关系。为此，本章引入由粗糙度参数 调制的球谐方向编码。其形式可写为：
其中， 为球谐基函数，与分别表示其阶数与次数。 由网络预测的粗糙度参数动态调制，因而不是固定系数。当 较小时，表示界面较粗糙，高阶球谐分量被抑制，编码以低频内容为主；当 较大时，表示界面较光滑，高阶球谐成分被保留，有利于表示尖锐的镜面反射峰值。图 2.34展示了基于球谐基 与 的方向集中参数化过程。随着 的变化，高阶球谐分量会被自适应抑制或保留，从而实现对不同粗糙度界面的角域表征。当 较小时，方向编码更偏向低频、平滑的角度变化；当 较大时，编码则能够表示更尖锐、更强烈的镜面样反射峰。这一编码机制使网络能够更好地刻画超声图像中与入射方向紧密相关的界面回波变化[166,167,172]。
图 2.34 基于球谐基与 的方向集中参数化
