INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-8bc3e7a45e108bff', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 物理属性预测网络表达能力增强 / 采样方式改进', '部体积区域的统计描述，后续编码与特征提取因而作用于具有空间尺度的采样单元。对于基于位置编码的连续神经场，可对该高斯分布进行积分位置编码（integrated positional encoding），得到该截锥体采样单元的编码表示：[48]
图 2.35进一步展示了点采样与截锥体采样在编码层面的差异。对于单点采样，位置编码仅作用于单个空间坐标；而对于截锥体采样，编码实际上是对一个具有均值和协方差的局部体积区域进行积分后的结果。这样得到的输入特征对局部空间尺度更敏感，也更适合后续多频位置编码与高频结构建模。因此，截锥体采样改变的是采样对象的空间定义，而非单纯提高采样密度；frustum 表示及其高斯近似为位置编码、方向编码和神经场物理属性预测提供了具有尺度信息的输入。', 'integrated positional encoding 48 2.35 frustum 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 属 性 预 测 网 络 表 达 能 力 增 强 理属 属性 性预 预测 测网 网络 络表 表达 达能 能力 力增 增强 采 样 方 式 改 进 采样 样方 方式 式改 改进 部 体 积 区 域 统 计 描 述 部体 体积 积区 区域 域的 的统 统计 计描 描述 后 编 码 特 征 提 取 因 而 作 用 具 有 空 间 尺 度 单 元 后续 续编 编码 码与 与特 特征 征提 提取 取因 因而 而作 作用 用于 于具 具有 有空 空间 间尺 尺度 度的 的采 样单 单元 对 位 置 对于 于基 于位 位置 置编 码的 的连 可 该 高 斯 分 布 行 可对 对该 该高 高斯 斯分 分布 布进 进行 行积 积分 分位 得 到 截 锥 示 得到 到该 该截 截锥 锥体 体采 元的 的编 码表 表示 图 一 步 展 点 层 面 差 异 进一 一步 步展 展示 示了 了点 点采 样与 与截 样在 在编 码层 层面 面的 的差 差异 于单 单点 仅 个 坐 标 码仅 仅作 单个 个空 间坐 坐标 而对 于截 实 际 上 均 值 协 局 结 果 码实 实际 际上 上是 是对 对一 一个 个具 有均 均值 值和 和协 协方 方差 差的 的局 局部 域进 分后 后的 的结 结果 这 输 入 更 敏 感 这样 样得 到的 的输 输入 入特 征对 对局 部空 度更 更敏 敏感 也 适 合 多 频 构 模 也更 更适 适合 合后 续多 多频 频位 与高 高频 频结 结构 构建 建模 此 因此 变 象 定 义 样改 改变 变的 的是 是采 样对 对象 象的 的空 间定 定义 非 纯 密 而非 非单 单纯 纯提 提高 高采 样密 密度 其 近 似 示及 及其 其高 斯近 近似 似为 为位 向 供 信 息 方向 向编 码和 和神 场物 测提 提供 供了 了具 有尺 度信 信息 息的', '/#research', 'doctoral-thesis', 1, '2026-08-04', '8bc3e7a45e108bffa03ae44c7894c9944cae7bfdf0a112a9836899fb85cb0e2d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d779cc7d151de6b2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 物理属性预测网络表达能力增强 / 周期激活函数改进', '除编码与采样之外，网络本身的非线性表达能力同样决定了高频组织边界能否被准确重建，因此还需进一步讨论激活函数设计对连续神经场表征质量的影响。
即使引入位置编码与方向编码，若网络内部仍采用 ReLU 等分段线性激活函数，高频信息在多层传播过程中仍可能逐渐衰减，从而限制连续神经场对复杂连续场的表达能力。标准 ReLU 类激活函数虽然在许多视觉任务中表现良好，但对高频振荡信号的拟合能力有限，容易将复杂细节过度平滑。为进一步增强网络对高频函数的拟合能力，本文在连续神经场中采用周期激活函数[43–45]。UPI-NeRF 参考 SIREN 的设计，将空间分支和方向分支中的 MLP 激活函数替换为正弦激活，并采用与之匹配的初始化方式，以进一步增强空间分支和方向分支对高频结构与尖锐外观变化的建模能力。
其中， 与 分别为权重与偏置， 控制激活频率。为保证训练过程的数值稳定性，周期激活函数在输入层与隐层采用特定初始化方式，以保证训练初期梯度分布稳定，避免高频表示在深层网络中迅速衰减。[46,166,167,172]', 'relu 43 45 upi-nerf siren mlp 46 166 167 172 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 属 性 预 测 网 络 表 达 能 力 增 强 理属 属性 性预 预测 测网 网络 络表 表达 达能 能力 力增 增强 周 期 激 活 函 数 改 进 周期 期激 激活 活函 函数 数改 改进 除 编 码 采 样 之 外 除编 编码 码与 与采 采样 样之 之外 本 身 非 线 同 决 定 高 频 组 织 边 界 否 被 准 确 络本 本身 身的 的非 非线 线性 性表 力同 同样 样决 决定 定了 了高 高频 频组 组织 织边 边界 界能 能否 否被 被准 准确 确重 因 此 还 需 一 步 讨 论 设 计 对 征 质 量 影 响 因此 此还 还需 需进 进一 一步 步讨 讨论 论激 数设 设计 计对 对连 场表 表征 征质 质量 量的 的影 影响 即 使 引 入 位 置 方 向 即使 使引 引入 入位 位置 置编 与方 方向 向编 若 内 部 仍 用 若网 络内 内部 部仍 仍采 采用 等 分 段 等分 分段 段线 性激 信 息 多 层 传 播 过 程 可 逐 渐 衰 减 频信 信息 息在 在多 多层 层传 传播 播过 过程 程中 中仍 仍可 可能 能逐 逐渐 渐衰 衰减 从 而 限 制 复 杂 从而 而限 限制 制连 场对 对复 复杂 杂连 续场 的表 标 标准 类 虽 然 许 视 觉 任 务 现 良 好 类激 数虽 虽然 然在 在许 许多 多视 视觉 觉任 任务 务中 中表 表现 现良 良好 但 振 荡 号 拟 合 有 但对 对高 频振 振荡 荡信 信号 号的 的拟 拟合 合能 力有 有限 容 易 将 细 节 度 平 滑 容易 易将 将复 杂细 细节 节过 过度 度平 平滑 为进 步增 强网 络对 频函 数的 文 本文 文在 在连 场中 中采 用周 参 考 参考 的设 空 间 支 将空 空间 间分 分支 支和 和方 向分 支中 中的 替 换 正 弦 数替 替换 换为 为正 正弦 弦激 并 匹 配 初 始 化 式 并采 用与 与之 之匹 匹配 配的 的初 初始 始化 化方 方式 以 结 构 尖 锐 观 变 模 以进 强空 支对 频结 结构 构与 与尖 尖锐 锐外 外观 观变 变化 化的 的建 建模 模能 其 其中 别 权 偏 分别 别为 为权 权重 重与 与偏 偏置 控 率 控制 制激 活频 频率 保 证 训 练 值 稳 为保 保证 证训 训练 练过 程的 的数 数值 值稳 稳定 定性 输 隐 特 数在 在输 输入 入层 层与 与隐 隐层 层采 用特 特定 定初 梯 布 以保 练初 初期 期梯 梯度 度分 分布 布稳 避 免 示 深 迅 速 避免 免高 频表 表示 示在 在深 深层 层网 络中 中迅 迅速 速衰', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd779cc7d151de6b275731dab9bc23ca052a4e62a8381eb878463646858b2c551') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-131b8f8e26970d1c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 物理属性预测网络表达能力增强 / 周期激活函数改进', '尖锐外观变化的建模能力。
其中， 与 分别为权重与偏置， 控制激活频率。为保证训练过程的数值稳定性，周期激活函数在输入层与隐层采用特定初始化方式，以保证训练初期梯度分布稳定，避免高频表示在深层网络中迅速衰减。[46,166,167,172]
与 ReLU 相比，正弦激活具有天然的周期性与平滑性[43–45]，能够更好地表达连续空间中的快速振荡模式。这一点对于超声图像尤为重要，因为散斑纹理、薄层界面和局部反射峰都具有明显高频特征。如果网络激活函数本身不具备足够高的表达带宽，即便输入使用了多频编码，高频信息也可能在前向传播中被逐渐削弱。UPI-NeRF 的实验表明，在位置/方向编码与 sine 激活同时引入后，NeRF、Mip-NeRF、Ref-NeRF、Ultra-NeRF 与 Ultra-NeRF-CB 等不同基线均出现显著性能提升，说明这种表示能力增强具有较强普适性。
采样方式、位置/方向编码与周期激活函数共同构成了本章物理属性预测网络的表达能力增强模块。其中，采样方式确保网络输入符合超声扫描线几何，位置与方向编码增强网络对空间高频结构和方向依赖特性的感知能力，周期激活函数则进一步提升网络对复杂连续场的拟合能力。上述设计提高了连续神经场对中间物理属性的表达能力，并为参数化物理渲染提供更准确的输入。第2.7.3　 节通过不同超声 NeRF 基线检验该模块的适用性与增益稳定性。[47,48,168,169]', '46 166 167 172 relu 43 45 upi-nerf sine nerf mip-nerf ref-nerf ultra-nerf ultra-nerf-cb 2.7.3 47 48 168 169 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 属 性 预 测 网 络 表 达 能 力 增 强 理属 属性 性预 预测 测网 网络 络表 表达 达能 能力 力增 增强 周 期 激 活 函 数 改 进 周期 期激 激活 活函 函数 数改 改进 尖 锐 外 观 变 化 模 尖锐 锐外 外观 观变 变化 化的 的建 建模 模能 其 其中 分 别 权 偏 置 分别 别为 为权 权重 重与 与偏 偏置 控 制 频 率 控制 制激 活频 频率 保 证 训 练 过 程 值 稳 定 为保 保证 证训 训练 练过 过程 程的 的数 数值 值稳 稳定 定性 输 入 层 隐 采 用 特 初 始 方 式 数在 在输 输入 入层 层与 与隐 隐层 层采 采用 用特 特定 定初 初始 始化 化方 方式 以 梯 度 布 以保 练初 初期 期梯 梯度 度分 分布 布稳 避 免 高 示 深 迅 速 衰 减 避免 免高 高频 频表 表示 示在 在深 深层 层网 络中 中迅 迅速 速衰 衰减 相 比 相比 正 弦 具 有 天 然 平 滑 正弦 弦激 活具 具有 有天 天然 然的 的周 期性 性与 与平 平滑 滑性 够 更 好 地 空 间 快 振 荡 能够 够更 更好 好地 地表 达连 续空 空间 间中 中的 的快 快速 速振 振荡 荡模 模式 这 一 点 对 图 像 尤 要 这一 一点 点对 对于 声图 图像 像尤 尤为 为重 重要 因 散 斑 纹 因为 为散 散斑 斑纹 纹理 薄 界 面 局 部 反 射 峰 都 明 显 征 薄层 层界 界面 面和 和局 局部 部反 反射 射峰 峰都 都具 有明 明显 显高 频特 特征 如 果 本 身 不 备 足 带 宽 如果 果网 络激 数本 本身 身不 不具 具备 备足 足够 够高 高的 的表 达带 带宽 即 便 使 多 编 码 即便 便输 入使 使用 用了 了多 多频 频编 编码 信 息 也 可 前 向 传 播 被 逐 渐 削 弱 频信 信息 息也 也可 可能 能在 在前 前向 向传 传播 播中 中被 被逐 逐渐 渐削 削弱 实 验 的实 实验 验表 表明 位 在位 位置 方向 向编 码与 同 时 引 后 活同 同时 时引 引入 入后 等 线 均 出 现 著 提 升 等不 不同 同基 基线 线均 均出 出现 现显 显著 著性 性能 能提 提升 说 种 较 普 适 说明 明这 这种 种表 示能 强具 有较 较强 强普 普适 适性 样 采样 样方 共 构 成 块 与周 数共 共同 同构 构成 成了 了本 本章 章物 络的 强模 模块 确 符 合 扫 描 几 何 式确 确保 保网 络输 入符 符合 合超 声扫 扫描 描线 线几 几何 结 依 赖 感 知 置与 与方 码增 强网 络对 对空 间高 频结 结构 构和 和方 向依 依赖 赖特 特性 性的 的感 感知 知能 则 步 复 杂 拟 数则 则进 进一 一步 步提 升网 对复 复杂 杂连 续场 的拟 拟合 合能 上 述 设 计 上述 述设 设计 计提 提高 高了 了连 场对 对中 中间 间物 并 参 渲 染 供 准 并为 为参 参数 数化 化物 理渲 渲染 染提 提供 供更 更准 准确 确的 的输 节 通 节通 通过 过不 同超 检 该 益 线检 检验 验该 该模 块的 的适 适用 用性 与增 增益 益稳', '/#research', 'doctoral-thesis', 1, '2026-08-04', '131b8f8e26970d1c5eeb4663be576cded7685737d396f4a2bc5b37989fde52b9') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`