INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b89acbdd6db2de86', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 参数化物理渲染建模', '在2.4.3　 节中，已经从总体上给出了 UPI-NeRF 的方法框架；在2.5　 节中，则进一步讨论了物理属性预测网络的表达能力增强设计。基于前述建模，神经场网络 在规范空间中沿每条射线输出一组局部物理属性，而本节关注的问题是：如何利用这些局部物理属性，构造符合超声成像机理的参数化渲染过程，并由此生成二维超声图像。本节与前述表征设计分工明确：2.5　 节讨论局部介质属性的表示；本节则研究这些属性如何经参数化物理模型转化为可观测的回波图像。
连续神经场能够表示局部介质属性，却不能单独保证合成图像符合超声回波形成规律。与光学 NeRF 直接回归颜色与密度不同，超声图像的形成依赖于波在介质中的传播、衰减、散射、反射以及成像系统响应。若仅令网络直接预测图像灰度，则容易把复杂的成像过程压缩为缺乏物理约束的黑盒映射，虽然可能在训练视角下拟合图像，但难以保证在未见视角下仍具有稳定的几何一致性和合理的声学真实性。因此，UPI-NeRF 在连续神经场表征之外，引入了一个参数化物理渲染算子 ，用于沿射线模拟超声传播与图像形成过程。其基本形式可写为[50,55,56,69]
其中， 为上一节中定义的局部物理属性集合， 表示由亚分辨散射体引起的背散射项， 表示由宏观介质界面引起的反射项，为超声成像系统的点扩散函数以实现从回波强度到图像像素的成像过程映射， 则表示深度 处的局部图像响应。图 2.36与图 2.37给出了散射体引起的背散射与宏观介质界面引起的反射的示意图。为简化记号，以下均在固定一条射线的条件下讨论，省略射线索引[51,54–56,69]。', '2.4.3 upi-nerf 2.5 nerf 50 55 56 69 2.36 2.37 51 54 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 参 数 化 渲 染 模 参数 数化 化物 理渲 渲染 染建 建模 节 节中 已 从 总 体 上 给 出 已经 经从 从总 总体 体上 上给 给出 出了 方 法 框 架 的方 方法 法框 框架 则 进 一 步 讨 论 属 性 预 测 网 络 表 达 能 力 增 强 设 计 则进 进一 一步 步讨 讨论 论了 了物 理属 属性 性预 预测 测网 网络 络的 的表 表达 达能 能力 力增 增强 强设 设计 前 述 于前 前述 述建 场网 规 范 空 间 沿 每 条 射 线 输 组 局 部 在规 规范 范空 空间 间中 中沿 沿每 每条 条射 射线 线输 输出 出一 一组 组局 局部 部物 而 本 关 注 问 题 而本 本节 节关 关注 注的 的问 问题 题是 如 何 利 用 这 些 如何 何利 利用 用这 这些 些局 构 造 符 合 成 像 机 过 程 构造 造符 符合 合超 声成 成像 像机 机理 理的 的参 化渲 染过 过程 并 由 此 生 二 图 并由 由此 此生 生成 成二 二维 维超 声图 图像 征 分 工 明 确 节与 与前 述表 表征 征设 计分 分工 工明 明确 介 质 示 节讨 论局 部介 介质 质属 性的 表示 研 究 型 转 可 观 回 波 节则 则研 研究 究这 些属 性如 何经 经参 理模 模型 型转 转化 化为 为可 可观 观测 测的 的回 回波 波图 够 场能 能够 够表 示局 却 不 单 独 保 证 形 律 却不 不能 能单 单独 独保 保证 证合 合成 成图 像符 声回 波形 形成 成规 规律 光 学 与光 光学 直 接 归 颜 色 密 度 同 直接 接回 回归 归颜 颜色 色与 与密 密度 度不 不同 依 赖 传 播 像的 的形 成依 依赖 赖于 于波 波在 在介 质中 中的 的传 传播 衰 减 衰减 散 散射 反 以 系 统 响 应 反射 射以 以及 及成 像系 系统 统响 响应 若 仅 令 灰 若仅 仅令 令网 络直 接预 测图 像灰 灰度 容 易 把 复 杂 压 缩 缺 乏 约 束 黑 盒 映 则容 容易 易把 把复 复杂 杂的 的成 像过 程压 压缩 缩为 为缺 缺乏 乏物 理约 约束 束的 的黑 黑盒 盒映 映射 虽 然 训 练 视 角 下 拟 虽然 然可 可能 能在 在训 训练 练视 视角 角下 下拟 拟合 合图 但 难 未 见 仍 具 有 稳 定 几 致 真 实 但难 难以 以保 证在 在未 未见 见视 下仍 仍具 具有 有稳 稳定 定的 的几 几何 何一 一致 致性 性和 和合 合理 的声 声学 学真 真实 实性 因 因此 之 外 在连 场表 征之 之外 引 入 个 算 子 引入 入了 了一 一个 个参 染算 算子 用于 于沿 沿射 线模 模拟 拟超 声传 播与 与图 像形 成过 其 式 写 其基 基本 本形 形式 式可 可写 写为 其中 义 集 为上 上一 一节 中定 定义 义的 的局 性集 集合 亚 辨 起 背 项 示由 由亚 亚分 分辨 辨散 射体 体引 引起 起的 的背 背散 射项 宏 界 面 由宏 宏观 观介 质界 界面 面引 的反 点 扩 函 现 到 素 为超 统的 的点 点扩 扩散 散函 函数 数以 以实 实现 现从 从回 波强 强度 度到 到图 像像 像素 素的 程映 深 则表 示深 深度 处 处的 部图 像响 意 了散 射与 与宏 射的 的示 示意 意图 简 记 号 为简 简化 化记 记号 均 固 件 以下 下均 均在 在固 固定 定一 一条 线的 的条 条件 件下 下讨 省 略 索 省略 略射 线索 索引', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b89acbdd6db2de860ee5b21f25480f73078826f28af27b2e41cbe7563f229563') ON CONFLICT(`id`) DO UPDATE SET `lo