INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b7d1e78ce0da5cc2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 参数化物理渲染建模', '现从回波强度到图像像素的成像过程映射， 则表示深度 处的局部图像响应。图 2.36与图 2.37给出了散射体引起的背散射与宏观介质界面引起的反射的示意图。为简化记号，以下均在固定一条射线的条件下讨论，省略射线索引[51,54–56,69]。
图 .36 散射体引起的背散射示意图
Figure 2.36 Illustration of backscattering caused by scatterers
图 .37 宏观介质界面引起的反射示意图
Figure 2.37 Illustration of reflection caused by the interface of a macroscopic medium
本节把背散射统计、界面方向反射和成像系统响应纳入可微渲染过程，以约束局部属性到B-mode图像的映射[154–156]。参数化物理渲染按照“剩余波强—背散射—界面反射—成像系统响应”的链条组织图像生成，并将超声物理规律作为归纳偏置引入连续神经场。UPI-NeRF 在该链条中采用瑞利分布描述散斑包络统计，以提高背散射纹理的真实性；同时采用基于微表面统计的方向参数化机制描述界面反射的入射角依赖性，以增强视角相关界面回波的表达能力[50,53,58–60]。', '2.36 2.37 51 54 56 69 36 figure illustration of backscattering caused by scatterers 37 reflection the interface macroscopic medium b-mode 154 156 upi-nerf 50 53 58 60 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 参 数 化 渲 染 模 参数 数化 化物 理渲 渲染 染建 建模 现 从 回 波 强 度 到 图 像 素 成 过 程 映 射 现从 从回 回波 波强 强度 度到 到图 图像 像像 像素 素的 的成 成像 像过 过程 程映 映射 则 表 示 深 则表 表示 示深 深度 处 局 部 响 应 处的 的局 局部 部图 像响 响应 与图 给 出 散 体 引 起 背 宏 观 介 质 界 面 反 意 给出 出了 了散 散射 射体 体引 引起 起的 的背 背散 射与 与宏 宏观 观介 介质 质界 界面 面引 的反 反射 射的 的示 示意 意图 简 记 号 为简 简化 化记 记号 以 下 均 固 定 一 条 线 件 讨 论 以下 下均 均在 在固 固定 定一 一条 条射 射线 线的 的条 条件 件下 下讨 讨论 省 略 索 省略 略射 线索 索引 射示 本 节 把 统 计 本节 节把 把背 射统 统计 方 向 系 纳 入 可 微 面方 方向 向反 射和 和成 像系 系统 统响 应纳 纳入 入可 可微 微渲 染过 约 束 属 性 以约 约束 束局 部属 属性 性到 像的 的映 按 照 染按 按照 剩 余 剩余 余波 面反 链 组 织 生 的链 链条 条组 组织 织图 像生 生成 并 将 规 律 作 归 偏 置 并将 将超 理规 规律 律作 作为 为归 归纳 纳偏 偏置 置引 引入 入连 该 采 用 瑞 利 分 布 描 述 斑 包 络 在该 该链 条中 中采 采用 用瑞 瑞利 利分 分布 布描 描述 述散 散斑 斑包 包络 络统 提 高 纹 真 实 以提 提高 高背 射纹 纹理 理的 的真 真实 实性 同 时 机 制 角 依 赖 同时 时采 用基 于微 微表 表面 面统 计的 的方 向参 化机 机制 制描 述界 的入 入射 射角 角依 依赖 赖性 增 视 相 关 达 能 力 以增 增强 强视 视角 角相 相关 关界 面回 波的 的表 表达 达能 能力', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b7d1e78ce0da5cc2d6c9d3c8237f2f351695f06cf9addc1356e825f3f30b3ca0') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e539ec5e67240d94', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 参数化物理渲染建模 / 基于瑞利分布的散射机制', '超声图像中的散斑纹理主要来源于大量亚分辨散射体在同一分辨单元内的相干叠加。这类纹理是介质微观结构在回波图像中的统计表现，不宜按独立噪声直接去除。背散射项因而描述分辨单元内随机散射场的包络统计，而非单个像素的任意灰度扰动。UPI-NeRF 据此以符合高频超声回波包络统计的瑞利分布，替代接近“离散发生/不发生”假设的伯努利或连续伯努利模型。[36,70–72]
设沿某条射线传播到深度 处时该位置的背散射能量项写为
其中， 是刻画局部散斑随机性的随机变量。这里， 反映了波在介质中传播到深度 后仍然保留的有效能量，而 则反映了该深度处分辨单元内部大量亚分辨散射体共同作用所引起的局部散射包络。该式表明，背散射项由传播衰减与局部统计散射共同决定，而非独立于传播过程的附加纹理项。
上式刻画了一个经典的高频超声散射模型：当一个分辨单元内存在大量亚波长尺度的散射体，且各散射体相位近似独立并服从均匀分布时，总回波包络可由大量随机相量叠加得到。根据中心极限定理，复平面上的实部与虚部将趋近高斯分布，从而其包络近似服从瑞利分布。因此， 可以写为
