INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-acb2f7ab2f4ff7af', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 参数化物理渲染建模 / 基于瑞利分布的散射机制', '络可由大量随机相量叠加得到。根据中心极限定理，复平面上的实部与虚部将趋近高斯分布，从而其包络近似服从瑞利分布。因此， 可以写为
其中， 为由神经场网络预测的散射幅度参数，用于控制该位置处背散射包络分布的尺度。若进一步从相量叠加模型出发，则有
该参数具有明确的物理含义： 越大，表示该位置的局部散射场包络整体更强，生成的散斑纹理在统计上也更显著； 越小，则说明局部散射包络整体较弱。与伯努利类模型的离散“开/关”假设不同，瑞利分布将散射描述为大量微观散射体叠加形成的连续随机场包络，更符合超声散斑的形成机制。表 2.2 与图 2.38分别从参数化形式与概率密度函数（PDF）形态两个维度对伯努利分布、连续伯努利分布及瑞利分布进行比较。表 2.2 显示，伯努利分布及其连续变体需联合使用散射密度 与幅度参数 进行描述，其底层逻辑仍受限于离散随机机制，难以自然映射超声散斑包络的连续演化过程；相比之下，瑞利分布仅受单一幅度参数 控制，便能刻画高频超声背散射的包络统计规律，兼顾物理可解释性与建模效率。图 2.38 呈现相应的概率密度差异：相较于伯努利分布族倾向于产生离散或生硬的响应，瑞利分布展现出更为平滑的连续包络曲线。这种概率密度形态的差异会影响重建图像中散斑纹理的视觉表现，即瑞利分布能够减少不自然的离散散射点，生成更符合超声回波包络统计的散斑结构。[67,68]', '2.2 2.38 pdf 67 68 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 参 数 化 渲 染 模 参数 数化 化物 理渲 渲染 染建 建模 瑞 利 分 布 散 射 机 制 于瑞 瑞利 利分 分布 布的 的散 散射 射机 机制 络 可 由 大 量 随 相 叠 加 得 到 络可 可由 由大 大量 量随 随机 机相 相量 量叠 叠加 加得 得到 根 据 心 极 限 定 根据 据中 中心 心极 极限 限定 定理 复 平 面 上 实 部 虚 将 趋 近 高 斯 复平 平面 面上 上的 的实 实部 部与 与虚 虚部 部将 将趋 趋近 近高 高斯 斯分 从 而 其 包 似 服 从而 而其 其包 包络 络近 近似 似服 服从 从瑞 因 此 因此 以 写 可以 以写 写为 其中 网 预 测 幅 度 为由 由神 场网 网络 络预 预测 测的 射幅 幅度 度参 用 控 该 位 置 处 背 尺 用于 于控 控制 制该 该位 位置 置处 处背 背散 射包 络分 的尺 尺度 若 进 一 步 型 出 发 若进 进一 一步 步从 从相 加模 模型 型出 出发 则 有 则有 具 明 确 含 义 该参 数具 具有 有明 明确 确的 的物 理含 含义 越 越大 表 示 局 整 体 更 强 表示 示该 置的 的局 局部 部散 射场 场包 络整 整体 体更 更强 生 成 斑 纹 统 计 也 显 著 生成 成的 散斑 斑纹 纹理 理在 在统 统计 计上 上也 也更 更显 显著 小 越小 说 较 弱 则说 说明 明局 体较 较弱 伯 努 类 离 与伯 伯努 努利 利类 类模 型的 的离 离散 开 关 假 设 不 同 假设 设不 不同 描 述 微 观 形 布将 将散 射描 描述 述为 为大 量微 微观 观散 射体 体叠 加形 形成 的连 续随 机场 符 合 更符 符合 合超 声散 斑的 的形 成机 图 与图 别 式 概 率 密 函 分别 别从 从参 化形 形式 式与 与概 概率 率密 密度 度函 函数 态 两 个 对 形态 态两 两个 个维 维度 度对 对伯 行 比 续伯 布及 及瑞 布进 进行 行比 比较 显示 变 需 联 使 及其 其连 续变 变体 体需 需联 联合 合使 使用 用散 射密 与幅 行描 底 层 逻 辑 仍 受 其底 底层 层逻 逻辑 辑仍 仍受 受限 限于 于离 散随 机机 难 自 然 映 演 过 程 难以 以自 自然 然映 映射 射超 斑包 络的 续演 演化 化过 过程 之 下 相比 比之 之下 仅 单 布仅 仅受 受单 单一 一幅 便 能 刻 画 频 规 律 便能 能刻 刻画 画高 高频 频超 声背 射的 的包 络统 计规 规律 兼 顾 解 释 性 效 兼顾 顾物 理可 可解 解释 释性 性与 与建 模效 效率 呈 现 应 差 异 呈现 现相 相应 应的 的概 度差 差异 族 倾 向 产 或 硬 响 相较 较于 于伯 布族 族倾 倾向 向于 于产 产生 生离 散或 或生 生硬 硬的 的响 响应 展 滑 曲 线 布展 展现 现出 出更 更为 为平 平滑 滑的 续包 络曲 曲线 这 种 会 影 像 视 觉 这种 种概 度形 态的 的差 异会 会影 影响 响重 建图 图像 像中 中散 理的 的视 视觉 觉表 表现 即 够 减 少 点 即瑞 布能 能够 够减 减少 少不 不自 然的 散散 射点 回 波 结 构 成更 声回 回波 波包 计的 斑结 结构', '/#research', 'doctoral-thesis