INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0515154859fe00de', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 参数化物理渲染建模 / 基于方向参数化的反射机制', '在刻画组织内部散射统计特性之后，还需要进一步处理组织界面处随入射方向变化的反射行为，以更完整地描述超声图像中的视角依赖效应。
2.6.1　 节主要解决的是介质内部微观散射所形成的散斑纹理，2.6.2　 节关注的则是介质宏观界面处的反射问题。与背散射不同，界面反射往往来源于明显的声阻抗不连续，例如不同组织类型的边界、器官表面或较强的结构界面。这类回波不仅取决于局部阻抗失配程度，还高度依赖于入射方向与界面法向之间的几何关系。因此，若忽略反射的方向依赖性，而仅将其视为各向同性能量项，则很难准确刻画超声图像中最具辨识度的高亮界面结构。UPI-NeRF 的第二个关键改进，正是在于引入了基于方向参数化的反射机制，以更精细地描述介质界面处的入射角依赖回波。[7,61,70,71]
