INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1106547f0a033fcb', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 参数化物理渲染建模 / 基于方向参数化的反射机制', '-Fisher 分布的概率密度函数
Figure 2.40 Probability density functions of the von Mises-Fisher distribution under different values.
为了解决这一问题，UPI-NeRF 借鉴计算机图形学中的微表面（microfacet）思想[42,165,171]，如图 2.39所示，将宏观界面参数化建模为大量微小表面元的集合。神经场网络预测得到的 表示该位置处的宏观平均法向，局部界面由大量围绕该宏观法向分布的微表面法向 构成，反射的角域扩散可由微表面法向的统计分布导出，无需人为设定经验指数。在 UPI-NeRF 中，微表面法向分布采用 von Mises–Fisher（vMF）分布刻画，其概率密度函数写为
其中， 为由神经场网络预测的法向集中参数，也可理解为与界面粗糙度相对应的参数。图 2.40 展示了不同 下 vMF 分布的概率密度曲线，直观反映了界面粗糙度对法向集中程度的影响，其物理含义十分清楚：当 较大时，微表面法向高度集中于宏观法向附近，说明界面较为平滑，反射峰更尖锐；当 较小时，微表面法向分布更为分散，说明界面更为粗糙，反射能量在更宽的角域内扩散。在这一微表面统计模型下，方向因子可以进一步写为', 'fisher figure 2.40 probability density functions of the von mises-fisher distribution under different values. upi-nerf microfacet 42 165 171 2.39 mises vmf 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 参 数 化 渲 染 模 参数 数化 化物 理渲 渲染 染建 建模 方 向 反 射 机 制 于方 方向 向参 化的 的反 反射 射机 机制 分 布 概 率 密 度 函 分布 布的 的概 概率 率密 密度 度函 函数 解 决 这 一 问 题 为了 了解 解决 决这 这一 一问 问题 借 鉴 计 算 图 形 学 微 表 面 借鉴 鉴计 计算 算机 机图 图形 形学 学中 中的 的微 微表 表面 思 想 思想 如 如图 所 示 所示 将 宏 观 界 大 量 小 元 集 合 将宏 宏观 观界 界面 面参 化建 模为 为大 大量 量微 微小 小表 面元 元的 的集 集合 网 络 预 测 得 到 场网 网络 络预 预测 测得 得到 到的 该 位 置 处 平 均 法 表示 示该 该位 位置 置处 处的 的宏 观平 平均 均法 法向 局 部 由 围 绕 局部 部界 面由 由大 量围 围绕 绕该 该宏 观法 向分 面法 构 成 构成 角 域 扩 散 可 统 导 出 射的 的角 角域 域扩 扩散 散可 可由 由微 向的 的统 统计 计分 布导 导出 无 需 人 设 定 验 指 无需 需人 人为 为设 设定 定经 经验 验指 指数 采 用 布采 采用 刻 画 布刻 刻画 其 写 其概 数写 写为 其中 为由 由神 测的 的法 向集 集中 中参 也 粗 糙 相 对 应 也可 可理 理解 解为 为与 与界 面粗 粗糙 糙度 度相 相对 对应 应的 的参 展 不 同 展示 示了 了不 不同 下 曲 线 度曲 曲线 直 映 程 影 响 直观 观反 反映 映了 了界 度对 对法 中程 程度 度的 的影 影响 含 义 十 清 楚 其物 理含 含义 义十 十分 分清 清楚 当 较 时 较大 大时 高 附 近 向高 高度 度集 中于 于宏 向附 附近 说 明 滑 说明 明界 面较 较为 为平 平滑 峰 更 尖 锐 射峰 峰更 更尖 尖锐 较小 小时 布更 更为 为分 分散 面更 为粗 能 宽 内 射能 能量 量在 在更 更宽 宽的 域内 内扩 型 在这 一微 面统 计模 模型 型下 因 子 以 进 步 向因 因子 子可 可以 以进 进一 一步 步写', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1106547f0a033fcbbf4d1fdc2a17d45be29f9b01bd52905f5e3a7e719df0046c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
