INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-8f2c670dc5617bea', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 超声三维重建的实验设置与图像质量评价 / 实验设置', '为比较不同三维表征与渲染机制，实验设置离散体素插值和连续神经场两类基线[6,24,25,32,48,171]。体素方法包括PNN和VNN；神经场方法包括五种代表性模型。所有方法采用一致的数据划分与计算环境，差异来自各自的表征或渲染机制。
在网络结构的对齐与超参数设定上，所有神经场基线模型（包含本文提出的 UPI-NeRF）均在统一计算环境与实验协议下实现。除了特有的物理渲染模块外，本文所提框架中核心多层感知机（MLP）的层数与维度均与标准 NeRF 基线保持一致。在射线采样策略上，基线方法采用每条射线 128 个粗采样点（Coarse points）与 128 个细采样点（Fine points）的分层采样机制，而本文方法则采用等计算量成本的改进采样策略。所有模型均采用均方误差（MSE）作为基础的图像域监督信号[32,48,171]，以控制监督信号、计算复杂度和推理效率比较中的非目标差异。在优化设置方面，所有基线模型与本文提出的 UPI-NeRF 均采用 Adam 优化器，并结合带有 1.6 轮预热的指数衰减学习率调度策略 。批处理规模设为 512，初始学习率相应设置为 。所有模型均训练 32 轮 。全部实验均在搭载 32 GB 显存的 NVIDIA RTX 4090 GPU 上完成（CUDA 11.8）。', '24 25 32 48 171 pnn vnn upi-nerf mlp nerf 128 coarse points fine mse adam 1.6 512 gb nvidia rtx 4090 gpu cuda 11.8 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 设 置 图 像 质 量 评 价 建的 的实 验设 设置 置与 与图 图像 像质 质量 量评 评价 比 较 不 同 表 征 渲 染 机 制 为比 比较 较不 不同 同三 维表 表征 征与 与渲 渲染 染机 机制 离 散 体 素 插 值 两 类 线 置离 离散 散体 体素 素插 插值 值和 和连 场两 两类 类基 基线 方 法 包 括 素方 方法 法包 包括 五 种 代 性 模 型 场方 括五 五种 种代 代表 表性 性模 模型 所 有 采 用 一 致 数 据 划 计 算 环 境 所有 有方 法采 采用 用一 一致 致的 的数 数据 据划 划分 分与 与计 计算 算环 环境 差 异 来 自 各 或 差异 异来 来自 自各 各自 自的 的表 征或 或渲 网 络 构 对 齐 参 定 上 在网 网络 络结 结构 构的 的对 对齐 齐与 与超 超参 参数 数设 设定 定上 有神 场基 线模 含 本 文 提 出 包含 含本 本文 文提 提出 出的 均 统 协 议 下 现 均在 在统 统一 一计 境与 与实 验协 协议 议下 下实 实现 除 特 块 外 除了 了特 特有 有的 的物 理渲 染模 模块 块外 框 架 核 心 多 层 感 知 文所 所提 提框 框架 架中 中核 核心 心多 多层 层感 感知 知机 度 标 准 的层 层数 数与 与维 维度 度均 均与 与标 标准 保 持 线保 保持 持一 射 样 策 略 在射 射线 线采 采样 样策 策略 略上 每 条 线方 用每 每条 条射 个 粗 点 个粗 粗采 样点 细 个细 细采 的分 分层 层采 样机 而 则 等 成 改 进 而本 文方 法则 则采 用等 等计 算量 量成 成本 本的 的改 改进 进采 误 有模 型均 均采 用均 均方 方误 误差 作 础 域 监 督 信 号 作为 为基 基础 础的 的图 像域 域监 监督 督信 信号 以 控 以控 控制 制监 复 杂 推 效 率 非 目 算复 复杂 杂度 度和 和推 推理 理效 效率 率比 较中 中的 的非 非目 目标 标差 优 化 面 在优 优化 化设 置方 方面 有基 型与 与本 器 化器 并 合 带 并结 结合 合带 带有 轮 预 热 指 衰 减 学 习 调 轮预 预热 热的 的指 指数 数衰 衰减 减学 学习 习率 率调 调度 度策 批 处 规 批处 处理 理规 规模 模设 设为 初 始 相 应 初始 始学 率相 相应 应设 置为 训 练 均训 训练 全 部 搭 载 全部 部实 验均 在搭 搭载 显 存 显存 存的 完 上完 完成', '/#research', 'doctoral-thesis', 1, '2026-08-04', '8f2c670dc5617bea2525041bfd740d051f5f90430826b416d8328ef49f193f59') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=exclu