INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-dba161037ceaac0c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 超声三维重建的实验设置与图像质量评价 / 评估指标', '在评估重建图像的客观质量时，本文选取了峰值信噪比（Peak Signal-to-Noise Ratio, PSNR）、结构相似度（Structural Similarity, SSIM）以及学习感知图像块相似度（Learned Perceptual Image Patch Similarity, LPIPS）作为核心量化指标 。为便于对不同方法的综合性能进行直观对比，引入了一个综合误差指标 ：[173,174]
在该公式中，PSNR 用于反映像素级的绝对保真度，SSIM 衡量图像局部结构与对比度的相似性，而 LPIPS 侧重于评估高频纹理（如超声散斑）在深度特征空间中的人类视觉感知差异；综合指标 的值越小，代表整体重建质量越高。
在统计学分析方面，为了严密评估不同重建方法之间在定量指标上差异的显著性与实际提升幅度，本文采用双侧 Welch''s t 检验（Two-sided Welch''s t-test）计算 p 值，并结合 Cohen''s d 指标评估效应量（Effect size）大小。对于任意两组独立的模型评估结果，假设其样本均值分别为 和 ，样本方差分别为 和 ，样本容量分别为 和 。由于不同方法的评估指标方差可能存在不齐性，本文采用 Welch-Satterthwaite 近似计算检验统计量 及其对应的自由度 ，并且进一步双侧 值可通过自由度为 的 t 分布的累积分布函数（Cumulative Distribution Function, CDF） 计算求得：', 'peak signal-to-noise ratio psnr structural similarity ssim learned perceptual image patch lpips 173 174 welch two-sided t-test cohen effect size welch-satterthwaite cumulative distribution function cdf 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 设 置 图 像 质 量 评 价 建的 的实 验设 设置 置与 与图 图像 像质 质量 量评 评价 估 指 标 评估 估指 指标 客 观 时 在评 估重 建图 像的 的客 客观 观质 量时 本 文 选 取 峰 值 信 噪 比 本文 文选 选取 取了 了峰 峰值 值信 信噪 噪比 构 相 似 度 结构 构相 相似 似度 以 学 习 感 知 块 以及 及学 学习 习感 感知 知图 像块 块相 作 核 心 化 作为 为核 核心 心量 量化 化指 便 对 不 同 方 法 综 合 性 能 进 行 直 为便 便于 于对 对不 不同 同方 方法 法的 的综 综合 合性 性能 能进 进行 行直 直观 观对 对比 引 入 一 个 误 差 引入 入了 了一 一个 个综 合误 误差 差指 该 公 式 在该 该公 公式 式中 用 反 映 素 级 绝 保 真 用于 于反 反映 映像 像素 素级 级的 的绝 绝对 对保 保真 真度 衡 局 部 衡量 量图 像局 局部 部结 构与 与对 比度 度的 的相 似性 而 侧 高 频 纹 侧重 重于 于评 估高 高频 频纹 纹理 如 散 斑 如超 声散 散斑 深 特 征 空 间 人 类 视 觉 异 在深 深度 度特 特征 征空 空间 间中 中的 的人 人类 类视 视觉 觉感 知差 差异 合指 越 小 的值 值越 越小 代 表 整 体 代表 表整 整体 体重 建质 量越 越高 统 计 面 在统 统计 计学 学分 析方 方面 严 密 之 定 上 显 著 际 提 升 幅 为了 了严 严密 密评 估不 同重 建方 法之 之间 间在 在定 定量 量指 标上 上差 异的 的显 显著 著性 性与 与实 实际 际提 提升 升幅 幅度 采 双 文采 采用 用双 双侧 检 检验 算 计算 并 并结 结合 效 应 标评 估效 效应 应量 大 大小 任 意 两 组 独 立 模 型 对于 于任 任意 意两 两组 组独 独立 立的 的模 模型 型评 估结 假 其 样 均 别 假设 设其 其样 样本 本均 均值 值分 分别 别为 本方 方差 差分 容 本容 容量 量分 由 可 存 齐 由于 于不 的评 标方 差可 可能 能存 存在 在不 不齐 齐性 近 近似 似计 算检 验统 计量 自 及其 其对 对应 应的 的自 自由 由度 且 步 并且 且进 进一 一步 步双 通 过 值可 可通 通过 过自 度为 布 累 积 函 数 分布 布的 的累 累积 积分 布函 函数 求 得 算求 求得', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'dba161037ceaac0ca7b7d7f6e1eba052ee527ac1eff4fb8bde7b77308951ef20') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text