INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f1181ebed0071924', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 超声三维重建的实验设置与图像质量评价 / 评估指标', '本文采用 Welch-Satterthwaite 近似计算检验统计量 及其对应的自由度 ，并且进一步双侧 值可通过自由度为 的 t 分布的累积分布函数（Cumulative Distribution Function, CDF） 计算求得：
然而，p 值极易受到样本容量的影响。为了进一步客观衡量两组方法性能差异的实际相对幅度，本文引入了 Cohen''s d 效应量指标。其计算方式为两组样本均值之差的绝对值与合并标准差（Pooled standard deviation） 的比值：
在本文的实验评估中，根据统计学领域的标准经验法则，当 p < 0.05 时，表明两种方法的性能差异在统计学上是显著的；当 时，则视为存在高度显著的差异；当 d > 0.8 时，表示两方法之间存在较大的性能差异（Large effect size）；而当 d > 2.0 时，则表明所提方法相较于对比基线不仅在统计上高度显著，且在实际重建性能上具备极大的优势。
上述数据划分、训练设置、图像质量指标与统计检验构成第3章的新视角合成公共协议；第3章另增加平移和旋转误差，用于评价位姿修正。', 'welch-satterthwaite cumulative distribution function cdf cohen pooled standard deviation 0.05 0.8 large effect size 2.0 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 设 置 图 像 质 量 评 价 建的 的实 验设 设置 置与 与图 图像 像质 质量 量评 评价 估 指 标 评估 估指 指标 本 文 采 用 本文 文采 采用 近 似 计 算 检 统 近似 似计 计算 算检 检验 验统 统计 计量 其 对 应 自 由 度 及其 其对 对应 应的 的自 自由 由度 并 且 进 一 步 双 侧 并且 且进 进一 一步 步双 双侧 值 可 通 过 值可 可通 通过 过自 度为 布 累 积 函 数 分布 布的 的累 累积 积分 布函 函数 求 得 算求 求得 然 而 然而 极 易 受 到 样 容 影 响 值极 极易 易受 受到 到样 样本 本容 容量 量的 的影 影响 客 观 衡 两 组 方 法 性 能 差 异 际 相 幅 为了 了进 步客 客观 观衡 衡量 量两 两组 组方 方法 法性 性能 能差 差异 异的 实际 际相 相对 对幅 幅度 引 入 文引 引入 入了 效 效应 应量 量指 式 均 之 绝 合 准 其计 算方 方式 式为 为两 组样 本均 均值 值之 之差 差的 的绝 绝对 对值 值与 与合 合并 并标 标准 准差 比 的比 比值 在本 文的 验评 估中 根 据 学 领 域 则 根据 据统 计学 学领 领域 域的 的标 准经 经验 验法 法则 当 时 表 明 种 上 显 著 表明 明两 两种 种方 法的 的性 异在 在统 学上 上是 是显 显著 著的 视 存 高 则视 视为 为存 存在 在高 高度 度显 的差 示 间 较 大 表示 示两 两方 法之 之间 间存 在较 较大 大的 而当 所 提 线 不 仅 则表 明所 所提 提方 法相 相较 较于 于对 对比 比基 基线 线不 不仅 仅在 计上 上高 具 备 优 势 且在 在实 际重 建性 能上 上具 具备 备极 极大 的优 优势 述 划 上述 述数 数据 据划 划分 训 练 训练 练设 构 成 标与 与统 计检 验构 构成 成第 新 角 公 共 协 议 章的 的新 新视 视角 角合 合成 成公 公共 共协 协议 另 增 加 平 移 旋 转 误 章另 另增 增加 加平 平移 移和 和旋 旋转 转误 误差 位 姿 修 正 用于 于评 价位 位姿 姿修 修正', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f1181ebed00719245442c84e2d308bf57b0257504cabb5ddecf9ccb3032917b3') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-edce07bc92ae3f72', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 离散体素表征与连续神经场表征对比', '该实验检验非均匀采样下，连续函数的跨坐标共享能否比局部体素写入更好地保持未观测区域的结构连续性。两类表征在相同数据划分和指标下比较新视角合成、结构保持与资源开销。
实验比较UPI-NeRF与PNN、VNN[6,24,25]在256、128和64个训练视图下的表现。三种设置保持扫查轨迹形状不变，仅逐级降低空间覆盖密度，因而可用于观察不同表征对稀疏采样的敏感性。图 2.41展示了对应的位姿分布。
图 2.41 不同采样密度的训练数据集的位姿分布。
Figure 2.41 Training-pose distributions at different sampling densities.
图 .42 不同训练视图稀疏度下各方法的重建质量对比
Figure 2.42 Reconstruction quality across methods under different training-view sparsities.
图 2.42显示，PNN和VNN在256视图下尚能维持基本结构，降至128和64视图后分别出现撕裂、细节缺失和插值伪影。该现象与离散网格依赖局部观测和邻域插值的机制一致：覆盖不足时，缺失区域难以由共享场景约束补偿。[26,27,35,73]', 'upi-nerf pnn vnn 24 25 256 128 64 2.41 figure training-pose distributions at different sampling densities. 42 2.42 reconstruction quality across methods under training-view sparsities. 26 27 35 73 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 离 散 体 素 表 征 对 比 离散 散体 体素 素表 表征 征与 场表 征对 对比 该 检 非 均 匀 采 样 下 该实 验检 检验 验非 非均 均匀 匀采 采样 样下 函 数 跨 坐 标 共 享 能 否 局 部 写 入 更 好 地 保 持 未 观 测 区 域 构 性 续函 函数 数的 的跨 跨坐 坐标 标共 共享 享能 能否 否比 比局 局部 部体 素写 写入 入更 更好 好地 地保 保持 持未 未观 观测 测区 区域 域的 的结 结构 构连 续性 两 类 相 同 据 划 指 较 新 视 角 合 成 两类 类表 征在 在相 相同 同数 数据 据划 划分 分和 和指 指标 标下 下比 比较 较新 新视 视角 角合 合成 资 源 开 销 构保 持与 与资 资源 源开 开销 验比 个 训 练 图 现 个训 训练 练视 视图 图下 下的 的表 表现 种 设 置 扫 查 轨 迹 形 状 不 变 三种 种设 设置 置保 持扫 扫查 查轨 轨迹 迹形 形状 状不 不变 仅 逐 级 降 低 空 间 覆 盖 密 度 仅逐 逐级 级降 降低 低空 空间 间覆 覆盖 盖密 密度 因 而 可 用 察 稀 疏 敏 感 因而 而可 可用 用于 于观 观察 察不 不同 同表 对稀 稀疏 疏采 样的 的敏 敏感 感性 展 示 应 位 姿 布 展示 示了 了对 对应 应的 的位 位姿 姿分 分布 集 同采 样密 度的 的训 练数 据集 集的 各 方 法 质 量 同训 图稀 疏度 度下 下各 各方 方法 法的 的重 建质 质量 量对 显 显示 尚 本 下尚 尚能 能维 维持 持基 基本 本结 至 降至 后 别 出 撕 裂 图后 后分 分别 别出 出现 现撕 撕裂 细 节 缺 失 插 值 伪 影 细节 节缺 缺失 失和 和插 插值 值伪 伪影 象 网 格 依 赖 邻 机 制 一 致 该现 现象 象与 与离 散网 网格 格依 依赖 赖局 部观 测和 和邻 邻域 域插 值的 的机 机制 制一 一致 足 时 盖不 不足 足时 难 以 由 景 约 束 补 偿 失区 域难 难以 以由 由共 享场 场景 景约 约束 束补 补偿', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'edce07bc92ae3f7203a62b3d2308b8fc257a1ed81fc0b7dc90a2f8740a4c73c6') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1a2914fc65158446', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 离散体素表征与连续神经场表征对比', '图 2.42显示，PNN和VNN在256视图下尚能维持基本结构，降至128和64视图后分别出现撕裂、细节缺失和插值伪影。该现象与离散网格依赖局部观测和邻域插值的机制一致：覆盖不足时，缺失区域难以由共享场景约束补偿。[26,27,35,73]
相对而言，UPI-NeRF在视图稀疏条件下仍然保持了较好的解剖结构连续性和局部纹理质量，显示出更强的鲁棒性。从统计结果看，即使在仅使用 64 张训练图像的低数据条件下，其重建指标与视觉质量依然显著优于使用 256 张图像训练的 PNN 和 VNN（UPI-NeRF-64 > PNN-256: , ；UPI-NeRF-64 > VNN-256: , ） 。该结果将性能差异归因于连续神经场对整个三维场景的共享建模，而非更高的采样密度。对于自由手超声这样天然采样不均匀与局部稀疏存在的问题，连续神经场表征比离散体素插值更适合作为三维重建表示。
实验结果支持2.4.1　和2.4.2　节的理论判断：离散体素在稀疏、非均匀采样下更易受空洞和插值误差影响；连续神经场通过共享函数和多视角一致性约束维持了更好的结构连续性。该结论限于当前数据与采样协议。[34]', '2.42 pnn vnn 256 128 64 26 27 35 73 upi-nerf upi-nerf-64 pnn-256 vnn-256 2.4.1 2.4.2 34 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 离 散 体 素 表 征 对 比 离散 散体 体素 素表 表征 征与 场表 征对 对比 图 显 示 显示 视 下 尚 能 持 本 构 视图 图下 下尚 尚能 能维 维持 持基 基本 本结 结构 降 至 降至 后 别 出 现 撕 裂 图后 后分 分别 别出 出现 现撕 撕裂 细 节 缺 失 插 值 伪 影 细节 节缺 缺失 失和 和插 插值 值伪 伪影 该 象 网 格 依 赖 局 部 观 测 邻 域 机 制 一 致 该现 现象 象与 与离 散网 网格 格依 依赖 赖局 局部 部观 观测 测和 和邻 邻域 域插 值的 的机 机制 制一 一致 覆 盖 不 足 时 覆盖 盖不 不足 足时 区 难 以 由 共 享 景 约 束 补 偿 失区 区域 域难 难以 以由 由共 共享 享场 场景 景约 约束 束补 补偿 相 而 言 相对 对而 而言 稀 疏 条 件 仍 然 保 较 好 解 剖 性 纹 质 量 在视 图稀 稀疏 疏条 条件 件下 下仍 仍然 然保 保持 持了 了较 较好 好的 的解 解剖 剖结 构连 续性 性和 和局 部纹 纹理 理质 质量 更 强 鲁 棒 示出 出更 更强 强的 的鲁 鲁棒 棒性 从 统 计 看 从统 统计 计结 果看 即 使 仅 用 即使 使在 在仅 仅使 使用 张 训 练 像 低 数 据 张训 训练 练图 图像 像的 的低 低数 数据 据条 其 指 标 觉 著 优 其重 建指 指标 标与 与视 视觉 觉质 量依 依然 然显 显著 著优 优于 于使 张图 像训 练的 将 差 异 归 因 整 个 模 该结 果将 将性 性能 能差 差异 异归 归因 因于 于连 场对 对整 整个 个三 维场 景的 的共 享建 建模 非 高 采 样 密 度 而非 非更 更高 高的 的采 采样 样密 密度 自 手 这 天 均 匀 存 问 题 对于 于自 自由 由手 手超 声这 这样 样天 天然 然采 样不 不均 均匀 匀与 与局 部稀 疏存 存在 在的 的问 问题 适 合 作 征比 比离 素插 值更 更适 适合 合作 作为 为三 建表 表示 支 果支 支持 论 判 断 节的 的理 理论 论判 判断 素在 在稀 易 受 空 洞 误 响 非均 匀采 样下 下更 更易 易受 受空 空洞 洞和 值误 误差 差影 影响 通 过 函 多 角 场通 通过 过共 享函 函数 数和 和多 多视 视角 角一 致性 性约 束维 了更 更好 的结 限 当 前 协 议 结论 论限 限于 于当 当前 前数 据与 与采 样协 协议', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1a2914fc651584469c92899b720a00642dd2092183008632a8fd02fa173a893c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3fb944a817ac980d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 神经场表达增强消融实验', '该消融检验位置与方向编码、分层采样和周期激活是否按预期改善高频与方向响应。只有当增益跨越不同神经场基线并同时体现在结构、感知和灰度指标上，才能排除特定网络或单一指标造成的偶然改善。
实验在多个神经场模型中加入2.5　节定义的采样、编码和周期激活模块，并以“+”标记增强版本，例如NeRF+。在保持渲染机制不变的条件下，比较增强前后的重建结果，以分离网络表达能力的贡献。[43,44,48,168]
表 2.3 引入表达增强模块前后各模型在图像质量与推理效率上的定量对比
Table . Reconstruction quality and efficiency with representational enhancement.
Mip-NeRF/
Mip-NeRF+
Ref-NeRF/
Ref-NeRF+
Ultra-NeRF/
Ultra-NeRF+
Ultra-NeRF-CB/
Ultra-NeRF-CB+
注释：“+”表示采用了本文提出的优化，比如说NeRF/NeRF+
图 .43 神经场表达增强前后各基线模型的重建质量对比
Figure 2.43 Reconstruction quality before and after neural-field enhancement.', '2.5 nerf+ 43 44 48 168 2.3 table reconstruction quality and efficiency with representational enhancement. mip-nerf mip-nerf+ ref-nerf ref-nerf+ ultra-nerf ultra-nerf+ ultra-nerf-cb ultra-nerf-cb+ nerf figure 2.43 before after neural-field 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 表 达 增 强 消 融 场表 表达 达增 增强 强消 消融 融实 该 检 位 置 方 向 编 码 该消 融检 检验 验位 位置 置与 与方 方向 向编 编码 层 采 样 周 期 激 活 否 按 预 改 善 高 频 响 应 分层 层采 采样 样和 和周 周期 期激 激活 活是 是否 否按 按预 预期 期改 改善 善高 高频 频与 向响 响应 只 有 当 益 跨 越 不 同 线 并 时 体 现 构 只有 有当 当增 增益 益跨 跨越 越不 不同 同神 场基 基线 线并 并同 同时 时体 体现 现在 在结 结构 感 知 灰 度 指 标 上 感知 知和 和灰 灰度 度指 指标 标上 才 能 排 除 特 定 网 络 或 单 一 造 成 偶 然 才能 能排 排除 除特 特定 定网 网络 络或 或单 单一 一指 标造 造成 成的 的偶 偶然 然改 多 个 模 型 加 入 验在 在多 多个 个神 场模 模型 型中 中加 加入 节 义 节定 定义 义的 的采 块 码和 活模 模块 以 并以 记 版 本 标记 记增 强版 版本 例 如 例如 保 持 渲 染 机 制 变 条 件 下 在保 保持 持渲 渲染 染机 机制 制不 不变 变的 的条 条件 件下 比 较 前 后 比较 较增 强前 前后 后的 的重 建结 离 力 贡 献 以分 分离 离网 络表 达能 能力 力的 的贡 贡献 引 各 图 像 质 量 推 效 率 对 引入 入表 强模 块前 后各 各模 型在 在图 图像 像质 质量 量与 与推 推理 理效 效率 率上 上的 的定 定量 量对 对比 注 释 注释 示 用 文 提 出 优 化 表示 示采 采用 用了 了本 本文 文提 提出 出的 的优 优化 说 比如 如说 各基 线模 型的 建质', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3fb944a817ac980d06f5f5fb48983bef277a964a5126c4ccdeb3d712899ee513') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e87b1c42e414c466', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 神经场表达增强消融实验', '，比如说NeRF/NeRF+
图 .43 神经场表达增强前后各基线模型的重建质量对比
Figure 2.43 Reconstruction quality before and after neural-field enhancement.
表 2.3的实验数据表明，在推理时间仅小幅增加的条件下，表达能力增强模块对所有受试基线模型均带来了统计显著的性能改善（NeRF+(, ), Mip-NeRF+(, ), Ref-NeRF+(, ), Ultra-NeRF+(, ), Ultra-NeRF-CB+(, ).）。从图 2.43可以清晰观察到，未经增强的模型通常难以完整恢复整个场景，表现为边界模糊、局部结构缺失以及高频纹理不足；引入增强模块后，重建图像中的组织边界更加清晰，局部纹理更丰富，高频结构表达能力明显提升。该改善在多类 NeRF 基线上均可观察到，说明2.5　 节提出的表达增强机制不依赖单一网络结构，在受试基线范围内具有一致作用。
表达增强后，物理渲染差异更易在对照中辨认。直接强度回归模型中，Ref-NeRF+的综合结果高于NeRF+和Mip-NeRF+；超声物理渲染模型中，Ultra-NeRF-CB+高于Ultra-NeRF+。这些结果说明高频拟合能力会影响不同渲染机制的可辨识程度，但比较范围仅限当前基线和实验协议。[7,36]', 'nerf nerf+ 43 figure 2.43 reconstruction quality before and after neural-field enhancement. 2.3 mip-nerf+ ref-nerf+ ultra-nerf+ ultra-nerf-cb+ 2.5 36 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 表 达 增 强 消 融 场表 表达 达增 增强 强消 消融 融实 比 如 说 比如 如说 图 前 后 各 线 模 型 质 量 对 强前 前后 后各 各基 基线 线模 模型 型的 的重 建质 质量 量对 对比 数 据 明 的实 验数 数据 据表 表明 推 时 间 仅 小 幅 加 条 件 下 在推 推理 理时 时间 间仅 仅小 小幅 幅增 增加 加的 的条 条件 件下 能 力 块 所 有 受 试 均 带 来 统 计 显 著 性 改 善 达能 能力 力增 强模 模块 块对 对所 所有 有受 受试 试基 型均 均带 带来 来了 了统 统计 计显 显著 著的 的性 性能 能改 改善 从 从图 可 以 清 晰 观 察 到 可以 以清 清晰 晰观 观察 察到 未 通 常 难 完 整 恢 复 个 景 未经 经增 强的 的模 型通 通常 常难 难以 以完 完整 整恢 恢复 复整 整个 个场 场景 现 边 界 糊 表现 现为 为边 边界 界模 模糊 局 部 构 缺 失 高 频 纹 不 足 局部 部结 结构 构缺 缺失 失以 以及 及高 高频 频纹 纹理 理不 不足 引 入 引入 入增 块后 像 组 织 更 建图 图像 像中 中的 的组 组织 织边 界更 更加 加清 丰 富 部纹 理更 更丰 丰富 提 升 频结 构表 力明 明显 显提 提升 该 多 类 该改 善在 在多 多类 上 线上 上均 均可 可观 说明 节 出 机 制 依 赖 单 一 网 络 节提 提出 出的 的表 强机 机制 制不 不依 依赖 赖单 单一 一网 网络 络结 范 围 内 具 致 作 用 在受 线范 范围 围内 内具 具有 有一 一致 致作 作用 强后 渲 染 差 异 易 照 辨 认 理渲 渲染 染差 差异 异更 更易 易在 在对 对照 照中 中辨 辨认 直 接 度 回 归 直接 接强 强度 度回 回归 归模 型中 综 合 的综 综合 合结 果高 高于 染模 这 些 拟 会 影 响 同 识 程 这些 些结 果说 明高 频拟 拟合 合能 力会 会影 影响 响不 不同 同渲 染机 制的 的可 可辨 辨识 识程 程度 但 较 限 当 协 议 但比 比较 较范 围仅 仅限 限当 当前 前基 线和 和实 验协 协议', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e87b1c42e414c46622d20b2b53be4744dec3eb962f01a710f3bccbee098308e1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5a95670b34643446', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 参数化物理建模消融实验', '物理渲染消融分别检验瑞利背散射和方向参数化反射。若两者分别改善散斑统计与界面方向响应，联合模型应在纹理、结构和灰度指标间取得互补收益。
在统一表达增强条件下，实验比较第2.5　节所述的7种渲染策略[7,32,36,42,48,171]：直接强度回归的NeRF+和Ref-NeRF+，伯努利散射的Ultra-NeRF+和Ultra-NeRF-CB+，以及UPI-NeRF(B)、UPI-NeRF(R)和UPI-NeRF(B+R)。表 2.4给出基线和单组件定量结果，图 2.44展示包括联合模型在内的定性比较及其定量指标。
表 2.4 不同参数化物理渲染机制在图像质量与推理效率上的定量对比
Table . Reconstruction quality and efficiency of parameterized physical rendering.
图 .44 多次扫查场景下不同参数化物理渲染机制的重建质量对比
Figure 2.44 Reconstruction quality of physical rendering methods in multi-sweep scans.
基于瑞利分布的背散射建模主要改善散斑纹理的真实性。表 2.4 中，UPI-NeRF(B) 的重建指标高于 Ultra-NeRF+ （, ）及 Ultra-NeRF-CB+ （, ）。图 2.44显示，引入瑞利分布背散射的UPI-NeRF(B)能够生成更连续且更符合超声成像特征的散斑纹理。该结果表明，采用瑞利分布对微观散射体进行建模，相较于伯努利分布假设，有助于生成在统计意义上更连续且更接近真实超声响应的散斑纹理 。[65,70–72]', '2.5 32 36 42 48 171 nerf+ ref-nerf+ ultra-nerf+ ultra-nerf-cb+ upi-nerf b+r 2.4 2.44 table reconstruction quality and efficiency of parameterized physical rendering. 44 figure rendering methods in multi-sweep scans. 65 70 72 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 参 数 化 模 消 融 参数 数化 化物 理建 建模 模消 消融 融实 渲 染 别 检 瑞 利 背 散 射 方 向 反 理渲 渲染 染消 融分 分别 别检 检验 验瑞 瑞利 利背 背散 散射 射和 和方 方向 向参 化反 反射 若 两 者 改 善 斑 统 计 界 面 响 应 若两 两者 者分 别改 改善 善散 散斑 斑统 统计 计与 与界 界面 面方 向响 响应 联 合 型 纹 联合 合模 模型 型应 应在 在纹 纹理 构 灰 度 指 标 间 取 得 互 补 收 益 结构 构和 和灰 灰度 度指 指标 标间 间取 取得 得互 互补 补收 收益 一 表 达 增 强 条 件 下 在统 统一 一表 表达 达增 增强 强条 条件 件下 比 较 验比 比较 较第 节 所 述 节所 所述 述的 种 策 略 种渲 染策 策略 直 接 回 归 直接 接强 强度 度回 回归 归的 伯 努 伯努 努利 利散 射的 以 以及 给 出 线 单 组 定 量 给出 出基 基线 线和 和单 单组 组件 件定 定量 量结 图 展 示 包 括 内 性 其 展示 示包 包括 括联 型在 在内 内的 的定 定性 性比 较及 及其 其定 量指 不 同 机 制 像 质 推 效 率 上 对 不同 同参 染机 机制 制在 在图 图像 像质 质量 量与 与推 推理 理效 效率 率上 上的 量对 对比 多 次 扫 查 景 多次 次扫 扫查 查场 场景 景下 下不 制的 的重 建质 布 主 要 真 于瑞 利分 分布 布的 的背 射建 模主 主要 要改 斑纹 理的 的真 真实 实性 高 建指 标高 高于 显 显示 引 入 引入 入瑞 布背 能 够 生 成 更 且 符 特 征 能够 够生 生成 成更 更连 续且 且更 更符 符合 合超 声成 成像 像特 特征 征的 的散 该 明 该结 果表 表明 采 用 微 观 体 进 行 采用 用瑞 布对 对微 微观 观散 射体 体进 进行 行建 相 假 设 相较 较于 于伯 布假 假设 有 助 意 义 近 有助 助于 于生 成在 计意 意义 义上 上更 更接 接近 近真 实超 声响 应的', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5a95670b34643446488a847b37373d54f28d93673aa74fe4e0d8096e340759bc') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f42478ad1ebe6309', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 参数化物理建模消融实验', '，引入瑞利分布背散射的UPI-NeRF(B)能够生成更连续且更符合超声成像特征的散斑纹理。该结果表明，采用瑞利分布对微观散射体进行建模，相较于伯努利分布假设，有助于生成在统计意义上更连续且更接近真实超声响应的散斑纹理 。[65,70–72]
方向参数化反射机制[7,42,165]的贡献则主要表现在界面细节和感知质量上。表 2.4 中，UPI-NeRF(R) 的重建指标也高于缺乏方向建模的 Ultra-NeRF-CB+（, ）。图 2.44显示，引入方向参数化反射的UPI-NeRF(R)在组织界面高亮、边缘细节和视角依赖结构方面表现更优。通过对组织界面声学反射的角依赖性进行直接参数化，该机制在重建跨视角的大型宏观解剖边界时表征了更明显的方向梯度变化 。同时，Ref-NeRF+优于NeRF+的结果也从侧面表明，方向相关外观是超声界面建模中不可忽略的因素。
UPI-NeRF(B+R)在当前协议下取得LPIPS 0.128±0.006、SSIM 0.637±0.040和PSNR 29.89±0.72，单帧渲染时间为27.92 ms，显存占用为1018.4 MB。与Ref-NeRF+和Ultra-NeRF-CB+的差异达到统计显著且效应量较大。结果支持背散射与方向反射在纹理统计和界面响应上的互补作用。', 'upi-nerf 65 70 72 42 165 2.4 ultra-nerf-cb+ 2.44 ref-nerf+ nerf+ b+r lpips 0.128 0.006 ssim 0.637 0.040 psnr 29.89 0.72 27.92 ms 1018.4 mb 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 参 数 化 模 消 融 参数 数化 化物 理建 建模 模消 消融 融实 引 入 瑞 利 布 背 散 射 引入 入瑞 瑞利 利分 分布 布背 背散 散射 射的 能 够 生 成 更 且 符 合 像 特 征 斑 纹 能够 够生 生成 成更 更连 续且 且更 更符 符合 合超 声成 成像 像特 特征 征的 的散 散斑 斑纹 纹理 该 表 明 该结 果表 表明 采 用 对 微 观 体 进 行 采用 用瑞 布对 对微 微观 观散 射体 体进 进行 行建 相 较 伯 努 假 设 相较 较于 于伯 伯努 努利 布假 假设 有 助 统 计 意 义 上 接 近 真 响 应 有助 助于 于生 成在 在统 统计 计意 意义 义上 上更 更接 接近 近真 真实 实超 声响 响应 应的 方 向 反 机 制 方向 向参 化反 反射 射机 机制 贡 献 则 主 要 现 界 面 细 节 感 知 质 量 的贡 贡献 献则 则主 主要 要表 表现 现在 在界 界面 面细 细节 节和 和感 感知 知质 质量 量上 指 标 也 高 缺 乏 的重 建指 指标 标也 也高 高于 于缺 缺乏 乏方 向建 模的 图 显 示 显示 入方 组 织 亮 在组 组织 织界 面高 高亮 边 缘 视 角 依 赖 构 优 边缘 缘细 和视 视角 角依 依赖 赖结 结构 构方 方面 面表 现更 更优 通 过 学 性 直 通过 过对 对组 面声 声学 学反 的角 赖性 性进 行直 直接 接参 跨 大 型 宏 解 剖 时 梯 度 变 该机 制在 在重 建跨 跨视 角的 的大 大型 型宏 宏观 观解 解剖 剖边 边界 界时 时表 表征 征了 了更 更明 明显 显的 的方 向梯 梯度 度变 变化 同 同时 优于 从 侧 的结 果也 也从 从侧 侧面 关 外 不 可 忽 略 因 素 向相 相关 关外 外观 观是 是超 声界 面建 模中 中不 不可 可忽 忽略 略的 的因 因素 当 前 协 议 下 取 得 在当 当前 前协 协议 议下 下取 取得 单 帧 渲 染 间 单帧 帧渲 渲染 染时 时间 间为 存 占 显存 存占 占用 用为 差 异 达 到 著 效 的差 差异 异达 达到 到统 计显 显著 著且 且效 效应 应量 量较 较大 支 持 互 补 作 果支 支持 持背 射与 与方 向反 射在 在纹 理统 计和 和界 面响 应上 上的 的互 互补 补作 作用', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f42478ad1ebe63099f4d29ed6a0d2e1ccb09fa2640212d2f284e955fc1aa484a') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5c2a07c586dbb2e2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 超声三维重建实验结果与分析 / 参数化物理建模消融实验', '40和PSNR 29.89±0.72，单帧渲染时间为27.92 ms，显存占用为1018.4 MB。与Ref-NeRF+和Ultra-NeRF-CB+的差异达到统计显著且效应量较大。结果支持背散射与方向反射在纹理统计和界面响应上的互补作用。
消融结果与2.6　节的预测一致：瑞利背散射主要改善散斑统计，方向参数化反射主要改善界面高亮和方向依赖；联合模型在当前协议下获得更均衡的重建质量。
上述实验分别识别了表达增强与物理渲染的贡献，结论限于当前数据和评价协议。第3章在该连续表征基础上进一步处理扫查间整体错位和帧级轨迹扰动。[66–68,83]', '40 psnr 29.89 0.72 27.92 ms 1018.4 mb ref-nerf+ ultra-nerf-cb+ 2.6 66 68 83 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 实 验 结 果 分 析 建实 实验 验结 结果 果与 与分 分析 参 数 化 模 消 融 参数 数化 化物 理建 建模 模消 消融 融实 单 帧 渲 染 时 间 单帧 帧渲 渲染 染时 时间 间为 显 存 占 用 显存 存占 占用 用为 差 异 达 到 统 计 著 且 效 应 量 较 大 的差 差异 异达 达到 到统 统计 计显 显著 著且 且效 效应 应量 量较 较大 支 持 背 散 射 方 向 反 纹 界 面 响 上 互 补 作 果支 支持 持背 背散 散射 射与 与方 方向 向反 反射 射在 在纹 纹理 理统 计和 和界 界面 面响 响应 应上 上的 的互 互补 补作 作用 融结 节 预 测 一 致 节的 的预 预测 测一 一致 瑞 利 主 要 改 善 斑 瑞利 利背 射主 主要 要改 改善 善散 散斑 斑统 高 亮 依 赖 向参 化反 善界 面高 高亮 亮和 和方 向依 依赖 联 合 型 当 前 协 议 下 获 得 更 均 衡 质 联合 合模 模型 型在 在当 当前 前协 协议 议下 下获 获得 得更 更均 均衡 衡的 的重 建质 质量 述 别 识 表 增 强 贡 献 上述 述实 验分 分别 别识 识别 别了 了表 表达 达增 增强 强与 与物 理渲 染的 的贡 贡献 论 限 据 评 价 结论 论限 限于 于当 前数 数据 据和 和评 评价 价协 该 征 础 进 步 处 扫 查 整 体 错 位 级 轨 迹 扰 动 章在 在该 该连 续表 表征 征基 基础 础上 上进 进一 一步 步处 处理 理扫 扫查 查间 间整 整体 体错 错位 位和 和帧 帧级 级轨 轨迹 迹扰 扰动', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5c2a07c586dbb2e2d71e9449bac50a39c8ad5dcc2d2c193d074f8a22ed99e679') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3d7146786b441dd7', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第2章 基于超声物理与连续神经场的超声三维重建 / 本章小结', '本章建立了由空间映射、观测质量控制、连续神经场表征和物理一致渲染组成的超声三维重建链路。二维像素、声学扫描线、探头位姿与规范空间之间的关系使离散B-scan序列具有物理尺度和可追溯坐标；列级接触状态进一步限定了进入优化的可信射线。
实验结果支持上述设计：UMAP与随机森林在降维后保持了列级筛选质量；UPI-NeRF(B+R)的结果表明，瑞利背散射和方向参数化反射分别作用于纹理统计与界面响应。
由此，本章获得了可连续查询、可跨视角渲染并受观测质量约束的三维超声表示。不过，该方法仍以输入位姿总体可信为前提；真实多组超声扫查序列中的整体错位和逐帧抖动会继续破坏空间一致性。为此，第 3 章　进一步研究位姿—表征联合优化。', 'b-scan umap upi-nerf b+r 第 章 基 于 超 声 物 理 连 续 神 经 场 三 维 重 建 基于 于超 超声 声物 物理 理与 与连 连续 续神 神经 经场 场的 的超 声三 三维 维重 重建 本 小 结 本章 章小 小结 立 由 空 间 映 射 章建 建立 立了 了由 由空 空间 间映 映射 观 测 质 量 控 制 观测 测质 质量 量控 控制 表 征 一 致 渲 染 组 成 链 路 场表 表征 征和 和物 理一 一致 致渲 渲染 染组 组成 成的 建链 链路 二 像 素 二维 维像 像素 学 扫 描 线 声学 学扫 扫描 描线 探 头 位 姿 规 范 之 关 系 使 离 散 探头 头位 位姿 姿与 与规 规范 范空 间之 之间 间的 的关 关系 系使 使离 离散 序 列 具 有 尺 度 可 追 溯 坐 标 序列 列具 具有 有物 理尺 尺度 度和 和可 可追 追溯 溯坐 坐标 级 接 触 状 态 进 步 限 定 入 优 化 信 列级 级接 接触 触状 状态 态进 进一 一步 步限 限定 定了 了进 进入 入优 优化 化的 的可 可信 信射 射线 实 验 果 支 持 上 述 设 计 实验 验结 结果 果支 支持 持上 上述 述设 设计 随 机 森 林 降 后 保 筛 选 与随 随机 机森 森林 林在 在降 降维 维后 后保 保持 持了 了列 级筛 筛选 选质 明 的结 果表 表明 瑞 利 背 方 向 参 数 反 分 别 作 用 纹 统 界 面 响 应 瑞利 利背 背散 散射 射和 和方 方向 向参 参数 数化 化反 反射 射分 分别 别作 作用 用于 于纹 纹理 理统 统计 计与 与界 界面 面响 响应 此 由此 获 得 查 询 章获 获得 得了 了可 可连 续查 查询 跨 视 角 并 受 约 束 示 可跨 跨视 视角 角渲 染并 并受 受观 量约 约束 束的 的三 维超 声表 表示 不 过 不过 该 法 仍 以 输 总 体 前 提 该方 方法 法仍 仍以 以输 输入 入位 姿总 总体 体可 信为 为前 前提 真 多 整 错 逐 帧 抖 动 会 继 破 坏 性 真实 实多 多组 组超 声扫 扫查 查序 列中 中的 的整 整体 体错 错位 位和 和逐 逐帧 帧抖 抖动 动会 会继 继续 续破 破坏 坏空 间一 致性 为此 研 究 步研 研究 究位 联 合 征联 联合 合优', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3d7146786b441dd750c08c93a1d291f9367312768c53cc8d3c1a8281bcbe04a7') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-58f36cc99481f977', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 引言', '第2章建立了物理一致的自由手超声三维表征，但其可靠性仍取决于图像与探头位姿的正确对应。实际多次扫查来自不同方向、接触状态和时间段，外部定位误差、参考架微动、短时遮挡及组织受压会造成扫查间整体偏移；同一单次扫查内还可能出现逐帧高频抖动。若直接使用这些位姿，重建将产生重复边界、局部模糊和空间错位，并削弱后续语义融合的几何基础。
本章把超声扫查序列配准表述为位姿修正与三维表征协同优化，而非相互独立的“先配准、后重建”。多次扫查图像、初始位姿和神经场共同映射到规范空间，由外观、局部几何、匹配不确定性和轨迹连续性提供互补约束。更准确的位姿可提高多视角监督一致性，更稳定的场景表示又能为位姿更新提供有效梯度。针对误差尺度差异，本章先以外观检索、分层定位、几何内点验证和不确定性加权处理扫查级全局偏差，再以统计噪声先验、Lie群B样条自蒸馏和平滑运动学约束处理帧级局部噪声。理论分析预期各约束依次解决候选发现、错误匹配抑制、病态几何降权和轨迹连续性；实验在随机扰动、冷启动和局部抖动条件下检验这些预测，为第4章的三维语义融合提供统一空间。', 'lie 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 引 言 引言 建 立 物 理 一 致 自 由 手 三 维 章建 建立 立了 了物 物理 理一 一致 致的 的自 自由 由手 手超 声三 三维 维表 但 其 可 靠 性 仍 取 决 图 像 探 头 正 确 对 应 但其 其可 可靠 靠性 性仍 仍取 取决 决于 于图 图像 像与 与探 探头 头位 姿的 的正 正确 确对 对应 实 际 多 次 来 不 同 方 向 实际 际多 多次 次扫 查来 来自 自不 不同 同方 方向 接 触 状 态 时 间 段 接触 触状 状态 态和 和时 时间 间段 外 部 定 误 差 外部 部定 定位 位误 误差 参 考 架 微 动 参考 考架 架微 微动 短 遮 挡 组 织 受 压 会 造 成 整 体 偏 移 短时 时遮 遮挡 挡及 及组 组织 织受 受压 压会 会造 造成 成扫 查间 间整 整体 体偏 偏移 单 内 还 能 出 现 逐 帧 高 频 抖 同一 一单 单次 查内 内还 还可 可能 能出 出现 现逐 逐帧 帧高 高频 频抖 抖动 若 直 使 用 这 些 若直 直接 接使 使用 用这 这些 些位 重 将 产 生 复 边 界 重建 建将 将产 产生 生重 重复 复边 边界 局 模 糊 空 错 局部 部模 模糊 糊和 和空 空间 间错 错位 并 削 弱 后 续 语 义 融 几 何 础 并削 削弱 弱后 后续 续语 语义 义融 融合 合的 的几 几何 何基 基础 本 把 述 修 协 本章 章把 把超 准表 表述 述为 为位 姿修 修正 正与 与三 征协 协同 同优 而 非 相 互 独 而非 非相 相互 互独 独立 立的 先 先配 后重 查图 初 始 神 经 场 共 映 射 到 规 范 初始 始位 姿和 和神 神经 经场 场共 共同 同映 映射 射到 到规 规范 范空 观 由外 外观 部几 匹 轨 迹 连 提 供 补 约 束 匹配 配不 不确 确定 定性 性和 和轨 轨迹 迹连 连续 续性 性提 提供 供互 互补 补约 约束 更 视 角 监 督 更准 准确 确的 的位 姿可 可提 提高 高多 多视 视角 角监 监督 督一 致性 稳 景 示 又 新 有 效 梯 度 更稳 稳定 定的 的场 场景 景表 表示 示又 又能 能为 姿更 更新 新提 供有 有效 效梯 梯度 针 尺 异 针对 对误 差尺 尺度 度差 差异 以 检 索 章先 先以 以外 观检 检索 分 层 分层 层定 点 验 证 加 权 处 级 全 何内 内点 点验 验证 证和 和不 性加 加权 权处 处理 理扫 查级 级全 全局 局偏 偏差 再 统 计 噪 再以 以统 统计 计噪 噪声 声先 先验 群 样 条 蒸 馏 平 滑 运 学 样条 条自 自蒸 蒸馏 馏和 和平 平滑 滑运 运动 动学 学约 束处 理帧 帧级 级局 部噪 论 析 预 期 各 依 解 候 选 发 理论 论分 分析 析预 预期 期各 各约 束依 依次 次解 解决 决候 候选 选发 发现 抑 制 错误 误匹 配抑 抑制 病 降 病态 态几 何降 降权 权和 随 机 扰 实验 验在 在随 随机 机扰 扰动 冷 启 件 下 测 冷启 启动 动和 和局 部抖 动条 条件 件下 下检 检验 验这 些预 预测 为第 章的 的三 维语 合提 供统 统一 一空', '/#research', 'doctoral-thesis', 1, '2026-08-04', '58f36cc99481f9776fa21c5f42b7e7c4f38f35ce3a26d8e8ea45e414d305960d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_