INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b86bd8abddc026ad', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程', '同一对象沿不同轨迹重复采集所得序列统称为多组超声扫查序列。第2章在给定位姿下建立连续表征[88–91]，本章则修正扫查级刚性偏差与帧级局部扰动，使切片在同一规范空间保持一致[8,92-97,99]。本节定义配准正逆问题、规范空间映射及位姿—表征联合目标；3.3　节和3.4　节分别求解两类误差[100,101,118,121]。', '88 91 92-97 99 3.3 3.4 100 101 118 121 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 流 程 准流 流程 同 一 对 象 沿 不 轨 迹 重 复 采 集 所 得 统 称 多 组 同一 一对 对象 象沿 沿不 不同 同轨 轨迹 迹重 重复 复采 采集 集所 所得 得序 列统 统称 称为 为多 多组 组超 给 定 下 建 立 连 续 章在 在给 给定 定位 姿下 下建 建立 立连 连续 续表 本 则 修 正 级 刚 性 偏 差 帧 局 部 扰 动 本章 章则 则修 修正 正扫 查级 级刚 刚性 性偏 偏差 差与 与帧 帧级 级局 局部 部扰 扰动 使 切 片 规 范 空 间 保 持 致 使切 切片 片在 在同 一规 规范 范空 空间 间保 保持 持一 一致 节 义 逆 问 题 本节 节定 定义 义配 准正 正逆 逆问 问题 映 射 间映 映射 射及 及位 目 标 合目 目标 节和 分 别 求 解 两 类 误 节分 分别 别求 求解 解两 两类 类误 误差', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b86bd8abddc026ad675399e61536f85632f0eaec6db1aec78ef8af4270d038a1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-793ad7f19c251933', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程 / 超声图像配准的正逆问题', '在第二章中，三维重建已被统一表述为正问题与逆问题。该表述同样适用于本章的配准任务，只是逆问题中的未知量发生了变化。
Figure . Schematic illustration of ultrasound sweep-sequence registration.
Figure . The forward and inverse problems of 3D registration.
如图 3.1与图 3.2所示，对于配准而言，正问题保持不变，即：在已知三维介质场 与成像配置 的条件下，计算对应视角下的二维超声图像。其形式仍可写为
这里， 表示统一三维规范空间中的介质场或其参数化表示， 表示探头位姿与成像参数的集合， 则表示超声前向成像过程。
超声图像配准的逆问题在第二章三维介质场反演基础上进一步引入位姿修正：给定多视角二维观测及其初始位姿，同时估计能够解释观测图像的三维表示与位姿修正参数。设共有二维观测结果集合与成像配置集合，其基本形式可写为
