INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-592c4ac892267a1b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程 / 位姿修正与规范空间映射', '在明确超声扫查序列配准的正逆问题之后，还需要进一步说明不同扫查数据如何被映射到同一规范空间中，才能为后续联合优化提供统一坐标基础。在多次扫查场景下，位姿误差可分解为两个层次：一个是扫查级的全局刚性偏差，另一个是帧级的局部高频抖动。因此，本章的逆问题可以进一步理解为：在已知初始观测位姿的基础上，同时估计扫查级全局偏差和帧级局部扰动，使修正后的位姿既能在整体上实现多次扫查对齐，又能在局部上保持连续和平滑。[88,118,121]
设多次扫查数据集记为 ，其中第 个扫查记为 ；第 个扫查中包括的所有图片为，其中的第 帧二维图像记为 ，其外部跟踪系统记录的观测位姿为 。为了同时建模扫查级全局偏差与帧级局部抖动，本章将修正后的位姿 写为
其中， 表示第 个扫查的扫查级全局刚性偏差，用于校正不同扫查之间的整体错位； 表示第 帧在该单次扫查内部的局部 Lie代数扰动，用于描述高频局部跟踪抖动。这种分解使“全局对齐”和“局部平滑”能够在同一位姿模型中分而治之。
