INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-de0e5c426c88e38c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程 / 位姿修正与规范空间映射', '位姿模型中分而治之。
更进一步，复用2.2.2　 节中的从二维像素坐标系到三维规范空间的映射，从而实现从二维图像中的像素点为，二维方向向量为，基于对角缩放矩阵 与修正后的位姿 通过映射算子 嵌入三维规范空间下的三维空间点 和三维方向向量 。
该映射与第二章中的单次扫查场景保持形式一致，但此处的位姿矩阵已从固定输入扩展为待优化变量。随着 与 在联合优化过程中不断更新，二维图像中的像素位置、射线方向和沿射线采样得到的三维查询点也会同步更新。由此，不同超声扫查序列中的二维切片可在同一个规范空间中建立一致的空间关系，从而为后续神经渲染和几何匹配提供统一坐标基础。规范空间映射使多组超声扫查序列摆脱各自局部坐标系的约束，并在一个共享三维空间中建立空间对应关系，从而为后续全局配准和局部降噪提供共同参考系。同时，该映射将位姿修正对图像生成的影响直接纳入了可微映射过程，因此后续渲染损失对位姿参数的梯度能够通过 直接回传，实现几何校正与场景表示学习的耦合优化。如图 3.3 所示，通过统一位姿模型将多组超声扫查序列中的原始错位切片分解为扫查级全局刚性偏差和帧级局部抖动，并经由规范空间映射将所有切片投影到统一三维坐标系中。[8,118]
图 3.3 统一位姿修正与规范空间映射。', '2.2.2 3.3 118 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 流 程 准流 流程 修 正 规 范 空 间 映 射 姿修 修正 正与 与规 规范 范空 空间 间映 映射 模 型 分 而 治 之 姿模 模型 型中 中分 分而 而治 治之 更 进 一 步 更进 进一 一步 复 用 复用 节 从 二 维 像 素 坐 标 系 到 三 节中 中的 的从 从二 二维 维像 像素 素坐 坐标 标系 系到 到三 三维 维规 间的 的映 实 现 图 点 从而 而实 实现 现从 维图 图像 像中 的像 素点 点为 方 向 量 维方 方向 向向 向量 量为 对 角 缩 放 矩 阵 于对 对角 角缩 缩放 放矩 矩阵 后 与修 正后 后的 的位 通 过 算 子 通过 过映 射算 算子 嵌 入 下 嵌入 入三 间下 下的 的三 维空 间点 和三 该 单 次 场 景 保 持 形 式 致 该映 射与 与第 第二 二章 章中 的单 单次 次扫 查场 场景 景保 保持 持形 形式 式一 一致 但 此 处 已 固 定 输 扩 展 待 变 但此 此处 处的 姿矩 阵已 已从 从固 固定 定输 输入 入扩 扩展 展为 为待 待优 化变 变量 随 着 随着 不 断 新 在联 化过 过程 程中 中不 不断 断更 更新 置 素位 位置 线 沿 采 样 得 询 也 会 同 射线 线方 向和 和沿 沿射 线采 采样 样得 得到 到的 维查 查询 询点 点也 也会 会同 同步 步更 由 由此 切 片 可 个 建 立 关 不同 同超 列中 的二 维切 切片 片可 可在 在同 同一 一个 个规 间中 中建 建立 立一 致的 的空 间关 关系 续 神 经 渲 染 几 何 匹 提 供 统 础 而为 为后 后续 续神 神经 经渲 渲染 染和 和几 几何 何匹 匹配 配提 提供 供统 统一 一坐 标基 基础 使 多 组 摆 脱 各 自 局 部 约 束 射使 使多 多组 组超 列摆 摆脱 脱各 各自 自局 局部 部坐 系的 的约 约束 并 共 享 应 并在 在一 个共 共享 享三 立空 间对 对应 应关 全 降 噪 参 考 续全 全局 局配 准和 和局 部降 降噪 噪提 供共 共同 同参 参考 考系 时 同时 将 生 成 影 响 直 接 纳 微 射将 将位 正对 对图 像生 生成 成的 的影 影响 响直 直接 接纳 纳入 入了 了可 可微 微映 射过 因 损 失 数 梯 度 能 够 因此 此后 续渲 染损 损失 失对 对位 姿参 参数 数的 的梯 梯度 度能 能够 够通 回 传 接回 回传 校 示 学 习 耦 现几 何校 校正 与场 景表 表示 示学 学习 习的 的耦 耦合 如 如图 所 所示 原 始 错 解 级 刚 性 偏 差 帧 抖 动 过统 一位 型将 将多 的原 原始 始错 错位 位切 片分 分解 解为 为扫 查级 级全 局刚 刚性 性偏 偏差 差和 和帧 帧级 级局 部抖 抖动 有 投 并经 经由 由规 将所 所有 有切 片投 投影 影到 到统 一三 维坐 系中', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'de0e5c426c88e38c369bec8a817a90d860af5c3429f0c84c92ad7c726c97db37') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-bf47ef50db906a1a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程 / 规范空间下的位姿—表征联合优化', '完成规范空间映射之后，下一步的关键便是把位姿修正与连续神经场表征学习放入同一优化过程，从而将配准问题与三维建模问题真正耦合起来。
基于第3.2.1　 节的正逆问题定义和第3.2.2　 节的统一位姿模型与规范空间映射，位姿修正参数与三维连续神经场表征参数需要在同一可微框架中联合优化。本文采用 Global-local aligned neural radiance fields（GLA-NeRF）构建面向多组超声扫查序列的位姿—表征联合优化框架。该框架将位姿修正与三维表征学习统一纳入同一规范空间和神经渲染目标。GLA-NeRF 区分两类轨迹退化：一类是扫查级全局刚性偏差，另一类是帧级局部跟踪抖动；在此基础上，再分别引入全局配准模块与局部降噪模块，对应解决跨扫查粗对齐和单次扫查内连续性恢复问题。[88–91]
具体而言，在 3.2.2　 节所定义的统一位姿模型下，每一帧二维超声切片都通过修正后的位姿 与像素物理尺度矩阵 被映射到共同的三维规范空间。设二维图像中的像素位置与方向分别为 和 ，则通过映射算子 可得到其在规范空间中的三维位置与方向。参照第二章中的超声射线传播方式，将二维 B-scan 中的每一列像素视为一条声学扫描线。设二维射线的起点和方向分别为 和 ，则沿深度参数 采样可得到 和 。', '3.2.1 3.2.2 global-local aligned neural radiance fields gla-nerf 88 91 b-scan 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 流 程 准流 流程 规 范 空 间 下 规范 范空 空间 间下 下的 的位 完 成 映 射 之 后 完成 成规 间映 映射 射之 之后 一 步 关 键 便 把 修 正 连 续 神 经 场 学 习 放 入 同 过 下一 一步 步的 的关 关键 键便 便是 是把 把位 姿修 修正 正与 与连 连续 续神 神经 经场 场表 征学 学习 习放 放入 入同 同一 一优 化过 过程 从 而 将 问 题 三 维 建 模 真 耦 起 来 从而 而将 将配 准问 问题 题与 与三 三维 维建 建模 模问 题真 真正 正耦 耦合 合起 起来 于第 节 逆 定 义 节的 的正 正逆 逆问 题定 定义 义和 和第 统 型 的统 统一 一位 姿模 模型 型与 与规 参 数 需 要 可 微 框 架 正参 参数 数与 维连 征参 数需 需要 要在 在同 一可 可微 微框 框架 架中 中联 本 文 采 用 本文 文采 采用 构 面 向 多 组 构建 建面 面向 向多 多组 组超 列的 化框 该 纳 渲 染 目 标 该框 架将 将位 维表 习统 一纳 纳入 一规 间和 和神 经渲 渲染 染目 目标 区 分 两 类 轨 迹 退 区分 分两 两类 类轨 轨迹 迹退 退化 级 全 局 刚 性 偏 差 一类 类是 是扫 查级 级全 全局 局刚 刚性 性偏 偏差 另 帧 部 跟 踪 抖 动 另一 是帧 帧级 级局 局部 部跟 跟踪 踪抖 抖动 此 础 上 在此 此基 基础 础上 再 别 引 块 降 噪 再分 分别 别引 引入 入全 局配 准模 模块 块与 与局 部降 降噪 噪模 对 应 解 决 跨 粗 齐 单 次 内 恢 复 对应 应解 解决 决跨 跨扫 查粗 粗对 对齐 齐和 和单 单次 次扫 查内 内连 续性 性恢 恢复 复问 具 体 言 具体 体而 而言 所 节所 所定 义的 型下 每 二 切 片 都 通 每一 一帧 帧二 二维 维超 声切 切片 片都 都通 通过 过修 正后 后的 像 素 物 理 尺 度 矩 阵 与像 像素 素物 物理 理尺 尺度 度矩 矩阵 被 到 共 被映 射到 到共 共同 同的 的三 维规 设 图 置 方 设二 维图 图像 像中 中的 的像 素位 位置 置与 与方 方向 向分 别为 则 算 子 则通 过映 射算 算子 得 其 可得 得到 到其 其在 在规 间中 维位 照 线 传 播 式 参照 照第 第二 二章 章中 声射 射线 线传 传播 播方 方式 将二 视 条 描 的每 一列 列像 素视 视为 为一 一条 条声 声学 学扫 扫描 描线 点 维射 线的 的起 起点 点和 和方 沿 深 则沿 沿深 深度 度参 样 采样 样可', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'bf47ef50db906a1aa54e6936123d151920c6c3d4f14241cebe05b94d9b213126') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoi