INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-9239462d96605683', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程 / 规范空间下的位姿—表征联合优化', '的像素位置与方向分别为 和 ，则通过映射算子 可得到其在规范空间中的三维位置与方向。参照第二章中的超声射线传播方式，将二维 B-scan 中的每一列像素视为一条声学扫描线。设二维射线的起点和方向分别为 和 ，则沿深度参数 采样可得到 和 。
经由规范空间映射后，可得到对应的三维查询 与
再由连续神经场 预测该位置处的声学强度响应
这样，整个多次扫查数据集被嵌入到同一个连续神经场之中，从而形成一个多视图一致的三维表示。
在此基础上，GLA-NeRF 通过神经渲染误差同时优化连续神经场表征参数 与位姿修正参数 。设在当前估计位姿下渲染得到的二维图像为 ，真实观测图像为 ，则第 个扫查中第 帧对应的渲染一致性损失可写为[8,99–101]
由于规范空间映射 对位姿参数可微，因此图像重建误差的梯度不仅会更新神经场参数 ，也会同步反向传播到扫查级全局刚性偏差 和帧级局部扰动 上。在此机制下，原本错位的切片会在渲染目标的驱动下逐步收敛到更合理的解剖轨迹，而神经场也会因为获得更几何一致的三维查询而变得更加稳定。[6,61,118,121]
然而，超声场景下的位姿优化不能仅依赖这一光度型渲染损失。其原因在于，二维超声图像是薄层断层切片而非透视投影，帧间重叠有限，且散斑、声影以及出平面去相关会显著削弱纯光度一致性监督的约束能力。因此，GLA-NeRF 将 与后续3.3　 节的全局匹配损失 以及 3.4　 节的局部连续轨迹正则项 共同纳入统一目标函数，即', 'b-scan gla-nerf 99 101 61 118 121 3.3 3.4 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 流 程 准流 流程 规 范 空 间 下 规范 范空 空间 间下 下的 的位 像 素 置 方 向 分 别 的像 像素 素位 位置 置与 与方 方向 向分 分别 别为 则 通 过 映 射 算 子 则通 通过 过映 映射 射算 算子 可 得 到 其 三 维 可得 得到 到其 其在 在规 间中 中的 的三 三维 维位 参 照 二 线 传 播 式 参照 照第 第二 二章 章中 声射 射线 线传 传播 播方 方式 将 将二 二维 每 一 视 条 学 描 的每 每一 一列 列像 素视 视为 为一 一条 条声 声学 学扫 扫描 描线 设 起 点 设二 维射 线的 的起 起点 点和 和方 沿 深 度 数 则沿 沿深 深度 度参 参数 采 样 采样 样可 经 由 后 经由 由规 间映 射后 对 应 询 到对 对应 应的 维查 查询 再 连 续 神 场 再由 由连 连续 续神 神经 经场 预 测 该 处 强 响 预测 测该 该位 置处 处的 的声 学强 强度 度响 响应 这 这样 整 个 多 次 据 集 被 嵌 入 同 之 整个 个多 多次 次扫 查数 数据 据集 集被 被嵌 嵌入 入到 到同 同一 一个 个连 场之 之中 从 而 形 成 图 致 示 从而 而形 形成 成一 多视 视图 图一 一致 致的 维表 表示 此 础 上 在此 此基 基础 础上 渲 染 误 差 时 过神 经渲 渲染 染误 误差 差同 同时 时优 化连 场表 征参 修 正 与位 姿修 修正 正参 当 前 估 计 设在 在当 当前 前估 估计 计位 姿下 下渲 染得 到的 的二 维图 图像 像为 真 实 观 真实 实观 观测 测图 则第 个扫 查中 中第 帧 性 损 失 写 帧对 的渲 染一 致性 性损 损失 失可 可写 写为 由于 于规 微 对位 姿参 数可 可微 因 重 建 梯 不 仅 会 更 新 因此 此图 像重 重建 建误 差的 的梯 梯度 度不 不仅 仅会 会更 更新 新神 场参 也 步 反 级 全 局 刚 偏 也会 会同 同步 步反 反向 向传 播到 到扫 查级 级全 全局 局刚 刚性 性偏 偏差 部 扰 动 和帧 帧级 级局 局部 部扰 扰动 机 制 此机 机制 制下 原 本 错 切 片 目 标 驱 逐 收 敛 理 解 剖 轨 迹 原本 本错 错位 位的 的切 切片 片会 会在 在渲 染目 目标 标的 的驱 驱动 动下 下逐 逐步 步收 收敛 敛到 到更 更合 合理 理的 的解 解剖 剖轨 轨迹 获 几 何 变 加 稳 定 而神 场也 会因 因为 为获 获得 得更 更几 几何 何一 询而 而变 变得 更加 加稳 稳定 然 然而 景 能 依 赖 光 型 声场 场景 景下 姿优 化不 不能 能仅 仅依 依赖 赖这 这一 一光 光度 度型 型渲 染损 其原 原因 因在 在于 薄 层 断 非 透 投 影 维超 声图 像是 是薄 薄层 层断 断层 层切 片而 而非 非透 透视 视投 投影 叠 有 限 帧间 间重 重叠 叠有 有限 且 散 斑 且散 散斑 以 出 平 面 去 相 关 显 著 削 弱 纯 监 督 约 束 力 声影 影以 以及 及出 出平 平面 面去 去相 相关 关会 会显 显著 著削 削弱 弱纯 纯光 度一 性监 监督 督的 的约 约束 束能 能力 与后 后续 节 匹 节的 的全 局匹 匹配 配损 项 的局 部连 续轨 迹正 正则 则项 共 纳 统 函 共同 同纳 纳入 入统 统一 一目 标函 函数 即', '/#research', 'doctoral-thesis', 1, '2026-08-04', '9239462d966056835c443dc3827a76b6f2c63a95b07537178863de1be83d6890') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`tit