INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b97d8851df7fe7b6', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 配准流程 / 规范空间下的位姿—表征联合优化', '声图像是薄层断层切片而非透视投影，帧间重叠有限，且散斑、声影以及出平面去相关会显著削弱纯光度一致性监督的约束能力。因此，GLA-NeRF 将 与后续3.3　 节的全局匹配损失 以及 3.4　 节的局部连续轨迹正则项 共同纳入统一目标函数，即
其中，第一项采用第 3.3.4　 节定义的超声适应性组合损失，负责神经渲染一致性；第二项负责恢复扫查间全局空间一致性；第三项负责恢复单次扫查内局部连续性。由此，GLA-NeRF 将“全局配准、局部降噪和神经渲染”耦合到同一闭环优化框架中[62,63,70,71]。
