INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-37a2bfc8edb9877c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 基于外观的图像索引', '对于多组超声扫查序列，像 SCNeRF 一类方法常使用基于初始位姿邻近关系或最大视角差的启发式视图选择策略。然而，这类几何先验在超声图像中通常并不可靠：由于超声图像是二维断层切片而非透视投影，哪怕只是轻微的出平面平移，也可能导致图像所对应的解剖内容发生根本变化；与此同时，不同序列之间的原始位姿本身就可能存在较大刚性偏差。因此，初始位姿接近并不意味着图像内容相似，相反，不同位姿下的某些切片反而可能包含相近的解剖结构。基于此，本文不再依赖空间先验，而采用基于图像外观的检索机制来选择候选配准视图[105]。
具体而言，对任意查询图像 ，利用预训练 NetVLAD 网络提取其全局描述子[103,105–107] 。NetVLAD 的作用在于把图像映射到一个高维且具有判别性的特征空间，使该特征向量能够较好地捕捉图像中的宏观组织结构与纹理特征，同时对散斑噪声保持一定鲁棒性。对于第 个扫查中的一帧图像 ，在其余扫查的图像集合中，基于余弦相似度检索与 最相近的 个近邻图像，得到候选子集 ：
其中， 表示候选图像数，在 GLA-NeRF 中取 。该策略的核心作用在于：将后续精细匹配限制在具有相似解剖内容的少量候选图像对之间，从而显著减少由于解剖差异过大而引发的错误对应。相比依赖初始位姿的视图选择方式，基于外观的索引机制更契合超声图像“内容相关而几何先验不可靠”的特点。', 'scnerf 105 netvlad 103 107 gla-nerf 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 外 观 图 像 索 引 于外 外观 观的 的图 图像 像索 索引 对 多 组 对于 于多 多组 组超 一 类 方 法 常 使 用 初 始 邻 近 关 系 或 最 大 视 角 差 启 发 式 选 择 策 略 一类 类方 方法 法常 常使 使用 用基 于初 初始 始位 姿邻 邻近 近关 关系 系或 或最 最大 大视 视角 角差 差的 的启 启发 发式 式视 视图 图选 选择 择策 策略 然 而 然而 这 几 何 先 验 通 并 不 可 靠 这类 类几 几何 何先 先验 验在 在超 声图 像中 中通 通常 常并 并不 不可 可靠 由 二 维 断 切 片 非 透 投 影 由于 于超 像是 是二 二维 维断 断层 层切 切片 片而 而非 非透 透视 视投 投影 哪 怕 只 轻 微 出 平 面 移 哪怕 怕只 只是 是轻 轻微 微的 的出 出平 平面 面平 平移 也 能 导 致 所 应 解 剖 内 容 生 根 本 变 也可 可能 能导 导致 致图 像所 所对 对应 应的 的解 解剖 剖内 内容 容发 发生 生根 根本 本变 变化 此 同 时 与此 此同 同时 之 间 原 身 就 存 较 刚 性 偏 不同 同序 列之 之间 间的 的原 原始 姿本 本身 身就 就可 能存 存在 在较 较大 大刚 刚性 性偏 偏差 因 因此 接 意 味 着 相 似 姿接 接近 近并 不意 意味 味着 着图 像内 容相 相似 反 相反 下 某 些 包 含 结 构 同位 姿下 下的 的某 某些 些切 片反 反而 而可 能包 包含 含相 相近 近的 剖结 结构 于此 文 再 依 赖 空 本文 文不 不再 再依 依赖 赖空 空间 间先 采 检 机 制 来 候 而采 采用 于图 像外 的检 检索 索机 机制 制来 来选 择候 候选 选配 准视 具 体 言 具体 体而 而言 任 询 对任 任意 意查 查询 询图 利 预 训 练 利用 用预 预训 训练 网 络 提 取 其 描 述 子 网络 络提 提取 取其 其全 局描 描述 述子 作 把 映 射 到 个 高 且 有 判 别 特 的作 作用 用在 在于 于把 把图 像映 映射 射到 到一 一个 个高 高维 维且 且具 具有 有判 判别 别性 性的 的特 特征 征空 该 向 量 够 好 地 捕 捉 宏 织 纹 理 使该 该特 征向 向量 量能 能够 够较 较好 好地 地捕 捕捉 捉图 中的 的宏 宏观 观组 组织 织结 构与 与纹 纹理 理特 散 斑 噪 保 持 鲁 棒 时对 对散 散斑 斑噪 噪声 声保 保持 持一 一定 定鲁 鲁棒 棒性 于第 帧 个扫 查中 的一 一帧 帧图 余 集 在其 其余 余扫 查的 像集 集合 合中 弦 度 于余 余弦 弦相 似度 度检 索与 最相 个近 近邻 邻图 得 得到 到候 选子 子集 其中 示 数 表示 示候 选图 像数 中取 核 心 该策 略的 的核 核心 心作 将 后 续 精 细 匹 限 少 将后 后续 续精 精细 细匹 匹配 配限 限制 制在 在具 有相 似解 容的 的少 少量 量候 像对 对之 从 显 著 减 异 过 错 误 从而 而显 显著 著减 减少 少由 于解 剖差 差异 异过 过大 大而 而引 引发 发的 的错 错误 误对 比 相比 比依 赖初 姿的 的视 择方 方式 更 契 的索 引机 制更 更契 契合 合超 相关 关而 而几 验不 点 特点', '/#research', 'doctoral-thesis', 1, '2026-08-04', '37a2bfc8edb9877c6fabc52da604f44c4d90ea3acc6f610bd33ad458712c94fc') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=exc