INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-36c5c176746faef1', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 基于外观的图像索引', 'RF 中取 。该策略的核心作用在于：将后续精细匹配限制在具有相似解剖内容的少量候选图像对之间，从而显著减少由于解剖差异过大而引发的错误对应。相比依赖初始位姿的视图选择方式，基于外观的索引机制更契合超声图像“内容相关而几何先验不可靠”的特点。
外观索引既缩小匹配范围，也为全局配准链提供初始候选约束。多组超声扫查序列之间的初始几何关系通常不可靠。外观检索先缩小候选范围，可避免后续局部匹配受到大量语义不相关图像对的干扰。基于外观的图像索引由此提供“解剖内容先验”[103,105–107]，使原本不受约束的跨扫查图像匹配问题，被转化为更局部、更可控的候选定位问题。', 'rf 103 105 107 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 外 观 图 像 索 引 于外 外观 观的 的图 图像 像索 索引 取 中取 该 策 略 核 心 作 用 该策 策略 略的 的核 核心 心作 作用 用在 在于 将 后 续 精 细 匹 限 制 具 有 相 似 解 剖 内 容 少 量 候 选 对 之 间 将后 后续 续精 精细 细匹 匹配 配限 限制 制在 在具 具有 有相 相似 似解 解剖 剖内 内容 容的 的少 少量 量候 候选 选图 像对 对之 之间 从 而 显 著 减 由 差 异 过 大 发 错 误 应 从而 而显 显著 著减 减少 少由 由于 于解 剖差 差异 异过 过大 大而 而引 引发 发的 的错 错误 误对 对应 比 依 赖 初 始 视 择 方 式 相比 比依 依赖 赖初 初始 始位 姿的 的视 视图 图选 选择 择方 方式 机 更 契 的索 引机 机制 制更 更契 契合 合超 声图 关 几 何 先 验 不 可 靠 容相 相关 关而 而几 几何 何先 先验 验不 不可 可靠 特 点 的特 特点 既 缩 小 范 围 观索 引既 既缩 缩小 小匹 配范 范围 也 链 提 供 约 束 也为 为全 准链 链提 提供 供初 始候 选约 约束 多 组 系 通 常 多组 组超 列之 间的 的初 始几 何关 关系 系通 通常 常不 检 观检 检索 索先 先缩 小候 选范 避 免 部 受 到 语 义 干 扰 可避 避免 免后 续局 局部 部匹 配受 受到 到大 大量 量语 语义 义不 不相 关图 对的 的干 干扰 此 引由 由此 此提 容先 使 原 本 跨 问 题 使原 原本 本不 不受 受约 束的 的跨 跨扫 查图 像匹 配问 问题 被 转 被转 转化 化为 为更 更局 控 更可 可控 控的 的候 选定 位问', '/#research', 'doctoral-thesis', 1, '2026-08-04', '36c5c176746faef136994b94659bd37b8598d2e5cca30b7aedc33b9022b4c1a5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-c6ddebc9a1c5f293', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 分层定位与几何内点验证', '在通过外观信息建立初步检索与候选对应后，还需要进一步结合层级匹配与几何内点验证，筛除伪匹配并稳定估计跨扫查对应关系。在得到候选图像子集之后，下一步需要在候选图像对之间建立可靠的稀疏对应关系。由于超声图像受 散斑、声影和局部组织重复纹理影响显著，直接使用像素强度匹配或基础光流估计往往不稳定。因此，本文采用“局部特征提取—深度匹配—几何内点验证”的分层定位策略。[102,175–177]
首先，对每幅图像 提取一组局部特征：
其中，pᵏᵢ表示第k个关键点的二维像素坐标，dᵏᵢ表示其对应的D维描述子。GLA-NeRF使用SIFT提取局部特征[179]。在图 3.6所示的同一组Left-Cross、Mid-Cross和Right-Cross扫查图像中，关键点主要分布在组织边界、纹理过渡与局部高响应区域。三幅图像中稳定结构的重复出现为后续跨视角匹配提供了局部描述基础。
图 3.6 候选超声图像中的局部特征点分布
Figure . Distribution of local feature points in candidate ultrasound images
随后，针对候选图像对 ，采用基于图神经网络的 LightGlue 建立初始匹配点集合[110]：', '102 175 177 pki dki gla-nerf sift 179 3.6 left-cross mid-cross right-cross figure distribution of local feature points in candidate ultrasound images lightglue 110 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 几 何 内 点 验 证 位与 与几 几何 何内 内点 点验 验证 通 过 外 观 信 息 建 立 初 步 检 索 候 选 对 应 后 在通 通过 过外 外观 观信 信息 息建 建立 立初 初步 步检 检索 索与 与候 候选 选对 对应 应后 还 需 要 进 一 结 级 匹 还需 需要 要进 进一 一步 步结 结合 合层 层级 级匹 匹配 配与 筛 除 伪 并 稳 估 计 跨 关 系 筛除 除伪 伪匹 配并 并稳 稳定 定估 估计 计跨 跨扫 查对 应关 关系 得 到 图 像 子 集 之 在得 得到 到候 选图 图像 像子 子集 集之 之后 下 间 可 靠 稀 疏 下一 步需 要在 在候 像对 对之 之间 间建 立可 可靠 靠的 的稀 稀疏 疏对 由 受 由于 于超 声图 像受 散 斑 散斑 影 部 组 织 重 复 纹 理 响 显 著 声影 影和 和局 局部 部组 组织 织重 重复 复纹 纹理 理影 影响 响显 显著 直 接 使 用 素 强 度 或 础 光 流 往 不 直接 接使 使用 用像 像素 素强 强度 度匹 配或 或基 基础 础光 光流 流估 计往 往往 往不 不稳 因 此 因此 本 文 采 本文 文采 采用 特 提 取 部特 特征 征提 提取 深 深度 策 略 的分 位策 策略 首 先 首先 每 幅 对每 每幅 幅图 取一 一组 组局 其 其中 示 表示 示第 个 键 二 维 坐 标 个关 关键 键点 点的 的二 二维 维像 素坐 坐标 示其 其对 应的 描 述 维描 描述 述子 取局 在图 所 同 所示 示的 的同 同一 查图 像中 主 布 边 界 点主 主要 要分 分布 布在 在组 织边 边界 渡 高 区 域 理过 过渡 渡与 与局 部高 高响 响应 应区 区域 三 构 出 现 续 视 角 供 三幅 中稳 定结 结构 构的 的重 复出 出现 现为 为后 后续 续跨 跨视 视角 角匹 配提 提供 供了 了局 部描 述基 选超 中的 的局 征点 点分 随 随后 针 针对 对候 神 经 网 络 用基 于图 图神 神经 经网 网络 络的 始 初始 始匹 配点 点集 集合', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'c6ddebc9a1c5f293254230c63882f9607bbd3db56ba1d1cf03819b61b88673a4') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ce0335aca8732dbc', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 分层定位与几何内点验证', 'e . Distribution of local feature points in candidate ultrasound images
随后，针对候选图像对 ，采用基于图神经网络的 LightGlue 建立初始匹配点集合[110]：
其中，cᵏᵢⱼ∈[0,1]表示第k对匹配的置信度。与传统最近邻匹配不同，LightGlue同时利用局部外观和上下文空间关系[110,112–116,178]。图 3.7以Mid-Cross为参考，分别建立其与Left-Cross、Right-Cross的初始对应。匹配覆盖多处组织边界和纹理结构，同时仍保留少量跨越不一致区域的长距离连线，说明初始匹配侧重提高候选对应的召回率，尚不能直接作为位姿优化的几何约束。
图 3.7 基于 LightGlue 的初始跨图像匹配结果
Figure . Initial inter-image correspondences established by LightGlue
初始匹配中仍然会包含不少由重复纹理、局部伪影或出平面去相关引起的错误对应。为此，本文进一步利用当前位姿估计将匹配像素映射为三维点对，并在此基础上采用 RANSAC 几何验证[111]。具体而言，先采用 RANSAC 估计图像对之间的相对变换估计，并以重投影误差阈值 为准则最大化内点数得到最优刚体关系，筛选几何内点集合：', 'distribution of local feature points in candidate ultrasound images lightglue 110 ckij 112 116 178 3.7 mid-cross left-cross right-cross figure initial inter-image correspondences established by ransac 111 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 几 何 内 点 验 证 位与 与几 几何 何内 内点 点验 验证 随 后 随后 针 对 候 选 图 像 针对 对候 候选 选图 图像 像对 采 用 神 经 网 络 采用 用基 于图 图神 神经 经网 网络 络的 建 立 初 始 匹 集 建立 立初 初始 始匹 匹配 配点 点集 集合 其 其中 示 表示 示第 置 信 度 对匹 配的 的置 置信 信度 传 统 最 近 邻 不 同 与传 传统 统最 最近 近邻 邻匹 配不 不同 时 利 部 外 观 上 下 文 空 间 关 系 同时 时利 利用 用局 局部 部外 外观 观和 和上 上下 下文 文空 空间 间关 关系 以 参 考 为参 参考 别 分别 别建 立其 其与 应 的初 始对 对应 覆 盖 多 处 组 织 边 界 纹 理 结 构 配覆 覆盖 盖多 多处 处组 组织 织边 边界 界和 和纹 纹理 理结 结构 仍 保 留 少 量 跨 越 一 致 区 域 长 距 离 连 线 时仍 仍保 保留 留少 少量 量跨 跨越 越不 不一 一致 致区 区域 域的 的长 长距 距离 离连 连线 说 明 侧 重 提 高 召 回 率 说明 明初 配侧 侧重 重提 提高 高候 选对 应的 的召 召回 回率 尚 能 直 接 作 约 束 尚不 不能 能直 直接 接作 作为 为位 姿优 的几 何约 约束 果 始跨 跨图 像匹 配结 结果 然 会 包 含 由 复 配中 中仍 仍然 然会 会包 包含 含不 不少 少由 由重 重复 复纹 伪 影 或 出 平 面 去 相 引 起 错 误 部伪 伪影 影或 或出 出平 平面 面去 去相 相关 关引 引起 起的 的错 错误 误对 此 为此 本 进 步 当 前 估 计 将 素 映 射 三 维 本文 文进 进一 一步 步利 用当 当前 前位 姿估 估计 计将 将匹 配像 像素 素映 映射 射为 为三 三维 维点 点对 并 础 并在 在此 此基 基础 础上 上采 何验 具 体 而 言 具体 体而 而言 先 先采 之 变 换 计图 对之 之间 间的 的相 相对 对变 变换 换估 投 差 阈 值 并以 以重 重投 投影 影误 误差 差阈 阈值 则 大 数 得 到 刚 为准 准则 则最 最大 大化 化内 点数 数得 得到 到最 最优 优刚 刚体 体关 筛 筛选 选几', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ce0335aca8732dbc5a960ed9d070d7911425552179e0aa8d5f86ed926b1b00f5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-c1b07795b87bcef5', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 分层定位与几何内点验证', '本文进一步利用当前位姿估计将匹配像素映射为三维点对，并在此基础上采用 RANSAC 几何验证[111]。具体而言，先采用 RANSAC 估计图像对之间的相对变换估计，并以重投影误差阈值 为准则最大化内点数得到最优刚体关系，筛选几何内点集合：
其中，对应的几何误差定义为，满足误差阈值 的匹配被保留为严格内点集合
这里，πᵢ(pᵏᵢ)和πⱼ(pᵏⱼ)分别表示两个关键点在当前规范空间中的三维映射位置。仅当视觉匹配同时满足几何误差阈值时，对应点才进入后续优化。图 3.8显示，RANSAC在Left-Cross—Mid-Cross匹配中保留33/34对，在Right-Cross—Mid-Cross匹配中保留18/21对；被剔除的对应主要表现为跨越不一致解剖区域的长距离连线。该结果表明，几何验证在保留主体对应关系的同时排除了少量外点，使内点集合在空间方向上更一致[103,106,107,109]。
图 3.8 经 RANSAC 几何验证后保留下来的严格内点匹配
Figure . Strict inlier matches retained after RANSAC-based geometric verification
三幅图采用同一组Left-Cross、Mid-Cross和Right-Cross图像，使特征提取、初始匹配与几何验证可以在相同观测条件下直接比较。图 3.6给出三幅候选图像中的局部特征分布，图 3.7给出以Mid-Cross为中心建立的初始匹配，图 3.8给出RANSAC验证后的内点与外点。该处理链将局部外观相似性转化为经过三维几何检验的可靠对应，为后续位姿联合优化提供了受控的匹配约束。', 'ransac 111 pki pkj 3.8 left-cross mid-cross 33 34 right-cross 18 21 103 106 107 109 figure strict inlier matches retained after ransac-based geometric verification 3.6 3.7 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 几 何 内 点 验 证 位与 与几 几何 何内 内点 点验 验证 本 文 进 一 步 利 用 当 前 估 计 将 匹 像 素 映 射 三 维 对 本文 文进 进一 一步 步利 利用 用当 当前 前位 姿估 估计 计将 将匹 匹配 配像 像素 素映 映射 射为 为三 三维 维点 点对 并 此 础 上 采 并在 在此 此基 基础 础上 上采 采用 何验 具 体 而 言 具体 体而 而言 先 先采 图 之 间 相 变 换 计图 图像 像对 对之 之间 间的 的相 相对 对变 变换 换估 以 重 投 影 误 差 阈 值 并以 以重 重投 投影 影误 误差 差阈 阈值 则 最 大 数 得 到 刚 关 系 为准 准则 则最 最大 大化 化内 点数 数得 得到 到最 最优 优刚 刚体 体关 关系 筛 选 集 筛选 选几 点集 集合 其 其中 应 义 对应 应的 的几 何误 差定 定义 义为 满 足 满足 足误 被 保 留 严 格 的匹 配被 被保 保留 留为 为严 严格 格内 这 里 这里 别 示 两 个 键 规 范 空 置 分别 别表 表示 示两 两个 个关 关键 键点 点在 在当 前规 规范 范空 空间 间中 中的 的三 维映 射位 位置 仅 视 觉 同 时 仅当 当视 视觉 觉匹 配同 同时 时满 足几 值时 才 入 后 续 应点 点才 才进 进入 入后 后续 续优 显 显示 配中 中保 剔 除 主 要 现 跨 越 不 致 解 剖 区 域 长 距 离 连 线 被剔 剔除 除的 的对 应主 主要 要表 表现 现为 为跨 跨越 越不 不一 一致 致解 解剖 剖区 区域 域的 的长 长距 距离 离连 连线 该 结 果 明 该结 结果 果表 表明 排 少 量 外 证在 在保 留主 主体 体对 应关 系的 的同 时排 排除 除了 了少 少量 量外 外点 使 方 向 更 使内 合在 在空 间方 方向 向上 上更 更一 经 下 来 证后 后保 留下 下来 来的 的严 点匹 幅 组 三幅 幅图 图采 用同 同一 一组 特 提 取 使特 特征 征提 提取 初 始 可 观 测 条 件 直 接 比 较 初始 始匹 配与 证可 可以 以在 在相 相同 同观 观测 测条 条件 件下 下直 直接 接比 比较 给 出 候 部 布 给出 出三 幅候 候选 选图 像中 的局 局部 部特 征分 分布 出以 心 建 立 为中 中心 心建 建立 立的 的初 后的 的内 点与 与外 处 理 链 似 性 转 过 检 靠 该处 处理 理链 链将 将局 部外 外观 观相 相似 似性 性转 转化 化为 为经 经过 过三 维几 何检 检验 验的 的可 可靠 靠对 供 受 控 约 束 为后 续位 姿联 化提 提供 供了 了受 受控 控的 配约 约束', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'c1b07795b87bcef582b9a1b60a1a7e8279927f7571e1a350cd8b908368385f65') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.