INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-634deaeb5c0491d6', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 分层定位与几何内点验证', '3.6给出三幅候选图像中的局部特征分布，图 3.7给出以Mid-Cross为中心建立的初始匹配，图 3.8给出RANSAC验证后的内点与外点。该处理链将局部外观相似性转化为经过三维几何检验的可靠对应，为后续位姿联合优化提供了受控的匹配约束。
为了进一步刻画几何约束的统计强度，本文引入信息矩阵
其中表示几何误差对小 Lie代数扰动的 Jacobian，表示反对称矩阵算子，表示 3×3 单位矩阵。该信息矩阵反映了当前匹配对位姿估计的几何约束强度，为后续构造具有不确定性权重的匹配损失提供了基础。该信息矩阵的引入非常关键，因为它使后续优化不再把“匹配点数量”简单等价为“几何约束强度”，而能够从位姿微扰的角度量化不同图像对对刚体变换的真实约束能力。[118,121]
从整体上看，这一分层定位与几何内点验证过程实际上把“图像内容相似”和“空间几何一致”两个条件耦合在了一起。前者由 NetVLAD 检索提供粗约束，后者由 SIFT + LightGlue + RANSAC 提供精约束，从而为后续全局位姿优化提供高置信度的三维对应关系。对于初始位姿误差大且图像外观变化强的多组超声扫查序列，“先检索、后验证”比全图像均匀匹配或启发式几何筛选更适合建立稳定的全局配准约束[105,108]。', '3.6 3.7 mid-cross 3.8 ransac lie jacobian 118 121 netvlad sift lightglue 105 108 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 几 何 内 点 验 证 位与 与几 几何 何内 内点 点验 验证 给 出 三 幅 候 选 图 像 部 特 布 给出 出三 三幅 幅候 候选 选图 图像 像中 中的 的局 局部 部特 特征 征分 分布 以 出以 心 建 立 初 始 匹 为中 中心 心建 建立 立的 的初 初始 始匹 匹配 后 外 证后 后的 的内 点与 与外 外点 该 处 理 链 将 观 相 似 性 转 经 过 维 检 可 靠 对 应 该处 处理 理链 链将 将局 部外 外观 观相 相似 似性 性转 转化 化为 为经 经过 过三 三维 维几 何检 检验 验的 的可 可靠 靠对 对应 续 提 供 受 控 约 束 为后 后续 续位 姿联 化提 提供 供了 了受 受控 控的 的匹 配约 约束 进 一 步 刻 画 统 计 强 度 为了 了进 进一 一步 步刻 刻画 画几 何约 束的 的统 统计 计强 强度 本 文 引 入 信 息 矩 阵 本文 文引 引入 入信 信息 息矩 矩阵 其 示 误 差 小 其中 中表 表示 示几 何误 误差 差对 对小 代 数 扰 动 代数 数扰 扰动 动的 反 称 算 子 示反 反对 对称 称矩 阵算 算子 单 单位 位矩 映 当 前 估 该信 阵反 反映 映了 了当 当前 前匹 配对 对位 姿估 估计 计的 的几 束强 构 造 具 有 不 确 权 重 损 失 础 续构 构造 造具 具有 有不 不确 确定 定性 性权 权重 重的 配损 损失 失提 了基 基础 非 常 关 键 阵的 的引 入非 非常 常关 关键 因 它 使 再 把 因为 为它 它使 使后 续优 化不 不再 再把 量 配点 点数 数量 简 等 价 简单 单等 等价 价为 而 能 够 从 微 角 同 刚 体 变 换 真 实 力 而能 能够 够从 从位 姿微 微扰 扰的 的角 角度 度量 量化 不同 同图 像对 对对 对刚 刚体 体变 变换 换的 的真 真实 实约 束能 能力 整 上 看 从整 整体 体上 上看 这 程 际 这一 一分 证过 过程 程实 实际 际上 上把 容 像内 内容 容相 空 间 致 空间 间几 何一 一致 两 个 条 件 耦 起 两个 个条 条件 件耦 耦合 合在 在了 了一 一起 者 由 前者 者由 索 粗 检索 索提 供粗 粗约 后者 精 供精 精约 高 置 系 从而 而为 续全 局位 姿优 供高 高置 置信 信度 度的 的三 维对 应关 关系 大 且 多 组 对于 于初 始位 姿误 差大 大且 且图 像外 观变 变化 化强 强的 的多 多组 组超 先 先检 后验 比 均 匀 或 启 发 式 筛 更 适 稳 比全 全图 像均 均匀 匀匹 配或 或启 启发 发式 式几 何筛 筛选 选更 更适 适合 合建 立稳 稳定 定的 准约', '/#research', 'doctoral-thesis', 1, '2026-08-04', '634deaeb5c0491d642e2e9b705220a291678dea656878a6b8cd64eeb876c4cfa') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d93e8bed200e32a0', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 不确定性加权的Mahalanobis距离', '在获得较为可靠的几何对应后，还需进一步设计更稳健的距离度量与约束形式，以提高全局配准在复杂误差条件下的稳定性。即便经过图像检索、深度匹配和几何内点验证，不同关键点对应的可靠性仍然并不相同。如果像 SCNeRF 那样对所有对应点一视同仁地最小化三维欧氏距离，那么实际上隐含了一个过强的假设：所有匹配都服从相同方差、各向同性的高斯噪声模型。但在超声场景中，这一假设显然不成立。一个低置信度误匹配或一个几何条件病态的内点集，都可能在欧氏距离损失下产生过大的梯度，从而把整个扫查的全局位姿朝错误方向拉偏。为解决这一问题，本文采用不确定性加权的 Mahalanobis 距离[8,88–91,100,111]来替代简单欧氏距离。
设第 对匹配关键点在规范空间中的三维残差为 ，则其对应的距离项定义为多元高斯负对数似然形式。与普通欧氏距离不同，这里距离的大小不仅由残差本身决定，还由该匹配的协方差矩阵 所调制。也就是说，同样大小的空间误差，如果发生在高不确定性匹配上，其实际优化权重会更低；而发生在高置信度匹配上的误差，则会被更强地惩罚。[110,112,113,178]
协方差矩阵由外观不确定性与几何不确定性相加构成，即
其中 。这里， 由 LightGlue 的匹配置信度 控制，置信度越低，外观不确定性越大，对应匹配在优化中的作用越弱； 则通过把全局刚体位姿协方差 投影到具体空间点上，得到该匹配点在当前空间构型下的局部几何协方差。前者度量匹配对的外观可信度，后者度量该几何关系对位姿估计的约束强度。这两类不确定性的融合，使该距离项能够更全面地衡量对应关系的统计可靠性[105,114–116]', 'mahalanobis scnerf 88 91 100 111 110 112 113 178 lightglue 105 114 116 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 不 确 性 加 权 不确 确定 定性 性加 加权 权的 距 离 距离 获 得 较 可 靠 几 何 对 应 后 在获 获得 得较 较为 为可 可靠 靠的 的几 几何 何对 对应 应后 还 需 进 一 步 设 计 更 稳 健 度 量 约 束 形 式 还需 需进 进一 一步 步设 设计 计更 更稳 稳健 健的 的距 离度 度量 量与 与约 约束 束形 形式 以 提 高 复 杂 误 差 条 件 下 以提 提高 高全 准在 在复 复杂 杂误 误差 差条 条件 件下 下的 的稳 稳定 即 便 经 过 图 像 检 索 即便 便经 经过 过图 图像 像检 检索 深 匹 内 点 验 证 深度 度匹 匹配 配和 和几 何内 内点 点验 验证 同 关 键 仍 然 并 相 不同 同关 关键 键点 点对 应的 的可 靠性 性仍 仍然 然并 并不 不相 相同 如 果 如果 果像 那 样 所 有 视 仁 地 最 小 三 维 欧 氏 那样 样对 对所 所有 有对 应点 点一 一视 视同 同仁 仁地 地最 最小 小化 化三 三维 维欧 欧氏 氏距 么 实 际 上 隐 含 个 强 假 那么 么实 实际 际上 上隐 隐含 含了 了一 一个 个过 过强 强的 的假 假设 都 服 从 方 有匹 配都 都服 服从 从相 同方 方差 各 向 斯 噪 模 型 各向 向同 同性 性的 的高 高斯 斯噪 噪声 声模 模型 但 场 景 但在 在超 声场 场景 景中 这 显 成 立 这一 一假 设显 显然 然不 不成 成立 低 置 信 或 病 态 集 个低 低置 置信 信度 度误 误匹 配或 或一 个几 何条 件病 病态 态的 的内 点集 能 损 失 产 生 大 梯 都可 可能 能在 在欧 离损 损失 失下 下产 产生 生过 过大 大的 的梯 梯度 而 把 整 朝 错 拉 偏 从而 而把 把整 整个 个扫 查的 局位 姿朝 朝错 错误 误方 方向 向拉 拉偏 解 决 问 题 为解 解决 决这 一问 问题 本 文 采 用 本文 文采 采用 用不 来 替 代 简 单 来替 替代 代简 简单 单欧 设第 规 范 空 间 残 对匹 配关 点在 在规 规范 范空 空间 间中 中的 的三 维残 残差 差为 则 其 项 义 多 元 负 数 似 则其 其对 离项 项定 定义 义为 为多 多元 元高 斯负 负对 对数 数似 似然 然形 普 通 与普 普通 通欧 离不 里 仅 由 身 这里 里距 离的 的大 大小 小不 不仅 仅由 由残 差本 本身 身决 决定 该 协 矩 阵 还由 由该 该匹 配的 的协 协方 差矩 矩阵 调 制 所调 调制 也 就 说 也就 就是 是说 同样 样大 小的 的空 间误 发 果发 发生 生在 在高 高不 性匹 配上 重 会 其实 际优 化权 权重 重会 会更 更低 而发 高置 上的 的误 被 惩 罚 则会 会被 被更 更强 强地 地惩 惩罚 外 观 构 阵由 由外 外观 观不 性与 与几 何不 性相 相加 加构 构成 其中 的匹 配置 控 控制 越 度越 越低 性越 越大 作 弱 应匹 配在 在优 化中 的作 作用 用越 越弱 刚 体 则通 通过 过把 把全 局刚 刚体 体位 姿协 投 影 到 具 投影 影到 到具 具体 体空 间点 点上 当 前 部 得到 到该 配点 在当 当前 前空 间构 构型 型下 的局 局部 部几 何协 者 前者 者度 量匹 配对 对的 的外 观可 可信 系 估 后者 量该 该几 何关 关系 系对 对位 姿估 估计 计的 的约 束强 强度 两 类 融 这两 两类 类不 的融 融合 使 够 面 衡 统 使该 该距 项能 能够 够更 更全 全面 面地 地衡 衡量 量对 应关 系的 的统 统计 计可', '/#research', 'doctoral-thesis', 1, '2026-08