INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5ed10c6654289507', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 不确定性加权的Mahalanobis距离', '位姿协方差 投影到具体空间点上，得到该匹配点在当前空间构型下的局部几何协方差。前者度量匹配对的外观可信度，后者度量该几何关系对位姿估计的约束强度。这两类不确定性的融合，使该距离项能够更全面地衡量对应关系的统计可靠性[105,114–116]
因此，全局位姿优化主要由统计稳定且几何约束力较强的高置信度对应驱动，避免所有残差等权平均。相较于 Self-calibrating NeRF 对所有点统一最小化 L2 距离，本文将匹配置信度与几何信息矩阵共同纳入概率距离，以提高配准对错误对应的鲁棒性。
前述3.3.3　节完成外观检索、几何验证和不确定性加权形成的全局几何约束链；3.3.4　节进一步引入超声适应性渲染监督。前者提供跨扫查锚点，后者降低随机散斑对联合优化的干扰[103,106,118,121]。
本节通过外观索引、分层定位、几何内点验证和不确定性加权距离建立跨扫查全局几何约束，并通过超声适应性组合损失把该约束与连续神经场的渲染目标连接起来。该模块首先校正不同扫查之间的大尺度空间偏移，再为后续局部降噪与精细联合优化提供可信初值和稳定的图像监督[107]。', 'mahalanobis 105 114 116 self-calibrating nerf l2 3.3.3 3.3.4 103 106 118 121 107 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 不 确 性 加 权 不确 确定 定性 性加 加权 权的 距 离 距离 协 方 差 姿协 协方 方差 投 影 到 具 体 空 间 点 上 投影 影到 到具 具体 体空 空间 间点 点上 得 该 匹 当 前 构 型 下 部 几 何 得到 到该 该匹 匹配 配点 点在 在当 当前 前空 间构 构型 型下 下的 的局 局部 部几 几何 何协 者 度 量 对 外 观 可 信 前者 者度 度量 量匹 配对 对的 的外 外观 观可 可信 信度 后 关 系 估 计 约 束 强 后者 量该 该几 何关 关系 系对 对位 姿估 估计 计的 的约 约束 束强 强度 这 两 类 融 这两 两类 类不 性的 的融 融合 使 项 能 够 更 面 地 衡 应 统 靠 使该 该距 离项 项能 能够 够更 更全 全面 面地 地衡 衡量 量对 对应 应关 系的 的统 统计 计可 可靠 靠性 因 此 因此 主 要 由 稳 且 力 较 高 置 驱 动 局位 姿优 化主 主要 要由 由统 计稳 稳定 定且 且几 何约 束力 力较 较强 强的 的高 高置 置信 度对 应驱 驱动 避 免 所 有 残 等 平 均 避免 免所 所有 有残 残差 差等 等权 权平 平均 相 相较 较于 一 最 小 对所 有点 点统 统一 一最 最小 小化 本 文 将 息 矩 阵 共 同 纳 入 概 率 本文 文将 将匹 配置 度与 与几 何信 信息 息矩 矩阵 阵共 共同 同纳 纳入 入概 概率 率距 以 提 错 误 鲁 棒 以提 提高 高配 准对 对错 错误 误对 应的 的鲁 鲁棒 棒性 述 前述 节 完 成 检 索 节完 完成 成外 观检 检索 验 证 形 链 何验 验证 证和 和不 权形 形成 成的 局几 束链 进 步 引 适 渲 染 监 督 节进 进一 一步 步引 引入 入超 声适 适应 应性 性渲 渲染 染监 监督 供 跨 锚 者提 提供 供跨 跨扫 查锚 锚点 降 低 随 机 散 斑 干 扰 者降 降低 低随 随机 机散 散斑 斑对 对联 的干 干扰 通 过 本节 节通 通过 过外 观索 索引 内 建 立 何内 内点 点验 权距 离建 建立 立跨 查全 并 组 损 失 把 连 续 神 经 场 目 标 接 起 来 并通 过超 性组 组合 合损 损失 失把 把该 该约 束与 与连 连续 续神 神经 经场 场的 的渲 染目 目标 标连 连接 接起 起来 模 块 首 先 校 正 之 大 尺 偏 移 该模 模块 块首 首先 先校 校正 正不 不同 同扫 查之 之间 间的 的大 大尺 尺度 度空 间偏 偏移 再 噪 精 细 初 值 图 像 再为 为后 后续 续局 部降 降噪 噪与 与精 精细 细联 化提 供可 信初 初值 值和 和稳 定的 的图 图像 像监', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5ed10c665428950741a920f38b4c94bc9a058632f58ea807e8fa25c88e52bbfb') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> stateme