INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e564a6c1eac2076f', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 超声适应性的损失函数设计', '分层定位与几何内点验证为跨扫查全局配准提供了高置信度空间对应，但在位姿—表征联合优化中，全局刚性偏差的更新还会受到神经渲染误差的直接驱动。超声图像中的散斑、声影和方向相关回波具有明显的随机性与局部统计特征，若仍沿用面向自然图像的简单逐像素误差，位姿梯度容易被偶然纹理差异主导。因此，本节进一步给出服务于 GLA-NeRF 联合目标的超声适应性损失函数。
超声背散射更接近具有局部统计规律的随机场，而不是需要逐像素确定性复现的普通纹理。单独使用 L1 或 L2 损失会持续惩罚随机散斑的像素级偏差，并可能通过过度平滑获得较低重建误差；对于位姿优化而言，这种偏差还会削弱结构边界和局部强度分布所提供的稳定约束。为此，GLA-NeRF 将第 3.2.3　 节中的神经渲染项具体化为由强度、结构、感知和局部分布约束共同组成的组合损失[52,57,65,66]：
其中，强度项用于约束整体回声幅值，结构项用于保持组织边界与局部形态，感知项用于维持多尺度细节，局部分布项则通过比较滑动窗口内软直方图的 Kullback-Leibler 散度约束局部强度统计。该设计不要求不同扫查中的随机散斑逐像素完全一致，而是在允许有限随机差异的同时保持结构、感知和统计分布的一致性。因此，渲染误差对位姿参数的反向传播更集中于可重复的组织结构与回声分布，而不是不可重复的单点散斑。', 'gla-nerf l1 l2 3.2.3 52 57 65 66 kullback-leibler 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 适 应 性 损 失 函 数 设 计 声适 适应 应性 性的 的损 损失 失函 函数 数设 设计 几 何 内 点 验 证 跨 提 供 高 置 信 度 空 间 对 位与 与几 几何 何内 内点 点验 验证 证为 为跨 跨扫 查全 准提 提供 供了 了高 高置 置信 信度 度空 空间 间对 对应 但 但在 在位 化中 刚 偏 差 更 新 还 会 受 到 神 经 渲 染 误 直 接 驱 动 局刚 刚性 性偏 偏差 差的 的更 更新 新还 还会 会受 受到 到神 神经 经渲 渲染 染误 误差 的直 直接 接驱 驱动 图 像 散 斑 声图 图像 像中 中的 的散 散斑 影 方 向 相 关 回 波 具 有 明 显 随 机 部 统 特 声影 影和 和方 方向 向相 相关 关回 回波 波具 具有 有明 明显 显的 的随 随机 机性 性与 与局 局部 部统 统计 计特 特征 若 仍 沿 用 面 自 然 简 单 逐 素 若仍 仍沿 沿用 用面 面向 向自 自然 然图 像的 的简 简单 单逐 逐像 像素 素误 梯 容 易 被 偶 纹 理 异 主 导 姿梯 梯度 度容 容易 易被 被偶 偶然 然纹 纹理 理差 差异 异主 主导 因 此 因此 本 节 进 一 步 给 出 服 务 本节 节进 进一 一步 步给 给出 出服 服务 务于 目 标 合目 目标 标的 性损 背 射 近 规 律 场 声背 背散 散射 射更 更接 接近 近具 有局 计规 规律 律的 机场 而 不 需 要 确 复 现 普 通 而不 不是 是需 需要 要逐 素确 确定 定性 性复 复现 现的 的普 普通 通纹 独 使 单独 独使 使用 或 持 续 惩 罚 级 失会 会持 持续 续惩 惩罚 罚随 机散 斑的 的像 素级 级偏 并 可 能 过 平 滑 获 得 较 低 重 建 并可 可能 能通 通过 过过 过度 度平 平滑 滑获 获得 得较 较低 低重 重建 建误 言 对于 姿优 化而 而言 这 种 削 弱 结 构 边 界 强 布 所 稳 约 束 这种 种偏 差还 会削 削弱 弱结 结构 构边 边界 界和 和局 部强 强度 度分 分布 布所 所提 供的 的稳 稳定 定约 约束 为此 将 将第 项 体 由 节中 的神 染项 项具 具体 体化 化为 为由 由强 感 知 共 同 组 成 感知 知和 部分 布约 束共 共同 同组 组成 成的 的组 组合 合损 其 其中 整 幅 值 度项 项用 用于 于约 束整 整体 体回 回声 声幅 幅值 保 织 形 态 构项 于保 保持 持组 组织 织边 界与 部形 形态 维 多 尺 细 知项 于维 维持 持多 多尺 尺度 度细 细节 则 比 窗 口 软 布项 项则 则通 过比 比较 较滑 滑动 动窗 窗口 口内 内软 软直 直方 方图 图的 散度 度约 束局 度统 该 求 完 致 该设 计不 不要 要求 求不 不同 同扫 查中 斑逐 素完 完全 全一 一致 允 许 限 时 而是 是在 在允 允许 许有 有限 限随 机差 异的 的同 同时 时保 持结 和统 计分 布的 的一 致性 参 反 传 播 集 差对 对位 姿参 参数 数的 的反 反向 向传 传播 播更 更集 集中 中于 于可 可重 重复 复的 织结 构与 与回 声分 是不 不可 的单 单点 点散', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e564a6c1eac2076fb395d2e07b1e7d56fa680ba52c239059a1c6d05bdea62b3c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded