INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b16241c7bd67d231', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于分层定位的全局配准 / 超声适应性的损失函数设计', 'ibler 散度约束局部强度统计。该设计不要求不同扫查中的随机散斑逐像素完全一致，而是在允许有限随机差异的同时保持结构、感知和统计分布的一致性。因此，渲染误差对位姿参数的反向传播更集中于可重复的组织结构与回声分布，而不是不可重复的单点散斑。
由此，3.3.1 至 3.3.3　 节建立的外观检索、几何验证和不确定性加权距离从空间对应侧约束扫查级全局位姿，本节的超声适应性损失则从神经渲染侧提供表征一致性约束。二者共同进入第 3.2.3　 节的位姿—表征联合目标，并与第 3.4　 节的局部连续轨迹正则项协同优化，使全局配准既保留明确的几何锚点，又不过度依赖超声散斑的逐像素一致性。', 'ibler 3.3.1 3.3.3 3.2.3 3.4 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 分 层 定 全 局 于分 分层 层定 定位 位的 的全 全局 局配 适 应 性 损 失 函 数 设 计 声适 适应 应性 性的 的损 损失 失函 函数 数设 设计 散 度 约 束 部 强 统 散度 度约 约束 束局 局部 部强 强度 度统 统计 该 不 要 求 同 随 机 斑 逐 像 素 完 一 致 该设 计不 不要 要求 求不 不同 同扫 查中 中的 的随 随机 机散 散斑 斑逐 逐像 像素 素完 完全 全一 一致 而 允 许 有 限 差 异 时 保 持 结 构 而是 是在 在允 允许 许有 有限 限随 机差 差异 异的 的同 同时 时保 保持 持结 结构 感 知 布 感知 知和 和统 计分 分布 布的 的一 致性 因 此 因此 渲 染 误 对 参 反 向 传 播 更 集 可 重 复 组 织 回 渲染 染误 误差 差对 对位 姿参 参数 数的 的反 反向 向传 传播 播更 更集 集中 中于 于可 可重 重复 复的 的组 组织 织结 构与 与回 回声 声分 单 点 而不 不是 是不 不可 的单 单点 点散 由 由此 至 节 建 立 外 观 检 索 节建 建立 立的 的外 外观 观检 检索 几 何 验 证 确 加 权 距 离 从 空 间 侧 级 几何 何验 验证 证和 和不 不确 确定 定性 性加 加权 权距 距离 离从 从空 空间 间对 对应 应侧 侧约 束扫 查级 级全 局位 本 则 神 经 提 供 本节 节的 性损 失则 则从 从神 神经 经渲 染侧 侧提 提供 供表 征一 性约 二 者 共 进 入 二者 者共 共同 同进 进入 入第 的位 目 标 合目 目标 并 并与 与第 连 续 轨 迹 正 项 协 的局 部连 连续 续轨 轨迹 迹正 正则 则项 项协 协同 同优 使 既 留 明 锚 使全 准既 既保 保留 留明 明确 确的 的几 何锚 锚点 又 过 依 赖 又不 不过 过度 度依 依赖 赖超 声散 斑的 的逐 素一', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b16241c7bd67d231e8f095783847dffe805af55b68105f745948b00722e8f63c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b17ced33c7e457a8', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于连续轨迹正则化的局部降噪', '全局配准后，帧级高频扰动仍会破坏轨迹连续性和切片叠加[4-5,22,88-92,120,180]。这类扰动幅值较小却逐帧累积，与3.3　节的扫查级刚性偏差不同[93–96]。由于相邻超声切片重叠有限，且散斑、声影与出平面去相关削弱光度一致性，光学场景中的集束调整式位姿细化难以直接迁移；局部优化容易受伪影牵引而偏离真实轨迹。
为此，本节将SE(3)局部位姿扰动、跟踪器噪声边界、Lie群累积B样条自蒸馏和解析运动学约束纳入联合目标。统计先验限制异常更新，连续伪标签降低轨迹方差，速度、加速度与曲率约束排除不符合自由手操作规律的运动[120]。', '4-5 22 88-92 120 180 3.3 93 96 se lie 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 连 续 轨 迹 正 则 局 部 降 噪 于连 连续 续轨 轨迹 迹正 正则 则化 的局 局部 部降 降噪 全 后 全局 局配 准后 帧 级 高 频 扰 动 仍 会 破 坏 性 切 片 叠 加 帧级 级高 高频 频扰 扰动 动仍 仍会 会破 破坏 坏轨 迹连 续性 性和 和切 切片 片叠 叠加 这 类 幅 值 较 小 却 逐 累 积 这类 类扰 动幅 幅值 值较 较小 小却 却逐 逐帧 帧累 累积 节 刚 偏 差 不 同 节的 的扫 查级 级刚 刚性 性偏 偏差 差不 不同 由 相 邻 重 有 限 由于 于相 相邻 邻超 声切 片重 重叠 叠有 有限 且 散 斑 且散 散斑 影 出 平 面 去 关 削 弱 光 度 一 致 声影 影与 与出 出平 平面 面去 去相 相关 关削 削弱 弱光 光度 度一 一致 致性 学 场 景 集 束 调 整 式 细 难 以 直 接 迁 移 光学 学场 场景 景中 中的 的集 集束 束调 调整 整式 式位 姿细 细化 化难 难以 以直 直接 接迁 迁移 容 易 受 伪 牵 引 而 离 真 实 部优 化容 容易 易受 受伪 伪影 影牵 牵引 引而 而偏 偏离 离真 真实 实轨 此 为此 本 将 本节 节将 部位 姿扰 跟 踪 器 边 界 跟踪 踪器 器噪 噪声 声边 边界 群 群累 样 条 自 蒸 馏 解 析 运 约 纳 入 目 标 样条 条自 自蒸 蒸馏 馏和 和解 解析 析运 运动 动学 学约 约束 束纳 纳入 入联 合目 目标 统 计 先 验 制 异 常 更 新 统计 计先 先验 验限 限制 制异 异常 常更 更新 签 低 方 续伪 伪标 标签 签降 降低 低轨 迹方 方差 速 速度 曲 率 排 除 符 手 操 作 规 律 加速 度与 与曲 曲率 率约 束排 排除 除不 不符 符合 合自 自由 由手 手操 操作 作规 规律 律的 的运', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b17ced33c7e457a873822a1ea0c0e36c27c486d18f70e592bf1a709c9a9e9463') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3312921a65924922', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于连续轨迹正则化的局部降噪 / 位姿流形上的局部扰动表示', '由于探头位姿属于刚体运动群 ，而非欧氏向量空间[88,118]，因此后续的连续轨迹建模、样条插值以及导数计算都必须建立在 Lie群与 Lie代数的统一框架下进行。如图 3.9所示，SE(3) 是三维刚体运动构成的光滑流形，流形点 可通过对数映射投影到局部切空间 se(3)，也可通过切空间向量 指数映射由局部扰动返回到群元素。为了简化表达，本文采用 记号在向量表示与矩阵 Lie代数元素之间建立对应关系：
图 .9 Lie群 与 Lie代数 之间的映射关系示意图
Figure . Illustration of the mapping between the Lie group and Lie algebra .
图 .10 Lie代数的非交换性示意图
Figure . Illustration of non-commutativity of Lie algebra
在 Lie群上进行递推和求导时，还需要用到伴随变换。其把一个 Lie代数中的 twist 从一个局部坐标系传输到另一个局部坐标系中，可写为
