INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-34e20d09b6d36fd5', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于连续轨迹正则化的局部降噪 / 基于统计先验的局部噪声建模', '局部位姿优化容易发散的一个直接原因，是神经渲染误差在超声场景中提供的是弱监督。由于超声图像中散斑与回波结构高度依赖于成像方向，小的位姿变化可能引起较大的局部强度变化，而这些变化并不一定对应于真实几何错位。因此，若没有额外先验，优化器可能会通过不合理的位姿更新去拟合局部散斑伪影，从而产生轨迹漂移。[22,49]为避免这一问题，本文首先利用外部跟踪器的统计噪声特性，设第 个扫查中第 帧的局部位姿修正为 ，并假设真实传感器噪声满足零均值高斯分布，即 。其中， 表示由设备规格手册给定或通过数据估计得到的先验协方差矩阵。基于这一假设，可将每一帧局部位姿修正的约束写为高斯负对数似然损失，即
这一项的作用是抑制单帧位姿更新的异常放大，使位姿优化始终被限制在传感器物理噪声可接受的范围内。与简单的 正则相比，这里通过协方差矩阵直接编码了平移与旋转不同维度上的先验尺度，因此其约束具有更明确的物理意义。[88–91]
然而，逐帧NLL 仅能惩罚单个局部扰动过大，却无法保证整条轨迹的修正分布在统计意义上仍符合传感器噪声模型。例如，即使每一帧的修正都不大，它们也可能沿同一方向积累，从而形成系统性漂移。为此，本文进一步在分布层面引入 KL 散度约束。具体而言，利用核密度估计构造所有局部扰动的经验分布，', '22 49 88 91 nll kl 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 连 续 轨 迹 正 则 局 部 降 噪 于连 连续 续轨 轨迹 迹正 正则 则化 的局 局部 部降 降噪 统 计 先 验 建 模 于统 统计 计先 先验 验的 部噪 噪声 声建 建模 容 易 发 散 一 个 直 接 原 因 部位 姿优 化容 容易 易发 发散 散的 的一 一个 个直 直接 接原 原因 神 经 渲 染 误 差 场 景 提 供 弱 监 督 是神 神经 经渲 渲染 染误 误差 差在 在超 声场 场景 景中 中提 提供 供的 的是 是弱 弱监 监督 由 图 像 斑 回 波 结 构 高 度 依 赖 成 方 向 由于 于超 声图 图像 像中 中散 散斑 斑与 与回 回波 波结 结构 构高 高度 度依 依赖 赖于 于成 成像 像方 方向 小 变 可 能 引 起 较 大 强 小的 的位 姿变 变化 化可 可能 能引 引起 起较 较大 大的 部强 强度 度变 而 这 些 并 不 定 对 应 真 实 几 何 错 而这 这些 些变 化并 并不 不一 一定 定对 对应 应于 于真 真实 实几 几何 何错 错位 此 因此 若 没 有 额 外 若没 没有 有额 额外 外先 器 会 通 过 理 更 新 去 拟 伪 影 化器 器可 能会 会通 通过 过不 不合 合理 理的 姿更 更新 新去 去拟 拟合 合局 部散 斑伪 伪影 从 产 生 漂 移 从而 而产 产生 生轨 迹漂 漂移 避 免 问 题 为避 避免 免这 这一 一问 问题 本 文 首 利 用 跟 踪 特 性 本文 文首 首先 先利 利用 用外 外部 部跟 跟踪 踪器 器的 的统 计噪 声特 特性 设 设第 个扫 查中 中第 帧 修 帧的 姿修 修正 正为 假 传 感 满 足 零 均 值 斯 分 布 并假 假设 设真 实传 传感 感器 器噪 声满 满足 足零 零均 均值 值高 高斯 斯分 分布 即 其 其中 示 备 规 格 手 册 给 或 数 据 估 得 到 协 矩 阵 表示 示由 由设 设备 备规 规格 格手 手册 册给 给定 定或 或通 过数 数据 据估 估计 计得 得到 到的 的先 验协 协方 方差 差矩 矩阵 于这 一假 将 每 约 束 写 负 似 然 损 失 可将 将每 每一 一帧 帧局 正的 的约 约束 束写 写为 为高 斯负 负对 对数 数似 似然 然损 损失 项 作 抑 制 单 异 常 放 一项 项的 的作 作用 用是 是抑 抑制 制单 单帧 帧位 新的 的异 异常 常放 放大 使 始 终 被 限 物 受 范 围 内 使位 化始 始终 终被 被限 限制 制在 在传 器物 物理 理噪 声可 可接 接受 受的 的范 范围 围内 简 与简 简单 单的 相 比 则相 相比 里 编 码 平 旋 转 同 维 上 尺 这里 里通 过协 阵直 接编 编码 码了 了平 平移 移与 与旋 旋转 转不 不同 同维 维度 度上 上的 验尺 尺度 具 明 确 意 义 此其 其约 束具 具有 有更 更明 明确 确的 的物 理意 意义 然而 逐 逐帧 仅 惩 罚 扰 动 仅能 能惩 惩罚 罚单 单个 个局 部扰 扰动 动过 过大 却 无 法 保 证 整 条 仍 符 型 却无 无法 法保 保证 证整 整条 条轨 迹的 的修 正分 布在 在统 计意 义上 上仍 仍符 符合 合传 声模 模型 例 如 例如 都 即使 使每 正都 都不 不大 它 们 也 沿 积 累 它们 们也 也可 能沿 沿同 同一 一方 向积 积累 形 系 而形 形成 成系 系统 统性 性漂 为此 进 步 层 面 入 文进 进一 一步 步在 在分 布层 层面 面引 引入 散度 度约 体 言 具体 体而 而言 核 密 造 所 用核 核密 密度 度估 计构 构造 造所 所有 有局 动的 的经 经验 验分', '/#research', 'doctoral-thesis', 1, '2026-08-04', '34e20d09b6d36fd5700157e50fe7bf11bc519b9fe05217bf36e70b2a20e77bd9') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`l