INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-37355b9237922d5d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于连续轨迹正则化的局部降噪 / 基于统计先验的局部噪声建模', '，却无法保证整条轨迹的修正分布在统计意义上仍符合传感器噪声模型。例如，即使每一帧的修正都不大，它们也可能沿同一方向积累，从而形成系统性漂移。为此，本文进一步在分布层面引入 KL 散度约束。具体而言，利用核密度估计构造所有局部扰动的经验分布，
其中 为核函数带宽，再将其与理论先验分布 进行KL 散度匹配，得到
约束经验分布与理论先验高斯分布保持一致。这样，局部降噪不仅要求每一帧“不要偏得太远”，还要求所有帧的总体修正分布“不要偏离真实传感器噪声的统计边界”。[8,99,100,121]
点级先验限制单帧异常更新，分布级先验抑制整条轨迹的系统性漂移。二者的先验判断是：在切片重叠极小、光度监督弱约束时，纯集束调整式联合优化的可辨识性不足，加入噪声边界可缩小可行域并降低发散风险。该判断由3.5.4　节的现有实验检验[118]。', 'kl 99 100 121 3.5.4 118 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 连 续 轨 迹 正 则 局 部 降 噪 于连 连续 续轨 轨迹 迹正 正则 则化 的局 局部 部降 降噪 统 计 先 验 建 模 于统 统计 计先 先验 验的 部噪 噪声 声建 建模 却 无 法 保 证 整 条 修 分 布 意 义 上 仍 符 传 感 器 型 却无 无法 法保 保证 证整 整条 条轨 迹的 的修 修正 正分 分布 布在 在统 计意 意义 义上 上仍 仍符 符合 合传 传感 感器 器噪 声模 模型 例 如 例如 即 使 每 一 帧 都 不 大 即使 使每 每一 一帧 帧的 正都 都不 不大 它 们 也 可 能 沿 同 方 向 积 累 它们 们也 也可 可能 能沿 沿同 同一 一方 方向 向积 积累 从 而 形 成 系 性 漂 移 从而 而形 形成 成系 系统 统性 性漂 漂移 此 为此 本 文 进 步 层 面 引 入 本文 文进 进一 一步 步在 在分 布层 层面 面引 引入 散 度 约 束 散度 度约 约束 具 体 言 具体 体而 而言 利 用 核 密 估 构 造 所 有 扰 动 经 利用 用核 核密 密度 度估 估计 计构 构造 造所 所有 有局 部扰 扰动 动的 的经 经验 验分 其 其中 函 数 带 宽 为核 核函 函数 数带 带宽 再 将 理 论 再将 将其 其与 与理 理论 论先 行 进行 匹 度匹 匹配 得 到 得到 高 斯 持 致 束经 布与 验高 高斯 斯分 布保 保持 持一 一致 这 样 这样 仅 要 求 噪不 不仅 仅要 要求 求每 偏 太 远 不要 要偏 偏得 得太 太远 还 总 还要 求所 有帧 的总 总体 体修 离 真 实 边 界 偏离 离真 真实 实传 声的 的统 计边 边界 点 级 限 制 单 异 常 更 新 点级 级先 验限 限制 制单 单帧 帧异 异常 常更 更新 抑 布级 验抑 抑制 制整 的系 二 者 判 断 二者 者的 的先 验判 判断 断是 切 片 重 叠 极 小 在切 切片 片重 重叠 叠极 极小 光 监 督 弱 时 光度 度监 监督 督弱 弱约 束时 纯 集 调 式 辨 识 足 纯集 集束 束调 调整 整式 式联 的可 可辨 辨识 识性 性不 不足 加 缩 域 并 低 发 风 险 加入 入噪 声边 界可 可缩 缩小 小可 可行 行域 域并 并降 降低 低发 发散 散风 风险 该 由 该判 断由 节 现 检 节的 的现 现有 有实 实验 验检 检验', '/#research', 'doctoral-thesis', 1, '2026-08-04', '37355b9237922d5d4f9ca2ef0cb3cfda0469b6679ba5db1365b81378a97d4b00') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ac2863394d0b3cc8', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于连续轨迹正则化的局部降噪 / 基于 Lie群B样条的自蒸馏平滑', '统计先验主要约束可行域，不能直接给出低方差轨迹。基于自由手扫查的时间连续性，本文从含噪离散位姿提取控制点，并以Lie群累积B样条生成平滑伪标签，反向约束原始位姿。该自蒸馏机制将“防止异常更新”扩展为“提供连续轨迹引导”[120,180]。
如果直接用高噪声离散位姿作为控制点构造样条曲线，样条为了穿过这些噪声点拟合容易出现 Runge 现象，即会产生明显的高频震荡。为减轻这一问题，首先采用滑动窗口提取局部控制点。设窗口长度为 ，在每个窗口内通过 Lie群上的 Fréchet 均值构造控制点 ，有其协方差近似满足线性减少，即
这里， 作为局部切空间的参考点， 把相邻位姿投影到 Lie代数 中完成欧氏平均， 再把均值映回到 上。该过程相当于流形上的低通滤波：局部切空间平均用于消除高频噪声，理论上可将控制点的噪声方差降低到原始采样点的约。
在得到这些低方差控制点后，进一步构造累积 Lie群B样条轨迹[88,118]。之所以采用“累积”形式，而不是参考欧氏 B样条直接在 上对控制点做线性插值，是因为位姿所在的 并不是向量空间，不具备加法封闭性。欧氏空间中的 B样条可写成控制点的线性组合，而在 Lie群中，必须先用 把相邻控制点之间的广义位移映射到 Lie代数，再在 Lie代数中进行尺度调制，最后通过 和群乘法逐段累积。这种“差分—缩放—累积”的形式正是 Lie群累积 B样条能够自然推广欧氏 B样条并保持 连续性的根本原因。具体来说对于三次样条，在归一化局部时间参数 下，先定义相邻控制点之间的 Lie代数位移为。然后，累积样条轨迹写为', 'lie 120 180 runge fr chet 88 118 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 连 续 轨 迹 正 则 局 部 降 噪 于连 连续 续轨 轨迹 迹正 正则 则化 的局 局部 部降 降噪 群 样 条 自 蒸 馏 平 滑 样条 条的 的自 自蒸 蒸馏 馏平 平滑 统 计 先 验 主 要 约 束 可 行 域 统计 计先 先验 验主 主要 要约 约束 束可 可行 行域 不 能 直 接 给 出 低 方 差 不能 能直 直接 接给 给出 出低 低方 方差 差轨 由 手 时 间 性 于自 自由 由手 手扫 查的 的时 时间 间连 续性 本 文 从 含 离 散 提 取 控 制 点 本文 文从 从含 含噪 噪离 离散 散位 姿提 提取 取控 控制 制点 并 以 并以 累 积 群累 累积 生 成 伪 标 签 条生 生成 成平 滑伪 伪标 标签 反 向 原 始 反向 向约 束原 原始 始位 该 机 将 该自 馏机 机制 制将 防 止 异 常 更 新 防止 止异 异常 常更 更新 扩 展 扩展 展为 供 引 导 提供 供连 迹引 引导 如 果 用 高 作 构 造 曲 线 如果 果直 接用 用高 高噪 噪声 声离 姿作 作为 为控 点构 构造 造样 条曲 曲线 穿 过 这 些 拟 容 易 现 条为 为了 了穿 穿过 过这 这些 些噪 声点 点拟 拟合 合容 容易 易出 出现 象 现象 即 会 产 明 显 频 震 荡 即会 会产 产生 生明 明显 显的 的高 高频 频震 震荡 减 轻 一 问 题 为减 减轻 轻这 这一 一问 问题 首 采 动 窗 口 首先 先采 采用 用滑 滑动 动窗 窗口 口提 取局 部控 设 长 度 设窗 口长 长度 度为 每 个 内 通 在每 每个 个窗 口内 内通 通过 上 群上 上的 均 值 均值 值构 造控 有 其 协 近 似 满 足 少 有其 其协 协方 差近 近似 似满 满足 足线 线性 性减 减少 里 这里 切 空 参 考 为局 部切 切空 空间 间的 的参 参考 考点 把 相 邻 投 影 到 把相 相邻 邻位 姿投 投影 影到 代 数 代数 完 欧 氏 中完 完成 成欧 欧氏 氏平 平均 再 映 回 再把 把均 值映 映回 回到 程 当 流 形 滤 波 该过 过程 程相 相当 当于 于流 流形 形上 的低 低通 通滤 滤波 消 除 间平 均用 用于 于消 消除 除高 频噪 理 论 理论 论上 上可 可将 将控 点的 的噪 声方 差降 降低 低到 到原 始采 采样 样点 的约 得 后 在得 得到 到这 些低 差控 点后 进 步 进一 一步 步构 造累 条轨 之 所 之所 所以 以采 式 形式 而 而不 不是 是参 考欧 条直 接在 对 做 插 上对 对控 点做 做线 性插 插值 因 是因 因为 为位 姿所 所在 在的 量 并不 是向 向量 量空 具 备 加 法 封 闭 不具 具备 备加 加法 法封 封闭 闭性 氏空 间中 中的 写 组 条可 可写 写成 成控 的线 性组 组合 而在 群中 必 须 必须 须先 先用 广 义 移 射 邻控 点之 之间 的广 广义 义位 位移 移映 映射 射到 再在 尺 调 数中 中进 进行 行尺 尺度 度调 调制 最 最后 后通 乘 逐 段 和群 群乘 乘法 法逐 逐段 段累 种 这种 分 差分 缩 放 缩放 的形 式正 正是 够 然 推 条能 能够 够自 自然 然推 推广 广欧 保 持 条并 并保 保持 根 性的 的根 根本 本原 原因 体 来 说 三 次 具体 体来 来说 说对 对于 于三 三次 次样 归 在归 归一 一化 化局 部时 间参 参数 下 定 先定 定义 义相 数位 移为 然后 积样 迹写 写为', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ac286