INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ae2b6fb030521ded', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 基于连续轨迹正则化的局部降噪 / 基于 Lie群B样条的解析运动学约束', 'ed curvature 为。
这里采用单位度量对 twist 空间进行度量，因此该曲率可理解为操作 twist 变化的尖锐程度：当 时，轨迹局部接近恒定 screw motion；当 较大时，说明探头运动存在较强的高频弯折或急剧方向变化。
由于自由手超声依赖人工操作，探头轨迹在速度、加速度和曲率上都应受物理边界限制。设允许的最大速度、最大加速度和最大曲率分别为 、 和 ，则定义对数障碍函数形式的运动学约束损失为
这一项的作用是把“物理上不可能的高速、高加速度和高曲率运动”转化为优化中的高代价区域，从而阻止模型通过不合理的局部位姿剧烈变化去拟合图像伪影。
局部降噪模块以统计先验、连续轨迹自蒸馏和解析运动学边界共同约束位姿更新，使离散位姿收敛为符合传感器噪声统计与自由手操作连续性的平滑轨迹。相应地，第 个扫查的局部降噪总损失可写为
3.3　节恢复扫查间整体一致性，本节进一步恢复单次扫查内的连续轨迹；两级约束共同作用于位姿—表征联合优化。
本节以统计噪声先验限制异常更新，以Lie群B样条和运动学约束恢复连续轨迹，使帧级局部降噪与3.3　节的扫查级全局配准共同进入联合目标。3.4　节将通过位姿误差和新视角合成质量检验二者的作用。', 'lie ed curvature twist screw motion 3.3 3.4 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 连 续 轨 迹 正 则 局 部 降 噪 于连 连续 续轨 轨迹 迹正 正则 则化 的局 局部 部降 降噪 群 样 条 解 析 运 动 学 约 束 样条 条的 的解 解析 析运 运动 动学 学约 约束 这 里 采 用 单 度 量 对 这里 里采 采用 用单 单位 位度 度量 量对 空 间 进 行 空间 间进 进行 行度 因 此 该 曲 率 可 理 操 作 因此 此该 该曲 曲率 率可 可理 理解 解为 为操 操作 变 尖 锐 程 变化 的尖 尖锐 锐程 程度 当 时 接 近 恒 定 迹局 部接 接近 近恒 恒定 较 大 较大 大时 说 明 探 头 存 强 高 频 弯 折 或 急 剧 方 向 说明 明探 探头 头运 动存 存在 在较 较强 强的 的高 高频 频弯 弯折 折或 或急 急剧 剧方 方向 向变 由 自 手 依 赖 人 工 由于 于自 自由 由手 手超 声依 依赖 赖人 人工 工操 速 头轨 迹在 在速 速度 加 上 都 应 受 物 边 界 限 制 加速 度和 和曲 率上 上都 都应 应受 受物 物理 理边 边界 界限 限制 设 允 许 最 设允 允许 许的 的最 最大 大速 分 别 大加 和最 大曲 率分 分别 别为 义 数 障 碍 函 形 式 损 失 则定 定义 义对 对数 数障 障碍 碍函 函数 数形 形式 式的 的运 束损 损失 失为 一 项 把 这一 一项 项的 的作 作用 用是 是把 不 能 理上 上不 不可 可能 能的 高速 高加 和高 高曲 率运 转 代 价 区 域 转化 化为 为优 化中 中的 高代 代价 价区 区域 从 而 阻 止 模 型 通 过 烈 去 拟 图 像 伪 影 从而 而阻 阻止 止模 模型 型通 通过 过不 不合 合理 理的 部位 姿剧 剧烈 烈变 化去 去拟 拟合 合图 图像 像伪 伪影 块 以 统 计 先 验 噪模 模块 块以 以统 统计 计先 先验 蒸 馏 共 同 更 新 迹自 自蒸 蒸馏 馏和 和解 学边 界共 共同 同约 束位 姿更 更新 使 离 散 收 敛 符 传 感 器 性 平 滑 使离 离散 散位 姿收 收敛 敛为 为符 符合 合传 传感 感器 器噪 噪声 声统 计与 与自 手操 作连 续性 性的 的平 平滑 滑轨 相 地 相应 应地 个 总 写 个扫 查的 噪总 总损 失可 可写 写为 节 恢 复 整 体 致 节恢 恢复 复扫 查间 间整 整体 体一 一致 致性 本 步 次 内 本节 节进 进一 一步 步恢 复单 单次 次扫 查内 内的 的连 两 级 两级 级约 束共 同作 用于 异 常 节以 计噪 声先 验限 制异 异常 常更 条和 和运 束恢 复连 帧 使帧 帧级 级局 噪与 全 入 目 标 节的 的扫 查级 级全 全局 局配 准共 同进 进入 入联 合目 目标 将 误 差 视 角 成 质 检 二 者 节将 将通 过位 姿误 误差 差和 和新 新视 视角 角合 合成 成质 质量 量检 检验 验二 二者 者的', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ae2b6fb030521dedeec3bc9ddff9f2e2c4d9e6adab89c40a56c26dd07b6b2b1a') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2d09cfe9383548a2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析', '前述方法分别约束扫查级整体偏差与帧级局部扰动[8,88-91,99-101]。本节在统一协议下评价GLA-NeRF的三个层次：无噪声位姿用于选择神经渲染骨干；扫查级整体错位用于检验3.3　节的分层定位；帧级局部抖动用于检验3.4　节的连续轨迹正则化。评价同时报告位姿误差、规范空间几何一致性和新视角合成质量，以核对几何恢复与场景表征是否同步改善[118,121]。', '88-91 99-101 gla-nerf 3.3 3.4 118 121 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 前 述 方 法 别 约 束 级 整 体 偏 差 帧 局 部 扰 动 前述 述方 方法 法分 分别 别约 约束 束扫 查级 级整 整体 体偏 偏差 差与 与帧 帧级 级局 局部 部扰 扰动 本 节 统 一 协 议 下 评 价 本节 节在 在统 统一 一协 协议 议下 下评 评价 三 个 层 次 的三 三个 个层 层次 无 噪 用 选 择 神 经 渲 染 骨 干 无噪 噪声 声位 姿用 用于 于选 选择 择神 神经 经渲 渲染 染骨 骨干 错 检 体错 错位 位用 于检 检验 定 节的 的分 分层 层定 定位 抖 部抖 抖动 动用 连 续 轨 迹 正 则 的连 连续 续轨 轨迹 迹正 正则 则化 同 时 报 告 误 价同 同时 时报 报告 告位 姿误 误差 规 范 空 间 几 何 致 性 新 视 角 成 质 量 规范 范空 空间 间几 几何 何一 一致 致性 性和 和新 新视 视角 角合 合成 成质 质量 以 核 对 恢 复 场 景 否 步 改 善 以核 核对 对几 何恢 恢复 复与 与场 场景 景表 征是 是否 否同 同步 步改 改善', '/#research', 'doctoral-thesis', 1, '2026-08-04', '2d09cfe9383548a24d50faad33907caec040cc7fa258d04d7a97442f776df268') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-902bcea76ca55cbb', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 超声扫查序列配准的实验设置与配准质量评价 / 实验平台与数据集', '本章沿用第2.7.1.1　节的TUS-REC2024自由手二维超声数据及其采集、同步和划分协议。实验将独立扫查组织为多序列集合，并以人工配准结果作为参考位姿，以评价多次扫查在规范空间中的配准稳定性[21]。
为评价位姿—表征联合优化在不同误差尺度下的适用性，实验设置三类退化场景。随机全局扰动对每次扫查施加平移标准差15 mm、旋转标准差10°的刚体变换，用于模拟扫查间宏观偏移；冷启动移除外部跟踪初值，仅依据有向包围盒几何将各扫查置于共同初始姿态，用于检验弱先验条件下的可辨识性；局部抖动向逐帧位姿注入平移标准差2.5 mm、旋转标准差2.0°的高频噪声，用于评价连续轨迹约束。三类设置分别对应全局修正、粗初始化和局部平滑，不以单一退化替代其他误差来源。
三类设置分别检验扫查级刚性修正、弱初值条件下的粗配准和帧级连续轨迹恢复，使全局与局部模块在对应的误差尺度下接受评价。', '2.7.1.1 tus-rec2024 21 15 mm 10 2.5 2.0 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 设 置 质 量 评 价 准的 的实 验设 设置 置与 与配 准质 质量 量评 评价 平 台 数 据 集 验平 平台 台与 与数 数据 据集 本 沿 用 本章 章沿 沿用 用第 节 节的 自 由 手 二 维 其 采 自由 由手 手二 二维 维超 声数 据及 及其 其采 采集 同 步 划 协 议 同步 步和 和划 划分 分协 协议 将 独 立 组 织 多 验将 将独 独立 立扫 查组 组织 织为 为多 多序 列集 集合 并 以 人 工 作 参 考 并以 以人 人工 工配 准结 果作 作为 为参 参考 考位 次 规 范 空 间 稳 定 性 以评 价多 多次 次扫 查在 在规 规范 范空 空间 间中 中的 的配 准稳 稳定 定性 为评 价位 不 误 差 尺 度 下 适 化在 在不 不同 同误 误差 差尺 尺度 度下 下的 的适 适用 用性 三 类 退 场 景 置三 三类 类退 退化 化场 场景 随 机 全 局 扰 动 对 每 施 加 移 标 随机 机全 全局 局扰 扰动 动对 对每 每次 查施 施加 加平 平移 移标 标准 准差 旋 转 旋转 转标 刚 体 变 换 的刚 刚体 体变 变换 模 拟 宏 观 偏 用于 于模 模拟 拟扫 查间 间宏 宏观 观偏 偏移 冷 启 除 外 部 跟 踪 初 值 冷启 启动 动移 移除 除外 外部 部跟 跟踪 踪初 初值 仅 依 有 向 包 围 盒 几 何 各 共 始 态 仅依 依据 据有 有向 向包 包围 围盒 盒几 几何 何将 将各 各扫 查置 置于 于共 共同 同初 初始 始姿 姿态 检 弱 先 条 件 可 辨 识 于检 检验 验弱 弱先 先验 验条 条件 件下 的可 可辨 辨识 识性 抖 逐 帧 注 入 局部 部抖 抖动 动向 向逐 逐帧 帧位 姿注 注入 入平 高 频 噪 的高 高频 频噪 噪声 连 续 轨 迹 约 束 于评 价连 连续 续轨 轨迹 迹约 约束 别 应 修 正 类设 置分 分别 别对 对应 应全 局修 修正 粗 滑 粗初 始化 化和 和局 部平 平滑 单 一 替 代 他 来 源 不以 以单 单一 一退 化替 替代 代其 其他 他误 差来 来源 级 别检 验扫 查级 级刚 刚性 性修 恢 复 弱初 值条 的粗 粗配 准和 和帧 帧级 级连 迹恢 恢复 使 块 接 受 使全 局与 与局 部模 模块 块在 在对 应的 的误 下接 接受 受评', '/#research', 'doctoral-thesis', 1, '2026-08-04', '902bcea76ca55cbb88f07d49f479c26af05eb0e035f564ba5fbb2d8d52abb143') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-8af72e5ff317eee0', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 超声扫查序列配准的实验设置与配准质量评价 / 实验设置', '对比方法覆盖四类位姿优化型NeRF。NeRF--与BARF代表仅由光度一致性驱动的联合优化，SiNeRF通过正弦激活改善高频表达与收敛，SCNeRF进一步加入稀疏几何对应。为分离渲染骨干差异和配准约束贡献，实验先在无噪声位姿下选择基础骨干，再固定骨干评价全局配准与局部轨迹约束；该设计避免把骨干性能变化误归因于所提出的位姿模块。
渲染训练流程沿用第2.7.1.2　节的公共设置；本章额外维护扫查级全局位姿和帧级局部扰动，并同步评价位姿误差与新视角合成质量。batch size为1024，初始学习率按线性缩放设为1.024×10^-4，硬件环境按实际配准实验报告。', 'nerf nerf-- barf sinerf scnerf 2.7.1.2 batch size 1024 1.024 10 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 设 置 质 量 评 价 准的 的实 验设 设置 置与 与配 准质 质量 量评 评价 对 比 方 法 覆 盖 四 类 型 对比 比方 方法 法覆 覆盖 盖四 四类 类位 姿优 化型 代 仅 由 光 度 一 致 性 驱 动 代表 表仅 仅由 由光 光度 度一 一致 致性 性驱 驱动 动的 的联 通 过 正 弦 激 活 改 善 高 频 达 收 敛 通过 过正 正弦 弦激 激活 活改 改善 善高 高频 频表 表达 达与 与收 收敛 进 步 加 入 稀 疏 几 何 应 进一 一步 步加 加入 入稀 稀疏 疏几 几何 何对 对应 离 渲 染 骨 干 差 异 约 束 贡 献 为分 分离 离渲 渲染 染骨 骨干 干差 差异 异和 和配 准约 约束 束贡 贡献 先 无 噪 下 选 择 础 验先 先在 在无 无噪 噪声 声位 姿下 下选 选择 择基 基础 础骨 再 固 定 全 局 部 轨 迹 再固 固定 定骨 干评 价全 全局 局配 准与 与局 局部 部轨 轨迹 迹约 该 计 避 免 把 能 变 误 归 因 所 提 出 模 块 该设 设计 计避 避免 免把 把骨 干性 性能 能变 变化 化误 误归 归因 因于 于所 所提 提出 出的 的位 姿模 模块 训 练 流 程 沿 用 染训 训练 练流 流程 程沿 沿用 用第 节 公 共 节的 的公 公共 共设 本 额 外 维 护 级 帧 扰 本章 章额 额外 外维 维护 护扫 查级 级全 局位 姿和 和帧 帧级 级局 部扰 扰动 并 同 新 视 角 成 并同 同步 步评 价位 姿误 误差 差与 与新 新视 视角 角合 合成 成质 初 始 学 习 率 按 线 缩 放 初始 始学 学习 习率 率按 按线 线性 性缩 缩放 放设 设为 硬 件 环 境 际 报 告 硬件 件环 环境 境按 按实 实际 际配 验报 报告', '/#research', 'doctoral-thesis', 1, '2026-08-04', '8af72e5ff317eee0100bc3cadfbd5c7e4240087b9a9add484884895e062e19fa') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-312245566063240d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 超声扫查序列配准的实验设置与配准质量评价 / 评估指标', '本章评估指标分为位姿恢复精度和视图合成质量两类。位姿恢复精度是超声扫查序列配准任务的核心指标，分别采用平移误差和旋转误差进行评价，其中平移误差以毫米表示，旋转误差以角度表示，二者均相对于人工配准得到的参考轨迹计算。全局错位实验主要考察扫查级刚体偏差是否被恢复，局部抖动实验则考察逐帧高频噪声是否被抑制。
视图合成质量用于辅助判断位姿修正是否真正改善了规范空间中的图像解释能力。评价沿用第2.7.1.3　 节定义的 PSNR、SSIM、LPIPS 和综合指标 Avg.。这些指标在本章用于检验位姿修正后超声扫查序列观测是否能够形成更一致的连续神经场表征。', '2.7.1.3 psnr ssim lpips avg. 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 设 置 质 量 评 价 准的 的实 验设 设置 置与 与配 准质 质量 量评 评价 估 指 标 评估 估指 指标 本 恢 复 精 度 视 图 成 两 类 本章 章评 标分 分为 为位 姿恢 恢复 复精 精度 度和 和视 视图 图合 合成 成质 量两 两类 任 务 核 心 度是 是超 准任 任务 务的 的核 核心 心指 别 采 用 平 移 误 差 旋 转 进 行 分别 别采 采用 用平 平移 移误 误差 差和 和旋 旋转 转误 差进 进行 行评 其 以 毫 米 示 其中 中平 差以 以毫 毫米 米表 表示 角 以角 角度 度表 二 者 均 相 对 人 工 得 到 参 考 轨 迹 计 算 二者 者均 均相 相对 对于 于人 人工 工配 准得 得到 到的 的参 参考 考轨 轨迹 迹计 计算 全 局 错 主 要 察 级 刚 体 偏 否 被 全局 局错 错位 位实 验主 主要 要考 考察 察扫 查级 级刚 刚体 体偏 偏差 差是 是否 否被 被恢 部 抖 动 则 逐 帧 高 频 噪 抑 制 局部 部抖 抖动 动实 验则 则考 察逐 逐帧 帧高 高频 频噪 噪声 声是 被抑 抑制 辅 助 判 断 修 正 真 改 善 规 范 空 间 像 解 释 能 力 量用 用于 于辅 辅助 助判 判断 断位 姿修 修正 正是 否真 真正 正改 改善 善了 了规 规范 范空 空间 间中 中的 的图 图像 像解 解释 释能 能力 沿 价沿 沿用 用第 节 定 义 节定 定义 义的 综 和综 综合 合指 这 些 检 后 观 测 够 形 更 一 致 连 续 神 经 场 这些 些指 标在 在本 章用 于检 检验 验位 正后 后超 列观 观测 测是 否能 能够 够形 形成 成更 更一 一致 致的 的连 连续 续神 神经 经场 场表', '/#research', 'doctoral-thesis', 1, '2026-08-04', '312245566063240dfe56a9d33f55a7f3cb1d4dbc76e0bed00d4a15ed58fd4c88') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-020823187cd83f4b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 无噪声位姿下的渲染骨干选择', '候选位姿优化方法依赖神经渲染残差，因此先在无噪声位姿下比较骨干的新视角合成稳定性，并据此选择后续实验的共同表征基础。该实验不承担第2章整体重建方法的重新排名。
实验在真实位姿下比较NeRF--/SCNeRF、BARF和SiNeRF/GLA-NeRF，依据结构一致性、灰度保真度和综合指标选择后续配准实验的骨干，而不以单一感知指标排序。[88,99,121]
表 3.1 无噪声位姿条件下不同神经渲染骨干网络的新视角合成性能比较
Table . Novel-view synthesis under noise-free poses.
图 3.12 无噪声位姿条件下不同神经渲染骨干网络的新视角合成定性比较
Figure . Novel-view synthesis using different backbones under noise-free poses.
表 3.1 给出了不同骨干网络在真实位姿条件下的新视角合成结果。SiNeRF/GLA-NeRF 在 LPIPS 上并非单项最优，但其 SSIM、PSNR 和综合指标 Avg. 均明显优于 NeRF--/SCNeRF 与 BARF，尤其 SSIM 从约 0.47 提升至 0.661，PSNR 从约 29 dB 提升至 32.61 dB。这说明 SiNeRF 主干更有利于保持超声图像中的整体结构一致性和灰度保真度，而这两类性质对于后续位姿优化中的梯度稳定性更为关键。', 'nerf-- scnerf barf sinerf gla-nerf 88 99 121 3.1 table novel-view synthesis under noise-free poses. 3.12 figure using different backbones lpips ssim psnr avg. 0.47 0.661 29 db 32.61 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 无 噪 下 渲 染 骨 干 选 择 无噪 噪声 声位 姿下 下的 的渲 渲染 染骨 骨干 干选 选择 候 方 法 依 赖 神 经 残 差 候选 选位 姿优 化方 方法 法依 依赖 赖神 神经 经渲 染残 残差 因 此 先 比 较 新 视 角 成 稳 定 性 因此 此先 先在 在无 下比 比较 较骨 干的 的新 新视 视角 角合 合成 成稳 稳定 定性 并 据 后 续 共 同 础 并据 据此 此选 择后 后续 续实 验的 的共 共同 同表 征基 基础 该 不 承 担 该实 验不 不承 承担 担第 整 体 重 建 排 名 章整 整体 体重 重建 建方 法的 的重 重新 新排 排名 真 验在 在真 真实 实位 构 一 致 依据 据结 结构 构一 一致 致性 灰 度 保 综 指 标 灰度 度保 保真 真度 度和 和综 综合 合指 指标 标选 续配 的骨 而 以 单 感 知 而不 不以 以单 单一 一感 感知 知指 标排 排序 条 件 网 络 能 姿条 条件 件下 下不 不同 同神 干网 网络 络的 成性 性能 能比 图 成定 性比 给 出 给出 出了 了不 同骨 络在 成结 上 非 项 最 上并 并非 非单 单项 项最 最优 但 其 但其 均 明 显 均明 明显 显优 优于 尤 尤其 从 约 从约 提 升 至 提升 升至 这 说 这说 说明 主 更 有 利 持 像 主干 干更 更有 有利 利于 于保 保持 持超 声图 图像 像中 中的 的整 体结 性和 和灰 两 类 质 对 梯 关 键 而这 这两 两类 类性 性质 质对 对于 于后 续位 化中 的梯 梯度 度稳 性更 更为 为关 关键', '/#research', 'doctoral-thesis', 1, '2026-08-04', '020823187cd83f4bbddb4b042db71889cee02839d10248a7cd85e61bf49d3eab') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-54bebdd518d8989f', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 无噪声位姿下的渲染骨干选择', 'F，尤其 SSIM 从约 0.47 提升至 0.661，PSNR 从约 29 dB 提升至 32.61 dB。这说明 SiNeRF 主干更有利于保持超声图像中的整体结构一致性和灰度保真度，而这两类性质对于后续位姿优化中的梯度稳定性更为关键。
图 3.12 的定性结果也支持这一选择。NeRF--和SCNeRF 在组织边界附近存在明显模糊，BARF 虽能维持大体轮廓，但细节区域仍有平滑化倾向；SiNeRF 则更好地保留了强反射边界和细粒度散斑纹理。该比较据此选择 SiNeRF 作为提供可靠光度梯度的基础主干；结论仅用于渲染骨干选择，不代表连续神经场重建方法的总体排序。全局配准和局部降噪实验均以 SiNeRF 为骨干，并嵌入 GLA 模块形成完整的 GLA-NeRF 框架。[88]', 'ssim 0.47 0.661 psnr 29 db 32.61 sinerf 3.12 nerf-- scnerf barf gla gla-nerf 88 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 无 噪 下 渲 染 骨 干 选 择 无噪 噪声 声位 姿下 下的 的渲 渲染 染骨 骨干 干选 选择 尤 其 尤其 从 约 从约 提 升 至 提升 升至 这 说 明 这说 说明 主 更 有 利 保 持 图 像 整 体 构 一 致 性 灰 度 真 主干 干更 更有 有利 利于 于保 保持 持超 声图 图像 像中 中的 的整 整体 体结 结构 构一 一致 致性 性和 和灰 灰度 度保 保真 真度 而 两 类 质 对 后 续 梯 稳 定 关 键 而这 这两 两类 类性 性质 质对 对于 于后 后续 续位 姿优 化中 的梯 梯度 度稳 稳定 定性 性更 更为 为关 关键 也 支 的定 性结 果也 也支 支持 持这 这一 一选 组 织 边 界 附 近 存 显 模 糊 在组 组织 织边 边界 界附 附近 近存 存在 在明 明显 显模 模糊 虽 能 维 大 轮 廓 虽能 能维 维持 持大 大体 体轮 轮廓 但 细 节 区 域 仍 平 滑 倾 向 但细 细节 节区 区域 域仍 仍有 有平 平滑 滑化 化倾 倾向 则 好 地 留 强 反 射 粒 散 斑 纹 理 则更 更好 好地 地保 保留 留了 了强 强反 反射 射边 界和 和细 细粒 粒度 度散 散斑 斑纹 纹理 该 比 较 据 此 该比 比较 较据 据此 此选 作 供 可 靠 光 础 作为 为提 提供 供可 可靠 靠光 光度 度梯 度的 的基 基础 础主 论 仅 用 结论 论仅 仅用 用于 于渲 不 代 连 神 经 场 重 建 方 法 总 排 不代 代表 表连 连续 续神 神经 经场 场重 重建 建方 方法 法的 的总 总体 体排 排序 全 局 部 降 均 以 全局 局配 准和 和局 局部 部降 降噪 噪实 验均 均以 为骨 并 嵌 入 并嵌 嵌入 块 形 成 完 模块 块形 形成 成完 完整 整的 框 架 框架', '/#research', 'doctoral-thesis', 1, '2026-08-04', '54bebdd518d8989f9786c16f18ef9c2b88c6dc1603175cbf518a76da184a6267') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4393ea656d02caf6', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 全局配准消融实验', '确定共同渲染骨干后，全局消融按照“光度一致性—稀疏几何—分层候选—不确定性加权”的约束顺序展开。理论上，外观检索缩小候选空间，几何内点排除伪对应，不确定性权重降低病态匹配的影响；实验同时设置随机扰动与冷启动，以区分常规初值附近的修正能力和弱初值下的可辨识性。
实验在随机扰动和冷启动两种场景下评价3.3　节的全局配准模块，并同时报告位姿误差与新视角质量，用于判断几何恢复是否改善共享表征。[89–91,105]
表 3.2 随机扰动全局错位场景下全局配准与新视角合成性能消融实验
Table . Ablation results for global registration and novel-view synthesis under random global misalignment.
在随机扰动场景下，表 3.2显示，NeRF–、BARF和SiNeRF的最终平移误差为6.73～10.95 mm，旋转误差为5.44～8.79°；SCNeRF加入稀疏几何对应后降至5.85±3.08 mm和4.07±0.98°。结果说明纯光度监督难以恢复大尺度错位，而独立几何约束能够缩小误差。[175–177,179]
GLA-NeRF组件呈现递进改善：仅使用外观检索时误差为5.97±2.57 mm和3.99±1.35°，加入几何内点验证后降至4.67±0.85 mm和2.54±0.83°，进一步加入不确定性加权NLL后达到3.46±0.71 mm和1.53±0.57°。该递进关系与3.3　节关于候选筛选、几何验证和置信度加权的分层设计一致。', '3.3 89 91 105 3.2 table ablation results for global registration and novel-view synthesis under random misalignment. nerf barf sinerf 6.73 10.95 mm 5.44 8.79 scnerf 5.85 3.08 4.07 0.98 175 177 179 gla-nerf 5.97 2.57 3.99 1.35 4.67 0.85 2.54 0.83 nll 3.46 0.71 1.53 0.57 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 全 局 消 融 全局 局配 准消 消融 融实 确 定 共 同 渲 染 骨 干 后 确定 定共 共同 同渲 渲染 染骨 骨干 干后 按 照 局消 融按 按照 光 度 一 致 性 光度 度一 一致 致性 稀 疏 几 何 稀疏 疏几 几何 层 候 选 分层 层候 候选 不 加 权 不确 定性 性加 加权 约 束 顺 展 开 的约 约束 束顺 顺序 序展 展开 理 论 上 理论 论上 外 观 检 索 缩 小 空 间 外观 观检 检索 索缩 缩小 小候 选空 空间 内 点 排 除 伪 对 应 何内 内点 点排 排除 除伪 伪对 对应 重 降 低 病 态 匹 影 响 性权 权重 重降 降低 低病 病态 态匹 匹配 配的 的影 影响 时 设 置 随 机 扰 动 冷 启 验同 同时 时设 设置 置随 随机 机扰 扰动 动与 与冷 冷启 启动 以 区 常 规 初 值 附 近 修 正 能 力 弱 下 可 辨 识 以区 区分 分常 常规 规初 初值 值附 附近 近的 的修 修正 正能 能力 力和 和弱 弱初 值下 下的 的可 可辨 辨识 识性 两 种 场 景 评 价 验在 在随 动和 和冷 动两 两种 种场 场景 景下 下评 评价 节 模 块 节的 的全 准模 模块 并 报 告 误 差 新 视 角 质 量 并同 时报 报告 告位 姿误 误差 差与 与新 新视 视角 角质 质量 用 判 断 恢 复 否 改 善 享 用于 于判 判断 断几 何恢 恢复 复是 是否 否改 改善 善共 共享 享表 错 成 动全 局错 错位 位场 下全 准与 角合 合成 成性 性能 能消 动场 显 示 显示 最 终 平 移 的最 最终 终平 平移 移误 差为 旋 转 旋转 转误 入 至 加入 入稀 何对 应后 后降 降至 说 明 纯 监 督 难 大 尺 果说 说明 明纯 纯光 度监 监督 督难 难以 以恢 复大 大尺 尺度 度错 而 独 立 够 而独 独立 立几 何约 束能 能够 够缩 小误 组 件 呈 现 递 进 组件 件呈 呈现 现递 递进 进改 仅 使 仅使 使用 用外 索时 时误 证 入几 点验 验证 证后 步 进一 一步 步加 入不 达 到 后达 达到 该 关 系 该递 进关 关系 系与 筛 节关 关于 于候 选筛 筛选 信 计 何验 证和 和置 置信 信度 度加 权的 的分 层设 设计 计一', '/#research', 'doctoral-thesis', 1, '2026-08-04', '4393ea656d02caf653a358f1a20179ddaf1b0ffc00eedd602db8a8c6ebfd19e5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.