INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-879d9b9d8b3b8a7b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 全局配准消融实验', '9±1.35°，加入几何内点验证后降至4.67±0.85 mm和2.54±0.83°，进一步加入不确定性加权NLL后达到3.46±0.71 mm和1.53±0.57°。该递进关系与3.3　节关于候选筛选、几何验证和置信度加权的分层设计一致。
完整GLA-NeRF在随机扰动下取得LPIPS 0.197±0.011、SSIM 0.572±0.009、PSNR 29.05±0.74和Avg. 0.0561±0.0036。其LPIPS略高于SCNeRF，但其余指标更优，说明位姿误差改善并不要求所有图像指标同步最优，主要收益体现在空间结构一致性和整体保真度。[92,103,106,107]
表 3.3 冷启动全局错位场景下全局配准与新视角合成性能消融实验
Table . Ablation under cold-start global misalignment.
冷启动时，表 3.3显示纯光度方法的平移误差约为18 mm、旋转误差超过42°[8,88,99–101,118,121]；SCNeRF加入稀疏几何约束后达到4.70±0.88 mm和4.65±3.16°，完整GLA-NeRF进一步达到3.95±1.29 mm和2.77±1.70°。结果表明，当前弱初值设置需要独立几何约束链才能维持有效收敛。', '1.35 4.67 0.85 mm 2.54 0.83 nll 3.46 0.71 1.53 0.57 3.3 gla-nerf lpips 0.197 0.011 ssim 0.572 0.009 psnr 29.05 0.74 avg. 0.0561 0.0036 scnerf 92 103 106 107 table ablation under cold-start global misalignment. 18 42 88 99 101 118 121 4.70 0.88 4.65 3.16 3.95 1.29 2.77 1.70 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 实 验 结 果 分 析 准实 实验 验结 结果 果与 与分 分析 全 局 消 融 全局 局配 准消 消融 融实 加 入 几 何 内 点 证 后 降 至 加入 入几 几何 何内 内点 点验 验证 证后 后降 降至 进 一 步 不 确 定 性 权 进一 一步 步加 入不 不确 确定 定性 性加 加权 达 到 后达 达到 该 递 关 系 该递 递进 进关 关系 系与 节 候 选 筛 节关 关于 于候 候选 选筛 筛选 置 信 度 层 设 计 致 何验 证和 和置 置信 信度 度加 权的 的分 分层 层设 设计 计一 一致 完 整 完整 随 机 扰 动 下 取 得 在随 随机 机扰 扰动 动下 下取 取得 其 略 高 略高 高于 但 余 指 标 更 但其 其余 余指 指标 标更 更优 说 明 误 差 改 善 并 要 求 所 有 图 像 同 最 说明 明位 姿误 误差 差改 改善 善并 并不 不要 要求 求所 所有 有图 图像 像指 标同 同步 步最 最优 主 收 益 体 现 空 间 构 保 真 主要 要收 收益 益体 体现 现在 在空 空间 间结 结构 构一 致性 性和 和整 整体 体保 保真 真度 冷 启 错 场 景 新 视 角 成 能 冷启 启动 动全 局错 错位 位场 场景 景下 下全 准与 与新 新视 视角 角合 合成 成性 性能 能消 时 动时 显 示 纯 光 方 法 平 移 约 显示 示纯 纯光 光度 度方 方法 法的 的平 平移 移误 差约 约为 旋 转 过 旋转 转误 差超 超过 稀 疏 束 入稀 稀疏 疏几 何约 约束 束后 步达 果表 表明 当 前 弱 初 值 需 独 立 链 才 维 持 效 敛 当前 前弱 弱初 初值 值设 设置 置需 需要 要独 独立 立几 束链 链才 才能 能维 维持 持有 有效 效收 收敛', '/#research', 'doctoral-thesis', 1, '2026-08-04', '879d9b9d8b3b8a7b13e9714910d91f81c33e8b2bed3e8039865e24386501f205') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-aca19767f7252e0c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 超声扫查序列配准实验结果与分析 / 全局配准消融实验', ',118,121]；SCNeRF加入稀疏几何约束后达到4.70±0.88 mm和4.65±3.16°，完整GLA-NeRF进一步达到3.95±1.29 mm和2.77±1.70°。结果表明，当前弱初值设置需要独立几何约束链才能维持有效收敛。
冷启动组件消融中，外观检索、几何内点验证和不确定性加权NLL对应的误差依次为5.72±2.82 mm/4.92±2.00°、4.50±0.93 mm/4.89±3.69°和3.95±1.29 mm/2.77±1.70°。几何内点主要改善平移粗对齐，不确定性加权则进一步降低旋转误差，这与3.3.3　节Mahalanobis距离的作用机制一致[8,99,100,110,111]。
图 3.13 冷启动场景下六个独立扫查初始化状态的定性可视化。
Figure . Initialization of six independent sweeps in the cold-start setting.
