INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4b1302327669c5af', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第3章 基于位姿—表征联合优化的超声扫查序列配准 / 本章小结', '本章围绕多组超声扫查序列的空间一致性，构建了在同一规范空间中联合维护扫查级全局位姿、帧级局部扰动和连续神经场表征的优化框架。外观、几何、不确定性与连续轨迹约束分别作用于不同误差来源，避免把配准与重建割裂处理。
全局实验表明，候选检索、几何验证和不确定性加权能够递进改善随机扰动与冷启动条件下的扫查间对齐；局部实验表明，统计先验与Lie群B样条能够抑制逐帧抖动并恢复连续轨迹。
实验结果支持位姿与表征相互促进的理论判断：稳定几何提高多视角监督的一致性，连续表征增强位姿优化的可辨识性。经本章处理，不同扫查观测形成统一空间布局；第4章据此引入组织与器械语义。', 'lie 第 章 基 于 位 姿 基于 于位 位姿 表 征 联 合 优 化 超 声 扫 查 序 列 配 准 表征 征联 联合 合优 优化 化的 的超 超声 声扫 扫查 查序 序列 列配 配准 本 小 结 本章 章小 小结 围 绕 多 组 空 间 一 致 性 章围 围绕 绕多 多组 组超 列的 的空 空间 间一 一致 致性 构 建 同 规 范 维 护 级 全 局 构建 建了 了在 在同 同一 一规 规范 范空 间中 中联 合维 维护 护扫 查级 级全 全局 局位 帧 部 扰 动 连 续 神 经 场 框 架 帧级 级局 局部 部扰 扰动 动和 和连 连续 续神 神经 经场 场表 征的 的优 化框 框架 外 观 外观 几 何 几何 不 确 定 轨 迹 约 束 分 别 作 用 误 差 来 源 不确 确定 定性 性与 与连 续轨 轨迹 迹约 约束 束分 分别 别作 作用 用于 于不 不同 同误 误差 差来 来源 避 免 把 重 割 裂 处 理 避免 免把 把配 准与 与重 重建 建割 割裂 裂处 处理 实 验 明 局实 实验 验表 表明 候 选 检 索 候选 选检 检索 证 加 权 能 够 递 进 改 善 随 机 冷 启 条 件 下 对 齐 何验 验证 证和 和不 性加 加权 权能 能够 够递 递进 进改 改善 善随 随机 机扰 动与 与冷 冷启 启动 动条 条件 件下 下的 的扫 查间 间对 对齐 部实 统 计 先 统计 计先 先验 验与 群 样 抑 制 逐 抖 并 恢 复 样条 条能 够抑 抑制 制逐 逐帧 帧抖 抖动 动并 并恢 恢复 复连 果 支 持 相 互 促 论 判 断 验结 结果 果支 支持 持位 姿与 与表 征相 相互 互促 促进 进的 的理 理论 论判 判断 稳 提 高 视 角 监 督 稳定 定几 何提 提高 高多 多视 视角 角监 监督 督的 的一 增 强 可 辨 识 续表 征增 增强 强位 姿优 的可 可辨 辨识 识性 经本 章处 测 形 成 布 同扫 查观 观测 测形 形成 成统 统一 一空 间布 布局 据 此 引 入 织 器 械 语 义 章据 据此 此引 引入 入组 组织 织与 与器 器械 械语 语义', '/#research', 'doctoral-thesis', 1, '2026-08-04', '4b1302327669c5af272f5d7c50de514a6367f0b795b26a6cab0aa5b005969ad2') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e529cb8254e7b5fb', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 引言', '前两章分别建立了自由手超声的连续三维表征和多次扫查统一空间，使不同视角观测具备一致几何基础。然而，穿刺规划还需要回答结节位置、甲状腺边界、周围风险结构以及穿刺针与靶区之间的空间关系。因此，几何场必须进一步转化为可计算、可解释的组织与器械语义。逐帧二维分割难以独立承担这一任务。散斑、阴影、设备域差异和观测方向会造成组织边界缺失与误检；细长高亮的穿刺针易与组织界面和反射伪影混淆；解剖类别与针体占据还可能在同一点重叠。导航任务需要多视角证据在三维空间中保持一致，而不是得到彼此独立的二维预测。
本章按“稳定输入—可靠二维观测—连续三维语义—器械几何”展开。输入域规范化缓解显示差异，多任务迁移、冻结教师语义引导和结构化解剖几何约束改善低数据二维观测；连续位置场与成像平面条件场分别建模方向无关和方向相关后验，双分支、类别重加权及距离—拓扑约束处理重叠语义与细长针体。理论上条件信息可改善给定切面的解释，但方向无关三维结果仍取决于视角覆盖和边缘化，因此实验同时设置二维观测域与三维组织GT评价。', 'gt 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 引 言 引言 前 两 别 建 立 自 由 手 超 声 连 续 表 征 次 扫 查 统 一 空 间 前两 两章 章分 分别 别建 建立 立了 了自 自由 由手 手超 超声 声的 的连 连续 续三 维表 表征 征和 和多 多次 次扫 扫查 查统 统一 一空 空间 使 不 同 具 备 致 基 础 使不 不同 同视 测具 具备 备一 一致 致几 何基 基础 然 而 然而 规 划 还 需 要 回 答 结 节 位 置 刺规 规划 划还 还需 需要 要回 回答 答结 结节 节位 位置 边 界 腺边 边界 周 围 风 险 构 以 靶 区 之 关 系 周围 围风 风险 险结 结构 构以 以及 及穿 针与 与靶 靶区 区之 之间 间的 的空 间关 关系 因 此 因此 场 必 须 进 步 转 化 可 计 算 何场 场必 必须 须进 进一 一步 步转 转化 化为 为可 可计 计算 解 释 器 械 语 义 可解 解释 释的 的组 织与 与器 器械 械语 语义 逐 帧 二 难 独 承 担 这 任 务 逐帧 帧二 二维 维分 割难 难以 以独 独立 立承 承担 担这 这一 一任 任务 散 斑 散斑 阴 影 阴影 设 域 差 异 方 会 造 成 缺 失 误 检 设备 备域 域差 差异 异和 和观 测方 方向 向会 会造 造成 成组 织边 界缺 缺失 失与 与误 误检 细 长 高 亮 易 反 射 伪 混 淆 细长 长高 高亮 亮的 的穿 针易 易与 与组 织界 界面 面和 和反 反射 射伪 伪影 影混 混淆 剖 类 体 占 据 能 点 重 叠 解剖 剖类 类别 别与 与针 针体 体占 占据 据还 还可 可能 能在 在同 同一 一点 点重 重叠 导 航 证 保 持 导航 航任 务需 要多 角证 证据 据在 在三 维空 间中 中保 保持 持一 得 到 彼 预 而不 不是 是得 得到 到彼 彼此 此独 立的 的二 维预 预测 本 按 本章 章按 稳 定 输 入 稳定 定输 输入 靠 可靠 靠二 维观 维语 械几 展 开 展开 范 缓 显 示 入域 域规 规范 范化 化缓 缓解 解显 显示 示差 迁 移 多任 务迁 迁移 冻 教 师 约 束 改 善 低 数 冻结 结教 教师 师语 义引 引导 导和 和结 构化 化解 剖几 何约 约束 束改 改善 善低 低数 数据 据二 像 平 条 件 模 无 相 后 验 续位 置场 场与 与成 成像 像平 平面 面条 条件 件场 场分 建模 模方 向无 无关 关和 和方 向相 相关 关后 后验 双 支 双分 分支 加 权 距 离 别重 重加 加权 权及 及距 距离 拓 扑 处 理 拓扑 扑约 束处 处理 理重 叠语 义与 与细 长针 论 上 信 息 给 切 理论 论上 上条 件信 信息 息可 可改 善给 给定 定切 切面 面的 的解 但 果 仍 取 决 于 覆 盖 缘 但方 关三 维结 结果 果仍 仍取 取决 决于 于视 角覆 覆盖 盖和 和边 边缘 缘化 实 时 此实 实验 验同 同时 时设 设置 置二 测域 域与 与三 维组 评 价 评价', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e529cb8254e7b5fb9e122743045cdd5afd93236080d723721dc119d8212d02df') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-427ff43e3012d6e3', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向导航的任务定义与总体流程', '第2章建立了自由手超声的连续三维表征，第3章将多组扫查配准到统一规范空间。在此基础上，本章把导航对象限定为解剖对象与穿刺器械两类，研究目标是将不同切面中的二维超声观测转换为统一空间中的组织后验和穿刺针几何。本节先分析甲状腺周围结构在不同扫查切面中的影像表现，再定义对象集合、输入输出和评价边界，最后给出与后续方法及实验对应的总体流程。', '第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 任 务 定 义 总 体 流 程 向导 导航 航的 的任 任务 务定 定义 义与 与总 总体 体流 流程 建 立 自 由 手 超 声 连 续 表 征 章建 建立 立了 了自 自由 由手 手超 超声 声的 的连 连续 续三 维表 表征 将 扫 查 配 准 到 统 一 规 范 空 间 章将 将多 多组 组扫 扫查 查配 配准 准到 到统 统一 一规 规范 范空 空间 此 基 础 上 在此 此基 基础 础上 本 把 对 象 限 解 剖 器 械 两 类 本章 章把 把导 航对 对象 象限 限定 定为 为解 解剖 剖对 象与 刺器 器械 械两 两类 研 究 目 标 不 同 切 二 转 换 后 验 研究 究目 目标 标是 是将 将不 不同 同切 切面 面中 中的 的二 二维 维超 声观 测转 转换 换为 为统 一空 间中 的组 织后 后验 验和 和穿 节 先 析 周 围 结 构 影 像 现 本节 节先 先分 分析 析甲 腺周 周围 围结 结构 构在 在不 同扫 查切 的影 影像 像表 表现 再 集 合 再定 义对 象集 集合 输 入 出 评 价 边 界 输入 入输 输出 出和 和评 评价 价边 边界 最 给 方 法 实 应 最后 后给 给出 出与 与后 后续 续方 方法 法及 及实 实验 验对 对应 应的 的总', '/#research', 'doctoral-thesis', 1, '2026-08-04', '427ff43e3012d6e371e8533ae434595cc195ad762b777fed5f0e83834ebe7356') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-793afaa69369ddb6', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向导航的任务定义与总体流程 / 甲状腺解剖学与影像学分析', '甲状腺位于颈前下部，左右叶分列于气管两侧并由峡部相连。图 4.1 给出了甲状腺前面观及其主要毗邻结构：前方为皮肤、皮下组织和带状肌群，内侧邻近气管，外侧为颈动脉鞘内的大血管与神经结构。这些毗邻关系共同限定探头接触窗口和穿刺通道，结节位置只有放在甲状腺边界及周围风险结构的共同参照下才具有导航意义[181]。图 4.1 中的解剖结构并非全部作为本章的分割类别。结合现有数据标注和可定量评价条件，解剖建模聚焦甲状腺、结节和主要颈部血管；气管、肌群、神经等结构用于解释扫查窗口与局部风险，但不写入本章的输出集合。这一范围覆盖器官边界、穿刺靶区和主要血管风险，同时避免将缺少一致标注的邻近组织表述为已经完成的建模对象。
图 .1 甲状腺前面观及其周围关键解剖结构 [181]
Figure . Anterior view of the thyroid and its surrounding key anatomical structures.
图 .2 甲状腺超声横切、纵切与斜切扫查方式示意图
