INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-82352722a2e2cab1', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向导航的任务定义与总体流程 / 甲状腺解剖学与影像学分析', '纵切与斜切扫查方式示意图
Figure . Schematic illustration of transverse, longitudinal, and oblique ultrasound scanning of the thyroid
图 4.2 将甲状腺超声扫查归纳为横切、纵切和斜切三类平面[181]。横切扫查沿颈部头尾方向平移，可同时观察左右叶、峡部、气管和外侧血管，适合建立甲状腺与周围结构的横向关系；纵切扫查沿单侧腺叶长轴移动，用于补充上下极、包膜连续性和结节长径信息；斜切扫查沿局部目标或预期进针方向调整探头，使结节、血管与可能的穿刺路径尽量出现在同一切面。三类切面不是彼此独立的任务，而是对同一解剖对象集合的互补观测。本章以横切序列建立主体空间关系，以纵切序列补充头尾方向覆盖，并用斜切观测增强局部入路区域。各切面经位姿映射进入同一规范空间后，共同约束三维组织后验；切面差异则作为后续成像平面条件建模与三维组织GT评价的依据。
图 4.3 给出了甲状腺横切面超声图像及其结构标示。甲状腺实质位于气管外侧，颈总动脉和颈内静脉位于甲状腺外侧邻近区域；叠加图以红色标示甲状腺、绿色标示颈总动脉、蓝色标示颈内静脉。该切面能够在单帧中建立器官边界与主要血管风险之间的横向关系，是解剖对象集合中甲状腺和血管观测的主要来源，也为结节出现时判断其器官归属提供局部参照。', 'figure schematic illustration of transverse longitudinal and oblique ultrasound scanning the thyroid 4.2 181 gt 4.3 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 任 务 定 义 总 体 流 程 向导 导航 航的 的任 任务 务定 定义 义与 与总 总体 体流 流程 解 剖 学 影 像 析 腺解 解剖 剖学 学与 与影 影像 像学 学分 分析 纵 切 斜 扫 查 方 式 示 意 图 纵切 切与 与斜 斜切 切扫 扫查 查方 方式 式示 示意 意图 将 超 声 归 纳 横 将甲 腺超 超声 声扫 查归 归纳 纳为 为横 横切 类 平 切和 和斜 切三 三类 类平 平面 沿 颈 部 头 尾 移 查沿 沿颈 颈部 部头 头尾 尾方 方向 向平 平移 可 同 时 察 左 右 叶 可同 同时 时观 观察 察左 左右 右叶 峡 峡部 气 管 外 侧 血 气管 管和 和外 外侧 侧血 血管 适 合 建 立 周 围 结 构 关 系 适合 合建 建立 立甲 腺与 与周 周围 围结 结构 构的 的横 横向 向关 关系 单 长 轴 动 沿单 单侧 侧腺 腺叶 叶长 长轴 轴移 移动 用 于 补 充 上 下 极 用于 于补 补充 充上 上下 下极 包 膜 连 续 性 节 径 信 息 包膜 膜连 连续 续性 性和 和结 结节 节长 长径 径信 信息 局 目 标 或 预 期 进 调 整 探 沿局 局部 部目 目标 标或 或预 预期 期进 进针 针方 向调 调整 整探 探头 使 使结 能 路 尽 量 出 现 一 管与 与可 可能 能的 的穿 刺路 路径 径尽 尽量 量出 出现 现在 在同 同一 一切 切面 不 彼 此 独 类切 面不 不是 是彼 彼此 此独 独立 立的 而 对 象 集 互 而是 是对 对同 一解 剖对 对象 象集 集合 合的 的互 互补 补观 本 以 序 列 主 空 间 本章 章以 以横 切序 序列 列建 立主 主体 体空 空间 间关 覆 盖 以纵 列补 充头 向覆 覆盖 并 增 强 入 区 域 并用 用斜 切观 测增 增强 强局 部入 入路 路区 区域 各 经 位 姿 映 射 规 范 后 各切 面经 经位 位姿 姿映 映射 射进 进入 入同 一规 规范 范空 间后 共 约 束 验 共同 同约 约束 束三 维组 织后 后验 差 异 则 作 成 条 件 模 面差 差异 异则 则作 作为 为后 后续 续成 成像 像平 面条 条件 件建 建模 模与 与三 评 价 依 据 评价 价的 的依 依据 给 其 给出 出了 了甲 腺横 面超 声图 图像 像及 及其 其结 构标 标示 实 质 腺实 实质 质位 位于 于气 管外 脉 内 静 邻 近 颈总 总动 动脉 脉和 和颈 颈内 内静 静脉 脉位 于甲 腺外 侧邻 邻近 近区 叠 加 红 色 叠加 加图 图以 以红 红色 色标 示甲 绿 绿色 示颈 蓝 蓝色 该 够 帧 器 官 边 界 要 风 险 之 该切 面能 能够 够在 在单 单帧 帧中 中建 立器 器官 官边 边界 界与 与主 主要 要血 管风 风险 险之 之间 间的 来 源 是解 合中 中甲 腺和 和血 管观 的主 要来 来源 也 判 断 属 提 供 参 照 也为 为结 节出 现时 时判 判断 断其 其器 官归 归属 属提 提供 供局 部参 参照', '/#research', 'doctoral-thesis', 1, '2026-08-04', '82352722a2e2cab1f4390f0b8a975115aed1fc98e81d8be4ac4c313bd3b1d7f6') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`,