INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-23cfb561efeeed91', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向导航的任务定义与总体流程 / 甲状腺解剖学与影像学分析', '和颈内静脉位于甲状腺外侧邻近区域；叠加图以红色标示甲状腺、绿色标示颈总动脉、蓝色标示颈内静脉。该切面能够在单帧中建立器官边界与主要血管风险之间的横向关系，是解剖对象集合中甲状腺和血管观测的主要来源，也为结节出现时判断其器官归属提供局部参照。
图 .3 甲状腺横切面超声解剖结构示意图
Figure . Axial ultrasound view of the left thyroid lobe and related anatomical structures.
图 4.4 展示了甲状腺纵切面超声图像及其结构标示。纵切观测沿腺叶长轴呈现甲状腺实质和包膜的连续变化，并补充主要颈部血管在头尾方向上的延伸关系。与图 4.3 的横切面相比，纵切面减少了横向结构的同时保留了长轴连续性。两类切面提供的信息并不等价，单一切面只能观测局部截面，因此需要依靠空间位姿将多视角证据汇入同一三维表示。
图 .4 甲状腺纵切面超声解剖结构示意图
Figure . Longitudinal ultrasound anatomy of the thyroid and adjacent major cervical vessels.
表 4.1 汇总了三类扫查平面的探头摆放、主要显示结构和用途。横切、纵切与斜切共同决定多视角数据的空间覆盖，后续任务定义不再为不同切面设置不同对象类别。解剖对象在不同切面中应保持一致的空间归属，穿刺针的可见范围和响应强度则会随扫查方向及入射角变化。前者要求多视角观测在统一空间中形成稳定的组织后验，后者要求将穿刺针作为独立于解剖分类的器械占据进行建模。', 'figure axial ultrasound view of the left thyroid lobe and related anatomical structures. 4.4 4.3 longitudinal anatomy adjacent major cervical vessels. 4.1 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 任 务 定 义 总 体 流 程 向导 导航 航的 的任 任务 务定 定义 义与 与总 总体 体流 流程 解 剖 学 影 像 析 腺解 解剖 剖学 学与 与影 影像 像学 学分 分析 颈 内 静 脉 位 于 外 侧 邻 近 区 域 和颈 颈内 内静 静脉 脉位 位于 于甲 腺外 外侧 侧邻 邻近 近区 区域 叠 加 图 以 红 色 标 示 叠加 加图 图以 以红 红色 色标 标示 示甲 绿 动 绿色 示颈 颈总 总动 动脉 蓝 蓝色 该 切 能 够 单 帧 建 立 器 官 边 界 主 要 血 管 风 险 之 间 横 关 系 该切 切面 面能 能够 够在 在单 单帧 帧中 中建 建立 立器 器官 官边 边界 界与 与主 主要 要血 血管 管风 风险 险之 之间 间的 的横 横向 向关 关系 对 象 集 合 来 源 是解 剖对 对象 象集 集合 合中 中甲 腺和 和血 管观 的主 要来 来源 也 结 节 出 现 时 判 断 其 归 属 提 供 局 部 参 照 也为 为结 结节 节出 出现 现时 时判 判断 断其 其器 官归 归属 属提 提供 供局 局部 部参 参照 超 声 构 意 腺横 横切 面超 超声 声解 剖结 结构 构示 示意 意图 展 纵 展示 示了 了甲 腺纵 纵切 声图 图像 像及 及其 其结 构标 沿 叶 长 轴 呈 实 质 包 膜 连 续 变 化 切观 测沿 沿腺 腺叶 叶长 长轴 轴呈 呈现 现甲 腺实 实质 质和 和包 包膜 膜的 的连 连续 续变 变化 并 补 充 头 尾 方 上 延 伸 并补 补充 充主 要颈 颈部 部血 管在 在头 头尾 尾方 方向 向上 上的 的延 延伸 伸关 与图 相 比 面相 相比 减 少 同 保 留 性 面减 减少 少了 了横 向结 构的 的同 同时 时保 保留 留了 了长 轴连 续性 两 类 信 息 不 等 价 两类 类切 面提 供的 的信 信息 息并 并不 不等 等价 一 只 截 单一 一切 面只 只能 能观 测局 部截 截面 因 此 需 依 靠 空 姿 将 证 据 汇 入 表 因此 此需 需要 要依 依靠 靠空 空间 间位 位姿 姿将 将多 角证 证据 据汇 汇入 入同 同一 一三 维表 表示 扫 查 平 探 摆 放 汇总 总了 了三 三类 类扫 扫查 查平 平面 面的 的探 探头 头摆 摆放 显 用 途 要显 显示 示结 构和 和用 用途 斜 共 决 数 覆 盖 切与 与斜 斜切 切共 共同 同决 决定 定多 角数 数据 据的 的空 间覆 覆盖 后 再 设 置 别 后续 续任 义不 不再 再为 为不 不同 同切 面设 设置 置不 同对 象类 类别 应 持 致 象在 在不 面中 中应 应保 保持 持一 一致 致的 间归 可 见 范 围 响 强 度 则 会 随 射 针的 的可 可见 见范 范围 围和 和响 响应 应强 强度 度则 则会 会随 随扫 查方 向及 及入 入射 射角 角变 前 者 求 统 形 成 稳 验 前者 者要 要求 求多 测在 在统 统一 一空 间中 中形 形成 成稳 稳定 定的 的组 织后 后验 作 独 械 占 进 行 模 后者 求将 将穿 针作 作为 为独 独立 立于 于解 剖分 分类 类的 的器 器械 械占 占据 据进 进行 行建 建模', '/#research', 'doctoral-thesis', 1, '2026-08-04', '23cfb561efeeed911d89fe4643d26390c8dea094701fe397b4c61a925c28a7ad') ON CONFLICT(`id`) DO UPDATE SET `locale`=