INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6daa7076014cd175', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向导航的任务定义与总体流程 / 甲状腺解剖学与影像学分析', '任务定义不再为不同切面设置不同对象类别。解剖对象在不同切面中应保持一致的空间归属，穿刺针的可见范围和响应强度则会随扫查方向及入射角变化。前者要求多视角观测在统一空间中形成稳定的组织后验，后者要求将穿刺针作为独立于解剖分类的器械占据进行建模。
表 .1 面向甲状腺三维重建与穿刺导航的推荐扫查平面及主要观察目标
Table . Recommended scanning planes and main targets for thyroid 3D reconstruction and puncture navigation
甲状腺双叶、峡部、气管、前方带状肌群、颈总动脉、颈内静脉
构建甲状腺与周围结构的横向空间关系，是三维重建主扫查方式
单侧甲状腺叶、包膜、结节长径、上下极
补充头尾方向信息，增强包膜和结节长轴重建
结节、血管束、甲状腺后部区域、可能的针体路径
