INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3ed536f20b7c58de', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向导航的任务定义与总体流程 / 导航任务建模', '导航任务由解剖对象和器械对象共同构成。解剖对象集合定义为𝒜={甲状腺，结节，血管}：甲状腺表示器官主体及边界，结节表示穿刺靶区，血管限定为已有明确超声标注且可定量评价的主要颈部风险血管；气管、神经、肌群及甲状腺内微小血管不列为本章输出。器械对象集合定义为𝓘={穿刺针}，针体响应、三维占据、针轴、线段端点和针尖候选均为同一器械在不同处理阶段的观测或派生量。任务最终关注穿刺针轴线与结节靶区的相对位置、进靶状态及其到主要风险血管的最小距离。
沿用第3章建立的规范空间，设第帧超声图像为，其修正位姿为。二维像素在深度处对应的规范空间位置为：
式中，Π⁻¹表示依据超声标定关系将二维像素及深度反投影至探头坐标系。二维网络分别输出甲状腺、结节、血管和穿刺针的概率观测；这些观测经标定与位姿映射后，在规范空间中形成解剖组织后验和穿刺针占据概率，针轴及端点候选再由高置信支持区域估计。由此，任务输出分为二维语义观测、三维概率后验和器械派生几何三个层次，且均以规范空间W为共同坐标基准。', '第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 任 务 定 义 总 体 流 程 向导 导航 航的 的任 任务 务定 定义 义与 与总 总体 体流 流程 建 模 航任 务建 建模 由 解 剖 对 象 器 械 共 同 构 成 务由 由解 解剖 剖对 对象 象和 和器 器械 械对 象共 共同 同构 构成 集 合 象集 集合 合定 义为 结 节 结节 血 管 血管 表 示 官 主 边 界 腺表 表示 示器 器官 官主 主体 体及 及边 边界 靶 区 节表 示穿 刺靶 靶区 限 已 有 明 确 超 声 标 注 且 可 量 评 价 要 颈 部 风 险 管限 限定 定为 为已 已有 有明 明确 确超 超声 声标 标注 注且 且可 可定 定量 量评 评价 价的 的主 主要 要颈 颈部 部风 风险 险血 气 气管 神 经 神经 肌 群 内 微 小 不 列 本 输 出 肌群 群及 及甲 腺内 内微 微小 小血 管不 不列 列为 为本 本章 章输 输出 响 应 针体 体响 响应 占 据 维占 占据 轴 针轴 线 段 端 点 尖 候 选 均 一 处 理 阶 或 派 生 线段 段端 端点 点和 和针 针尖 尖候 候选 选均 均为 为同 同一 一器 械在 在不 不同 同处 处理 理阶 阶段 段的 的观 测或 或派 派生 生量 最 终 关 相 位 置 务最 最终 终关 关注 注穿 轴线 线与 与结 节靶 区的 的相 相对 对位 位置 进 态 其 到 距 离 进靶 靶状 状态 态及 及其 其到 到主 要风 管的 的最 最小 小距 距离 沿 用 沿用 用第 立 规 范 空 间 章建 建立 立的 的规 规范 范空 空间 设 帧 图 像 设第 第帧 帧超 声图 图像 像为 修 正 姿 其修 修正 正位 位姿 姿为 二 素 深 度 二维 维像 像素 素在 在深 深度 度处 处对 对应 应的 间位 置为 式 式中 依 系 将 反 投 影 至 探 头 坐 示依 依据 据超 标定 定关 关系 系将 将二 素及 及深 度反 反投 投影 影至 至探 探头 头坐 坐标 标系 网 络 别 维网 网络 络分 分别 别输 出甲 概 率 管和 和穿 针的 的概 概率 率观 这 些 映 射 后 这些 些观 测经 经标 定与 与位 姿映 映射 射后 形 验 在规 间中 中形 形成 成解 剖组 织后 后验 验和 针占 据概 再 高 信 支 持 域 估 计 轴及 及端 点候 选再 再由 由高 高置 置信 信支 支持 持区 区域 域估 估计 此 由此 语 务输 出分 分为 为二 维语 语义 义观 个 层 次 维概 率后 械派 生几 何三 三个 个层 层次 以 且均 均以 以规 基 准 为共 同坐 标基 基准', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3ed536f20b7c58de70e1ee5eef8b0bd94a09e1a7bb7a6fdca81b0da7d37ca411') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0d310c3c616de6bc', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 基于规范回声强度表征的甲状腺超声输入域规范化', '甲状腺B-mode图像由声束传播、组织散射、接收孔径、包络检波、对数压缩、时间增益补偿和设备后处理共同形成，像素值同时受到组织回波与显示链路影响。公开数据通常缺少RF数据、通道数据及完整系统参数，无法据此反演真实声场；直接使用显示域图像，又可能使网络把设备风格与采集设置误作语义线索。因此，本节将任务限定为输入域规范化，并将“分层图像域有效成像响应建模—采集条件模拟增强”处理链称为回声强度域规范化（echo-intensity domain normalization，EIDC）。前者估计较稳定的规范回声强度代理，后者模拟增益、动态范围、TGC、声影和散斑等合理变化；若显示域偏移确实影响概率观测，完整EIDC条件应在不同二维分割前端和外部数据上呈现多数正向变化[182-186]。', 'b-mode rf echo-intensity domain normalization eidc tgc 182-186 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 基 于 规 范 回 声 强 度 表 征 超 输 入 域 化 基于 于规 规范 范回 回声 声强 强度 度表 表征 征的 的甲 腺超 超声 声输 输入 入域 域规 范化 图 像 由 束 传 播 图像 像由 由声 声束 束传 传播 散 射 织散 散射 接 收 孔 径 接收 收孔 孔径 包 络 检 波 包络 络检 检波 对 数 压 缩 对数 数压 压缩 时 间 增 益 补 偿 设 备 后 处 理 共 同 形 成 时间 间增 增益 益补 补偿 偿和 和设 设备 备后 后处 处理 理共 共同 同形 形成 素 值 受 到 显 示 链 路 影 响 像素 素值 值同 同时 时受 受到 到组 织回 回波 波与 与显 显示 示链 链路 路影 影响 公 开 据 通 常 缺 少 公开 开数 数据 据通 通常 常缺 缺少 道 完 整 系 统 参 通道 道数 据及 及完 完整 整系 系统 统参 参数 无 法 此 反 演 真 实 场 无法 法据 据此 此反 反演 演真 真实 实声 声场 直 使 用 直接 接使 使用 用显 示域 域图 又 可 能 网 把 风 格 采 集 置 误 作 语 义 线 索 又可 可能 能使 使网 网络 络把 把设 备风 风格 格与 与采 采集 集设 设置 置误 误作 作语 语义 义线 线索 因 因此 本 节 将 任 务 限 定 本节 节将 将任 任务 务限 限定 定为 为输 并 并将 层 有 效 应 建 模 分层 层图 像域 域有 有效 效成 成像 像响 响应 应建 建模 条 件 拟 集条 条件 件模 模拟 拟增 增强 称 理链 链称 称为 为回 度域 前 者 估 计 较 稳 代 前者 者估 估计 计较 较稳 稳定 定的 的规 度代 代理 后者 者模 动 态 围 动态 态范 范围 斑 等 合 变 声影 影和 和散 散斑 斑等 等合 合理 理变 变化 若 偏 移 确 概 率 若显 域偏 偏移 移确 确实 实影 响概 概率 率观 不 二 端 外 部 上 呈 现 正 件应 应在 在不 不同 同二 二维 维分 割前 前端 端和 和外 外部 部数 据上 上呈 呈现 现多 多数 数正 正向 向变', '/#research', 'doctoral-thesis', 1, '2026-08-04', '0d310c3c616de6bcf522394dacc88eb13ca2ac8b29b643c0df3ed51cd32dc485') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=exclud