INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3890cd2bb9ac8d6d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 基于规范回声强度表征的甲状腺超声输入域规范化 / 基于图像域有效成像响应的规范化建模', '经验亮度增强或风格迁移可以改变图像外观，却不能保证超声成像响应的一致性。MimickNet表明临床后处理链会显著改变B-mode显示，PHOCUS则在潜在回波强度、成像响应和B-mode重投影之间建立了物理启发联系[182,183]。基于这一认识，EIDC不反演不可观测的真实声学链路，而是在公开B-mode数据的可观测范围内估计图像域有效成像响应，并据此获得供二维分割和三维语义融合使用的规范回声强度代理。
设第幅公开B-mode甲状腺超声图像为，潜在规范回声强度代理为，图像域有效成像响应为，采集与显示映射为，噪声及残余伪影为，则观测模型为
式中，⊗表示卷积，gᵢ描述采集与显示映射，hᵢ表示嵌入已发布B-mode图像中的有效成像响应。hᵢ不是探头真实声场的物理点扩散函数，也不对应某一型号设备的完整响应。在TN3K、DDTI等数据缺少RF数据、系统增益和TGC曲线的条件下，该模型只解释显示域退化与导出处理历史，并以稳定代理表征作为可实现的恢复目标[182,183,187-189]。
基于公式 ()，规范化输出、增强输入与下游预测定义为
式中，D(·)表示稳定化响应补偿，A(·;ξ)表示参数为ξ的采集条件模拟算子，fθ表示后续二维分割网络；B̂ᵢ、B̃ᵢ和Ŷᵢ分别表示规范回声强度代理、增强后的训练输入和分割预测。稳定化约束用于抑制盲逆问题中的高频放大，属于输入变换的数值边界，不另行解释为降噪模块或诊断输出。', 'mimicknet b-mode phocus 182 183 eidc gi hi tn3k ddti rf tgc 187-189 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 基 于 规 范 回 声 强 度 表 征 超 输 入 域 化 基于 于规 规范 范回 回声 声强 强度 度表 表征 征的 的甲 腺超 超声 声输 输入 入域 域规 范化 图 像 有 效 成 响 应 建 模 于图 图像 像域 域有 有效 效成 成像 像响 响应 应的 的规 化建 建模 经 验 亮 增 或 风 格 迁 移 可 以 改 变 外 经验 验亮 亮度 度增 增强 强或 或风 风格 格迁 迁移 移可 可以 以改 改变 变图 像外 外观 却 不 能 保 证 一 致 性 却不 不能 能保 保证 证超 声成 的一 一致 致性 明 临 床 后 处 理 链 会 显 著 表明 明临 临床 床后 后处 处理 理链 链会 会显 显著 著改 示 显示 则 潜 波 则在 在潜 潜在 在回 回波 波强 应和 重 投 影 之 间 立 物 启 发 联 系 重投 投影 影之 之间 间建 建立 立了 了物 物理 理启 启发 发联 联系 这 认 识 于这 这一 一认 认识 反 演 真 实 学 路 不反 反演 演不 不可 可观 的真 真实 实声 声学 学链 链路 而 公 开 而是 是在 在公 公开 数 据 围 内 估 计 数据 据的 的可 测范 范围 围内 内估 估计 计图 并 此 获 得 供 二 语 义 融 合 使 用 代 并据 据此 此获 获得 得供 供二 二维 维分 割和 和三 维语 语义 义融 融合 合使 使用 用的 度代 代理 设 幅 设第 第幅 幅公 声图 像为 在规 理为 应为 采 集 映 射 采集 集与 与显 示映 映射 射为 噪 残 余 伪 噪声 声及 及残 残余 余伪 伪影 影为 型 则观 测模 模型 型为 式 式中 卷 积 表示 示卷 卷积 描 述 描述 述采 嵌 已 布 示嵌 嵌入 入已 已发 发布 像中 中的 的有 探 头 场 点 扩 散 函 不是 是探 探头 头真 声场 场的 的物 理点 点扩 扩散 散函 函数 也 对 某 号 备 完 整 也不 不对 对应 应某 某一 一型 型号 号设 设备 备的 的完 完整 整响 等 缺 少 等数 据缺 缺少 统 益 系统 统增 增益 益和 曲 线 条 件 下 曲线 线的 的条 条件 件下 该 只 解 释 退 导 出 历 史 该模 型只 只解 解释 释显 示域 域退 退化 化与 与导 导出 出处 理历 历史 稳 定 作 现 目 标 并以 以稳 稳定 定代 理表 征作 作为 为可 可实 实现 现的 的恢 复目 目标 于公 公式 化输 输出 游 预 强输 入与 与下 下游 游预 预测 测定 定义 义为 补 偿 示稳 定化 化响 应补 补偿 参 示参 参数 数为 拟 算 子 的采 集条 件模 模拟 拟算 算子 续 网 络 示后 后续 续二 割网 网络 别 分别 别表 示规 训 练 强后 后的 的训 训练 练输 入和 和分 割预 约 束 抑 制 盲 逆 问 题 高 频 放 大 化约 约束 束用 用于 于抑 抑制 制盲 盲逆 逆问 问题 题中 的高 高频 频放 放大 属 换 值 边 界 属于 于输 入变 变换 换的 的数 数值 值边 边界 另 行 降 块 诊 断 不另 另行 行解 释为 为降 降噪 噪模 模块 块或 或诊 诊断 断输', '/#research', 'doctoral-thesis', 1, '2026-08-04', '3890cd2bb9ac8d6d9252abcec69f792b123b9db29eee43115067946750cad50f') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_t