INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2087eb850338d9f0', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 基于规范回声强度表征的甲状腺超声输入域规范化 / 基于图像域有效成像响应的规范化建模', 'A(·;ξ)表示参数为ξ的采集条件模拟算子，fθ表示后续二维分割网络；B̂ᵢ、B̃ᵢ和Ŷᵢ分别表示规范回声强度代理、增强后的训练输入和分割预测。稳定化约束用于抑制盲逆问题中的高频放大，属于输入变换的数值边界，不另行解释为降噪模块或诊断输出。
有效成像响应采用三级建模。phase-only image structure提供方向和尺度初始化；数据源级domain prototype response由代表性组织patch学习，用于描述同一数据来源中相对稳定的显示特征；image-level residual adaptation吸收单幅图像的裁剪、缩放、压缩及局部后处理差异。最终图像级响应写为
式中，d(i)表示图像所属的数据源或采集域，ĥd(i)与Δhᵢ分别表示域级原型响应和图像级残差响应，N(·)施加非负与归一化约束。域级共享先验降低逐图盲估计的不适定性，图像级残差则避免单一共享响应忽略样本处理差异。由此得到的理论预期是：响应补偿应减小显示链路造成的输入方差，同时保留后续分割所需的组织边界；其收益需由跨模型和跨数据集结果检验。
图 .5 EIDC 的图像域响应建模与规范回声强度表征机制
