INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-db6453b17bd0067d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 基于规范回声强度表征的甲状腺超声输入域规范化 / 基于图像域有效成像响应的规范化建模', '像域响应建模与规范回声强度表征机制
Figure . Image-domain response modeling and canonical echo-intensity representation mechanism of EIDC.
图 .6 EIDC 分层成像响应估计与规范回声强度恢复示例
Figure . Hierarchical imaging-response estimation and canonical echo-intensity recovery example in EIDC.
图 4.5概括了EIDC从公开B-mode图像、分层响应建模到规范回声强度代理和采集条件模拟的完整流程；图 4.6给出TN3K样本上的三级响应及补偿结果。相位初始化确定粗略方向与尺度，域级原型描述数据源共有特征，图像级残差只作样本适应。补偿结果用于构造下游输入，不作为独立视觉复原结果评价[184,187–189]。', 'figure image-domain response modeling and canonical echo-intensity representation mechanism of eidc. eidc hierarchical imaging-response estimation recovery example in 4.5 b-mode 4.6 tn3k 184 187 189 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 基 于 规 范 回 声 强 度 表 征 超 输 入 域 化 基于 于规 规范 范回 回声 声强 强度 度表 表征 征的 的甲 腺超 超声 声输 输入 入域 域规 范化 图 像 有 效 成 响 应 建 模 于图 图像 像域 域有 有效 效成 成像 像响 响应 应的 的规 化建 建模 机 制 域响 应建 模与 与规 征机 机制 层 估 计 示 例 分层 层成 应估 估计 计与 度恢 复示 示例 概 括 概括 括了 从 公 开 从公 公开 到 代 理 采 集 条 件 拟 完 整 流 程 层响 模到 到规 度代 代理 理和 和采 采集 集条 条件 件模 模拟 拟的 的完 完整 整流 流程 给 出 给出 样 本 上 级 补 偿 结 果 样本 本上 上的 三级 级响 应及 及补 补偿 偿结 结果 相 位 初 始 确 定 粗 略 方 尺 相位 位初 初始 始化 化确 确定 定粗 粗略 略方 方向 向与 与尺 尺度 原 型 描 述 数 据 源 共 特 域级 级原 原型 型描 描述 述数 数据 据源 源共 共有 有特 特征 残 差 只 作 适 像级 级残 残差 差只 只作 作样 本适 适应 用 构 造 下 游 果用 用于 于构 构造 造下 下游 游输 不 独 立 觉 评 价 不作 作为 为独 独立 立视 视觉 觉复 复原 原结 果评 评价', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'db6453b17bd0067d67a3e0664c50e1dde0903801cc5b9c86e8110379d16cc870') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-208b8584326775a2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 基于规范回声强度表征的甲状腺超声输入域规范化 / 面向采集条件模拟的数据增强', '获得规范回声强度代理后，还需扩大二维分割网络可见的采集分布。这里的数据增强被解释为采集条件模拟：只改变设备显示、传播伪影和轻微探头姿态相关因素，同时保持浅层—深层方向以及甲状腺、结节、风险结构和穿刺针之间的空间关系。多数据源超声研究表明，常规轻量增强与超声特异性增强的收益具有任务依赖性，因此增强强度以不改变边界语义为限[184]。
采集条件模拟分为三类：亮度、对比度和gamma变化描述整体增益、灰阶映射与动态范围差异；深度衰减、TGC、声影、雾化、散斑噪声和散斑抑制描述传播及设备后处理变化；水平翻转与轻微旋转、平移和缩放描述探头姿态及接触位置的小幅变化。训练采用随机、低强度组合，并排除垂直翻转、强弹性形变、MixUp和CutMix，以免破坏浅深方向、解剖邻接关系或病灶边界语义[184]。
图 .7 超声物理增强与轻量医学增强的可视化示例
Figure . Visualization examples of ultrasound-physics and lightweight medical augmentations.
图 4.7概括各类采集条件模拟的视觉作用及覆盖范围。实际训练不会同时高强度叠加全部变化；几何变换同步作用于图像和标注，因此既保持监督对应关系，也不改变多视角融合所用的原始帧序列与位姿。', '184 gamma tgc mixup cutmix figure visualization examples of ultrasound-physics and lightweight medical augmentations. 4.7 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 基 于 规 范 回 声 强 度 表 征 超 输 入 域 化 基于 于规 规范 范回 回声 声强 强度 度表 表征 征的 的甲 腺超 超声 声输 输入 入域 域规 范化 采 集 条 件 模 拟 数 据 增 向采 采集 集条 条件 件模 模拟 拟的 的数 数据 据增 增强 获 得 代 理 后 获得 得规 度代 代理 理后 还 需 扩 大 二 网 络 可 见 布 还需 需扩 扩大 大二 二维 维分 割网 网络 络可 可见 见的 的采 集分 分布 这 里 被 解 释 这里 里的 强被 被解 解释 释为 为采 只 改 变 设 备 显 示 只改 改变 变设 设备 备显 显示 传 播 伪 影 轻 微 探 头 姿 态 相 关 因 素 传播 播伪 伪影 影和 和轻 轻微 微探 探头 头姿 姿态 态相 相关 关因 因素 同 时 保 持 浅 层 同时 时保 保持 持浅 浅层 深 方 以 深层 层方 方向 向以 以及 及甲 结 节 结节 风 险 构 之 间 空 系 风险 险结 结构 构和 和穿 针之 之间 间的 的空 空间 间关 关系 源 研 究 明 多数 据源 源超 声研 研究 究表 表明 常 量 特 异 性 收 益 具 有 任 务 依 赖 常规 规轻 轻量 量增 强与 与超 声特 特异 异性 性增 强的 的收 收益 益具 具有 有任 任务 务依 依赖 赖性 此 不 边 界 语 义 限 因此 此增 强强 度以 以不 不改 变边 边界 界语 语义 义为 为限 类 拟分 分为 为三 三类 亮 亮度 对 比 对比 比度 度和 描 述 整 体 变化 化描 描述 述整 整体 体增 增益 灰 阶 映 射 动 围 差 灰阶 阶映 映射 射与 与动 动态 态范 范围 围差 差异 衰 减 深度 度衰 衰减 声影 雾 雾化 散 斑 噪 抑 制 处 散斑 斑噪 噪声 声和 和散 斑抑 抑制 制描 述传 播及 及设 备后 后处 处理 理变 水 平 翻 转 旋 水平 平翻 翻转 转与 与轻 微旋 旋转 移 缩 放 接 触 位 置 小 幅 平移 移和 和缩 缩放 放描 述探 态及 及接 接触 触位 位置 置的 的小 小幅 幅变 训 练 用 随 机 训练 练采 采用 用随 随机 低 合 低强 度组 组合 并 排 除 垂 直 并排 排除 除垂 垂直 直翻 弹 形 强弹 弹性 性形 形变 免 破 坏 以免 免破 破坏 坏浅 浅深 深方 剖 邻 或 病 灶 解剖 剖邻 邻接 接关 系或 或病 病灶 灶边 图 物 医 学 例 声物 物理 理增 量医 医学 学增 的可 可视 视化 化示 示例 概 括 各 觉 作 覆 盖 概括 括各 各类 类采 的视 视觉 觉作 作用 用及 及覆 覆盖 盖范 实 际 会 高 叠 加 全 部 实际 际训 练不 不会 会同 时高 高强 度叠 叠加 加全 全部 部变 换 步 像 标 注 何变 变换 换同 同步 步作 用于 于图 图像 像和 和标 标注 既 监 督 应 此既 既保 持监 监督 督对 对应 应关 也 融 所 原 始 帧 序 列 也不 变多 角融 融合 合所 所用 用的 的原 原始 始帧 帧序 序列 列与 与位 位姿', '/#research', 'doctoral-thesis', 1, '2026-08-04', '208b8584326775a20caadce9e25bc27198f95fcee593980b289c8e6a3e28ad91') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`