INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-549b42b6b8610c2a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 基于规范回声强度表征的甲状腺超声输入域规范化 / 面向采集条件模拟的数据增强', 'ight medical augmentations.
图 4.7概括各类采集条件模拟的视觉作用及覆盖范围。实际训练不会同时高强度叠加全部变化；几何变换同步作用于图像和标注，因此既保持监督对应关系，也不改变多视角融合所用的原始帧序列与位姿。
EIDC由图像域有效成像响应建模和采集条件模拟共同构成，其输出分别作为4.4　 节二维语义观测和4.5　 节三维后验建模的输入。4.6　 节以完整EIDC条件下的下游分割表现和外部泛化结果评价其有效性，所得结论限定为输入观测稳定性，不解释为原始声学测量的恢复。', 'ight medical augmentations. 4.7 eidc 4.4 4.5 4.6 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 基 于 规 范 回 声 强 度 表 征 超 输 入 域 化 基于 于规 规范 范回 回声 声强 强度 度表 表征 征的 的甲 腺超 超声 声输 输入 入域 域规 范化 采 集 条 件 模 拟 数 据 增 向采 采集 集条 条件 件模 模拟 拟的 的数 数据 据增 增强 图 概 括 各 类 觉 作 用 覆 盖 围 概括 括各 各类 类采 的视 视觉 觉作 作用 用及 及覆 覆盖 盖范 范围 实 际 训 练 不 会 同 时 高 叠 加 全 部 变 实际 际训 训练 练不 不会 会同 同时 时高 高强 度叠 叠加 加全 全部 部变 变化 换 步 像 标 注 何变 变换 换同 同步 步作 用于 于图 图像 像和 和标 标注 因 此 既 保 持 监 督 对 应 关 系 因此 此既 既保 保持 持监 监督 督对 对应 应关 关系 也 改 融 合 所 原 始 帧 序 列 位 姿 也不 不改 改变 变多 角融 融合 合所 所用 用的 的原 原始 始帧 帧序 序列 列与 与位 位姿 由 有 效 成 响 建 共 构 由图 像域 域有 有效 效成 成像 像响 响应 应建 建模 模和 和采 拟共 共同 同构 构成 其 出 别 其输 输出 出分 分别 别作 作为 节 二 语 义 节二 二维 维语 语义 义观 测和 后 验 节三 维后 后验 验建 模的 的输 以 完 整 节以 以完 完整 下 游 现 外 泛 结 果 评 价 性 件下 下的 的下 下游 游分 割表 表现 现和 和外 外部 部泛 泛化 化结 结果 果评 评价 价其 其有 效性 得 论 限 定 稳 所得 得结 结论 论限 限定 定为 为输 入观 测稳 稳定 定性 解 释 学 量 不解 解释 释为 为原 始声 声学 学测 测量 量的 的恢', '/#research', 'doctoral-thesis', 1, '2026-08-04', '549b42b6b8610c2a46d7d062a00786dbfb3d8078653ec8752661eda1916c5ba4') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1a8925f90a2f8d94', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制', '甲状腺穿刺导航的二维语义观测需在同一帧中同时描述器官、病灶、风险结构和器械，输出还将参与三维语义场与针体几何恢复，因而不能仅以单一病灶分割建模。本节围绕两类可检验问题构建多任务机制：低标注条件下，源任务表征迁移与冻结教师引导能否改善目标类别学习；四类语义共存时，结构化解剖几何约束能否降低不合理空间关系[129–131]。', '129 131 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 需 同 一 帧 时 描 述 器 官 腺穿 的二 测需 需在 在同 同一 一帧 帧中 中同 同时 时描 描述 述器 器官 病 灶 病灶 风 险 结 构 械 风险 险结 结构 构和 和器 器械 输 出 还 将 参 场 体 输出 出还 还将 将参 参与 与三 义场 场与 与针 针体 体几 因 而 不 能 仅 以 单 建 模 因而 而不 不能 能仅 仅以 以单 单一 一病 灶分 割建 建模 本 节 围 绕 两 类 检 验 问 题 本节 节围 围绕 绕两 两类 类可 可检 检验 验问 问题 题构 构建 建多 务机 低 标 注 条 件 下 低标 标注 注条 条件 件下 源 表 征 迁 移 冻 教 师 引 否 改 善 目 别 学 习 源任 务表 表征 征迁 迁移 移与 与冻 冻结 结教 教师 师引 引导 导能 能否 否改 改善 善目 目标 标类 类别 别学 学习 四 共 存 四类 类语 义共 共存 存时 化 剖 约 束 降 合 理 空 间 关 系 构化 化解 解剖 剖几 何约 约束 束能 否降 降低 低不 不合 合理 理空 空间 间关 关系', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1a8925f90a2f8d945b1f5a26d720dc26473ba23b34579133bbb36cc78fe39cc8') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-17d1f832eef76592', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 穿刺导航需求与多任务相关性', '甲状腺、结节、血管和穿刺针对应穿刺导航中的四类不同语义对象。甲状腺提供器官边界和解剖归属，结节提供靶区位置，血管是当前二维超声中较易稳定观察和像素级监督的宏观风险结构，穿刺针则提供器械候选和后续针轴恢复入口。四者之间既存在共享的超声纹理和空间上下文，也存在明确的方向性关系：器官边界更可能约束结节搜索空间，靶区和风险结构更可能帮助解释穿刺路径，针体形态又必须服从器械几何[135,136]。
实验采用“多源任务到单一目标任务”的方向设置，即每次将四类语义中的一类作为目标任务，其余三类作为源任务。这样的设计比固定的甲状腺到结节或血管到穿刺针二元关系更一般：它能够检验完整导航上下文对每个单一语义的帮助是否具有一致性，也能揭示不同目标任务对源任务知识的依赖强弱。若某一方向收益有限，也可以据此解释为任务相关性不足、数据域差异较大或源任务先验与目标任务解码发生冲突。
Table . Multi-task semantic directions and core hypotheses.
导航上下文有助于减少针体离散误检并提升连续性
靶区与器械上下文有助于定位甲状腺邻近风险结构
甲状腺范围压缩结节搜索空间，降低器官外伪阳性
检验完整导航语义对大器官边界的迁移价值', '135 136 table multi-task semantic directions and core hypotheses. 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 需 求 相 关 性 航需 需求 求与 与多 务相 相关 关性 结 节 结节 血 管 对 应 四 类 不 同 象 血管 管和 和穿 针对 对应 应穿 航中 中的 的四 四类 类不 不同 同语 义对 对象 提 供 器 官 边 界 剖 归 属 腺提 提供 供器 器官 官边 边界 界和 和解 解剖 剖归 归属 靶 区 位 置 节提 供靶 靶区 区位 位置 当 前 超 声 较 易 稳 定 察 像 素 级 监 督 宏 风 险 构 管是 是当 当前 前二 维超 超声 声中 中较 较易 易稳 稳定 定观 观察 察和 和像 像素 素级 级监 监督 督的 的宏 宏观 观风 风险 险结 结构 则 械 候 选 后 续 轴 入 口 针则 则提 器械 械候 候选 选和 和后 后续 续针 针轴 轴恢 复入 入口 者 之 间 既 存 共 享 纹 理 空 上 下 文 四者 者之 之间 间既 既存 存在 在共 共享 享的 的超 声纹 纹理 理和 和空 空间 间上 上下 下文 也 明 确 方 系 也存 在明 明确 确的 的方 方向 向性 性关 关系 更 能 约 束 搜 索 界更 更可 可能 能约 约束 束结 节搜 搜索 索空 帮 助 路 径 区和 和风 构更 能帮 帮助 助解 释穿 刺路 路径 体 形 态 又 必 须 服 从 针体 体形 形态 态又 又必 必须 须服 服从 从器 械几 实 验 采 用 实验 验采 采用 源 到 单 一 目 标 多源 源任 务到 到单 单一 一目 目标 标任 设 向设 设置 即 每 次 将 作 即每 每次 次将 将四 类语 义中 的一 一类 类作 作为 为目 其 余 其余 余三 三类 为源 这 样 计 比 固 或 元 般 这样 样的 的设 设计 计比 比固 固定 定的 的甲 腺到 到结 节或 或血 管到 到穿 针二 二元 元关 系更 更一 一般 它 够 检 完 整 个 否 具 有 致 它能 能够 够检 检验 验完 完整 整导 航上 文对 对每 每个 个单 一语 义的 的帮 助是 是否 否具 具有 有一 一致 致性 揭 示 知 识 依 赖 强 弱 也能 能揭 揭示 示不 同目 务对 对源 务知 知识 识的 的依 依赖 赖强 强弱 若 某 收 益 限 若某 某一 一方 向收 收益 益有 有限 以 据 此 足 也可 可以 以据 据此 此解 释为 为任 性不 不足 数 域 差 异 大 先 码 发 生 冲 突 数据 据域 域差 差异 异较 较大 大或 或源 务先 先验 验与 与目 务解 解码 码发 发生 生冲 冲突 于 减 少 离 散 误 并 升 连 文有 有助 助于 于减 减少 少针 体离 离散 散误 误检 检并 并提 提升 升连 连续 续性 邻 近 区与 与器 械上 于定 定位 位甲 腺邻 邻近 近风 范 围 压 缩 腺范 范围 围压 压缩 缩结 降 低 外 伪 阳 降低 低器 官外 外伪 伪阳 阳性 迁 移 价 值 航语 对大 大器 界的 的迁 迁移 移价 价值', '/#research', 'doctoral-thesis', 1, '2026-08-04', '17d1f832eef76592cbc39cb56adda58df35c991e26e54f3b9cdc3ed2ba6def6d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`