INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b7124e456b74727e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 任务分支机制框架与总体架构', '在上述任务相关性的基础上，任务分支机制框架作为二维语义观测的统一载体。输入图像先映射为共享编码器表征，再由甲状腺、结节、血管和穿刺针分支生成类别响应图；源任务信息通过编码器初始化、冻结教师模型或分支间语义引导进入目标任务，结构化解剖几何约束则约束输出的结构合理性。该框架可以接入多种编码器与解码器，但本章关于机制有效性的定量结论限定在同一骨干网络下的消融结果，不据此推断跨骨干性能。
设二维分割骨干集合为 B，任一骨干 可分解为编码器 和解码算子 。在任务分支机制中，不同语义类别 ={甲状腺,结节,血管,穿刺针} 共享编码器表征，但具有各自的任务分支 。因此，多标签二维语义概率观测可表示为
该形式将骨干结构与任务互助机制分离：骨干b负责特征提取和多尺度解码，任务分支及语义引导边决定源任务知识的传递方式。若同一机制在不同b上保持一致趋势，增益才更可能归因于任务关系建模。4.4.3—4.4.5节分别分析表征迁移、冻结教师语义引导和结构化解剖几何约束，4.4.6节说明多源部分标注训练。
