INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-fe591f15e58ec192', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 任务分支间语义引导机制', '源任务表征迁移主要改变目标任务训练的初始位置，但目标任务在后续解码阶段仍可能重新回到仅依赖灰度纹理的单任务预测。任务分支间语义引导机制的目的，是把源任务分支或冻结教师模型产生的语义条件持续注入目标任务分支，使目标预测从单纯的图像条件预测转化为带有源任务结构提示的条件预测。设第 l 层目标任务特征为 ，源任务或教师模型提供的先验特征为 ，则一般形式可写为[76,77,79]
其中 表示语义引导算子。该表达的关键不在于增加一个复杂网络，而在于让目标分支直接回答“哪些源任务语义证据对当前目标有用、这些证据应作用于哪些空间位置”。从概率建模角度看，语义引导希望用源语义变量 降低目标预测的不确定性：
在低数据场景中，本文采用冻结教师语义引导。教师模型在源任务训练后保持参数固定，其输出不会随少量目标任务标注共同漂移，因而能够提供相对稳定的语义条件。该设计将源任务编码器初始化带来的表征收益，与解码阶段持续使用源语义条件所产生的收益区分开来。若目标任务在冻结教师引导后继续改善，则增益来自源语义对目标分支解码的持续约束，而非参数初始化本身。
