INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e6cfe09e32724536', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 任务分支间语义引导机制', '目标分支解码的持续约束，而非参数初始化本身。
在候选引导单元中，本文将 CBAM 作为默认语义引导模块。其优势在于同时建模通道选择和空间显著性，并以相对较低的参数自由度筛选源任务先验中的有效信息。给定目标任务特征与源任务先验，先构造融合特征
CBAM 首先估计通道注意力，用于判断哪些语义通道对当前目标任务更重要：
随后估计空间注意力，用于判断哪些像素位置更可信：
最终目标分支特征通过通道—空间联合调制得到：
这一残差式形式保留了目标任务自身证据，同时允许源任务先验在“哪些语义通道有用”和“哪些空间位置可信”两个层面调节目标解码。对于甲状腺穿刺导航，甲状腺边界、结节弱边界、血管暗区和穿刺针细长回声具有不同外观尺度和噪声模式；单纯空间门控容易忽略类别通道差异，单纯通道调制又缺少对伪影位置的抑制。CBAM 的通道注意力有助于筛选源任务中的有效结构线索，空间注意力有助于抑制背景伪响应、声影干扰和离散误检，因此预期在最终分割质量上更稳健。
跨注意力、特征仿射调制和自适应区域先验用于比较不同语义引导偏置。跨注意力可进行全局特征交互，但对标注规模和教师噪声更敏感；仿射调制计算较轻，却缺少直接空间选择；区域先验可提供位置提示，但在多源语义组合中选择性有限。CBAM同时进行通道选择和空间抑制，理论上更适合低数据、噪声教师条件；其相对优势仍由实验比较决定。', 'cbam 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 支 间 引 务分 分支 支间 间语 义引 引导 导机 目 标 码 持 续 约 束 目标 标分 支解 解码 码的 的持 持续 续约 约束 而 非 参 数 初 始 化 本 身 而非 非参 参数 数初 初始 始化 化本 本身 候 选 单 元 在候 候选 选引 导单 单元 元中 文 将 本文 文将 作 默 认 模 块 作为 为默 默认 认语 导模 模块 其 优 势 于 同 时 建 通 道 择 空 显 著 性 其优 优势 势在 在于 于同 同时 时建 建模 模通 通道 道选 选择 择和 和空 空间 间显 显著 著性 并 以 相 对 较 低 自 由 度 筛 源 先 验 有 效 信 息 并以 以相 相对 对较 较低 低的 的参 数自 自由 由度 度筛 筛选 选源 源任 务先 先验 验中 中的 的有 有效 效信 信息 给 定 特 征 给定 定目 标任 务特 特征 征与 与源 构 造 融 合 先构 构造 造融 融合 合特 首 估 计 注 意 力 首先 先估 估计 计通 道注 注意 意力 用 判 断 哪 些 当 前 更 重 要 用于 于判 判断 断哪 哪些 些语 义通 道对 对当 当前 前目 务更 更重 重要 随 后 随后 后估 计空 间注 像 素 位 置 些像 像素 素位 位置 置更 更可 可信 最 终 过 最终 终目 支特 征通 通过 过通 联 调 得 到 间联 联合 合调 调制 制得 得到 这 一 残 差 式 形 保 留 证 据 这一 一残 残差 差式 式形 形式 式保 保留 留了 了目 务自 自身 身证 证据 允 许 时允 允许 许源 验在 道有 有用 些空 间位 置可 两 个 层 节 两个 个层 层面 面调 调节 节目 标解 对于 于甲 腺穿 边 界 腺边 边界 结 弱 结节 节弱 弱边 血 管 暗 区 细 长 回 声 具 不 外 尺 噪 血管 管暗 暗区 区和 和穿 针细 细长 长回 回声 声具 具有 有不 不同 同外 外观 观尺 尺度 度和 和噪 噪声 声模 模式 纯 门 控 容 易 忽 略 类 别 异 单纯 纯空 间门 门控 控容 容易 易忽 忽略 略类 类别 别通 道差 差异 又 缺 少 伪 影 抑 纯通 道调 制又 又缺 缺少 少对 对伪 伪影 影位 置的 的抑 抑制 助 线 索 的通 力有 有助 助于 于筛 务中 效结 结构 构线 线索 背 景 响 应 于抑 制背 背景 景伪 伪响 响应 干 扰 离 散 误 检 声影 影干 干扰 扰和 和离 离散 散误 误检 因 此 预 期 质 量 上 稳 健 因此 此预 预期 期在 在最 终分 割质 质量 量上 上更 更稳 稳健 跨 跨注 仿 射 适 域 比 偏 征仿 仿射 射调 制和 和自 自适 适应 应区 区域 域先 验用 于比 比较 较不 同语 导偏 偏置 进 行 全 局 交 互 力可 可进 进行 行全 全局 局特 征交 交互 但 规 教 师 敏 感 但对 对标 标注 注规 规模 模和 和教 教师 师噪 声更 更敏 敏感 算 轻 制计 计算 算较 较轻 却 直 接 却缺 少直 直接 接空 间选 提 供 示 验可 可提 提供 供位 置提 提示 限 但在 在多 多源 源语 义组 组合 合中 中选 择性 性有 有限 时进 行通 间抑 理 论 理论 论上 更适 适合 合低 低数 数据 条 件 声教 师条 条件 仍 实 决 其相 对优 势仍 仍由 由实 实验 验比 较决 决定', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e6cfe09e327245368978d6a7e3bb758650df60ec240695d67584e09810dd0c3a') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`so