INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d019a389a0debf0d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 任务分支间语义引导机制', '可进行全局特征交互，但对标注规模和教师噪声更敏感；仿射调制计算较轻，却缺少直接空间选择；区域先验可提供位置提示，但在多源语义组合中选择性有限。CBAM同时进行通道选择和空间抑制，理论上更适合低数据、噪声教师条件；其相对优势仍由实验比较决定。
因此，本文对 4.6.3　 节实验提出先验预测：在目标标注稀缺时，CBAM 冻结教师语义引导应提高目标类别最终 Dice，并在多数类别上改善早期训练表现；跨注意力可能在 Best@20 或 Epoch@A95 等收敛速度指标上表现更强，但其高容量交互未必带来最高最终 Dice。若该预测在多个目标语义和标注比例下成立，则可认为任务分支间语义引导确实改善了目标任务解码，而不是仅依赖源任务表征迁移。', 'cbam 4.6.3 dice best 20 epoch a95 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 支 间 引 务分 分支 支间 间语 义引 引导 导机 进 行 全 局 特 征 交 互 可进 进行 行全 全局 局特 特征 征交 交互 但 对 标 注 规 模 教 师 噪 声 更 敏 感 但对 对标 标注 注规 规模 模和 和教 教师 师噪 噪声 声更 更敏 敏感 仿 射 调 计 算 较 轻 仿射 射调 调制 制计 计算 算较 较轻 却 缺 少 直 接 空 选 择 却缺 缺少 少直 直接 接空 空间 间选 选择 区 域 先 验 提 供 位 置 示 区域 域先 先验 验可 可提 提供 供位 位置 置提 提示 源 合 性 有 限 但在 在多 多源 源语 义组 组合 合中 中选 择性 性有 有限 同 时 通 道 抑 同时 时进 行通 通道 道选 择和 和空 间抑 抑制 理 论 上 适 低 数 据 理论 论上 上更 更适 适合 合低 低数 数据 条 件 声教 师条 条件 其 相 优 势 仍 由 实 比 决 定 其相 相对 对优 优势 势仍 仍由 由实 实验 验比 比较 较决 决定 因 此 因此 本 文 本文 文对 节 出 预 节实 验提 提出 出先 验预 预测 目 稀 在目 目标 标标 注稀 稀缺 缺时 冻 结 应 高 类 别 最 终 冻结 结教 师语 导应 应提 提高 高目 标类 类别 别最 最终 并 改 善 早 期 训 练 表 现 并在 多数 数类 别上 上改 改善 善早 早期 期训 训练 练表 表现 跨 意 力 能 跨注 注意 意力 力可 可能 能在 或 等 收 敛 速 度 指 强 等收 收敛 敛速 速度 度指 指标 标上 上表 现更 更强 容 量 未 必 带 来 但其 其高 高容 容量 量交 互未 未必 必带 带来 来最 最高 高最 若 该 个 例 下 成 立 若该 该预 测在 多个 个目 标语 义和 和标 注比 比例 例下 下成 成立 则 认 确 码 则可 可认 认为 为任 导确 确实 实改 善了 了目 标任 务解 解码 而 不 仅 依 赖 迁 移 而不 不是 是仅 仅依 依赖 赖源 源任 务表 表征 征迁 迁移', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd019a389a0debf0d2467640649399b29fb0baee801c28a3a31ec6b619b8488bb') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b810a27bb3b9a9ae', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 结构化解剖几何约束机制', '任务分支间语义引导仍属于数据驱动的软特征调制。当训练集较小、标注不完整或目标呈现强几何结构时，仅依赖可学习先验边可能不足以抑制结构性错误。结构化解剖几何约束机制把临床解剖关系和器械几何形态写入训练目标，并区分数据集中的实际存在语义与像素级监督有效性：前者决定某一几何关系是否具有医学意义，后者以有效阳性、已确认不存在和缺失/不适用三种状态决定强监督是否启用。该约束在保留分割监督的同时，进一步收缩医学上可行的解空间。[136,192]
在穿刺导航场景下，普通四语义联合训练、加入 CBAM 语义引导、以及进一步加入结构化解剖几何约束的训练目标分别写为
语义引导相对普通联合训练的变化用于衡量任务分支交互收益，结构化解剖几何约束相对语义引导的变化用于衡量解剖—器械结构约束收益。解剖几何项由六类关系约束加权组成，分别对应结节归属、血管非重叠、血管邻近、针体直线性、伪针尖入靶和伪针尖避血管：
