INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6e8f3b2b45efdb8c', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 多任务学习数据集设计', '二维语义观测机制需要同时提供甲状腺边界、结节靶区、风险血管和可见针体等局部证据，但现有公开甲状腺超声数据集通常只覆盖其中一部分结构。若把未标注类别简单视为背景，模型会把缺失标注误学为阴性样本；若只使用单一数据集，又难以同时覆盖病灶、风险结构和器械候选。因此，本节首先从数据层面说明多源数据集如何被组织为部分标注多任务学习问题。[140,164,193,194]', '140 164 193 194 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 学 习 数 据 集 设 计 务学 学习 习数 数据 据集 集设 设计 需 要 同 时 提 供 边 界 制需 需要 要同 同时 时提 提供 供甲 腺边 边界 结 节 靶 区 结节 节靶 靶区 风 险 血 管 见 体 等 局 部 证 风险 险血 血管 管和 和可 可见 见针 针体 体等 等局 局部 部证 证据 但 现 有 公 开 超 声 通 常 只 覆 盖 其 一 构 但现 现有 有公 公开 开甲 腺超 超声 声数 集通 通常 常只 只覆 覆盖 盖其 其中 中一 一部 部分 分结 结构 若 把 未 标 注 类 别 简 单 背 景 若把 把未 未标 标注 注类 类别 别简 简单 单视 视为 为背 背景 模 型 会 缺 失 误 阴 性 样 本 模型 型会 会把 把缺 缺失 失标 注误 误学 学为 为阴 阴性 性样 样本 使 用 若只 只使 使用 用单 单一 一数 又 难 以 病 灶 又难 难以 以同 时覆 盖病 病灶 器 械 候 选 险结 构和 和器 器械 械候 候选 因 此 因此 首 先 从 层 说 明 源 如 被 问 题 本节 节首 首先 先从 从数 据层 层面 面说 说明 明多 多源 源数 集如 如何 何被 被组 织为 为部 分标 注多 习问 问题', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6e8f3b2b45efdb8c6910d0662c330d89a8dd345d628eb9afdf0c9e5181ccafca') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-3a82641742e64249', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 多任务学习数据集设计 / 多源数据集', '表 4.4 汇总二维语义观测所用的 11 个逻辑数据源。TG3K[131]提供甲状腺监督；TN3K[135]、DDTI Stage 1[132]、VTUS[196]和 ThyroidXL[197]提供结节监督；SegThy[195]由 32 例三维标注体数据沿 xy、xz 和 yz 三个方向切片，在 224×224 参考尺度下剔除前景少于 64 像素的切片，并仅将颈动脉标签映射为血管语义；Common Carotid[198]补充血管外观；Brachial Plexus Needle[146]与 BILab PAUS Needle[199]补充针体形态。本文自制数据拆分为两个逻辑数据源：NeckScan 提供甲状腺与血管监督，PVA-Phantom 提供甲状腺、结节、血管和穿刺针四类监督。二者具有不同对象与语义契约，不再合并为单一来源。
图 .9 多源超声分割数据集代表性样本及有效标注可视化
Figure . Samples and valid-annotation overlays from multi-source ultrasound datasets.
表 .4 多源超声分割数据池、单轮有效集及类别监督概况
