INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6e0ff1e63c9fae94', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 多任务学习数据集设计 / 多源数据集', ' 多源超声分割数据池、单轮有效集及类别监督概况
Table . Multi-source ultrasound dataset pools, effective sampling counts, and valid supervision.
Brachial Plexus Needle
结合表 4.4 和图 4.10 可见，多源合并的关键约束是：未标注类别不能被默认解释为真实背景。本文为每一帧、每一类别保存独立有效性状态。有效阳性参与前景监督，已确认不存在的类别作为真实阴性参与监督；缺失或不适用类别不计算该类损失与评价指标。该契约使 NeckScan 的结节和穿刺针通道保持无效，同时允许 PVA-Phantom 中已确认无结节、无血管或无针的帧提供可信负样本，避免把“缺失标注”和“结构不存在”混为同一状态。[140]
在完成数据集映射后，图 4.10 分别给出规范化数据池和动态采样后的第 0 轮训练/固定验证有效集。颜色采用对数尺度，单元格数字表示某一数据源对某一类别提供的有效监督图像数；同一图像可以同时贡献多个类别，因此各类别数字不能相加为唯一图像数。训练集采用按序列分组的轮换步长采样，使被下采样数据在不同轮次改变偏移并获得长期覆盖；验证集采用固定步长，保证各轮评价集合不变。', 'table multi-source ultrasound dataset pools effective sampling counts and valid supervision. brachial plexus needle 4.4 4.10 neckscan pva-phantom 140 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 学 习 数 据 集 设 计 务学 学习 习数 数据 据集 集设 设计 源 多源 源数 超 声 池 源超 超声 声分 割数 据池 单 轮 有 效 类 别 监 督 概 况 单轮 轮有 有效 效集 集及 及类 类别 别监 监督 督概 概况 结 合 表 结合 合表 图 和图 见 可见 并 关 键 约 束 源合 合并 并的 的关 关键 键约 约束 束是 未 标 注 不 能 被 默 认 真 实 背 景 未标 标注 注类 别不 不能 能被 被默 默认 认解 释为 为真 真实 实背 背景 本 文 每 一 帧 本文 文为 为每 每一 一帧 保 存 独 立 性 态 一类 别保 保存 存独 独立 立有 效性 性状 状态 阳 参 前 效阳 阳性 性参 参与 与前 前景 景监 已 确 作 阴 已确 确认 认不 不存 存在 在的 的类 别作 作为 实阴 阴性 与监 缺 失 或 适 用 算 该 损 评 价 指 缺失 失或 或不 不适 适用 用类 不计 计算 算该 该类 类损 损失 失与 与评 评价 价指 指标 契 使 该契 契约 约使 节 通 道 持 无 的结 结节 节和 和穿 针通 通道 道保 保持 持无 无效 同 时 允 许 同时 时允 允许 中已 认无 无结 血 管 提 供 信 负 样 无血 血管 管或 或无 无针 针的 的帧 帧提 提供 供可 可信 信负 负样 样本 避 免 把 避免 免把 失标 构 结构 构不 混 混为 为同 同一 一状 完 成 映 射 后 在完 完成 成数 集映 映射 射后 给 出 规 范 化 动 采 分别 别给 给出 出规 规范 范化 化数 池和 和动 动态 态采 采样 样后 后的 的第 训 练 轮训 训练 固 定 验 证 固定 定验 验证 证有 颜 色 对 尺 度 颜色 色采 采用 用对 对数 数尺 尺度 元 格 字 示 某 像 单元 元格 格数 数字 字表 表示 示某 某一 一数 据源 源对 对某 别提 供的 的有 效监 督图 图像 像数 以 贡 献 个 一图 像可 可以 以同 时贡 贡献 献多 多个 个类 因 此 各 相 加 唯 因此 此各 各类 别数 字不 能相 相加 加为 为唯 唯一 按 序 列 换 步 长 练集 集采 用按 按序 序列 列分 分组 组的 的轮 轮换 换步 步长 长采 下 次 改 变 偏 移 获 得 期 覆 盖 使被 被下 下采 样数 据在 在不 不同 同轮 轮次 次改 改变 变偏 偏移 移并 并获 获得 得长 长期 期覆 覆盖 证集 用固 定步 保证 证各 各轮 轮评 价集 集合 合不 不变', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6e0ff1e63c9fae942ce7d47ef1031f05bd48cd0ff221d004d68f4e8bdf9946bb') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level