INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f765e30b95d60d1e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 多任务学习数据集设计 / 自制 NeckScan 与 PVA-Phantom 数据集', '本章采用 5.4.3 节构建的 NeckScan 与 PVA-Phantom 数据集。NeckScan 共 1,917 帧，按训练/验证 1,534/383 划分，仅对甲状腺和血管提供有效监督；PVA-Phantom 共 3,220 帧，按 2,575/645 划分，对甲状腺、结节、血管和穿刺针均提供有效监督。两者均在各扫查视图内部按帧随机划分，验证比例为 20%，划分种子固定为 2026；同一语义的有效状态可以是前景阳性或已确认不存在，而非要求每帧都含有该结构。
两个自制数据源在本章中承担互补任务：NeckScan 用于补充颈部真实扫查外观下的甲状腺—血管联合监督，PVA-Phantom 用于在几何可控对象上验证四类联合分割与解剖—器械结构关系；其中带同步位姿的 PVA-Phantom 多视角序列还为三维语义场和针体概率场提供二维观测。数据采集、扫查序列组织、空间同步、标注契约及数据用途在 5.4.3 节统一说明。
NeckScan 和 PVA-Phantom 均不替代公开临床数据的外观多样性。公开数据主要用于扩展甲状腺、结节、血管和针体的来源域；NeckScan 补充颈部扫查条件下的器官—风险结构联合观测；PVA-Phantom 则用于在同一物理对象和坐标链路中分析二维语义、三维后验与器械几何。三者分别支撑跨源外观、颈部联合语义和空间可重复性。', 'neckscan pva-phantom 5.4.3 917 534 383 220 575 645 20 2026 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 学 习 数 据 集 设 计 务学 学习 习数 数据 据集 集设 设计 自 自制 本 采 用 本章 章采 采用 节 构 建 节构 构建 建的 共 帧 按 训 练 按训 训练 验 证 验证 划 划分 仅 对 血 管 提 供 有 效 监 督 仅对 对甲 腺和 和血 血管 管提 提供 供有 有效 效监 监督 结 结节 均 管和 和穿 针均 均提 两 者 各 扫 查 图 内 部 随 两者 者均 均在 在各 各扫 扫查 查视 视图 图内 内部 部按 按帧 帧随 随机 机划 比 例 证比 比例 例为 种 子 固 定 分种 种子 子固 固定 定为 同 一 态 以 前 景 阳 性 或 已 确 认 不 存 同一 一语 义的 的有 效状 状态 态可 可以 以是 是前 前景 景阳 阳性 性或 或已 已确 确认 认不 不存 存在 而 非 要 求 每 都 含 该 而非 非要 要求 求每 每帧 帧都 都含 含有 有该 该结 结构 个 源 承 担 互 补 两个 个自 制数 据源 源在 在本 章中 中承 承担 担互 互补 补任 于 充 颈 真 实 外 下 用于 于补 补充 充颈 颈部 部真 真实 实扫 查外 外观 观下 下的 的甲 联 合 管联 联合 合监 控 象 上 四 类 剖 于在 在几 何可 可控 控对 对象 象上 上验 证四 四类 类联 合分 与解 解剖 器 械 关 系 器械 械结 构关 关系 其 带 步 位 姿 其中 中带 带同 同步 步位 位姿 姿的 序 列 还 场 体 概 率 角序 序列 列还 还为 为三 义场 场和 和针 针体 体概 概率 率场 场提 供二 维观 据采 采集 查序 列组 空 间 空间 间同 标 注 契 约 途 标注 注契 契约 约及 及数 据用 用途 途在 统 说 明 节统 统一 一说 说明 替 代 公 开 临 床 样 均不 不替 替代 代公 公开 开临 临床 床数 据的 的外 观多 多样 样性 主 扩 展 开数 据主 主要 要用 于扩 扩展 展甲 来 域 体的 的来 来源 源域 条 件 官 部扫 查条 条件 件下 的器 器官 风 险 风险 险结 构联 合观 则 物 理 坐 链 路 析 则用 在同 一物 物理 理对 象和 和坐 坐标 标链 链路 路中 中分 分析 析二 后 维后 后验 验与 与器 械几 别 支 撑 跨 三者 者分 分别 别支 支撑 撑跨 跨源 源外 重 部联 合语 义和 和空 间可 可重 重复 复性', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f765e30b95d60d1e3a030d518dbdebe1c384f618835f968399df05842366d2e5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6172bc98e9ff7cc9', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向穿刺导航的可解释多任务二维语义观测机制 / 多任务学习数据集设计 / 数据集自适应结构化解剖几何约束策略', '结构化解剖几何约束只有在语义集合、解剖场景和参考来源同时匹配时才具有正当性。为避免把甲状腺场景中的结构关系错误迁移到非甲状腺数据集，本文在数据集层面定义实际存在语义与像素级监督有效性，并在几何项层面定义适用性权重与参考可信度。有效阳性和已确认不存在可以作为强监督，缺失/不适用状态只能在教师模型或源任务分支可靠时提供弱参考。
结构化解剖几何约束按“实际存在语义决定关系可用性、像素级有效性决定监督强度”启用。TG3K 仅使用甲状腺强监督；TN3K、DDTI Stage 1、VTUS 和 ThyroidXL 以结节强监督为主，甲状腺或血管关系仅在可靠教师或源分支可用时启用。SegThy 提供甲状腺—颈动脉非重叠与邻近监督，Common Carotid 仅补充血管外观，两个针体数据源仅约束针体形态。NeckScan 可评价甲状腺—血管关系；四类结构违反率只在 PVA-Phantom 中评价，结论不扩展至语义不完整的数据源。
本节建立了面向导航语义的二维多任务观测机制：源任务表征迁移和冻结教师引导缓解低标注学习，类别有效性契约避免把缺失标注误作背景，数据集自适应的解剖几何约束限制不合理结构关系。输出为具有明确类别含义、有效状态和适用边界的二维概率图，4.5 节据此研究多视角三维后验与器械几何恢复。', 'tg3k tn3k ddti stage vtus thyroidxl segthy common carotid neckscan pva-phantom 4.5 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 导 航 可 解 释 任 务 二 语 义 机 制 向穿 刺导 导航 航的 的可 可解 解释 释多 多任 任务 务二 二维 维语 语义 义观 测机 机制 学 习 数 据 集 设 计 务学 学习 习数 数据 据集 集设 设计 自 适 应 结 构 化 剖 约 束 策 略 集自 自适 适应 应结 结构 构化 化解 解剖 剖几 何约 约束 束策 策略 只 有 合 束只 只有 有在 在语 义集 集合 场 景 参 考 来 源 同 时 匹 配 才 具 正 当 性 剖场 场景 景和 和参 参考 考来 来源 源同 同时 时匹 匹配 配时 时才 才具 具有 有正 正当 当性 避 免 把 关 系 错 误 迁 移 到 非 为避 避免 免把 把甲 腺场 景中 中的 的结 构关 关系 系错 错误 误迁 迁移 移到 到非 非甲 腺数 本 文 层 定 实 际 存 像 素 级 监 督 效 本文 文在 在数 集层 层面 面定 定义 义实 实际 际存 存在 义与 与像 像素 素级 级监 监督 督有 有效 效性 并 项 用 权 重 信 度 并在 在几 何项 项层 义适 适用 用性 性权 权重 重与 与参 考可 可信 信度 阳 已 确 认 不 以 作 强 效阳 阳性 性和 和已 已确 确认 认不 不存 在可 可以 以作 作为 为强 强监 缺 失 缺失 态 能 教 师 模 型 或 支 靠 提 供 弱 不适 用状 状态 态只 只能 能在 在教 教师 师模 模型 型或 或源 源任 务分 分支 支可 可靠 靠时 时提 提供 供弱 弱参 按 束按 决 义决 决定 定关 系可 可用 级有 性决 定监 督强 强度 启 启用 仅 使 仅使 使用 用甲 腺强 节 主 以结 结节 节强 督为 为主 血 管 腺或 或血 血管 管关 系仅 仅在 靠教 师或 源分 用时 时启 供甲 颈 动 脉 叠 邻 近 颈动 动脉 脉非 非重 重叠 叠与 与邻 邻近 近监 补 充 外 仅补 补充 充血 管外 外观 两 个 体 形 两个 个针 针体 体数 据源 源仅 仅约 束针 体形 形态 评 价 可评 评价 价甲 四 类 违 反 率 四类 类结 构违 违反 反率 率只 只在 中评 论 扩 展 至 完 整 结论 论不 不扩 扩展 展至 至语 义不 不完 完整 整的 的数 建 立 本节 节建 建立 立了 了面 向导 航语 义的 的二 维多 务观 表 征 冻 引 缓 低 标 注 务表 表征 征迁 移和 和冻 冻结 结教 师引 引导 导缓 缓解 解低 低标 标注 注学 别 契 背 类别 别有 性契 契约 约避 把缺 失标 注误 误作 作背 背景 限 理 应的 的解 束限 限制 制不 不合 合理 理结 输 出 明 含 输出 出为 为具 有明 明确 确类 别含 含义 边 界 概 图 效状 态和 和适 用边 边界 界的 维概 概率 率图 此 研 究 后 验 器 械 节据 据此 此研 研究 究多 角三 维后 后验 验与 与器 器械 械几', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6172bc98e9ff7cc9f17f693e9ecbbc2275befe9c80d0dddca5652370e75123e1') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`pub