INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4834ea694754739d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场', '二维概率图是受位姿与成像方向影响的局部观测，直接体素写入会混合方向相关响应。本节据此构建连续多视角条件场，并在输出端进行方向边缘化和针体几何恢复。实验分别在统一二维观测域和既有针体几何GT上评价相应模块；缺少汇总量的三维组织语义不进入定量结论。
方法分为四个相互衔接的环节：表示层比较体素融合、连续位置场与成像平面条件场；标签层以双分支容纳解剖归属和器械占据；优化层处理类别不平衡、难负样本及针体拓扑；几何层通过类别感知融合和稳健估计恢复有限针体线段。4.6　节用现有实验检验各机制。', 'gt 4.6 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 二 概 率 图 受 位 姿 方 影 响 局 部 二维 维概 概率 率图 图是 是受 受位 位姿 姿与 与成 像方 方向 向影 影响 响的 的局 局部 部观 直 接 体 素 写 入 会 混 合 相 关 应 直接 接体 体素 素写 写入 入会 会混 混合 合方 向相 相关 关响 响应 本 节 据 此 构 建 连 续 本节 节据 据此 此构 构建 建连 连续 续多 角条 并 输 出 端 进 行 边 缘 化 并在 在输 输出 出端 端进 进行 行方 向边 边缘 缘化 化和 和针 针体 体几 实 验 别 统 一 域 既 有 实验 验分 分别 别在 在统 统一 一二 维观 测域 域和 和既 既有 有针 上 评 价 模 块 上评 评价 价相 相应 应模 模块 缺 少 汇 总 量 语 义 不 定 结 论 缺少 少汇 汇总 总量 量的 维组 织语 语义 义不 不进 进入 入定 定量 量结 结论 法 四 个 互 衔 环 方法 法分 分为 为四 四个 个相 相互 互衔 衔接 接的 的环 环节 表 示 层 比 较 融 表示 示层 层比 比较 较体 素融 融合 置 续位 位置 置场 场与 标 签 以 双 支 容 纳 解 剖 归 属 器 械 占 标签 签层 层以 以双 双分 分支 支容 容纳 纳解 解剖 剖归 归属 属和 和器 器械 械占 占据 优 处 理 类 衡 优化 化层 层处 处理 理类 类别 别不 不平 平衡 难 负 样 拓 扑 难负 负样 样本 本及 及针 体拓 拓扑 通 过 感 知 稳 健 估 计 限 线 段 何层 层通 通过 过类 别感 感知 知融 合和 和稳 稳健 健估 估计 计恢 复有 有限 限针 体线 线段 用 现 检 各 机 制 节用 用现 现有 有实 验检 检验 验各 各机 机制', '/#research', 'doctoral-thesis', 1, '2026-08-04', '4834ea694754739d4d73c33d466551bcc25e57525b40ceb0e0bdcb38dbc10619') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-8e40b449a014df3e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 体素概率融合与成像平面条件场', '多视角语义建模包含两个连续但不同的估计问题：首先由不规则二维切片恢复连续三维组织，其次将随成像方向变化的条件后验转化为导航查询所需的方向无关三维后验。体素概率融合、连续位置场和成像平面条件场分别对应局部经验估计、共享空间函数估计与条件概率估计。三者的表示能力递增，但误差来源也由网格量化扩展到观测条件和后验融合。', '第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 体 素 概 率 融 合 体素 素概 概率 率融 融合 合与 与成 语 义 建 模 包 含 两 个 连 续 但 不 同 估 计 问 题 角语 语义 义建 建模 模包 包含 含两 两个 个连 连续 续但 但不 不同 同的 的估 估计 计问 问题 首 先 由 规 则 二 切 片 首先 先由 由不 不规 规则 则二 二维 维切 切片 片恢 复连 续三 维组 其 次 将 随 方 变 化 后 验 转 导 航 查 询 所 需 无 关 其次 次将 将随 随成 像方 方向 向变 变化 化的 的条 件后 后验 验转 转化 化为 为导 导航 航查 查询 询所 所需 需的 的方 向无 无关 关三 维后 位 置 别 对 应 局 部 经 续位 位置 置场 场和 和成 场分 分别 别对 对应 应局 局部 部经 经验 验估 共 享 空 间 函 数 共享 享空 空间 间函 函数 数估 计与 与条 件概 率估 者 表 示 能 力 递 增 三者 者的 的表 表示 示能 能力 力递 递增 误 差 来 源 也 网 格 量 扩 展 到 但误 误差 差来 来源 源也 也由 由网 网格 格量 量化 化扩 扩展 展到 到观 测条 件和 和后 验融', '/#research', 'doctoral-thesis', 1, '2026-08-04', '8e40b449a014df3eba3d6ec44df4d6bc76ed63a431cb711fd335610903d70b0c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-9a52199908c98771', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 体素概率融合与成像平面条件场 / 体素概率融合及其误差边界', '设规范空间被划分为体素集合{V_k}，第i帧像素u经标定与位姿映射到V_k。记y_i^c(u)为类别c的二维概率观测，r_{i,u}为观测可靠性，则体素概率融合为：
该估计无需训练且可增量更新。在位姿准确、观测独立同分布并且覆盖充分时，加权均值能够降低随机噪声；自由手超声的相邻帧却高度相关，细小血管和针体还具有明显的方向可见性。若真实语义函数S_c(x)为L_c-Lipschitz连续、体素边长为h、体素内有效观测数为N_k，则均方误差可近似分解为：
式中依次为固定网格量化偏差、有限观测方差、位姿偏差和视角偏差。增加同一方向的相邻帧主要降低随机方差，不能消除网格量化、未覆盖空洞及方向相关的系统偏差。', 'c-lipschitz 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 体 素 概 率 融 合 体素 素概 概率 率融 融合 合与 与成 其 误 差 边 界 合及 及其 其误 误差 差边 边界 设 规 范 空 间 被 划 集 设规 规范 范空 空间 间被 被划 划分 分为 为体 素集 集合 帧 帧像 像素 经 标 定 位 姿 映 射 到 经标 标定 定与 与位 位姿 姿映 映射 射到 记 类 别 为类 类别 二 的二 二维 维概 率观 可 靠 性 为观 测可 可靠 靠性 则 则体 合为 该 估 计 无 需 训 练 且 增 量 更 新 该估 估计 计无 无需 需训 训练 练且 且可 可增 增量 量更 更新 准 确 在位 姿准 准确 独 立 同 布 并 覆 盖 充 时 测独 独立 立同 同分 分布 布并 并且 且覆 覆盖 盖充 充分 分时 加 权 均 值 能 够 降 低 随 机 噪 声 加权 权均 均值 值能 能够 够降 降低 低随 随机 机噪 噪声 自 由 手 超 相 邻 却 高 度 关 自由 由手 手超 超声 声的 的相 相邻 邻帧 帧却 却高 高度 度相 相关 细 小 血 管 还 具 有 明 显 方 见 细小 小血 血管 管和 和针 针体 体还 还具 具有 有明 明显 显的 的方 方向 向可 可见 见性 若 真 实 语 义 函 数 若真 真实 实语 语义 义函 函数 连 续 连续 长 素边 边长 长为 内 效 素内 内有 有效 效观 测数 数为 近 似 解 则均 均方 方误 差可 可近 近似 似分 分解 解为 式 依 次 固 网 格 化 偏 式中 中依 依次 次为 为固 固定 定网 网格 格量 量化 化偏 偏差 限 有限 限观 测方 方差 姿偏 差和 和视 角偏 一 主 要 增加 加同 同一 一方 向的 帧主 主要 要降 机方 不 消 除 不能 能消 消除 除网 未 洞 系 统 未覆 盖空 空洞 洞及 及方 向相 关的 的系 系统 统偏', '/#research', 'doctoral-thesis', 1, '2026-08-04', '9a52199908c9877145af73113a71713838ea249c77e52e077fd3417ceabe9d0c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-83957dda62a15a76', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 体素概率融合与成像平面条件场 / 连续三维语义场与有限层厚理想观测', '连续位置语义场以共享函数表示空间点的类别后验，使单次观测产生的梯度经网络参数作用于邻近位置，而非只更新一个离散体素：
共享函数解除输出分辨率与训练网格之间的强绑定，将局部独立估计转化为全域函数估计。连续性归纳偏置有利于填补不规则切片之间的有限间隙，但不能自动解释同一位置在不同声束方向下的系统性外观差异。
超声像素对应成像平面法向邻域内的有限体积响应。设像素中心为x_i(u)，平面法向为n_i，有效层厚为Δ，归一化响应核为κ_i(ρ)，则有限层厚理想语义观测模型为：
该积分沿声束层厚方向聚合局部体积证据，不在成像平面切向实施无差别平滑。若p_θ^c沿法向为L_n-Lipschitz连续，则平滑偏差不超过L_n∫κ_i(ρ)|ρ|dρ，Δ与κ_i共同定义物理可解释的观测尺度。', 'n-lipschitz 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 体 素 概 率 融 合 体素 素概 概率 率融 融合 合与 与成 连 续 语 义 有 限 层 厚 理 想 连续 续三 维语 语义 义场 场与 与有 有限 限层 层厚 厚理 理想 想观 位 置 以 共 享 函 数 表 示 空 间 点 类 别 后 验 续位 位置 置语 场以 以共 共享 享函 函数 数表 表示 示空 空间 间点 点的 的类 类别 别后 后验 使 单 次 产 生 梯 度 经 网 络 参 作 用 于 邻 近 使单 单次 次观 测产 产生 生的 的梯 梯度 度经 经网 网络 络参 参数 数作 作用 用于 于邻 邻近 近位 而 非 只 更 新 一 个 离 散 而非 非只 只更 更新 新一 一个 个离 离散 散体 解 除 输 出 辨 训 练 格 之 强 绑 定 数解 解除 除输 输出 出分 分辨 辨率 率与 与训 训练 练网 网格 格之 之间 间的 的强 强绑 绑定 将 局 部 独 立 估 计 转 化 全 域 将局 局部 部独 独立 立估 估计 计转 转化 化为 为全 全域 域函 数估 性 归 纳 偏 利 填 补 不 规 则 切 片 隙 续性 性归 归纳 纳偏 偏置 置有 有利 利于 于填 填补 补不 不规 规则 则切 切片 片之 的有 限间 间隙 但 能 自 动 释 同 声 束 方 下 系 统 外 差 异 但不 不能 能自 自动 动解 解释 释同 同一 一位 置在 在不 不同 同声 声束 束方 方向 向下 下的 的系 系统 统性 性外 外观 观差 差异 超 对 应 法 内 积 响 超声 声像 像素 素对 对应 应成 面法 法向 向邻 邻域 域内 内的 限体 体积 积响 响应 设 心 设像 素中 中心 心为 向为 效 有效 效层 厚为 核 归一 一化 化响 应核 核为 模 型 则有 想语 义观 测模 模型 型为 该 沿 聚 证 据 该积 积分 分沿 沿声 束层 厚方 向聚 聚合 合局 部体 积证 证据 实 施 无 滑 不在 在成 面切 切向 向实 实施 施无 无差 差别 别平 平滑 若 沿法 过 则平 滑偏 偏差 差不 不超 超过 物 可 尺 共同 同定 定义 义物 物理 理可 可解 释的 的观 测尺 尺度', '/#research', 'doctoral-thesis', 1, '2026-08-04', '83957dda62a15a761312143f31a4cfaac2eec98d9756070e695cceb2b3d8e0b6') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-bac70c13965a0331', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 体素概率融合与成像平面条件场 / 二维条件后验与方向无关三维后验', '成像平面条件场使用声束方向d_i、平面横向l_i以及扫查组、帧和射线嵌入e_g、e_f、e_r。观测条件定义为o_i=(d_i,l_i,e_g,e_f,e_r)，条件特征与类别后验分别为：
上述定义与实现一致：法向n_i只用于有限层厚积分的几何描述，不作为M16l语义头的学习输入。p_θ(c|x,o_i)表示给定成像方向和扫查状态后，空间点在二维观测域中的条件语义。导航查询需要方向无关三维后验，两者由后验融合联系：
条件场学习与方向边缘化是两个估计阶段。条件变量用于解释方向相关外观，融合权重决定这些预测如何进入最终三维概率；融合分布与实际观测方向分布不一致时，准确的二维条件预测仍可能被低可见性方向稀释。三维误差据此分解为：
