INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-9dac00185a8861b2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 体素概率融合与成像平面条件场 / 表示能力与可检验理论预测', '体素概率融合产生分段常数函数，连续位置场属于空间连续函数族F_pos，成像平面条件场属于条件函数族F_cond。忽略o的连续函数是条件场的特例，故F_pos⊂F_cond，并有：
在对数损失下，理想风险差为H(C|X)−H(C|X,O)=I(C;O|X)≥0。当观测方向在给定空间位置后仍携带类别信息时，条件场具有降低二维条件预测风险的理论可能；该优势能否传递至三维组织GT评价，还取决于类别感知融合和有效方向覆盖。连续位置场首先改变三维表示方式，预期降低离散写入误差并改善强度场连续性，但在已观测切片上的二维语义Dice不必同步提高。成像平面条件场直接扩大条件后验的函数族，因此应优先改善方向相关二维语义。上述判断分别对应表示误差、条件预测误差与融合误差，不预设各阶段指标单调变化。
