INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-26015757c5c16c18', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 重叠语义监督契约与解剖—器械双分支建模', '甲状腺、结节和血管描述空间点的解剖归属，穿刺针描述器械是否占据当前观测。针体可以覆盖甲状腺、结节或背景区域，因此解剖变量A与器械变量N构成联合状态(A,N)∈𝒜×{0,1}。单一五类softmax只允许互斥状态，不能同时表达解剖归属和针体占据。
双分支条件语义场以共享特征h_θ(x,o)连接解剖softmax分支和针体sigmoid分支：
解剖分支在背景、甲状腺、结节和血管之间进行互斥分类，器械分支在独立Bernoulli空间估计针体占据。对针体正样本，单一softmax会同时压低全部解剖logit；双分支中针体损失对解剖logit的直接梯度为零，因而避免器械监督抹除其下方的解剖信息。
监督契约在各数据入口保持一致。重叠解剖标签按血管、结节、甲状腺、背景的固定优先级投影为单一解剖目标，针体标签保留在独立通道。二维显示需要单标签时，先取解剖argmax，再由针体阈值覆盖显示层：
该规则只用于单标签可视化与导出，不改变训练中的重叠监督。双分支消除的是标签空间中的结构性冲突，并为针体建立独立梯度路径；它既不增加针体正样本，也不保证区域指标立即提高。若双分支条件语义场的总体Dice未超过单分支条件场，只能说明独立器械分支仍受类别先验和优化难度限制。类别重加权与细长结构约束在这一接口上继续作用。', 'softmax sigmoid bernoulli logit argmax dice 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 重 叠 语 义 监 督 契 约 解 剖 重叠 叠语 语义 义监 监督 督契 契约 约与 与解 解剖 器 械 双 支 建 模 器械 械双 双分 分支 支建 建模 结 节 血 管 描 述 空 间 点 归 属 结节 节和 和血 血管 管描 描述 述空 空间 间点 点的 的解 剖归 归属 否 占 据 当 前 针描 述器 械是 是否 否占 占据 据当 当前 前观 体 可 以 覆 盖 针体 体可 可以 以覆 覆盖 盖甲 或 背 景 区 域 节或 或背 背景 景区 区域 因 此 变 量 因此 此解 剖变 变量 与器 械变 构 联 合 态 构成 成联 联合 合状 状态 单 一 五 类 单一 一五 五类 只 允 许 互 斥 只允 允许 许互 互斥 斥状 不 能 同 时 表 达 不能 能同 同时 时表 表达 达解 属和 和针 体占 共 享 特 征 支条 件语 义场 场以 以共 共享 享特 特征 连 接 连接 接解 支和 剖分 支在 在背 之 进 行 管之 之间 间进 进行 行互 斥分 分类 独 立 械分 在独 独立 估 计 间估 估计 计针 对 正 样 本 对针 体正 正样 样本 会 压 低 全 部 会同 时压 压低 低全 全部 部解 损 失 支中 中针 体损 损失 失对 对解 直 梯 度 零 的直 直接 接梯 梯度 度为 为零 而 避 免 抹 除 其 下 方 信 息 因而 而避 避免 免器 械监 督抹 抹除 除其 其下 下方 方的 剖信 信息 各 数 入 口 保 持 致 约在 在各 各数 数据 据入 入口 口保 保持 持一 一致 标 签 按 叠解 剖标 标签 签按 按血 固 定 优 先 级 投 影 目 景的 的固 固定 定优 优先 先级 级投 投影 影为 为单 一解 剖目 目标 留 通 道 体标 签保 保留 留在 立通 通道 二 显 示 需 要 二维 维显 显示 示需 需要 要单 单标 签时 取 先取 取解 再 由 阈 值 层 再由 由针 体阈 阈值 值覆 盖显 示层 该 规 则 用 于 化 导 出 该规 规则 则只 只用 用于 于单 签可 可视 视化 化与 与导 导出 改 训 练 不改 改变 变训 训练 练中 中的 的重 叠监 消 性 冲 突 支消 消除 除的 的是 是标 签空 间中 的结 结构 构性 性冲 冲突 并 路 径 并为 为针 体建 建立 立独 立梯 度路 路径 它 既 增 加 它既 既不 不增 增加 加针 也 证 指 即 提 高 也不 不保 保证 证区 域指 指标 标立 立即 即提 提高 若 总 若双 场的 的总 总体 未 超 过 未超 超过 过单 单分 说 明 仍 受 别 验 难 限 制 只能 能说 说明 明独 立器 支仍 仍受 受类 类别 别先 先验 验和 和优 优化 化难 难度 度限 限制 权 细 长 束 这 上 继 续 作 别重 重加 加权 权与 与细 细长 长结 构约 约束 束在 在这 这一 一接 接口 口上 上继 继续 续作 作用', '/#research', 'doctoral-thesis', 1, '2026-08-04', '26015757c5c16c18775ad33ae84a7230718a67303a076fe3602ed92c0e8fe97d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`