INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-93097aeab6bfc656', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 细长针体的软管状监督与拓扑连续性约束', '类别均衡能够恢复针体分支的有效梯度，但像素级区域损失不能充分描述细长结构。针体宽度通常只有数个像素，亚像素位姿偏差、亮线宽度变化和标注误差会使硬二值边界产生较大的相对变化。令Γ为针体中心线、d(u,Γ)为像素到中心线的距离、σ为横向不确定性尺度、r为有限支持半径，软管状目标定义为：
该目标在中心附近保持高置信监督，边缘权重随距离平滑衰减，从而降低小尺度横向偏移引起的梯度突变。软管状监督沿用Focal–Tversky解剖损失，在针体分支中以软目标计算归一化Focal BCE与Tversky：
软标签可能扩大低概率响应，因而需要显式控制无针图像和管状支持以外的高置信预测。设Ω^−={u:ỹ_N(u)<τ_s}，H_q^−为Ω^−中按p_N(u)排序的前q比例像素，则困难负样本损失为：
当前设置取τ_s=0.05、q=0.01，并以0.1的系数加入困难负样本项：
区域重叠正确仍不保证中心线连通。令Skel(·)为可微软骨架化算子，拓扑精度、拓扑敏感度及clDice定义为：
拓扑连续性约束保留软目标和困难负样本项，并在固定0.05的针体重叠预算内按0.8∶0.2混合Tversky与clDice：
需要正结构的Tversky与clDice仅在有效针体目标存在时启用。软管状监督预期提高横向偏移容忍性，困难负样本项预期降低无针图像和管外区域的误检，clDice则改变中心线结构与概率排序。三者并不保证固定阈值下的含针图像检出率同步提高，因此4.6.4　 节同时报告区域、排序、误检和检出指标。', 'focal tversky bce 0.05 0.01 0.1 skel cldice 0.8 0.2 4.6.4 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 细 长 体 软 管 监 督 拓 扑 连 续 性 约 束 细长 长针 针体 体的 的软 软管 管状 状监 监督 督与 与拓 拓扑 扑连 连续 续性 性约 约束 类 别 均 衡 能 够 支 有 效 梯 度 类别 别均 均衡 衡能 能够 够恢 复针 体分 分支 支的 的有 有效 效梯 梯度 但 素 级 区 域 损 失 不 充 描 述 结 构 但像 像素 素级 级区 区域 域损 损失 失不 不能 能充 充分 分描 描述 述细 长结 结构 宽 通 常 只 数 个 体宽 宽度 度通 通常 常只 只有 有数 数个 个像 亚 位 姿 偏 差 亚像 素位 位姿 姿偏 偏差 亮 线 变 化 标 注 误 会 使 硬 二 值 边 界 产 生 较 大 相 对 亮线 线宽 度变 变化 化和 和标 标注 注误 误差 差会 会使 使硬 硬二 二值 值边 边界 界产 产生 生较 较大 大的 的相 相对 对变 令 心 为针 体中 中心 心线 到 距 离 为像 素到 到中 线的 的距 距离 横 确 定 尺 为横 横向 向不 不确 确定 定性 性尺 尺度 限 持 半 径 为有 有限 限支 支持 持半 半径 目 义 状目 目标 标定 定义 义为 该 附 近 保 高 置 信 该目 标在 在中 心附 附近 近保 保持 持高 高置 置信 信监 缘 权 重 随 滑 衰 减 边缘 缘权 权重 重随 随距 离平 平滑 滑衰 衰减 从 而 降 低 小 移 引 起 突 从而 而降 降低 低小 小尺 度横 向偏 偏移 移引 引起 起的 的梯 度突 突变 沿 用 督沿 沿用 解 剖 解剖 剖损 以 计 算 归 一 在针 支中 中以 以软 软目 标计 计算 算归 归一 一化 签 可 扩 概 率 响 应 软标 标签 签可 可能 能扩 扩大 大低 低概 概率 率响 响应 因 需 要 显 式 控 制 无 图 外 预 因而 而需 需要 要显 显式 式控 控制 制无 无针 针图 图像 像和 和管 状支 持以 以外 外的 的高 信预 预测 设 按 中按 排 序 前 排序 序的 的前 比 例 比例 例像 则 困 难 负 样 本 则困 困难 难负 负样 样本 本损 失为 当 取 当前 前设 设置 置取 并 并以 系 加 入 项 的系 系数 数加 加入 入困 本项 叠 正 仍 证 域重 重叠 叠正 正确 确仍 仍不 不保 保证 证中 线连 连通 微 骨 架 子 为可 可微 微软 软骨 骨架 架化 化算 算子 精 扑精 精度 敏 感 扑敏 敏感 感度 度及 留 束保 保留 留软 标和 和困 固 并在 在固 固定 内 的针 体重 叠预 预算 算内 内按 混 合 混合 要正 正结 构的 仅 存 时 启 仅在 在有 效针 体目 标存 存在 在时 时启 启用 期 提 容 忍 督预 预期 期提 提高 高横 移容 容忍 忍性 检 项预 期降 低无 管外 外区 域的 的误 误检 改 则改 改变 变中 线结 构与 与概 率排 者 阈 下 含 出 同 步 三者 者并 并不 证固 定阈 阈值 值下 下的 的含 含针 像检 检出 出率 率同 同步 步提 此 因此 节 报 告 节同 同时 时报 报告 告区 指 检和 和检 出指 指标', '/#research', 'doctoral-thesis', 1, '2026-08-04', '93097aeab6bfc656c43b45acf956579a001ed0c689d581cb4660f81be938edc2') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`