INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f77b65d7e9bc4b41', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 面向多视角观测的成像平面条件场 / 类别感知多视角后验融合与针体几何恢复', '成像平面条件场输出p_θ(c|x,o_g)，导航查询需要方向无关三维组织概率。均匀平均假定各扫查组对每一类别具有相同可见性，与横切、纵切、遮挡和有限视野条件不符。为此，类别存在率用于估计扫查组的类别可靠性。设扫查组g含N_g帧，其中N_(g,c)^+帧出现类别c，则：
类别存在率把各扫查组对类别c的有效观测机会转化为融合权重，可减少未观测该类别的方向对小结构概率的稀释。该权重不依赖待查询位置，仍受组内覆盖和标注分布影响。当前统一消融只评价观测平面的条件预测，因此本章保留上述融合作为三维输出机制，不据此主张已经获得三维语义定量优势。
针体几何恢复以三维针体概率q_N(x)为输入。双阈值迟滞先以高阈值τ_h生成可靠种子，再在低阈值τ_l下保留与种子连通的候选，τ_l<τ_h：
集合C恢复弱但连续的针体响应，同时排除孤立低置信伪影。候选被划分为K个碎片C_k后，先在碎片内归一化权重，避免大碎片完全支配方向估计。全局概率加权稳健拟合、碎片均衡稳健拟合和双阈值迟滞碎片恢复依次增加碎片规模校正与弱连续支持。轴线L(a,v)={a+tv}通过RANSAC初始化和Huber迭代重加权估计：
将候选投影到t=v̂ᵀ(x−â)后，以概率加权1%和99%分位数确定有限线段端点，降低少量轴向离群点对长度的影响：', 'a+tv ransac huber 99 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 成 像 平 条 件 场 的成 成像 像平 平面 面条 条件 件场 类 别 感 知 后 验 融 合 体 类别 别感 感知 知多 角后 后验 验融 融合 合与 与针 针体 体几 输 出 场输 输出 导 航 查 询 需 要 方 无 关 概 率 导航 航查 查询 询需 需要 要方 方向 向无 无关 关三 维组 织概 概率 均 匀 假 定 各 扫 对 每 一 具 有 相 同 可 见 性 均匀 匀平 平均 均假 假定 定各 各扫 扫查 查组 组对 对每 每一 一类 别具 具有 有相 相同 同可 可见 见性 横 切 与横 横切 纵 纵切 遮 挡 限 野 不 符 遮挡 挡和 和有 有限 限视 视野 野条 件不 不符 此 为此 存 用 于 估 计 靠 别存 存在 在率 率用 用于 于估 估计 计扫 组的 的类 别可 可靠 靠性 设 设扫 含 帧 其 其中 现 帧出 出现 现类 则 把 率把 把各 对类 效 机 会 转 化 权 重 的有 有效 效观 测机 机会 会转 转化 化为 为融 合权 权重 减 少 未 该 小 结 构 稀 释 可减 减少 少未 未观 测该 该类 别的 的方 向对 对小 小结 结构 构概 率的 的稀 稀释 依 赖 待 位 置 该权 重不 不依 依赖 赖待 待查 询位 位置 仍 受 内 覆 盖 标 注 布 影 响 仍受 受组 组内 内覆 覆盖 盖和 和标 标注 注分 分布 布影 影响 当 前 统 消 只 评 价 预 当前 前统 统一 一消 消融 融只 只评 评价 价观 测平 面的 的条 件预 预测 因 本 保 留 上 述 作 制 因此 此本 本章 章保 保留 留上 上述 述融 合作 作为 为三 维输 出机 机制 据 主 张 已 经 获 得 语 义 量 优 势 不据 据此 此主 主张 张已 已经 经获 获得 得三 维语 语义 义定 定量 量优 优势 以 复以 以三 维针 体概 入 为输 输入 双 阈 值 迟 滞 先 高 双阈 阈值 值迟 迟滞 滞先 先以 以高 高阈 生 种 子 生成 成可 靠种 种子 再 低 再在 在低 低阈 下 连 通 候 选 下保 留与 与种 子连 连通 通的 的候 候选 集 集合 弱 但 续 应 复弱 弱但 但连 连续 续的 的针 体响 响应 时 排 除 孤 立 信 伪 同时 时排 排除 除孤 孤立 立低 低置 置信 信伪 伪影 被 划 选被 被划 划分 分为 个 碎 片 个碎 碎片 归 先在 在碎 片内 内归 归一 一化 化权 避 免 大 完 全 支 配 避免 免大 大碎 片完 完全 全支 支配 配方 向估 局 加 稳 健 拟 全局 局概 率加 加权 权稳 稳健 健拟 拟合 衡 次 增 规 模 校 正 持 片均 均衡 衡稳 合和 和双 滞碎 片恢 复依 依次 次增 增加 加碎 片规 规模 模校 校正 正与 与弱 弱连 续支 支持 轴 线 轴线 过 通过 初 始 初始 始化 化和 迭 代 迭代 代重 重加 权估 将 投 到 将候 选投 投影 影到 以概 数 确 段 端 点 分位 位数 数确 确定 定有 限线 线段 段端 端点 降 离 群 长 度 降低 低少 少量 量轴 轴向 向离 离群 群点 点对 对长 长度 度的 的影', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f77b65d7e9bc4b4176da75c7708f7be4f0b61087df8bd36cabc31c1016fdf3d3') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_v