INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d1ac6ac8c5a6fc53', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析', '本节在统一平台和数据划分下对第4.3　—4.5　 节的理论预期进行后验检验。实验依次评价输入域规范化、二维多任务观测、多视角条件语义场和针体几何恢复。二维区域指标、针体概率指标与三维几何指标对应不同任务对象，分析时分别说明理论预测获得支持、仅获部分支持或被实验修正的部分。', '4.3 4.5 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 本 节 统 一 平 台 数 据 划 下 对 本节 节在 在统 统一 一平 平台 台和 和数 数据 据划 划分 分下 下对 对第 理 论 预 期 进 行 后 检 节的 的理 理论 论预 预期 期进 进行 行后 后验 验检 检验 依 次 评 价 输 入 域 规 范 化 验依 依次 次评 评价 价输 输入 入域 域规 规范 范化 二 任 务 二维 维多 多任 任务 务观 条 件 场 体 角条 条件 件语 义场 场和 和针 针体 体几 区 指 标 维区 区域 域指 指标 概 率 应 不 同 象 体概 概率 率指 标与 与三 维几 何指 标对 对应 应不 不同 同任 务对 对象 时 别 说 明 获 得 支 持 析时 时分 分别 别说 说明 明理 预测 测获 获得 得支 支持 仅 部 或 被 修 正 仅获 获部 部分 分支 持或 或被 被实 验修 修正 正的 的部', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd1ac6ac8c5a6fc53ec1e7e5db9661bae67d4ae6ba9462fc829c3239e3fd30777') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-bc15b15b950a0d80', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 甲状腺二维/三维语义分割与针体几何恢复的实验设置与评价 / 实验平台与数据集', '实验运行于Linux、Python 3.10.14、PyTorch 2.7.1和CUDA 12.8环境，主要计算设备为单张NVIDIA GeForce RTX 5090 GPU。评价按输入域规范化、低数据二维语义、多视角条件语义场和针体几何恢复四个层次组织。
输入域规范化采用 TN3K 和 DDTI 甲状腺结节超声数据；低数据二维语义观测使用 4.4.6 节建立的多源部分标注体系，其当前规范化数据池为 55,308/10,623 帧训练/验证图像，训练采用轮换步长动态下采样，验证采用固定步长。PVA-Phantom 四类二维监督及其带位姿多视角序列分别用于结构一致性、三维语义场与针体几何实验；NeckScan 用于补充甲状腺—血管联合外观。二维帧经探头标定、同步位姿和第 3 章多扫查配准映射到规范空间，三维解剖与针体几何标定结果直接作为 GT。', 'linux python 3.10.14 pytorch 2.7.1 cuda 12.8 nvidia geforce rtx 5090 gpu tn3k ddti 4.4.6 55 308 10 623 pva-phantom neckscan gt 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 二 腺二 二维 体 设 置 评 价 与针 针体 体几 复的 的实 验设 设置 置与 与评 评价 平 台 数 据 集 验平 平台 台与 与数 数据 据集 运 行 于 验运 运行 行于 环 境 环境 主 要 计 算 备 单 张 主要 要计 计算 算设 设备 备为 为单 单张 按 输 入 域 规 范 化 价按 按输 输入 入域 域规 规范 范化 低 低数 据二 条 件 场 四 个 层 次 角条 条件 件语 义场 场和 和针 复四 四个 个层 层次 次组 采 用 化采 采用 节 超 声 腺结 结节 节超 超声 声数 使 义观 测使 使用 建 立 源 部 标 注 系 节建 建立 立的 的多 多源 源部 部分 分标 标注 注体 体系 其 当 前 池 其当 当前 前规 化数 据池 池为 帧 训 练 帧训 训练 证 图 像 验证 证图 图像 轮 换 步 长 动 态 下 样 练采 用轮 轮换 换步 步长 长动 动态 态下 下采 采样 固 定 证采 用固 固定 定步 类 监 督 带 位 姿 序 列 别 构 一 致 性 四类 类二 维监 监督 督及 及其 其带 带位 位姿 姿多 角序 序列 列分 分别 别用 用于 于结 结构 构一 一致 致性 场与 何实 补 充 于补 补充 充甲 血 管 联 合 外 血管 管联 联合 合外 外观 经 探 头 维帧 帧经 经探 探头 头标 标定 同 同步 步位 姿和 和第 扫 查 配 准 映 射 到 空 间 章多 多扫 扫查 查配 配准 准映 映射 射到 到规 范空 空间 解 剖 直 接 作 维解 解剖 剖与 何标 定结 果直 直接 接作 作为', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'bc15b15b950a0d809ab29db724d55cb3ac9a16bdf80b400896a02d7c9fe05658') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b6c68594e2f05cce', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 甲状腺二维/三维语义分割与针体几何恢复的实验设置与评价 / 实验设置', '多视角条件语义场消融统一使用256帧训练子集，完成20轮数据遍历，随机种子设为0。所有设置在相同的484幅图像上评价，其中49幅含针、435幅无针；纳入分析的11组运行均正常完成并具有一致的指标定义。体素概率融合无需神经场反向优化，其余方法进行连续场参数更新。比较以相同训练数据、数据遍历轮数和评价集合为基础，不把参数更新次数差异解释为某一组件的独立效应。
消融按三个问题分组：连续表示、成像条件与重叠语义建模；类别重加权与重叠优化；软管状目标、难负样本与拓扑连续性约束。该组织只比较相邻设置中明确变化的组件，不把目标不同的方法排列成单调改进链。针体几何评价沿用已经完成的概率场与阈值设置。', '256 20 484 49 435 11 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 二 腺二 二维 体 设 置 评 价 与针 针体 体几 复的 的实 验设 设置 置与 与评 评价 条 件 场 消 融 统 一 使 用 角条 条件 件语 义场 场消 消融 融统 统一 一使 使用 帧 训 练 子 集 帧训 训练 练子 子集 完 成 完成 轮 数 据 遍 历 轮数 数据 据遍 遍历 随 机 种 随机 机种 种子 子设 设为 所 有 相 同 所有 有设 置在 在相 相同 同的 幅 图 像 上 幅图 图像 像上 上评 其 其中 含 幅含 含针 无 幅无 无针 纳 入 纳入 入分 析的 运 行 均 正 常 并 具 致 指 标 定 组运 运行 行均 均正 正常 常完 成并 并具 具有 有一 一致 致的 的指 指标 标定 定义 素 概 率 合 需 神 经 反 优 化 体素 素概 概率 率融 融合 合无 无需 需神 神经 经场 场反 反向 向优 优化 余 方 法 进 连 续 参 更 新 其余 余方 方法 法进 进行 行连 连续 续场 场参 参数 数更 更新 比 较 以 比较 较以 以相 同训 练数 基 础 历轮 数和 和评 价集 集合 合为 为基 基础 不 把 次 差 异 解 释 某 独 立 效 应 不把 把参 新次 次数 数差 差异 异解 解释 释为 为某 某一 一组 组件 件的 的独 独立 立效 效应 按 个 问 题 融按 按三 三个 个问 问题 题分 分组 表 示 续表 表示 重 叠 建 模 成像 像条 件与 与重 重叠 叠语 义建 建模 类 别 加 权 类别 别重 重加 加权 权与 叠优 软 管 目 软管 管状 状目 目标 难 负 样 本 拓 扑 性 约 束 难负 负样 样本 本与 与拓 拓扑 扑连 续性 性约 约束 该 只 邻 明 确 变 该组 织只 只比 较相 相邻 邻设 置中 中明 明确 确变 变化 化的 的组 排 列 单 调 改 链 把目 标不 不同 的方 法排 排列 列成 成单 单调 调改 改进 进链 沿 已 阈 值 何评 价沿 沿用 用已 已经 经完 成的 的概 率场 场与 与阈 阈值 值设', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b6c68594e2f05ccefa92341364fc9cb30d119d2d5d886104ffeacbb783314f50') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-97bce0f828f3cdac', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 甲状腺二维/三维语义分割与针体几何恢复的实验设置与评价 / 评估指标', '二维区域评价采用Dice、IoU、Precision和Recall。对评价图像i的有效区域Ω_i，预测与GT分别记为P_i^c和G_i^c，则：
四类mDice为甲状腺、结节、血管和针体Dice的算术平均，解剖宏平均Dice只汇总前三类：
针体极度稀疏，单一图像平均值不足以描述实际行为。设𝕀^+和𝕀^−分别为含针与无针图像集合，同时报告含针图像平均Dice、数据集汇总Dice、无针图像假阳性率和含针图像检出率：
固定工作阈值0.5用于区域、误检和检出指标；AUPRC=∫_0^1Precision(Recall)dRecall用于评价阈值无关的概率排序。最优Dice及相应阈值只用于辅助解释，不替代固定工作点结论。针体几何评价包括候选有效性、轴线角度差、针尖端点相对GT的差异、线段长度差、轴向覆盖率、最大无支撑间隔和对称中心线距离。', 'dice iou precision recall gt mdice 0.5 auprc 1precision drecall 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 二 腺二 二维 体 设 置 评 价 与针 针体 体几 复的 的实 验设 设置 置与 与评 评价 估 指 标 评估 估指 指标 区 域 采 用 维区 区域 域评 价采 采用 对 图 像 对评 价图 图像 有 效 的有 有效 效区 预 预测 测与 别 记 分别 别记 记为 则 四 类 四类 为甲 节 结节 血 管 血管 管和 和针 算 术 平 均 的算 算术 术平 平均 解 剖 宏 解剖 剖宏 宏平 只 汇 总 前 只汇 汇总 总前 前三 三类 极 度 稀 疏 体极 极度 度稀 稀疏 单 一 值 不 足 以 描 述 际 行 单一 一图 像平 均值 值不 不足 足以 以描 描述 述实 实际 际行 行为 含 无 集 合 别为 为含 含针 针与 与无 无针 针图 像集 集合 同 时 报 告 同时 时报 报告 告含 数 据 数据 据集 集汇 假 阳 性 率 检 出 像假 假阳 阳性 性率 率和 和含 像检 检出 出率 固 定 工 作 阈 固定 定工 工作 作阈 阈值 于 用于 于区 误 误检 检和 和检 出指 关 概 排 序 于评 价阈 值无 无关 关的 的概 概率 率排 排序 最 优 最优 相 应 辅 助 释 及相 相应 应阈 值只 只用 于辅 辅助 助解 解释 替 代 点 论 不替 替代 代固 作点 点结 结论 包 括 候 选 何评 价包 包括 括候 候选 选有 效性 轴 线 差 轴线 线角 角度 度差 尖 端 针尖 尖端 端点 点相 相对 异 的差 差异 段 长 线段 段长 长度 覆 盖 轴向 向覆 覆盖 盖率 大 支 撑 间 隔 称 心 距 离 最大 大无 无支 支撑 撑间 间隔 隔和 和对 对称 称中 中心 心线 线距 距离', '/#research', 'doctoral-thesis', 1, '2026-08-04', '97bce0f828f3cdacf7123390e8165423e42e78290e9a9b43d314138ecaab3460') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0aa3d550274b1d58', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 输入域规范化实验与结果分析', '本节评价第4.3　节的输入域规范化假设，量化依据为甲状腺结节分割数据[129–132]。EIDC作为完整数据条件作用于多个分割前端，结论限定于二维结节概率观测，不扩展到缺少同层级对照的针体分割、几何后处理或独立图像复原网络。
实验比较EIDC与B-mode基线在TN3K内部测试和DDTI外部测试上的Dice、IoU、Precision和Recall。总体变化用于评价输入观测稳定性，个别模型的Precision/Recall差异用于分析阈值与预测范围的权衡。
表 .5 TN3K 内部测试中 B-mode 与 EIDC 的分割结果对比
Table . TN3K internal-test comparison between B-mode and EIDC.
表 4.5 支持 4.3　 节的主要预期。在 TN3K 内部测试中，EIDC 对 7 个模型中的 6 个提升 Dice 和 IoU，平均 ΔDice 为 0.0403，平均 ΔIoU 为 0.0464；Recall 在 7 个模型中全部提升，Precision 在 6 个模型中提升。这说明规范回声强度代理表征并非只适配某一个网络，而是在多数前端上同时改善结节区域覆盖和区域重叠质量。例外也有解释价值：TRFE-Net 的 Dice 和 IoU 下降，但 Recall 上升 0.0515、Precision 下降 0.0782，说明该模型在 EIDC 条件下更倾向于扩大预测区域；因此不能只按单一 Dice 排名，而应结合 Precision 与 Recall 判断预测形态和阈值校准需求。', '4.3 129 132 eidc b-mode tn3k ddti dice iou precision recall table internal-test comparison between and eidc. 4.5 0.0403 0.0464 trfe-net 0.0515 0.0782 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 输 入 域 规 范 化 输入 入域 域规 规范 范化 化实 验与 与结 果分 本 节 评 价 本节 节评 评价 价第 假 设 节的 的输 化假 假设 量 依 据 数 量化 化依 依据 据为 为甲 腺结 结节 节分 割数 数据 作 完 整 条 件 用 于 个 前 端 作为 为完 完整 整数 据条 条件 件作 作用 用于 于多 多个 个分 割前 前端 论 限 定 二 概 率 结论 论限 限定 定于 于二 二维 维结 节概 概率 率观 不 扩 展 到 缺 少 同 层 级 对 照 体 不扩 扩展 展到 到缺 缺少 少同 同层 层级 级对 对照 照的 的针 针体 体分 后 处 理 或 独 立 图 像 原 网 络 何后 后处 处理 理或 或独 独立 立图 图像 像复 复原 原网 网络 比 较 验比 比较 基 线 基线 线在 内 部 试 内部 部测 测试 试和 外 上 外部 试上 上的 总 变 稳 性 总体 体变 变化 化用 于评 价输 入观 测稳 稳定 定性 别 模 型 个别 别模 模型 型的 差 异 阈 值 预 围 权 衡 差异 异用 于分 析阈 阈值 值与 与预 预测 测范 范围 围的 的权 权衡 表 试中 的分 割结 果对 对比 支 持 支持 主 要 期 的主 主要 要预 预期 个模 型中 中的 提 升 个提 提升 平 均 平均 全 中全 全部 部提 中提 这 说 明 回 声 强 度 代 征 并 非 只 适 配 某 一 这说 说明 明规 范回 回声 声强 强度 度代 代理 理表 表征 征并 并非 非只 只适 适配 配某 某一 一个 个网 而 时 改 善 区 覆 盖 重 叠 质 而是 是在 在多 多数 数前 端上 上同 同时 时改 改善 善结 节区 区域 域覆 覆盖 盖和 和区 域重 重叠 叠质 质量 例 也 有 解 释 例外 外也 也有 有解 解释 释价 价值 下 降 下降 但 上升 该 明该 该模 型在 更 倾 大 件下 下更 更倾 倾向 向于 于扩 扩大 大预 测区 因 此 能 按 单 因此 此不 不能 能只 只按 按单 单一 排 名 排名 应 合 而应 应结 结合 判 断 形 态 校 准 需 求 判断 断预 测形 形态 态和 和阈 值校 校准 准需 需求', '/#research', 'doctoral-thesis', 1, '2026-08-04', '0aa3d550274b1d586142dd214ab1168837da43bcc5a3c3c3d29be344a8166532') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level