INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6f5232f1701c8d32', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 输入域规范化实验与结果分析', '但 Recall 上升 0.0515、Precision 下降 0.0782，说明该模型在 EIDC 条件下更倾向于扩大预测区域；因此不能只按单一 Dice 排名，而应结合 Precision 与 Recall 判断预测形态和阈值校准需求。
