INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-078b9f4820326c77', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 输入域规范化实验与结果分析', '4 EIDC 输入域规范化的定性对比与 Dice 增益汇总
Figure . Qualitative comparison and Dice-gain summary for EIDC input-domain normalization.
图4.14补充表 4.5至表 4.7的定量比较。图4.14(a)中，代表性TN3K样本经EIDC处理后重叠更充分、边界偏移减小，平均Dice增益为0.058；图4.14(b)显示，TN3K与DDTI上均有6/7个模型获得正向增益。TRFE-Net在内部测试下降、DeepLabV3+在外部测试轻微下降，说明收益仍受架构与阈值校准影响。结合表 4.5至表 4.7，EIDC改善的是多数二维前端的输入稳定性，并非无条件提高所有模型。
实验比较直接B-mode训练与完整EIDC条件，未将成像响应建模和采集条件模拟增强拆分为独立消融。因此，结果支持图像域响应补偿与超声采集条件模拟的联合效应，不能分离单个算子的因果贡献。
从三维语义神经场角度看，EIDC的意义不止是二维Dice数值提高。更稳定的二维概率图可以减少多视角监督中的孤立伪目标，使映射到规范空间的组织概率观测更一致；边界更稳定的甲状腺和结节预测也有利于连续语义场和空间关系计算。4.6.4　 节的三维组织GT评价表明，更稳定的二维条件后验并不自动转化为更优的方向无关三维后验；因此，本节结果只支持输入观测稳定性，不被直接外推为三维导航性能。', 'eidc dice figure qualitative comparison and dice-gain summary for input-domain normalization. 4.14 4.5 4.7 tn3k 0.058 ddti trfe-net deeplabv3+ b-mode 4.6.4 gt 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 输 入 域 规 范 化 输入 入域 域规 规范 范化 化实 验与 与结 果分 定 性 对 比 化的 的定 定性 性对 对比 比与 增 益 汇 总 增益 益汇 汇总 图 补 充 表 补充 充表 至 至表 量 较 定量 量比 比较 代 代表 表性 样 本 经 样本 本经 处 理 后 重 叠 更 处理 理后 后重 重叠 叠更 更充 充分 边 界 偏 移 减 小 边界 界偏 偏移 移减 减小 平 均 平均 益为 显 示 显示 上 有 上均 均有 个 模 型 获 得 正 个模 模型 型获 获得 得正 正向 向增 内 部 试 下 降 在内 内部 部测 测试 试下 下降 外 轻 微 在外 外部 试轻 轻微 微下 说 明 收 仍 受 架 构 阈 值 校 准 影 响 说明 明收 收益 益仍 仍受 受架 架构 构与 与阈 阈值 值校 校准 准影 影响 合 结合 合表 改 善 数 二 前 端 稳 改善 善的 的是 是多 多数 数二 二维 维前 前端 端的 的输 入稳 稳定 并 非 无 条 件 提 高 所 并非 非无 无条 条件 件提 提高 高所 所有 有模 直 接 验比 较直 直接 训 练 完 整 训练 练与 与完 完整 未 将 成 像 应 建 采 集 拟 强 拆 独 立 消 融 未将 将成 成像 像响 响应 应建 建模 模和 和采 采集 集条 件模 模拟 拟增 增强 强拆 拆分 分为 为独 独立 立消 消融 因 此 因此 支 持 偿 超 声 联 效 果支 支持 持图 图像 像域 域响 应补 补偿 偿与 与超 超声 声采 拟的 的联 联合 合效 效应 不 能 离 单 算 子 贡 献 不能 能分 分离 离单 单个 个算 算子 子的 的因 因果 果贡 贡献 从 神 场 度 看 从三 义神 神经 经场 场角 角度 度看 意 止 的意 意义 义不 不止 止是 是二 数值 值提 概 率 可 以 少 监 督 孤 伪 目 标 更稳 定的 的二 维概 概率 率图 图可 可以 以减 减少 少多 角监 监督 督中 中的 的孤 孤立 立伪 伪目 目标 使 映 射 到 空 间 一 致 使映 映射 射到 到规 范空 空间 间的 的组 织概 率观 测更 更一 一致 节 预 也 利 于 连 续 关 系 计 界更 的甲 腺和 和结 结节 节预 预测 测也 也有 有利 利于 于连 连续 续语 义场 场和 和空 间关 关系 系计 计算 节的 维组 评 价 评价 价表 表明 自 动 转 优 方 维条 件后 后验 验并 并不 不自 自动 动转 转化 化为 为更 更优 优的 的方 方向 向无 无关 关三 维后 只 本节 节结 果只 只支 持输 入观 测稳 被 推 导 航 不被 被直 接外 外推 推为 为三 维导 导航 航性 性能', '/#research', 'doctoral-thesis', 1, '2026-08-04', '078b9f4820326c77eaeebcf41f60de8b792fa1a8815173032c4f33de9a99c04a') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, 