INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-a62a63a2c01efe52', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 可解释多任务二维语义观测机制实验与结果分析', '实验对应4.4　节的两类机制：多数据集低标注实验评价表征迁移与冻结教师语义引导，假体实验评价结构化解剖几何约束对区域指标和结构违反率的影响。两类实验分别回答低数据学习与解剖一致性问题，不将接口兼容性解释为实证性能。
Dice和IoU用于评价预测区域与真实区域的整体重叠，HD95和ASD用于评价边界定位误差，两类指标分别刻画区域一致性与边界长尾偏差。设预测区域和真实区域分别为P和G，对应边界点集为∂P和∂G，则双向边界距离集合定义为：
其中，Q0.95(·)表示经验距离分布的95%分位数。为将像素距离转换为具有导航意义的物理距离，设评价网格横、纵方向的等效像素间距分别为sx和sy，边界点p=(up,vp)与q=(uq,vq)之间的物理距离为：
该定义覆盖各向异性空间采样。本实验的W&B配置采用224×224评价网格，并按统一标定取sx=sy=0.09 mm/px，因此像素HD95与物理HD95之间满足：
因此，Dice、IoU、Precision和Recall等越大越好的指标用于检验区域识别，HD95、ASD及结构违反率V等越小越好的指标用于检验边界与结构可靠性。若结构化解剖几何约束仅提高区域指标而未降低结构违反率，则不能据此判定结构约束有效；若结构违反率显著下降而Dice提升有限，则说明几何先验主要发挥结构修正作用，而非单纯扩大预测区域。', '4.4 dice iou hd95 asd q0.95 95 sx sy up vp uq vq 224 0.09 mm px precision recall 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 可 解 释 任 务 二 机 制 可解 解释 释多 多任 任务 务二 二维 义观 测机 机制 制实 验与 与结 果分 对 应 验对 对应 节 两 类 节的 的两 两类 类机 数 据 集 低 标 注 评 价 表 征 迁 移 冻 教 师 引 导 多数 数据 据集 集低 低标 标注 注实 验评 评价 价表 表征 征迁 迁移 移与 与冻 冻结 结教 教师 师语 义引 引导 假 体 构 化 剖 约 束 区 域 指 违 反 率 影 响 假体 体实 价结 结构 构化 化解 解剖 剖几 何约 约束 束对 对区 区域 域指 指标 标和 和结 构违 违反 反率 率的 的影 影响 别 回 答 学 习 一 致 性 问 题 类实 验分 分别 别回 回答 答低 低数 据学 学习 习与 与解 剖一 一致 致性 性问 问题 不 将 接 口 兼 容 证 能 不将 将接 接口 口兼 兼容 容性 性解 释为 为实 实证 证性 性能 用 于 预 真 整 重 叠 用于 于评 价预 预测 测区 域与 与真 真实 实区 域的 的整 整体 体重 重叠 边 界 定 位 误 差 价边 边界 界定 定位 位误 误差 刻 画 长 尾 偏 类指 标分 别刻 刻画 画区 域一 性与 与边 界长 长尾 尾偏 偏差 设 设预 域和 和真 域分 别为 点 应边 界点 点集 集为 则 双 距 离 合 则双 双向 向边 界距 距离 离集 集合 合定 定义 义为 其 其中 示 经 布 表示 示经 经验 验距 离分 分布 布的 分位 位数 像 素 转 换 具 有 航 意 物 理 为将 将像 像素 素距 离转 转换 换为 为具 具有 有导 导航 航意 意义 义的 的物 物理 理距 网 格 横 设评 价网 网格 格横 纵 方 等 效 间 纵方 方向 向的 的等 等效 效像 素间 间距 距分 之 之间 间的 离为 该 覆 盖 各 异 空 采 样 该定 义覆 覆盖 盖各 各向 向异 异性 性空 空间 间采 采样 本 本实 验的 配 置 配置 置采 采用 并 按 统 取 并按 按统 统一 一标 标定 定取 因 此 因此 此像 与物 满 足 间满 满足 越 大 好 检 识 等越 越大 大越 越好 好的 的指 标用 于检 检验 验区 域识 识别 及结 小 靠 越小 小越 验边 界与 构可 可靠 靠性 若 仅 提 高 而 未 降 若结 束仅 仅提 提高 高区 标而 而未 未降 降低 低结 判 则不 不能 能据 据此 此判 判定 定结 构约 束有 有效 显 著 下 率显 显著 著下 下降 降而 升 限 提升 升有 有限 说 明 先 主 要 发 挥 修 正 作 则说 说明 明几 何先 先验 验主 主要 要发 发挥 挥结 构修 修正 正作 作用 非 单 纯 扩 而非 非单 单纯 纯扩 扩大 大预', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'a62a63a2c01efe52e9e62e6aee11771cb8cad9354c7055314c8cea5e66a7b3ac') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=exclu