INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1c3f0960dd940bc1', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 可解释多任务二维语义观测机制实验与结果分析', '12个类别—标注比例组合中有9个Dice提高，平均目标类别Dice由0.8133提高至0.8474，增量为0.0341；改善主要集中在血管和穿刺针。该结果支持稳定源语义对目标解码的条件化作用，但不构成统计显著性结论[79,136,192]。
表 4.8进一步表明，表征迁移相对目标低标注基线在12个组合中的8个降低了HD95，但平均HD95由21.461 px（1.932 mm）变为21.779 px（1.960 mm）。该均值退化主要受血管5%标注组合由21.397 px增至46.350 px影响，与Dice结果共同说明源任务表征并不必然改善目标类别的边界定位。
在表征迁移基础上加入CBAM语义引导后，10/12个组合的HD95下降，平均值由21.779 px（1.960 mm）降至14.416 px（1.297 mm），减少7.362 px（0.663 mm），相对降幅为33.8%。其中，血管5%和穿刺针5%标注组合分别由4.171 mm降至1.613 mm、由4.402 mm降至1.476 mm，表明语义引导对稀疏细长目标的离散远端误差具有较强抑制作用。甲状腺5%和结节10%组合分别增加0.092 mm和0.021 mm，说明该改善仍具有任务依赖性。', '12 dice 0.8133 0.8474 0.0341 79 136 192 4.8 hd95 21.461 px 1.932 mm 21.779 1.960 21.397 46.350 cbam 10 14.416 1.297 7.362 0.663 33.8 4.171 1.613 4.402 1.476 0.092 0.021 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 可 解 释 任 务 二 机 制 可解 解释 释多 多任 任务 务二 二维 义观 测机 机制 制实 验与 与结 果分 个 类 别 个类 类别 标 注 比 例 合 有 标注 注比 比例 例组 组合 合中 中有 提 高 提高 平 均 目 平均 均目 目标 标类 由 至 高至 增 量 增量 量为 改 善 主 要 集 血 管 改善 善主 主要 要集 集中 中在 在血 血管 管和 和穿 该 支 持 稳 定 源 对 码 条 件 化 作 用 该结 果支 支持 持稳 稳定 定源 源语 义对 对目 标解 解码 码的 的条 条件 件化 化作 作用 但 不 构 成 统 计 显 著 性 论 但不 不构 构成 成统 统计 计显 显著 著性 性结 结论 表 进 一 步 明 进一 一步 步表 表明 征 迁 移 相 低 基 线 表征 征迁 迁移 移相 相对 标低 低标 注基 基线 线在 个组 中的 降 个降 降低 低了 但平 变 变为 值 退 受 该均 均值 值退 退化 化主 要受 受血 注组 合由 增至 影 响 影响 共 同 说 并 必 然 边 界 位 果共 共同 同说 说明 明源 源任 务表 征并 并不 不必 必然 然改 善目 别的 的边 边界 界定 定位 础 上 加 入 在表 移基 基础 础上 上加 加入 引 导 后 义引 引导 导后 合的 下 下降 值由 降至 减 少 减少 幅 对降 降幅 幅为 其 其中 合分 分别 别由 稀 疏 细 长 离 散 远 端 误 差 具 较 强 抑 明语 导对 对稀 稀疏 疏细 细长 长目 标的 的离 离散 散远 远端 端误 误差 差具 具有 有较 较强 强抑 抑制 制作 节 和结 结节 别增 增加 仍 依 赖 明该 该改 善仍 仍具 有任 务依 依赖 赖性', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1c3f0960dd940bc1553248250b21fe1b288630b9b1c6bad05c18a113fc612156') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e1423bbc3cc53625', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 可解释多任务二维语义观测机制实验与结果分析', '分别由4.171 mm降至1.613 mm、由4.402 mm降至1.476 mm，表明语义引导对稀疏细长目标的离散远端误差具有较强抑制作用。甲状腺5%和结节10%组合分别增加0.092 mm和0.021 mm，说明该改善仍具有任务依赖性。
图4.15按与表 4.8至表 4.10一致的Dice排序选取样本，比较低标注基线、表征迁移与CBAM语义引导的预测形态；总体判断以定量结果为准。
图 4.15 低数据小样本泛化的验证集预测可视化示例
Figure . Validation prediction examples under the low-data few-shot generalization setting.
图4.15所示样本中，CBAM引导对结节和甲状腺主要修正边界范围，对血管表现为局部边界调整，对针体则减少离散响应并改善连续性。由于样本按表 4.8至表 4.10的Dice排序选取，这些观察仅解释平均指标对应的形态变化，不用于证明四类目标均普遍改善[125,133,199]。
表 .9 低数据训练早期收敛原始结果
