INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-255fa6743e80478e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 多视角语义场的二维观测域消融实验与结果分析', '.3476，含针检出率则降至0.8776。加入clDice后，AUPRC提高至0.2501、汇总Dice提高至0.3552、平均假阳性像素降至27.22，但检出率进一步降至0.8367。结果表明误检抑制和概率排序改善伴随固定阈值灵敏度下降。
三组消融分别对应表示误差、类别梯度、概率排序和固定阈值检出。Focal–Dice更适合总体区域重叠，拓扑约束更有利于针体概率排序；二者不能合并为无条件最优设置。比较仅来自同一随机种子，不解释为总体统计显著性。
