INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-cdf1187f9ec095b8', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 多视角语义场的二维观测域消融实验与结果分析', '.6406：软管状监督基本保持原响应，难负样本抑制减少横向扩张，拓扑连续性约束补充轴向支持。样例B的对应值为0.0672、0.0033、0.1266和0.0942，软目标使细弱响应消失，难负样本阶段恢复主要针段，拓扑约束后局部重叠再次下降。
图 4.19不承担逐样本单调性证明。两例仅用于说明表 4.14中的条件性收益：难负样本抑制主要降低高置信误检，拓扑约束改善汇总重叠和概率排序，而单幅图像的固定阈值重叠仍可能下降。', '6406 0.0672 0.0033 0.1266 0.0942 4.19 4.14 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 场 二 域 消 融 角语 义场 场的 的二 二维 维观 测域 域消 消融 融实 验与 与结 果分 软 管 监 督 基 本 保 持 原 响 应 软管 管状 状监 监督 督基 基本 本保 保持 持原 原响 响应 难 负 样 抑 制 减 少 横 扩 张 难负 负样 样本 本抑 抑制 制减 减少 少横 横向 向扩 扩张 拓 扑 连 续 性 约 束 补 充 轴 支 拓扑 扑连 连续 续性 性约 约束 束补 补充 充轴 轴向 向支 支持 例 样例 对 值 的对 对应 应值 值为 目 标 使 细 弱 失 软目 目标 标使 使细 细弱 弱响 应消 消失 阶 段 主 要 本阶 阶段 段恢 复主 主要 要针 针段 后 局 部 重 叠 再 次 下 降 扑约 束后 后局 局部 部重 重叠 叠再 再次 次下 下降 图 不 承 担 逐 单 调 证 明 不承 承担 担逐 逐样 本单 单调 调性 性证 证明 两 仅 用 于 说 表 两例 例仅 仅用 用于 于说 说明 明表 条 件 收 益 中的 的条 条件 件性 性收 收益 低 高 置 信 误 检 制主 要降 降低 低高 高置 置信 信误 误检 改 善 汇 总 概 率 排 序 束改 改善 善汇 汇总 总重 叠和 和概 概率 率排 排序 而 幅 像 固 定 阈 仍 可 能 而单 单幅 幅图 图像 像的 的固 固定 定阈 阈值 值重 叠仍 仍可 可能 能下', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'cdf1187f9ec095b8fb375e4b629e559f4056b93234011f116880052a164dddd4') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-1fac379db850a7ad', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 穿刺针三维几何恢复实验与结果分析', '针体三维几何恢复实验检验两个问题：在相同针体概率场上，碎片处理与稳健估计能否改善轴线和有限线段恢复；双阈值迟滞碎片方法能否在不同工作阈值下保持稳定几何。三维针体几何标定结果直接作为GT。
表 .15 三种针体几何恢复方法的GT评价结果
Table . GT-based evaluation of three needle-geometry recovery methods.
表 4.15显示，全局概率加权稳健拟合将轴线角度差控制在0.191°，但覆盖率为0.9270，仍存在1.7520 mm最大无支撑间隔。碎片均衡后轴线角度差降至0.100°，对称中心线距离由0.3429 mm降至0.3327 mm，覆盖率基本不变，说明碎片内权重归一化削弱了大碎片对方向估计的支配，却不能恢复阈值筛选时丢失的轴向支持。
双阈值迟滞碎片恢复以高置信种子约束低阈值连通扩展，使覆盖率达到1、最大无支撑间隔降为0，对称中心线距离进一步降至0.3225 mm；其轴线、端点和长度均与GT一致。结果支持稳健拟合抑制离群点、碎片均衡校正规模偏置、迟滞恢复补充弱连续证据的机制分析。
表 .16 双阈值迟滞碎片恢复的GT阈值稳定性
Table . GT-based threshold stability of hysteresis fragment recovery.', 'gt 15 table gt-based evaluation of three needle-geometry recovery methods. 4.15 0.191 0.9270 1.7520 mm 0.100 0.3429 0.3327 0.3225 16 threshold stability hysteresis fragment recovery. 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 针三 维几 验与 与结 果分 体 检 两 个 问 题 针体 体三 验检 检验 验两 两个 个问 问题 相 同 概 率 场 上 在相 相同 同针 体概 概率 率场 场上 碎 片 处 理 稳 健 估 计 能 否 改 善 轴 线 有 限 段 碎片 片处 处理 理与 与稳 稳健 健估 估计 计能 能否 否改 改善 善轴 轴线 线和 和有 有限 限线 线段 段恢 双 阈 值 迟 滞 方 法 不 工 作 下 保 持 定 双阈 阈值 值迟 迟滞 滞碎 片方 方法 法能 否在 在不 不同 同工 工作 作阈 值下 下保 保持 持稳 稳定 定几 标 直 接 维针 体几 何标 标定 定结 果直 直接 接作 作为 表 种 三种 种针 复方 法的 评 价 评价 价结 显 示 显示 全 局 加 权 拟 合 将 度 差 控 制 全局 局概 率加 加权 权稳 健拟 拟合 合将 将轴 线角 角度 度差 差控 控制 制在 但 覆 盖 但覆 覆盖 盖率 率为 仍 存 仍存 存在 最 大 无 支 撑 间 隔 最大 大无 无支 支撑 撑间 间隔 均 衡 后 降 至 片均 均衡 衡后 后轴 差降 降至 对 称 心 距 离 由 对称 称中 中心 心线 线距 距离 离由 基 本 变 率基 基本 本不 不变 说 明 内 重 归 一 化 削 弱 配 说明 明碎 片内 内权 权重 重归 归一 一化 化削 削弱 弱了 了大 大碎 片对 对方 方向 向估 计的 的支 支配 却 筛 选 时 丢 失 却不 不能 能恢 复阈 值筛 筛选 选时 时丢 丢失 失的 的轴 轴向 向支 支持 以 高 置 信 子 约 束 低 连 通 扩 展 片恢 复以 以高 高置 置信 信种 种子 子约 约束 束低 低阈 值连 连通 通扩 扩展 使 达 到 使覆 率达 达到 隔降 降为 进 步 离进 进一 一步 步降 其 其轴 端 点 长 端点 点和 和长 长度 度均 均与 致 一致 抑 群 果支 合抑 抑制 制离 离群 群点 校 正 规 模 偏 衡校 校正 正规 规模 模偏 偏置 补 充 续 证 据 机 滞恢 复补 补充 充弱 弱连 连续 续证 证据 据的 的机 机制 制分 复的 性 值稳 定性', '/#research', 'doctoral-thesis', 1, '2026-08-04', '1fac379db850a7ad4c2ccf30a68588dce71f24e4d49ac309b6735a2e219d5c41') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-6e017ee8e2423ba1', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 多视角三维语义分割与穿刺针几何恢复实验结果与分析 / 穿刺针三维几何恢复实验与结果分析', '均衡校正规模偏置、迟滞恢复补充弱连续证据的机制分析。
表 .16 双阈值迟滞碎片恢复的GT阈值稳定性
Table . GT-based threshold stability of hysteresis fragment recovery.
高阈值由0.075提高至0.125时，轴线角度差增加至0.522°，针尖端点相对GT的差异增加至0.389 mm，长度差增加至0.897 mm；三个阈值下覆盖率均为1，最大无支撑间隔均为0。阈值升高逐步剔除低置信端点证据并产生有限端点偏差，但未引起碎片断裂或方向翻转，表明该方法在当前阈值范围内保持轴向连续性。
图 .20 针体几何恢复的GT评价与阈值稳定性
Figure . GT-based evaluation and threshold stability of needle-geometry recovery.
图 4.20将表 4.15和表 4.16的既有结果按误差、完整性与阈值稳定性组织。方法对比说明迟滞碎片恢复消除了轴向空隙并获得完整覆盖；阈值对比说明工作点升高主要影响轴线角度差和针尖端点相对GT的差异，不改变轴向连续性。
本节完成二维针体占据、三维候选、稳健轴线、有限端点与GT评价的证据闭环。结论限定于现有假体数据和已完成实验，不外推为临床针尖定位精度，也不设置需要新增实验才能成立的结论。', '16 gt table gt-based threshold stability of hysteresis fragment recovery. 0.075 0.125 0.522 0.389 mm 0.897 20 figure evaluation and needle-geometry 4.20 4.15 4.16 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 语 义 实 验 结 果 析 角三 维语 语义 义分 复实 实验 验结 结果 果与 与分 分析 针三 维几 验与 与结 果分 均 衡 校 正 规 模 偏 置 均衡 衡校 校正 正规 规模 模偏 偏置 迟 滞 补 充 弱 连 续 证 据 机 制 迟滞 滞恢 复补 补充 充弱 弱连 连续 续证 证据 据的 的机 机制 制分 表 双 阈 值 碎 片 双阈 阈值 值迟 滞碎 碎片 片恢 复的 稳 定 性 值稳 稳定 定性 高 由 高阈 值由 提 至 提高 高至 时 轴 线 度 差 增 加 轴线 线角 角度 度差 差增 增加 加至 尖 端 点 相 对 针尖 尖端 端点 点相 相对 异 的差 差异 异增 长 长度 个 下 覆 盖 率 三个 个阈 值下 下覆 覆盖 盖率 率均 均为 最 大 无 支 撑 间 隔 最大 大无 无支 支撑 撑间 间隔 隔均 升 逐 步 剔 除 低 信 并 产 生 有 限 值升 升高 高逐 逐步 步剔 剔除 除低 低置 置信 信端 点证 据并 并产 产生 生有 有限 限端 点偏 偏差 但 未 引 起 断 裂 或 方 翻 转 但未 未引 引起 起碎 片断 断裂 裂或 或方 方向 向翻 翻转 明 该 法 当 前 范 围 内 保 持 表明 明该 该方 方法 法在 在当 当前 前阈 值范 范围 围内 内保 保持 持轴 轴向 向连 续性 图 体 针体 体几 评 价 评价 价与 与阈 将 将表 和表 既 按 误 的既 既有 有结 果按 按误 误差 完 整 完整 整性 性与 性组 比 说 消 空 隙 获 得 法对 对比 比说 说明 明迟 复消 消除 除了 了轴 向空 空隙 隙并 并获 获得 得完 整覆 工 作 主 要 影 响 值对 明工 工作 作点 点升 高主 主要 要影 影响 响轴 差和 和针 不 改 变 不改 改变 变轴 本 节 成 二 占 本节 节完 完成 成二 二维 维针 体占 占据 候 选 维候 候选 健 稳健 健轴 点与 闭 环 价的 的证 据闭 闭环 论 于 现 假 数 已 结论 论限 限定 定于 于现 现有 有假 假体 体数 数据 据和 和已 已完 成实 外 推 临 床 位 精 不外 外推 推为 为临 临床 床针 尖定 定位 位精 精度 也 设 需 新 才 能 立 也不 不设 设置 置需 需要 要新 新增 增实 验才 才能 能成 成立 立的 的结', '/#research', 'doctoral-thesis', 1, '2026-08-04', '6e017ee8e2423ba1767ac527cbe93720d54ed1e65478baf6763da5ce041a9e8e') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-ff785fbdc5ffe191', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第4章 面向多视角观测的三维甲状腺组织分割与穿刺针几何恢复 / 本章小结', '本章从甲状腺穿刺导航对靶区、风险结构和介入器械统一空间解释的需求出发，建立输入域规范化、多任务二维语义观测、连续条件语义场和针体几何恢复方法链。连续位置语义场处理离散写入，成像平面条件场解释方向相关观测，解剖—器械双分支消除重叠语义冲突；类别重加权与针体专项约束分别调节稀缺类别梯度、无针误检和中心线结构。
二维观测域消融表明，连续位置场主要改善强度连续性，成像平面条件是语义指标的主要增量来源。双分支为针体建立独立优化接口，但未直接提高总体Dice；类别重加权提高针体响应，同时增加无针误检风险。在当前设置下，Focal–Dice取得较好的总体重叠结果。
针体专项消融表明，难负样本抑制能够降低无针误检，clDice进一步改善AUPRC和汇总Dice，但固定阈值检出率下降。总体重叠、概率排序、无针特异性和检出率对应不同风险，不能相互替代。当前统一消融不含三维组织语义汇总量，因而不将三维类别感知融合写成已获定量验证的优越性结论。
针体几何恢复采用双阈值候选、碎片均衡、RANSAC–Huber轴线和加权分位端点。当前GT评价中，覆盖率为1、最大无支撑间隔为0；在0.075～0.125阈值范围内，最大轴线角度差为0.522°，最大针尖端点差异为0.389 mm。结论限于现有假体实验，不依赖新增实验。', 'dice focal cldice auprc ransac huber gt 0.075 0.125 0.522 0.389 mm 第 章 面 向 多 视 角 观 测 三 维 甲 状 腺 组 织 分 割 穿 刺 针 几 何 恢 复 面向 向多 多视 视角 角观 观测 测的 的三 三维 维甲 甲状 状腺 腺组 组织 织分 分割 割与 与穿 穿刺 刺针 针几 几何 何恢 恢复 本 小 结 本章 章小 小结 从 导 航 对 靶 区 章从 从甲 腺穿 刺导 导航 航对 对靶 靶区 风 险 构 介 入 器 械 统 一 空 间 解 释 需 求 出 发 风险 险结 结构 构和 和介 介入 入器 器械 械统 统一 一空 空间 间解 解释 释的 的需 需求 求出 出发 建 立 输 域 规 范 化 建立 立输 输入 入域 域规 规范 范化 任 务 二 语 义 多任 任务 务二 二维 维语 语义 义观 连 续 条 件 场 体 方 法 链 连续 续条 条件 件语 义场 场和 和针 针体 体几 复方 方法 法链 位 置 处 理 离 散 写 续位 位置 置语 场处 处理 理离 离散 散写 写入 成 像 平 相 关 成像 像平 平面 面条 件场 场解 释方 方向 向相 相关 关观 剖 解剖 双 支 消 除 重 叠 冲 突 械双 双分 分支 支消 消除 除重 重叠 叠语 义冲 冲突 类 别 加 权 专 项 约 束 调 节 稀 缺 梯 度 类别 别重 重加 加权 权与 与针 体专 专项 项约 约束 束分 分别 别调 调节 节稀 稀缺 缺类 别梯 梯度 无 误 检 心 线 无针 针误 误检 检和 和中 中心 心线 线结 融 表 明 维观 测域 域消 消融 融表 表明 主 要 改 善 强 性 置场 场主 主要 要改 改善 善强 强度 度连 续性 指 标 增 量 来 源 件是 是语 义指 指标 标的 的主 要增 增量 量来 来源 独 优 接 口 支为 为针 体建 立独 独立 立优 优化 化接 接口 但 未 直 提 高 总 但未 未直 直接 接提 提高 高总 总体 响 应 权提 高针 体响 响应 同 时 同时 时增 增加 加无 检风 当 前 设 下 在当 当前 前设 设置 置下 取 得 较 好 果 取得 得较 较好 好的 的总 体重 叠结 结果 项消 难 负 样 抑 制 能 够 降 低 难负 负样 样本 本抑 抑制 制能 能够 够降 降低 低无 进 步 进一 一步 步改 汇 和汇 汇总 固 定 阈 值 率 但固 固定 定阈 阈值 值检 检出 出率 率下 下降 概 排 序 概率 率排 排序 特 异 不 针特 特异 异性 性和 和检 率对 对应 应不 不同 同风 互 替 代 不能 能相 相互 互替 替代 含 前统 一消 融不 不含 含三 维组 织语 义汇 总量 因 而 将 感 知 合 已 获 验 证 越 论 因而 而不 不将 将三 维类 别感 感知 知融 融合 合写 写成 成已 已获 获定 定量 量验 验证 证的 的优 优越 越性 性结 结论 采 用 候 选 复采 采用 用双 双阈 值候 候选 碎 片 均 衡 碎片 片均 均衡 轴 端 点 轴线 线和 和加 权分 分位 位端 端点 评 价 评价 价中 覆 盖 覆盖 盖率 率为 最 大 撑 隔 最大 大无 无支 支撑 撑间 间隔 隔为 围 内 值范 范围 围内 差 大轴 线角 角度 度差 差为 尖 大针 针尖 尖端 点差 差异 异为 限 于 现 有 假 实 论限 限于 于现 现有 有假 假体 体实 实验 依 赖 新 不依 依赖 赖新 新增 增实', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'ff785fbdc5ffe191d083af4a7bc9d7068a02c3ae58efb2aefad33820a2d31c3d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_lev