INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-53a4fb2f0fa36de7', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 引言', '第2—4章依次建立了物理一致三维重建、多次扫查空间统一和组织—器械语义建模方法。本章将这些方法置于同一甲状腺假体、外部定位和器械标定链路中，考察算法输出能否获得一致的物理坐标、明确的数据来源和可追溯的模块级评价。
本章验证分为三个层次：硬件与坐标层连接图像平面、探头、定位世界坐标和器械工作点；算法与数据层组织有效观测、二维概率、修正位姿、三维场和针体几何；证据层将输入条件、中间量、输出与实测指标逐项对应。该分层使标定残差、方法指标和系统功能具有各自明确的评价对象。
据此，本章先给出原理样机需求、技术指标、硬件设计和软件架构，再通过双目标定、连续轨迹跟踪、N线探头标定和针尖枢轴标定评价几何链路，随后以甲状腺假体为共同对象验证二维语义、超声扫查序列配准、三维语义和针体几何的软件集成。分项误差只界定相应变换或模块的性能，不通过简单相加推断未直接测量的端到端穿刺精度。', '第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 引 言 引言 依 次 立 物 理 一 致 三 维 重 章依 依次 次建 建立 立了 了物 物理 理一 一致 致三 三维 维重 重建 多 扫 查 空 间 组 织 多次 次扫 扫查 查空 空间 间统 统一 一和 和组 组织 器 械 语 义 模 方 法 器械 械语 语义 义建 建模 模方 方法 本 将 这 些 置 于 同 本章 章将 将这 这些 些方 法置 置于 于同 同一 一甲 腺假 外 部 定 位 标 链 路 外部 部定 定位 位和 和器 械标 标定 定链 链路 路中 考 察 算 输 出 能 否 获 得 坐 考察 察算 算法 法输 输出 出能 能否 否获 获得 得一 致的 的物 理坐 坐标 明 确 数 据 来 源 可 追 溯 块 级 评 价 明确 确的 的数 数据 据来 来源 源和 和可 可追 追溯 溯的 的模 模块 块级 级评 评价 分 个 层 章验 证分 分为 为三 三个 个层 层次 硬 件 连 接 图 像 平 面 硬件 件与 与坐 标层 层连 连接 接图 图像 像平 平面 探 头 探头 世 界 工 作 点 位世 世界 界坐 标和 械工 工作 作点 有 效 观 测 法与 与数 据层 层组 织有 有效 效观 观测 二 概 率 二维 维概 概率 修 正 姿 修正 正位 位姿 场 针 几 何 维场 场和 和针 针体 体几 几何 入 条 证据 层将 将输 输入 入条 条件 量 中间 间量 实 指 逐 项 对 应 出与 与实 实测 测指 指标 标逐 逐项 项对 对应 该 使 残 差 该分 分层 层使 使标 定残 残差 功 具 各 自 象 法指 和系 统功 功能 能具 具有 有各 各自 自明 的评 价对 对象 此 据此 先 给 原 样 机 需 求 章先 先给 给出 出原 原理 理样 样机 机需 需求 技 术 技术 术指 设 计 软 架 件设 设计 计和 和软 软件 件架 架构 再 通 过 双 目 再通 通过 过双 双目 目标 续 轨 迹 跟 踪 连续 续轨 轨迹 迹跟 跟踪 线 尖 枢 轴 线探 头标 定和 针尖 尖枢 枢轴 轴标 定评 价几 何链 随 后 以 共 随后 后以 以甲 体为 为共 共同 同对 象验 证二 维语 序 列 配 准 声扫 查序 序列 列配 配准 集 成 义和 何的 的软 件集 集成 误 只 相 变 换 或 性 分项 项误 误差 差只 只界 界定 定相 相应 应变 变换 换或 或模 块的 的性 性能 不 简 单 加 推 断 未 直 端 到 精 度 不通 过简 简单 单相 相加 加推 推断 断未 未直 直接 接测 测量 量的 的端 端到 到端 端穿 刺精 精度', '/#research', 'doctoral-thesis', 1, '2026-08-04', '53a4fb2f0fa36de71741e8256c89e1116703966019f0bb83a6720fc12d31b2ae') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e32e52ad02ab0303', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现', '第2—4章分别给出超声三维重建、扫查序列配准和组织—器械语义建模方法。本节从假体穿刺导航的实际任务出发，给出技术指标、硬件设计总览和软件设计总览，说明硬件观测如何经软件组织为算法输入，算法中间量如何转化为可解释的界面反馈，以及各阶段实验结果如何回写至任务状态与评价指标。讨论范围为原理样机与假体条件下的系统构建和分阶段验证。', '第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 分 别 给 出 三 维 重 章分 分别 别给 给出 出超 声三 三维 维重 重建 扫 查 序 列 配 准 组 织 扫查 查序 序列 列配 配准 准和 和组 组织 器 械 语 义 模 方 法 器械 械语 语义 义建 建模 模方 方法 本 节 从 际 任 务 发 本节 节从 从假 体穿 航的 的实 实际 际任 任务 务出 出发 技 术 指 标 出技 技术 术指 指标 硬 件 设 计 总 览 软 硬件 件设 设计 计总 总览 览和 和软 软件 说 明 观 测 如 何 经 算 输 入 说明 明硬 件观 观测 测如 如何 何经 经软 件组 织为 为算 算法 法输 输入 间 量 转 化 可 解 释 界 面 反 馈 法中 中间 间量 量如 何转 转化 化为 为可 可解 解释 释的 的界 界面 面反 反馈 以 各 阶 段 结 果 回 写 至 态 评 价 以及 及各 各阶 阶段 段实 实验 验结 结果 果如 何回 回写 写至 至任 务状 状态 态与 与评 评价 价指 讨 论 范 围 条 下 讨论 论范 范围 围为 为原 机与 体条 条件 件下 下的 的系 建和 和分 分阶 段验', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e32e52ad02ab03035d3361914679d70b83d09239e9a6f13c90f29e76e7bca0cf') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5430f0a2bb43cd7d', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 系统需求与技术指标 / 系统需求与设计目标', '原理样机面向假体条件下的自由手超声扫查与穿刺定位。系统需要同步组织B-mode、双目图像、工具位姿和时间信息，建立图像平面、探头、定位世界坐标与器械工作点之间的变换，并将二维观测、序列配准、三维重建和针体几何纳入统一任务语义。软件不仅调用算法，还承担硬件接入、参数配置、状态管理、结果解释与任务门控。
上述需求转化为模块解耦、坐标定义明确、来源可追溯和证据分层四项原则。跨模块交换的数据必须携带对象与运行标识、时间信息、坐标系、长度单位、变换方向和质量标志；界面同时展示任务输入、关键参数、中间证据、阶段输出与评价范围，使操作者能够判断结果为何产生、是否可用于下一阶段，而不是只查看最终图像。', 'b-mode 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 需 求 技 术 指 标 统需 需求 求与 与技 技术 术指 指标 设 计 目 与设 设计 计目 目标 面 向 条 件 下 自 由 手 扫 查 定 位 机面 面向 向假 体条 条件 件下 下的 的自 自由 由手 手超 声扫 扫查 查与 与穿 刺定 定位 要 同 步 组 织 需要 要同 同步 步组 组织 双 图 像 双目 目图 图像 工 具 姿 时 间 信 息 工具 具位 位姿 姿和 和时 时间 间信 信息 立 平 建立 立图 像平 平面 探 头 探头 世 界 坐 器 械 作 点 之 变 换 位世 世界 界坐 坐标 标与 与器 器械 械工 工作 作点 点之 之间 间的 的变 变换 并 将 二 维 观 测 并将 将二 二维 维观 观测 序 列 配 准 序列 列配 配准 三 重 针 几 何 纳 入 一 任 务 语 义 三维 维重 重建 建和 和针 针体 体几 几何 何纳 纳入 入统 统一 一任 任务 务语 语义 软 不 仅 调 用 算 法 软件 件不 不仅 仅调 调用 用算 算法 还 承 担 硬 接 还承 承担 担硬 硬件 件接 接入 参 数 置 参数 数配 配置 态 管 状态 态管 管理 结 果 解 释 门 控 结果 果解 解释 释与 与任 务门 门控 上 述 转 化 模 块 耦 上述 述需 求转 转化 化为 为模 模块 块解 解耦 明 确 标定 定义 义明 明确 来 源 可 追 溯 据 分 层 四 项 则 来源 源可 可追 追溯 溯和 和证 证据 据分 分层 层四 四项 项原 原则 跨 交 必 须 携 带 对 象 运 行 识 跨模 块交 交换 换的 的数 数据 据必 必须 须携 携带 带对 对象 象与 与运 运行 行标 标识 标系 长 度 单 长度 度单 单位 方 质 量 志 换方 方向 向和 和质 质量 量标 标志 展 示 输 界面 面同 同时 时展 展示 示任 务输 输入 关 键 关键 键参 中间 间证 阶 段 出 评 价 范 围 阶段 段输 输出 出与 与评 评价 价范 范围 使 操 者 能 够 判 断 产 生 使操 操作 作者 者能 能够 够判 判断 断结 果为 为何 何产 产生 否 于 是否 否可 可用 用于 于下 下一 一阶 而 只 看 最 终 而不 不是 是只 只查 查看 看最 最终 终图', '/#research', 'doctoral-thesis', 1, '2026-08-04', '5430f0a2bb43cd7d48b62dbadf56a16d9ca306b849ea2969b3b4ebfaff07ebd6') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-75ab8c280b4cc739', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 系统需求与技术指标 / 系统技术指标', '在系统需求基础上，定量评价仅采用已经形成实测证据的模块级指标，包括有效接触检测、双目标定、连续跟踪、N线探头标定、针尖枢轴标定、二维语义、扫查序列配准、三维强度与语义重建以及针体几何恢复。表中目标值用于统一方法与原理样机的评价口径，不解释为医疗器械注册指标或临床安全阈值。
表 5.1按照研究任务、评价指标、目标值、实验结果和结论组织定量证据。各项指标分别对应有效接触、空间标定、二维语义、扫查序列配准、三维重建和针体几何，从而使需求定义、界面反馈与实验评价保持同一口径。
