INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-85954091e2026910', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 导航软件设计总览', '在上述需求约束下，导航软件的核心任务是在硬件、算法与操作者之间建立可核对的桥梁。硬件层负责观测与状态，算法层负责从图像和位姿估计语义、空间与几何，交互层负责选择任务、配置参数、呈现关键中间量并判断阶段完成条件。由此，软件架构不按代码包或结果文件罗列，而按导航任务中的数据状态转换组织。', '第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 软 件 设 计 总 览 航软 软件 件设 设计 计总 总览 上 述 需 求 约 束 下 在上 上述 述需 需求 求约 约束 束下 核 心 任 务 硬 件的 的核 核心 心任 任务 务是 是在 在硬 硬件 算 法 操 作 者 之 间 立 可 对 桥 梁 算法 法与 与操 操作 作者 者之 之间 间建 建立 立可 可核 核对 对的 的桥 桥梁 层 负 责 观 测 态 件层 层负 负责 责观 观测 测与 与状 状态 从 图 像 位 姿 估 语 义 法层 责从 从图 图像 像和 和位 位姿 姿估 估计 计语 语义 空 几 何 空间 间与 与几 几何 交 互 选 择 交互 互层 责选 选择 择任 配 置 参 数 配置 置参 参数 呈 关 键 量 并 判 断 阶 段 完 成 条 呈现 现关 关键 键中 中间 间量 量并 并判 判断 断阶 阶段 段完 完成 成条 条件 由 此 由此 架 不 按 代 码 包 或 结 果 文 罗 列 件架 架构 构不 不按 按代 代码 码包 包或 或结 结果 果文 文件 件罗 罗列 而 据 转 换 组 织 而按 按导 航任 务中 中的 的数 数据 据状 态转 转换 换组 组织', '/#research', 'doctoral-thesis', 1, '2026-08-04', '85954091e202691072173cd3ec9260abf0b54b0520b64c72fbb137f8f93a5e7d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2168808e05fa7250', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 导航软件设计总览 / 软件运行环境与分层职责', '软件运行于图形计算工作站，采用AMD Ryzen 9 9950X处理器、96 GB系统内存和NVIDIA GeForce RTX 5090图形处理器（32 GB显存）。CPU承担设备状态、记录索引、参数校验与坐标计算，GPU承担二维语义推理、三维神经场优化和空间结果渲染。该配置用于说明本章软件与算法的运行环境，不作为算法性能优越性的证据。
软件分为设备与记录接入、任务状态与数据契约、算法服务、可视化与交互、证据与结果管理五个层次。不同算法通过统一任务记录交换数据。对第i条记录，软件使用下式所示的数据契约描述标识、时间、源/目标坐标系、参数、结果、质量和有效性，其中各字段均可由界面追溯。
其中，id_i和t_i分别表示任务与时间标识，ℱ_i^src和ℱ_i^dst表示源/目标坐标系，u_i为参数配置，x_i为阶段结果，q_i为定量质量，m_i为有效性与证据作用域标志。该数据契约使硬件观测、算法结果和界面状态能够由同一记录解释。
表 .2 导航系统功能模块、关键证据与研究输出
