INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-089814a9604b5dbf', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 导航软件设计总览 / 任务数据流与坐标一致性约束', '如图 5.2所示，软件总体架构由任务交互、硬件与实验对象、导航任务数据流、核心算法和证据反馈五部分构成。顶部四工作台给出操作顺序；硬件层提供B-mode、双目观测和工具位姿；数据层维护时间、坐标与质量状态；算法层完成二维语义、序列配准、三维强度与语义建模及针体几何恢复；底部将功能、模块实测指标和本文评价范围对应展示。
导航数据流以图像、位姿和标定观测为起点，经时间关联与接触筛选形成同步有效观测。有效B-mode一路进入二维分割形成解剖与针体概率，另一路与同步位姿共同进入序列配准；修正位姿分别与有效B-mode和二维概率结合，形成三维强度场、三维组织语义与针体概率。针体概率进一步转换为轴线、有限线段和模型端点候选。图像质量、概率可靠性、坐标一致性和几何有效性均作为显式状态参与阶段门控。
图 .2 甲状腺超声穿刺导航软件总体架构与操作流程
Figure . Software architecture and workflow of thyroid puncture navigation.
图 5.2同时表达操作流、数据流和结果反馈流。四个工作台规定任务选择与参数配置位置，中部拓扑说明数据如何分流、汇合与转换，质量节点决定结果能否向下游传递，底部给出核心方法与相应实验指标。该组织使论文方法、界面任务对象和软件状态模型保持同一语义。', '5.2 b-mode figure software architecture and workflow of thyroid puncture navigation. 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 软 件 设 计 总 览 航软 软件 件设 设计 计总 总览 任 务 数 据 流 坐 标 一 致 性 约 束 任务 务数 数据 据流 流与 与坐 坐标 标一 一致 致性 性约 约束 如 图 如图 所 示 所示 架 由 交 互 件总 总体 体架 架构 构由 由任 务交 交互 硬 对 象 硬件 件与 与实 实验 验对 对象 航任 核 心 算 法 反 馈 五 部 分 成 核心 心算 算法 法和 和证 证据 据反 反馈 馈五 五部 部分 分构 构成 顶 四 工 作 台 给 出 操 顺 序 顶部 部四 四工 工作 作台 台给 给出 出操 操作 作顺 顺序 层 提 供 件层 层提 提供 双 目 观 测 具 位 姿 双目 目观 观测 测和 和工 工具 具位 位姿 维 护 时 间 据层 层维 维护 护时 时间 质 量 态 标与 与质 质量 量状 状态 完 二 语 义 法层 层完 完成 成二 二维 维语 语义 列 配 准 序列 列配 配准 三 强 度 模 针 几 何 恢 复 三维 维强 强度 度与 与语 义建 建模 模及 及针 针体 体几 几何 何恢 恢复 底 将 功 能 底部 部将 将功 功能 块 指 本 文 评 价 范 围 应 展 模块 块实 实测 测指 指标 标和 和本 本文 文评 评价 价范 范围 围对 对应 应展 展示 以 像 航数 流以 以图 图像 定 起 点 姿和 和标 标定 定观 测为 为起 起点 经 关 联 接 触 筛 选 形 同 步 有 效 经时 间关 关联 联与 与接 接触 触筛 筛选 选形 形成 成同 同步 步有 有效 效观 路 进 入 割 解 剖 概 率 一路 路进 进入 入二 维分 分割 割形 成解 解剖 剖与 与针 体概 概率 另 共 另一 路与 与同 步位 姿共 共同 同进 入序 修 正 别 修正 正位 姿分 分别 别与 与有 结 合 和二 维概 率结 结合 场 成三 度场 组 织 维组 组织 织语 义与 转 换 轴 线 率进 进一 一步 步转 转换 换为 为轴 轴线 限 段 型 端 候 有限 限线 线段 段和 和模 模型 型端 端点 点候 候选 像质 可 靠 率可 可靠 靠性 均 显 式 参 阶 门 控 性和 和几 何有 效性 性均 均作 作为 为显 显式 式状 态参 参与 与阶 阶段 段门 门控 程 构与 与操 作流 流程 表 达 同时 时表 表达 达操 果 流和 和结 结果 果反 馈流 个 规 择 置 四个 个工 台规 规定 定任 务选 选择 择与 与参 参数 数配 配置 置位 位置 拓 扑 说 明 中部 部拓 拓扑 扑说 说明 明数 据如 如何 何分 分流 汇 汇合 合与 与转 节 决 否 向 下 游 传 递 量节 节点 点决 决定 定结 果能 能否 否向 向下 下游 游传 传递 方 相 部给 出核 心方 方法 法与 与相 相应 应实 验指 该 使 论 该组 织使 使论 论文 文方 界 面 保 持 界面 面任 务对 象和 和软 件状 态模 型保 保持 持同 同一 一语', '/#research', 'doctoral-thesis', 1, '2026-08-04', '089814a9604b5dbfa17ebc64b7780bcd8a33f033f98aaa3c8306660083a37b0f') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excl