INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b00d01953e0139d4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 导航软件设计总览 / 四工作台交互组织', '四个工作台采用一致的页面骨架：中央区域呈现当前任务与关键可视化，右侧参数面板提供类型化配置和受控执行入口，结果面板汇总当前记录中的数值与证据作用域，运行日志区记录过程状态。阶段标签用于切换研究步骤，页面顶部的任务对象与状态条用于避免跨记录误组合。
跨模块传递由数据、坐标、质量和来源四类门控共同决定。设第k阶段的四类条件分别为数据完整性、坐标一致性、质量有效性和来源可追溯性，则阶段结果只有在门控乘积为1时才作为下一阶段输入；否则界面返回具体诊断项，操作者可据此修正输入或参数后重新执行当前阶段。
该定义把界面状态与算法依赖关系统一起来：门控为1表示结果可进入下一工作台；门控为0时，软件保留当前记录与失败原因，但不建立超出证据范围的跨模块关系。', '第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 软 件 设 计 总 览 航软 软件 件设 设计 计总 总览 四 工 作 台 交 互 组 织 四工 工作 作台 台交 交互 互组 组织 个 采 用 一 致 页 面 骨 架 四个 个工 台采 采用 用一 一致 致的 的页 页面 面骨 骨架 央 区 域 呈 当 前 任 务 关 键 可 视 化 中央 央区 区域 域呈 呈现 现当 当前 前任 任务 务与 与关 关键 键可 可视 视化 右 侧 参 数 板 提 供 类 型 配 置 受 控 执 行 入 口 右侧 侧参 参数 数面 面板 板提 提供 供类 类型 型化 化配 配置 置和 和受 受控 控执 执行 行入 入口 结 果 汇 记 录 值 据 结果 果面 板汇 汇总 总当 前记 记录 录中 中的 的数 数值 值与 与证 证据 据作 作用 用域 运 日 志 过 程 态 运行 行日 日志 志区 区记 录过 过程 程状 状态 阶 段 标 签 于 切 换 研 究 步 骤 阶段 段标 标签 签用 用于 于切 切换 换研 研究 究步 步骤 顶 部 对 象 条 避 免 跨 误 合 面顶 顶部 部的 的任 务对 对象 象与 与状 态条 条用 于避 避免 免跨 跨记 录误 误组 组合 模 块 传 递 由 跨模 模块 块传 传递 递由 由数 数据 坐 坐标 质 量 来 源 门 共 同 决 定 质量 量和 和来 来源 源四 四类 类门 门控 控共 共同 同决 决定 设第 分 别 完 整 性 段的 的四 类条 条件 件分 分别 别为 为数 据完 完整 整性 标一 致性 有 效 追 溯 量有 有效 效性 性和 源可 可追 追溯 溯性 则 只 乘 积 则阶 段结 果只 只有 有在 在门 控乘 乘积 积为 时 才 下 输 时才 才作 作为 为下 下一 一阶 段输 输入 否 界 返 回 具 诊 断 项 否则 则界 界面 面返 返回 回具 具体 体诊 诊断 断项 操 者 此 修 正 或 后 重 新 操作 作者 者可 可据 据此 此修 修正 正输 入或 或参 数后 后重 重新 新执 行当 前阶 该 义 把 算 法 依 赖 起 该定 定义 义把 把界 面状 态与 与算 算法 法依 依赖 赖关 关系 统一 一起 起来 控为 表 示 进 表示 示结 果可 可进 进入 入下 一工 保 留 失 败 因 件保 保留 留当 录与 与失 失败 败原 原因 但 不 立 出 范 围 但不 不建 建立 立超 超出 出证 据范 范围 围的 的跨 块关', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b00d01953e0139d4b9d245b4587f3cbf0758db405e25127c6ae953b1328371bd') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-0b16e453d5552e91', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 导航软件设计总览 / 参数配置、中间可视化与结果反馈', '参数配置遵循“可见、可校验、可追溯”原则。阈值、模型、坐标方向、长度单位与结果存储位置均由类型化控件呈现，执行前显示参数与任务记录的对应关系。中间可视化保留接触区域、类别概率、候选匹配、几何内点、修正轨迹、三维场和针体支撑，使异常能够定位到具体数据转换环节。
结果反馈按照研究对象分层：设备与标定采用重投影、连续轨迹和器械工作点误差；二维语义采用输入域增益、区域指标和结构违反率；序列配准分别采用全局与局部位姿误差；三维语义与针体几何采用三维一致性、覆盖率和中心线误差。界面将数值与任务对象、参数及中间可视化绑定，避免不同层级指标之间的含义混淆。', '第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 软 件 设 计 总 览 航软 软件 件设 设计 计总 总览 参 数 配 置 参数 数配 配置 间 可 视 化 结 果 反 馈 中间 间可 可视 视化 化与 与结 结果 果反 反馈 遵 循 置遵 遵循 见 可见 校 可校 校验 追 溯 可追 追溯 则 原则 阈 值 阈值 模 型 模型 坐 标 方 向 坐标 标方 方向 长 度 单 位 存 储 均 由 类 控 呈 长度 度单 单位 位与 果存 存储 储位 位置 置均 均由 由类 类型 型化 化控 控件 件呈 呈现 执 行 前 显 示 任 务 记 录 对 应 关 执行 行前 前显 显示 示参 数与 与任 任务 务记 记录 录的 的对 对应 应关 关系 保 留 接 触 区 域 化保 保留 留接 接触 触区 区域 别 概 率 类别 别概 概率 候 选 匹 候选 选匹 匹配 几 何 内 点 几何 何内 内点 修 正 轨 迹 修正 正轨 轨迹 三 维 场 针 支 撑 三维 维场 场和 和针 针体 体支 支撑 使 异 常 能 够 定 到 具 据 转 换 环 节 使异 异常 常能 能够 够定 定位 位到 到具 具体 体数 数据 据转 转换 换环 环节 按 照 研 究 象 分 层 馈按 按照 照研 研究 究对 对象 象分 分层 备 采 用 重 投 影 设备 备与 与标 标定 定采 采用 用重 重投 投影 连 续 器 械 工 作 误 差 连续 续轨 迹和 和器 器械 械工 工作 作点 点误 误差 二 语 义 输 入 增 益 二维 维语 语义 义采 用输 输入 入域 域增 增益 指 违 域指 指标 标和 和结 结构 构违 违反 反率 序 列 准 全 局 部 姿 序列 列配 配准 准分 分别 别采 用全 全局 局与 与局 局部 部位 位姿 姿误 一 致 性 义与 与针 体几 何采 用三 维一 一致 致性 覆 盖 心 线 覆盖 盖率 率和 和中 中心 心线 线误 界 面 将 界面 面将 将数 数值 值与 务对 绑 数及 及中 化绑 绑定 避 免 不 同 级 之 含 混 淆 避免 免不 不同 同层 层级 级指 标之 之间 间的 的含 含义 义混 混淆', '/#research', 'doctoral-thesis', 1, '2026-08-04', '0b16e453d5552e919b9c9e2ca9153be54552d43890f8447880dabde96e760937') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d63ff29f5292b2d0', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 导航软件设计总览 / 功能完成条件与评价边界', '原理样机已经连接实时采集、标定与误差分析、二维语义、序列配准、三维强度与语义重建以及针体几何恢复。每个阶段均提供任务输入、类型化参数、算法执行、中间过程可视化、结果输出和日志反馈，使操作者能够在同一界面骨架内完成完整实验流程。
统一接口使各阶段共享对象标识、来源、时间、坐标系、单位、变换方向和质量状态。这些字段既支持从设备接入到定位评价的顺序执行，也支持依据质量反馈返回上游调整参数；系统评价始终保持指标与观测对象对应，不将分项误差简单叠加为单一精度。
上述技术指标、硬件设计和软件设计共同界定了原理样机的任务范围。5.3　—5.7　 节沿01—04工作台展开：先建立空间标定和可追溯扫查输入，再形成有效二维观测与统一空间，最后构建三维强度、三维语义和针体几何，并在每一阶段对应说明操作者动作、中间证据、实测结果与评价边界。', '5.3 5.7 01 04 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 软 件 设 计 总 览 航软 软件 件设 设计 计总 总览 功 能 完 成 条 评 价 边 界 功能 能完 完成 成条 条件 件与 与评 评价 价边 边界 已 经 连 接 时 采 集 机已 已经 经连 连接 接实 实时 时采 采集 标 定 误 差 分 析 标定 定与 与误 误差 差分 分析 二 维 语 义 二维 维语 语义 序 列 配 准 序列 列配 配准 三 强 度 重 以 针 几 何 恢 复 三维 维强 强度 度与 与语 义重 重建 建以 以及 及针 针体 体几 几何 何恢 恢复 每 个 阶 段 均 提 供 任 务 输 入 每个 个阶 阶段 段均 均提 提供 供任 任务 务输 输入 类 型 化 参 数 类型 型化 化参 参数 算 法 执 行 算法 法执 执行 间 过 程 可 视 中间 间过 过程 程可 可视 视化 结 果 出 日 志 反 馈 结果 果输 输出 出和 和日 日志 志反 反馈 使 操 作 者 够 同 一 面 骨 架 内 整 流 使操 操作 作者 者能 能够 够在 在同 同一 一界 界面 面骨 骨架 架内 内完 成完 完整 整实 实验 验流 流程 口 各 共 享 对 象 识 统一 一接 接口 口使 使各 各阶 段共 共享 享对 对象 象标 标识 来 源 来源 时间 坐 坐标 标系 单 位 单位 变 换 方 向 质 量 态 变换 换方 方向 向和 和质 质量 量状 状态 这 些 字 既 支 持 从 备 到 顺 这些 些字 字段 段既 既支 支持 持从 从设 设备 备接 接入 入到 到定 定位 位评 价的 的顺 顺序 序执 也 依 据 返 回 上 游 调 也支 持依 依据 据质 量反 馈返 返回 回上 上游 游调 调整 整参 始 终 保 指 观 测 应 统评 价始 始终 终保 保持 持指 指标 标与 与观 观测 测对 象对 对应 不 将 项 简 叠 加 精 不将 将分 分项 项误 差简 简单 单叠 叠加 加为 为单 单一 一精 精度 述 技 术 上述 述技 技术 术指 硬 范 围 硬件 计和 和软 计共 共同 同界 界定 定了 了原 机的 的任 务范 范围 节 沿 节沿 工 台 展 开 工作 作台 台展 展开 先 立 空 追 溯 扫 查 先建 建立 立空 空间 间标 定和 和可 可追 追溯 溯扫 扫查 查输 再 形 有 效 再形 形成 成有 有效 效二 维观 测与 与统 一空 最 后 最后 后构 建三 义和 和针 并 说 明 动 并在 在每 每一 一阶 段对 应说 说明 明操 者动 动作 间证 证据 实测 测结 果与', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd63ff29f5292b2d0b13a16a9a098bf5485dd5924f5aaeed5c5eedc0443727511') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-b1e3961cd8f790cf', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺超声穿刺导航系统原理样机实现 / 本章系统验证路线', '本章以甲状腺假体和空间坐标链为公共基础组织验证。5.3　 节对应01工作台的空间标定功能；5.4　 节连接01工作台的多源采集与02工作台的数据检查；5.5　 节对应02工作台的接触筛选和二维语义；5.8　 节对应03工作台的表征、候选验证及全局—局部配准；5.7　 节对应04工作台的三维强度、三维语义、针体概率、几何恢复与定位条件核对。
各节均从实际需求和输入条件出发，先说明参数与方法如何产生中间量，再由实验结果评价阶段输出，最后给出该输出在后续任务中的作用。GUI图直接呈现任务记录、参数配置、关键中间可视化和定量结果，因而同时承担软件设计说明与实验结果展示。
界面图随具体任务分别布置：双目标定、连续定位跟踪、N线探头标定和针尖枢轴标定各自在相应方法与结果段落中出现；数据检查和接触筛选也分别对应扫查数据构建与有效观测形成。该安排减少重复图形，并使每幅界面图都直接回答当前实验的输入、操作、过程和结果。
本节明确了原理样机的需求边界、硬件组成、数据与算法架构以及分阶段验证路线。同步超声图像、外部定位位姿和统一坐标关系构成模块间接口，二维语义、序列配准、三维重建与针体几何均保留各自的原始证据和分项指标。5.3　 节首先检验这些模块所依赖的空间变换。', '5.3 01 5.4 02 5.5 5.8 03 5.7 04 gui 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 原 理 样 机 实 现 统原 原理 理样 样机 机实 实现 本 路 线 本章 章系 统验 证路 路线 以 空 间 坐 标 链 公 共 基 础 组 织 章以 以甲 腺假 体和 和空 空间 间坐 坐标 标链 链为 为公 公共 共基 基础 础组 组织 织验 节 对 应 节对 对应 工 作 台 定 功 能 工作 作台 台的 的空 间标 标定 定功 功能 连 接 节连 连接 多 源 采 集 的多 多源 源采 采集 集与 数 据 检 查 的数 数据 据检 检查 触 筛 选 二 维 语 义 的接 接触 触筛 筛选 选和 和二 二维 维语 语义 表 征 的表 表征 候 全 局 候选 选验 证及 及全 全局 部 配 准 局部 部配 配准 三 强 度 的三 三维 维强 强度 针 概 率 针体 体概 概率 几 何 恢 复 位 条 件 核 几何 何恢 恢复 复与 与定 定位 位条 条件 件核 核对 各 均 从 际 需 求 输 入 出 发 各节 节均 均从 从实 实际 际需 需求 求和 和输 输入 入条 件出 出发 先 说 明 参 方 法 如 产 生 量 先说 说明 明参 参数 数与 与方 方法 法如 如何 何产 产生 生中 中间 间量 再 由 结 果 评 价 阶 段 再由 由实 实验 验结 结果 果评 评价 价阶 阶段 段输 输出 最 后 给 该 续 任 务 用 最后 后给 给出 出该 该输 出在 在后 后续 续任 任务 务中 中的 的作 作用 图 直 呈 记 录 图直 直接 接呈 呈现 现任 务记 记录 置 数配 配置 关 键 可 视 化 关键 键中 间可 可视 视化 化和 和定 定量 量结 因 而 同 时 承 担 软 设 计 展 示 因而 而同 同时 时承 承担 担软 软件 件设 设计 计说 明与 与实 果展 展示 界 面 随 具 分 别 布 界面 面图 图随 随具 具体 体任 务分 分别 别布 布置 双 目 双目 目标 跟 踪 连续 续定 位跟 跟踪 探 头 尖 枢 轴 自 相 落 线探 探头 头标 定和 和针 针尖 尖枢 枢轴 轴标 定各 各自 自在 在相 相应 应方 法与 与结 果段 段落 落中 中出 出现 也 扫 有 效 观 测 形 成 查和 和接 选也 也分 别对 应扫 扫查 查数 据构 与有 有效 效观 观测 测形 形成 安 排 减 少 重 该安 安排 排减 减少 少重 重复 复图 图形 并 使 每 幅 都 回 答 当 前 并使 使每 每幅 幅界 图都 都直 接回 回答 答当 当前 前实 验的 的输 操 操作 过 程 过程 程和 和结 确 边 本节 节明 明确 确了 了原 机的 的需 求边 边界 硬 硬件 件组 组成 算 架 据与 与算 算法 法架 架构 构以 以及 及分 分阶 段验 步 像 同步 步超 声图 图像 外 姿 一 模 块 口 外部 部定 位位 位姿 姿和 和统 统一 一坐 标关 关系 系构 构成 成模 模块 块间 间接 接口 序 列 序列 列配 保 留 始 项 指 维重 重建 与针 体几 何均 均保 保留 留各 自的 的原 原始 始证 证据 据和 和分 分项 项指 指标 首 这 些 所 依 赖 变 换 节首 首先 先检 检验 验这 这些 些模 块所 所依 依赖 赖的 间变 变换', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'b1e3961cd8f790cfb20bd9046acdb51a5cb3e110e0b3a6a50794faa95ebf840c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence