INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-db5d71b63dcdf1a2', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 设备实时采集与空间标定系统集成与实验验证', '01设备实时采集与空间标定工作台为原理样机建立连续观测和空间坐标链。本节按照双目系统标定、连续定位跟踪、N线探头标定和针尖枢轴标定四项任务展开，说明操作者如何配置几何模型、观察优化过程，并依据分项残差确认相应变换满足下游使用条件。
工作台设置设备与数据接入、双目标定、定位跟踪验证、N线探头标定和针尖枢轴标定五个阶段。各阶段共享任务记录选择、参数面板、结果面板和日志区，中央区域则按研究对象切换角点与极线、轨迹与误差、N线重投影以及枢轴几何。多源采集阶段在5.4　 节结合假体扫查数据说明。
四项标定实验分别在图 5.3—图 5.6中呈现。界面在空间链路上保持相同的交互顺序：选择任务记录并核对输入，配置模型与筛选参数，观察估计或优化过程，最后读取误差指标与阶段输出。
下述实验均先核对观测与参数是否满足模型假设，再观察估计过程是否稳定，随后以对应残差评价固定变换，最后说明输出在系统中的用途。双目重投影、轨迹误差、N线重投影和枢轴残差对应不同几何对象，需要分别解释。', '01 5.4 5.3 5.6 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 设 备 实 时 采 集 空 间 标 定 成 设备 备实 实时 时采 采集 集与 与空 空间 间标 标定 定系 统集 集成 成与 与实 实验 验验 工 作 台 原 理 样 机 立 连 续 观 测 坐 链 定工 工作 作台 台为 为原 原理 理样 样机 机建 建立 立连 连续 续观 观测 测和 和空 间坐 坐标 标链 本 节 按 照 双 目 本节 节按 按照 照双 双目 目系 统标 位 跟 踪 续定 定位 位跟 跟踪 线 探 头 针 尖 枢 轴 四 项 任 务 展 开 线探 探头 头标 定和 和针 针尖 尖枢 枢轴 轴标 定四 四项 项任 任务 务展 展开 说 明 操 者 如 何 配 置 几 模 型 说明 明操 操作 作者 者如 如何 何配 配置 置几 几何 何模 模型 察 优 化 过 程 观察 察优 优化 化过 过程 并 依 据 分 残 差 确 认 相 应 变 换 满 足 下 游 使 用 条 件 并依 依据 据分 分项 项残 残差 差确 确认 认相 相应 应变 变换 换满 满足 足下 下游 游使 使用 用条 条件 数 接 入 台设 设置 置设 备与 与数 数据 据接 接入 目标 踪验 五 个 阶 段 定五 五个 个阶 阶段 各 共 享 记 录 选 择 各阶 段共 共享 享任 务记 记录 录选 选择 参 面 板 参数 数面 面板 结 果 日 志 区 结果 果面 板和 和日 日志 志区 央 域 则 研 究 对 象 切 角 点 极 中央 央区 区域 域则 则按 按研 研究 究对 对象 象切 切换 换角 角点 点与 与极 极线 轨 迹 误 轨迹 迹与 与误 误差 重 投 影 以 线重 重投 投影 影以 以及 及枢 轴几 多 源 多源 源采 集阶 段在 合 扫 查 节结 结合 合假 体扫 扫查 查数 据说 别 图 项标 定实 验分 分别 别在 在图 呈 现 中呈 呈现 界 路 上 保 持 同 交 互 顺 序 界面 面在 在空 间链 链路 路上 上保 保持 持相 相同 同的 的交 交互 互顺 顺序 核 输 择任 录并 并核 核对 对输 输入 筛 置模 型与 与筛 筛选 选参 估 计 或 察估 估计 计或 或优 最 后 读 取 指 出 最后 后读 读取 取误 差指 指标 标与 与阶 段输 输出 述 均 先 否 下述 述实 验均 均先 先核 对观 测与 与参 数是 是否 否满 足模 型假 假设 再 稳 再观 计过 程是 否稳 稳定 随 评 价 固 随后 后以 以对 对应 应残 差评 评价 价固 固定 定变 途 后说 明输 出在 在系 统中 中的 的用 用途 目重 迹误 不 影和 和枢 轴残 差对 应不 不同 同几 何对 需 要 解 释 需要 要分 别解 解释', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'db5d71b63dcdf1a2def619128f2927a67e2a581410ab494740db27984bd9b756') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-c3dc97bab2eeea50', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 设备实时采集与空间标定系统集成与实验验证 / 定位系统标定与轨迹跟踪实验 / 双目相机标定', '双目标定实验用于验证2.3.1　 节所述相机模型与立体几何链路在实机平台中的可用性[14,84–87]。实验以棋盘格角点覆盖、极线一致性和重投影误差检验内外参估计，重点判断左右相机相对位姿是否能够支撑近红外标志点配对和三角测量。
实验采用标准棋盘格标定板，在不同距离、视角和姿态下采集同步左右图像。规则平面几何和稳定角点拓扑[14,84–87]提供同名观测，亚像素优化减小离散像素误差。图 5.3将左右角点、对极约束、立体校正、参数配置与结果状态置于同一页面，使输入覆盖、几何一致性和标定精度可以连续核对。
