INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-e7f85d4d4819edf7', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 设备实时采集与空间标定系统集成与实验验证 / 器械标定', '外部视觉系统测得的是参考架位姿，而导航显示和误差评估需要超声成像平面、针尖、针轴与目标组织的空间关系。因此，器械标定在图 5.5和图 5.6中分别建立探头图像平面变换和针尖工作点偏移，并将原始观测、筛选参数、优化过程、残差和可用状态对应起来。[4,5,84–87,145,147]', '5.5 5.6 84 87 145 147 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 设 备 实 时 采 集 空 间 标 定 成 设备 备实 实时 时采 采集 集与 与空 空间 间标 标定 定系 统集 集成 成与 与实 实验 验验 器 械 器械 械标 外 部 视 觉 测 得 参 考 架 位 姿 外部 部视 视觉 觉系 统测 测得 得的 的是 是参 参考 考架 架位 位姿 而 显 示 误 差 评 估 需 要 像 平 面 而导 航显 显示 示和 和误 误差 差评 评估 估需 需要 要超 声成 成像 像平 平面 针 尖 针尖 轴 目 组 织 关 针轴 轴与 与目 目标 标组 组织 织的 的空 间关 关系 因 此 因此 图 定在 在图 和图 分 别 立 探 头 变 换 工 作 点 偏 移 中分 分别 别建 建立 立探 探头 头图 图像 面变 变换 换和 和针 尖工 工作 作点 点偏 偏移 并 将 原 始 观 并将 将原 原始 始观 观测 筛 选 数 筛选 选参 参数 优 化 过 程 优化 化过 过程 残 可 用 态 对 应 起 来 残差 差和 和可 可用 用状 状态 态对 对应 应起 起来', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'e7f85d4d4819edf744763da660bb3bdbc9a82415629dc146c09e93d04b948d1d') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-7962a1cfbba4c5ca', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 设备实时采集与空间标定系统集成与实验验证 / 器械标定 / N线超声探头标定', '基于2.3.2.1　 节的N线几何模型，实验同步采集标定块参考架位姿、探头参考架位姿和超声图像。图 5.5在软件界面中，依次展示图像交点、初始估计、三维粗配准、联合优化、三维几何与逐帧重投影误差，再由N线模型形成空间—像素对应并求解探头标定矩阵。图 5.5下部将优化后三维几何与逐帧误差曲线并列显示。三维视图用于检查成像平面、N线目标点、两组交点和IPE约束的空间一致性，曲线则用于识别不同姿态下的误差波动。图 5.5上部并列展示初始估计、三维粗配准和联合优化后的像素重投影。同一组代表性观测在三个阶段连续显示，使优化前后的对应关系、局部偏差及收敛结果可以直接比较。
N线探头标定需要同时报告二维重投影误差、三维有效误差、IPE 误差和法向距离[4,5,84–87]。二维重投影误差反映图像交点与模型交点的一致性，三维有效误差反映恢复点在空间中的偏差，IPE 误差检查N线几何约束在成像平面内是否一致，法向距离则描述点集偏离超声切片平面的程度。
图 .5 N线探头标定工作台的优化过程与误差评价
