INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-a27b65d8bcfc1f3a', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 设备实时采集与空间标定系统集成与实验验证 / 器械标定 / 穿刺针尖枢轴标定', '穿刺针枢轴标定用于求解针尖在参考架坐标系中的固定坐标。图 5.6在软件界面中，将针尖—光球几何、多姿态枢轴点、内外点分布和逐样本残差对应显示。设第i个姿态下参考架到世界坐标系的旋转和平移为R_i和t_i，针尖局部坐标为p_R，固定支点世界坐标为q_W；考虑定位噪声后，以下式所示的最小二乘问题联合估计针尖偏移与固定支点。
图 .6 穿刺针尖枢轴标定工作台的几何关系与残差评价
Figure . Needle-tip pivot calibration: geometry and residual evaluation.
本研究共采集77个针体姿态，其中52个进入枢轴求解；鲁棒筛选后保留37个内点和15个外点，针尖偏移为(233.971, 6.130, -27.586) mm。图 5.6给出的内点残差RMSE、P95和最大误差分别为3.0118 mm、5.1475 mm和5.4711 mm，定位架光球注册RMSE均值为0.5283 mm。几何视图、残差曲线和统计面板共同验证参考架—针尖固定关系的可估计性。
图 5.6把针尖中心坐标系下的光球分布、针轴方向、枢轴内外点和残差界限置于同一页面，操作者可据此判断采样姿态是否充分、鲁棒筛选是否合理以及固定工作点是否达到设定精度。', '5.6 figure needle-tip pivot calibration geometry and residual evaluation. 77 52 37 15 233.971 6.130 27.586 mm rmse p95 3.0118 5.1475 5.4711 0.5283 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 设 备 实 时 采 集 空 间 标 定 成 设备 备实 实时 时采 采集 集与 与空 空间 间标 标定 定系 统集 集成 成与 与实 实验 验验 器 械 器械 械标 针 尖 枢 轴 刺针 针尖 尖枢 枢轴 轴标 用 于 求 解 参 考 架 坐 固 针枢 定用 用于 于求 求解 解针 尖在 在参 参考 考架 架坐 坐标 标系 系中 中的 的固 固定 定坐 图 软 件 界 面 在软 软件 件界 界面 面中 将 将针 光 球 几 何 光球 球几 几何 多 姿 态 点 多姿 姿态 态枢 轴点 内 外 分 布 逐 样 本 残 差 对 应 显 示 内外 外点 点分 分布 布和 和逐 逐样 样本 本残 残差 差对 对应 应显 显示 设第 个 下 到 世 旋 转 平 移 个姿 态下 下参 架到 到世 世界 界坐 系的 的旋 旋转 转和 和平 平移 移为 局 部 尖局 局部 部坐 标为 支 定支 支点 点世 虑 位 噪 后 考虑 虑定 定位 位噪 噪声 声后 以 式 所 最 小 二 乘 问 题 联 合 估 计 偏 以下 下式 式所 所示 示的 的最 最小 小二 二乘 乘问 问题 题联 联合 合估 估计 计针 尖偏 偏移 移与 与固 工 作 台 关 评 价 定工 工作 作台 台的 的几 何关 关系 系与 与残 差评 评价 研 究 共 本研 研究 究共 共采 个针 针体 体姿 其 其中 进 入 个进 进入 入枢 轴求 鲁 棒 筛 选 保 留 鲁棒 棒筛 筛选 选后 后保 保留 个内 内点 点和 个外 给 出 给出 出的 的内 点残 大 误 别 和最 最大 大误 误差 差分 分别 别为 注 册 位架 架光 球注 注册 均 值 均值 值为 视 何视 视图 曲 线 板 同 差曲 曲线 线和 和统 统计 计面 面板 板共 共同 同验 证参 可 性 尖固 定关 的可 可估 计性 把 心 把针 尖中 中心 心坐 系下 下的 的光 球分 方 向 针轴 轴方 方向 限 置 一 页 轴内 和残 差界 界限 限置 置于 于同 同一 一页 页面 操 者 据 此 判 断 否 充 操作 作者 者可 可据 据此 此判 判断 断采 采样 样姿 态是 是否 否充 充分 理 达 精 度 选是 否合 合理 理以 以及 及固 作点 点是 否达 达到 到设 设定 定精 精度', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'a27b65d8bcfc1f3acc5bd901b6ff299476068984a9b05a073efadb6cb1cc24ea') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-9c170f1ac9a7668b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 设备实时采集与空间标定系统集成与实验验证 / 器械标定 / 穿刺针尖枢轴标定', 'm。几何视图、残差曲线和统计面板共同验证参考架—针尖固定关系的可估计性。
图 5.6把针尖中心坐标系下的光球分布、针轴方向、枢轴内外点和残差界限置于同一页面，操作者可据此判断采样姿态是否充分、鲁棒筛选是否合理以及固定工作点是否达到设定精度。
枢轴残差反映的是针尖固定点在多姿态采样下的一致性，并不等同于完整导航任务中的针尖 TRE[139,145]。实际导航误差还会受到外部定位架配准误差、探头标定误差、时间同步误差以及图像中针尖可见性的共同影响。因此，上述毫米级残差应被解释为针尖偏移标定的几何一致性结果，而不是完整穿刺导航系统的最终误差。
本节输出双目成像参数、连续工具位姿质量、图像平面到外部空间的固定变换和针尖工作点偏移。01工作台将每项输出与具体观测、参数、优化过程和残差关联，并直接标明其下游用途，从而形成假体扫查、三维重建和针体定位所需的空间基础。', '5.6 tre 139 145 01 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 设 备 实 时 采 集 空 间 标 定 成 设备 备实 实时 时采 采集 集与 与空 空间 间标 标定 定系 统集 集成 成与 与实 实验 验验 器 械 器械 械标 针 尖 枢 轴 刺针 针尖 尖枢 枢轴 轴标 几 何 视 图 几何 何视 视图 残 差 曲 线 计 面 板 共 同 参 考 架 残差 差曲 曲线 线和 和统 统计 计面 面板 板共 共同 同验 证参 参考 考架 固 关 可 估 性 尖固 固定 定关 关系 系的 的可 可估 估计 计性 把 心 坐 下 光 球 分 布 把针 尖中 中心 心坐 坐标 标系 系下 下的 的光 光球 球分 分布 方 向 针轴 轴方 方向 内 外 点 界 限 置 于 一 页 轴内 内外 外点 点和 和残 差界 界限 限置 置于 于同 同一 一页 页面 操 作 者 据 此 判 断 样 姿 态 否 充 操作 作者 者可 可据 据此 此判 判断 断采 采样 样姿 姿态 态是 是否 否充 充分 鲁 棒 筛 选 合 理 以 工 达 到 精 度 鲁棒 棒筛 筛选 选是 否合 合理 理以 以及 及固 定工 工作 作点 点是 否达 达到 到设 设定 定精 精度 反 映 多 致 轴残 差反 反映 映的 的是 是针 定点 点在 在多 多姿 态采 样下 的一 一致 致性 并 不 等 完 整 任 务 并不 不等 等同 同于 于完 完整 整导 航任 任务 务中 中的 的针 际 误 还 会 受 部 位 配 准 实际 际导 航误 误差 差还 还会 会受 受到 到外 外部 部定 定位 位架 架配 配准 准误 探 头 探头 头标 定误 步 像 见 影 响 时间 间同 同步 步误 差以 及图 图像 像中 中针 尖可 可见 见性 性的 的共 同影 影响 因 因此 上 述 毫 米 级 应 被 解 释 偏 移 结 果 上述 述毫 毫米 米级 级残 差应 应被 被解 解释 释为 为针 尖偏 偏移 移标 定的 的几 何一 性结 结果 而 最 终 而不 不是 是完 整穿 统的 的最 最终 终误 本 节 输 出 双 目 数 本节 节输 输出 出双 双目 目成 成像 像参 参数 连 续 具 质 量 连续 续工 工具 具位 位姿 姿质 质量 平 变 换 像平 平面 面到 部空 间的 的固 定变 变换 换和 和针 尖工 点偏 台 将 每 项 观 测 作台 台将 将每 每项 项输 出与 与具 具体 体观 观测 优 化 过 程 联 优化 化过 过程 程和 差关 关联 直 接 明 其 游 用 途 并直 直接 接标 标明 明其 其下 下游 游用 用途 从 形 扫 查 从而 而形 形成 成假 体扫 扫查 三 维 重 所 需 基 础 三维 维重 重建 建和 针体 体定 位所 所需 需的 的空 间基 基础', '/#research', 'doctoral-thesis', 1, '2026-08-04', '9c170f1ac9a7668b9485b5c396bd68d08b9866c7b18bb83101d87c7eeb675db7') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-01a3c9e88ae9d0cf', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建', '甲状腺假体为四个工作台提供共同物理对象。本节先确定解剖结构与材料，使靶区、风险结构和扫查通道能够重复呈现；随后由01工作台组织超声、双目和位姿观测，由02工作台检查记录来源、类别覆盖与样本可用性，将物理对象转换为可进入算法链的多源扫查数据。
本节按假体结构设计、材料制备和多源数据构建展开。结构与配方保证几何和声学条件，采集界面负责设备与通道状态，数据检查界面负责样本与标注状态。三者共同回答实验对象是否可重复、输入是否可追溯以及哪些观测能够进入二维、配准与三维任务。', '01 02 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 四 个 工 作 台 提 供 共 同 物 理 对 象 体为 为四 四个 个工 工作 作台 台提 提供 供共 共同 同物 物理 理对 对象 本 节 先 确 定 解 剖 结 材 料 本节 节先 先确 确定 定解 解剖 剖结 结构 构与 与材 材料 使 靶 区 使靶 靶区 风 险 通 道 能 够 重 复 呈 现 风险 险结 构和 和扫 查通 通道 道能 能够 够重 重复 复呈 呈现 随 后 由 随后 后由 组 织 台组 组织 织超 双 目 位 姿 观 测 双目 目和 和位 位姿 姿观 观测 检 记 录 来 台检 检查 查记 记录 录来 来源 类 别 覆 盖 样 可 用 性 类别 别覆 覆盖 盖与 与样 样本 本可 可用 用性 将 转 换 进 入 算 法 链 将物 象转 转换 换为 为可 可进 进入 入算 算法 法链 链的 的多 按 设 计 节按 按假 体结 构设 设计 制 备 展 开 料制 制备 备和 和多 源数 建展 展开 配 方 保 几 何 学 条 件 与配 配方 方保 保证 证几 几何 何和 和声 声学 学条 条件 采 集 界 面 负 责 态 采集 集界 界面 面负 负责 责设 设备 备与 与通 道状 状态 标 注 据检 查界 责样 本与 与标 标注 注状 三 者 回 答 实 否 三者 者共 同回 回答 答实 实验 验对 象是 是否 否可 可重 输 追 溯 以 哪 些 二 维 输入 入是 可追 追溯 溯以 以及 及哪 哪些 些观 测能 够进 入二 二维 准 任 务 配准 准与 与三 三维 维任 任务', '/#research', 'doctoral-thesis', 1, '2026-08-04', '01a3c9e88ae9d0cfd1f773f7b4bc7cd342225ebdc1f4d59109d89b1c4f4a075f') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-f3c6b6d5ca0a2a8b', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / 甲状腺假体结构设计', '高保真甲状腺颈部假体、3D 打印假体和介入训练平台的相关研究表明，假体需要同时呈现甲状腺、结节和颈前区软组织的声像差异，并维持稳定的空间几何关系[148–153]。据此，本文在结构设计中同时考虑解剖布局、超声可见性和定位系统可观测性，使其能够支撑系统算法链路的重复采集和定量比较。
甲状腺假体采用分层结构设计。第一层级复现甲状腺及其周围关键颈前区结构，用于提供接近真实扫查场景的解剖背景和风险边界；第二层级在甲状腺内部布置多个形态差异明显的结节单元，用于模拟穿刺靶区并检验三维重建与分割算法对复杂边界的表达能力。这样的设计兼顾结构复杂度、超声可见性、加工可行性和实验可重复性。
Figure . Three-dimensional anatomical design of the thyroid and its surrounding spatially adjacent structures.
图 .8 甲状腺内部结节单元设计三维图
Figure . Structural design of four nodule units embedded within the thyroid phantom.
图 5.7给出了颈前区整体假体的三维结构。甲状腺假体总体结构包括肩胛舌骨肌、胸骨甲状肌、胸骨舌骨肌、胸锁乳突肌、气管、甲状腺、颈内静脉、颈内动脉、迷走神经、下半头骨、颈椎脊柱、锁骨和皮肤等结构。其中，骨骼与气管主要提供外形支撑和强回声或声影边界，肌群与皮肤构成浅层软组织通道和探头接触背景，动静脉及神经所在区域提供穿刺风险约束，甲状腺本体作为主要成像对象和结节载体。该设计使甲状腺处于具有周围组织干扰和入路约束的局部穿刺场景中。', '3d 148 153 figure three-dimensional anatomical design of the thyroid and its surrounding spatially adjacent structures. structural four nodule units embedded within phantom. 5.7 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 结 设 计 体结 结构 构设 设计 高 保 真 颈 部 高保 保真 真甲 腺颈 颈部 部假 打 印 介 入 训 练 平 台 相 关 研 究 表 明 打印 印假 体和 和介 介入 入训 训练 练平 平台 台的 的相 相关 关研 研究 究表 表明 需 要 同 时 呈 现 体需 需要 要同 同时 时呈 呈现 现甲 节 前 区 软 组 织 像 差 异 结节 节和 和颈 颈前 前区 区软 软组 组织 织的 的声 声像 像差 差异 并 维 持 稳 定 空 间 几 何 并维 维持 持稳 稳定 定的 的空 空间 间几 几何 何关 关系 此 据此 本 文 考 虑 解 剖 布 局 本文 文在 在结 计中 中同 时考 考虑 虑解 解剖 剖布 布局 可 见 性 位 观 测 声可 可见 见性 性和 和定 定位 位系 统可 可观 观测 测性 使 其 能 够 支 撑 算 法 链 路 重 复 采 集 量 比 较 使其 其能 能够 够支 支撑 撑系 统算 算法 法链 链路 路的 的重 重复 复采 采集 集和 定量 量比 比较 用 分 层 体采 采用 用分 分层 层结 一 级 周 围 键 第一 一层 层级 级复 复现 腺及 及其 其周 周围 围关 关键 键颈 区结 于 提 供 接 近 实 场 景 背 风 险 边 界 用于 于提 提供 供接 接近 近真 真实 实扫 查场 场景 景的 的解 剖背 背景 景和 和风 风险 险边 边界 二 内 置 个 形 态 显 单 元 第二 二层 级在 在甲 腺内 内部 部布 布置 置多 多个 个形 形态 态差 异明 明显 显的 的结 节单 单元 模 拟 靶 检 三 割 对 杂 达 力 于模 模拟 拟穿 刺靶 靶区 区并 并检 检验 验三 三维 维重 重建 与分 分割 割算 法对 对复 复杂 杂边 界的 的表 表达 达能 能力 这 样 兼 顾 度 这样 样的 的设 计兼 兼顾 顾结 构复 杂度 加 工 行 加工 工可 可行 行性 和实 实验 验可 可重 复性 图 部结 元设 计三 维图 给 出 整 给出 出了 了颈 区整 整体 体假 体的 的三 维结 总 包 括 肩 胛 舌 骨 肌 体总 总体 构包 包括 括肩 肩胛 胛舌 舌骨 骨肌 胸 胸骨 骨甲 状肌 骨舌 锁 乳 突 胸锁 锁乳 乳突 突肌 气 管 气管 静 脉 颈内 内静 静脉 动 内动 动脉 迷 走 神 经 迷走 走神 神经 下 半 头 下半 半头 头骨 椎 脊 柱 颈椎 椎脊 脊柱 皮 肤 等 锁骨 骨和 和皮 皮肤 肤等 等结 其中 骼 主 外 强 回 或 影 骨骼 骼与 与气 管主 主要 要提 供外 外形 形支 撑和 和强 强回 回声 声或 或声 声影 影边 群 成 浅 通 道 探 触 肌群 群与 与皮 肤构 构成 成浅 浅层 层软 织通 通道 道和 和探 探头 头接 接触 触背 所 域 约 束 动静 脉及 及神 经所 所在 在区 区域 域提 供穿 刺风 险约 约束 作 象 载 腺本 本体 体作 作为 为主 要成 成像 像对 对象 象和 和结 节载 载体 该 处 具 有 干 扰 该设 计使 使甲 腺处 处于 于具 具有 有周 围组 织干 干扰 扰和 和入 入路 路约 束的 的局 局部 部穿 刺场 景中', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'f3c6b6d5ca0a2a8b51f4669a1525925d142083768537ac94e5edb694cf20219b') O