INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-c3ecb7dbee4bafe4', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / 多组织配方与制备流程', '和针刺操作层面更接近实际场景。
表 .3 常见人体组织声学参数及组成对比
Table . Comparison of acoustic parameters and compositions of common human tissues.
基于这一分析，本研究将假体中的材料划分为三类[148–153]。第一类是硬质支撑结构，包括气管与骨骼，它们在本研究中主要承担几何支撑和声学边界作用，因此采用 PLA 进行 3D 打印成型。虽然 PLA 并不用于模拟真实骨骼或软骨的全部声学常数，但它能够稳定提供外形约束，并在超声图像中形成高回声界面和明显声影。第二类是管状中空结构，即动静脉。静脉采用内径 10 mm、外径 12 mm 的软硅胶管，动脉采用内径 6 mm、外径 9 mm 的软硅胶管，以反映二者在管径和壁厚上的差异。管腔内部注入添加石墨颗粒的水—甘油混合物，用于模拟血液的低回声腔性表现及轻微内部散射。第三类是甲状腺、结节以及胸锁乳突肌、胸骨舌骨肌、胸骨甲状肌等软组织结构，它们共同采用 BDAM 材料体系制备，并通过不同配方和浓度来获得差异化的成像和力学效果。具体的材料实现方式及其作用如表 5.4所示。
