INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-5ddef376f2c46369', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / 多组织配方与制备流程', '结节以及胸锁乳突肌、胸骨舌骨肌、胸骨甲状肌等软组织结构，它们共同采用 BDAM 材料体系制备，并通过不同配方和浓度来获得差异化的成像和力学效果。具体的材料实现方式及其作用如表 5.4所示。
