INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-313d44b01f505374', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / 多组织配方与制备流程', 'VA:醋酸钙为 100:1、100:1.5 和 100:2 的结节配方后指出，较高醋酸钙比例虽然会增强局部衰减，但可能导致结节下边界显示不清[150,152]。考虑到本文的重建和分割任务依赖完整边界，本研究采用 100:1 作为结节基配方。
假体制备流程可概括为“硬质结构预制—软管布置—分层灌模—冻融成型—模块装配”。首先完成气管、骨骼和外部模具的 3D 打印，并预先布置动静脉软硅胶管；随后按颈前区外层、甲状腺本体和内部结节的顺序分层灌注对应 BDAM 前驱凝胶；凝胶完成三次冻融循环后进行脱模和装配，并向血管软管中注入石墨颗粒—水—甘油混合液。扫查时将假体置于水槽或充分耦合环境中，以减少空气界面导致的强反射和图像丢失。至此，本节构建了可重复用于超声扫查、三维重建和穿刺导航验证的甲状腺假体平台。', 'va 100 1.5 150 152 3d bdam 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 组 织 配 方 制 备 流 程 多组 组织 织配 配方 方与 与制 制备 备流 流程 醋 酸 钙 醋酸 酸钙 钙为 结 节 后 指 出 的结 结节 节配 方后 后指 指出 较 高 比 例 虽 然 会 增 强 局 部 衰 减 较高 高醋 钙比 比例 例虽 虽然 然会 会增 增强 强局 局部 部衰 衰减 但 可 能 致 下 边 界 显 示 不 清 但可 可能 能导 导致 致结 节下 下边 边界 界显 显示 示不 不清 考 虑 到 本 文 重 分 割 任 务 依 赖 完 整 考虑 虑到 到本 本文 文的 的重 重建 建和 和分 分割 割任 任务 务依 依赖 赖完 完整 整边 研 究 采 用 本研 研究 究采 采用 作 基 作为 为结 节基 基配 概 括 体制 程可 可概 概括 括为 硬 质 预 硬质 质结 结构 构预 预制 软 管 布 置 软管 管布 布置 层 灌 模 分层 层灌 灌模 冻 融 成 型 冻融 融成 成型 块 装 模块 块装 装配 首 先 气 首先 先完 完成 成气 气管 骨 骼 外 具 骨骼 骼和 和外 外部 部模 模具 具的 打 印 打印 并 动 静 脉 硅 胶 并预 预先 先布 置动 动静 静脉 脉软 软硅 硅胶 胶管 随 按 颈 前 区 随后 后按 按颈 颈前 前区 区外 外层 内 顺 序 注 对 应 腺本 本体 体和 和内 内部 部结 节的 的顺 顺序 序分 灌注 注对 对应 驱 凝 前驱 驱凝 凝胶 三 次 循 环 进 行 脱 胶完 成三 三次 次冻 融循 循环 环后 后进 进行 行脱 脱模 模和 和装 向 血 入 石 墨 颗 粒 并向 向血 血管 管软 管中 中注 注入 入石 石墨 墨颗 颗粒 水 甘 油 混 合 液 甘油 油混 混合 合液 时 将 于 槽 或 充 耦 境 查时 时将 将假 体置 置于 于水 水槽 槽或 或充 充分 分耦 耦合 合环 环境 境中 以 少 空 面 反 射 图 像 丢 失 以减 减少 少空 空气 气界 界面 面导 致的 的强 强反 反射 射和 和图 图像 像丢 丢失 至 此 至此 复 本节 节构 建了 了可 可重 重复 复用 用于 于超 声扫 维 平 台 三维 维重 和穿 航验 证的 的甲 体平 平台', '/#research', 'doctoral-thesis', 1, '2026-08-04', '313d44b01f505374e4c138d3815344fda338e5d8a0d4670a5a82de0664efa8aa') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-a5bab83df74c39a5', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / NeckScan 与 PVA-Phantom 数据集构建', '前述假体、双目近红外定位和器械标定共同提供可重复采集对象与空间基础；同时，自制 NeckScan 补充颈部扫查外观与甲状腺—血管联合语义。操作者先在 01 工作台接入多源观测并核对通道、刷新状态和采集参数，随后在 02 工作台选择扫查记录，检查图像数量、类别有效性、已确认不存在状态与样本可用性。通过检查的观测再分流至二维语义、序列配准和三维建模。
每个数据单元由原始观测、图像—位姿关系、实验对象、扫查视图、采集时间、语义有效性和算法结果共同描述。软件以对象、采集和处理三个层级维护关联，并在时间、位姿、坐标与来源一致时建立三维样本，使数据选择、算法运行和结果输出可以沿同一任务标识追溯。', 'neckscan pva-phantom 01 02 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 集 据集 集构 前 述 前述 述假 双 目 近 红 外 定 位 器 械 标 共 同 提 供 可 重 复 采 对 象 空 间 基 础 双目 目近 近红 红外 外定 定位 位和 和器 器械 械标 标定 定共 共同 同提 提供 供可 可重 重复 复采 采集 集对 对象 象与 与空 空间 间基 基础 时 同时 自 制 自制 补 充 颈 部 观 补充 充颈 颈部 部扫 查外 外观 观与 与甲 血 管 联 合 语 义 血管 管联 联合 合语 语义 操 作 者 先 操作 作者 者先 先在 工 台 接 入 测 并 核 通 道 工作 作台 台接 接入 入多 源观 观测 测并 并核 核对 对通 通道 刷 新 态 参 刷新 新状 状态 态和 和采 集参 参数 随 后 随后 后在 选 择 记 录 台选 选择 择扫 查记 记录 检 图 像 量 检查 查图 图像 像数 数量 类 别 有 效 性 类别 别有 有效 效性 已 确 认 不 存 样 本 用 已确 确认 认不 不存 存在 在状 态与 与样 样本 本可 可用 用性 过 再 分 流 至 二 维 通过 过检 查的 的观 测再 再分 分流 流至 至二 二维 维语 序 列 配 准 三 模 序列 列配 配准 准和 和三 三维 维建 建模 每 个 单 元 由 原 始 每个 个数 据单 单元 元由 由原 原始 始观 姿 关 位姿 姿关 关系 实 实验 验对 视 查视 视图 集时 时间 算 法 结 果 描 义有 性和 和算 算法 法结 结果 果共 同描 描述 软 件 以 软件 件以 以对 处 理 层 级 护 集和 和处 处理 理三 三个 个层 层级 级维 维护 护关 关联 并在 在时 坐 来 一 致 立 坐标 标与 与来 来源 源一 一致 致时 时建 建立 立三 维样 使 使数 据选 运 行 输 出 沿 任 务 识 追 溯 法运 运行 行和 和结 果输 输出 出可 可以 以沿 沿同 同一 一任 任务 务标 标识 识追 追溯', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'a5bab83df74c39a5f757f8b9453c23a0556460103a837543e671a9151894b5e5') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-817545213ac1654f', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / NeckScan 与 PVA-Phantom 数据集构建 / 采集对象与多组超声扫查序列组织', '自制数据包含两个相互独立的逻辑来源。NeckScan 记录颈部横切与纵切扫查，用于甲状腺和血管联合语义；PVA-Phantom 以前述甲状腺穿刺假体为对象，包含甲状腺本体、结节单元、血管结构和可见针体，用于四类导航语义与空间几何验证。二者不因共享同一采集与预处理工具链而合并，避免把不同对象、类别范围和监督含义混为单一数据源。
NeckScan 由左、右两侧的横切和纵切共 4 组扫查视图组成；PVA-Phantom 由粗扫查、左侧、中部和右侧区域的横切与纵切共 8 组视图组成。局部精细扫查用于补充结节与血管边界，粗扫查用于建立较大范围空间覆盖，横切与纵切则为细长血管和针体提供互补方向证据。该组织方式使单帧二维分割、超声扫查序列配准和三维语义场训练能够共享可追溯数据单元。
每个有效数据单元至少包含 B-mode 图像、采集时间信息以及与探头参考架对应的外部定位位姿。探头标定将图像像素映射到超声成像平面，外部定位结果将成像平面映射到统一世界坐标，第 3 章的超声扫查序列配准再校正不同扫查之间的剩余刚性偏差和局部扰动。由此，同一帧数据既可用于二维语义学习，也可作为带空间坐标的三维语义观测。', 'neckscan pva-phantom b-mode 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 集 据集 集构 采 对 象 组 序 列 织 采集 集对 对象 象与 多组 组超 声扫 查序 序列 列组 组织 自 制 包 含 两 个 相 互 独 立 逻 辑 来 自制 制数 据包 包含 含两 两个 个相 相互 互独 独立 立的 的逻 逻辑 辑来 来源 记 录 颈 部 横 切 纵 记录 录颈 颈部 部横 横切 切与 与纵 纵切 切扫 用 于 血 管 联 合 语 义 用于 于甲 腺和 和血 血管 管联 联合 合语 语义 以 前 述 以前 前述 述甲 腺穿 刺假 体为 为对 本 含甲 腺本 本体 结 节 单 元 结节 节单 单元 可 见 针 管结 结构 构和 和可 可见 见针 针体 四 类 空 间 几 何 于四 四类 类导 航语 义与 与空 空间 间几 几何 何验 二 者 不 因 共 享 同 一 预 处 理 工 具 链 而 并 二者 者不 不因 因共 共享 享同 同一 一采 集与 与预 预处 处理 理工 工具 具链 链而 而合 合并 避 免 把 避免 免把 把不 不同 同对 别 范 围 监 督 混 类别 别范 范围 围和 和监 监督 督含 含义 义混 混为 为单 单一 一数 据源 由 左 由左 右 侧 右两 两侧 侧的 的横 切和 和纵 切共 视 图 成 组扫 查视 视图 图组 组成 粗 由粗 粗扫 左侧 区 域 中部 部和 和右 右侧 侧区 区域 域的 组视 局 精 细 补 充 边 界 局部 部精 精细 细扫 查用 于补 补充 充结 节与 与血 管边 边界 较 大 覆 盖 于建 建立 立较 较大 大范 围空 间覆 覆盖 则 长 提 供 方 向 切则 则为 为细 细长 长血 管和 和针 体提 提供 供互 互补 补方 方向 向证 证据 该 式 使 帧 维 分 割 该组 织方 方式 式使 使单 单帧 帧二 二维 维分 分割 配 准 三 场 训 练 能 够 追 溯 列配 配准 准和 和三 三维 维语 义场 场训 训练 练能 能够 够共 享可 可追 追溯 溯数 据单 每 有 效 至 少 每个 个有 有效 效数 元至 至少 少包 像 图像 时 信 息 探 头 参 考 架 应 外 定 位 姿 集时 时间 间信 信息 息以 以及 及与 与探 探头 头参 参考 考架 架对 对应 应的 的外 外部 部定 定位 位位 位姿 标 将 素 映 射 到 平 面 头标 标定 定将 将图 像像 像素 素映 映射 射到 到超 声成 成像 像平 平面 果 世 坐 位结 结果 果将 将成 面映 到统 统一 一世 世界 界坐 坐标 再 校 正 之 剩 余 刚 性 偏 差 扰 动 章的 的超 准再 再校 校正 正不 同扫 查之 之间 间的 的剩 剩余 余刚 刚性 性偏 偏差 差和 和局 部扰 扰动 此 由此 既 学 习 一帧 帧数 据既 既可 可用 于二 义学 学习 也 作 带 观 测 也可 可作 作为 为带 带空 间坐 标的 的三 义观 观测', '/#research', 'doctoral-thesis', 1, '2026-08-04', '817545213ac1654f24ad30cba6738b282ba147ae1154af0256793dcb25b98322') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d6232d05de48b2ec', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / NeckScan 与 PVA-Phantom 数据集构建 / 空间同步、语义标注与数据划分', '二维图像进入三维语义场之前依次经过时间关联、探头空间标定和多次扫查位姿修正。该链路把图像像素、探头参考架、外部定位世界坐标和规范空间连接起来，使二维语义概率能够投影到一致的物理位置。对于缺少有效位姿、标定关系或空间覆盖的数据，只能用于二维外观分析，不能作为三维语义场的有效监督。
数据集标注围绕甲状腺、结节、血管和穿刺针四类导航语义组织，但两个来源采用不同契约：NeckScan 仅令甲状腺和血管有效，结节与穿刺针标记为缺失/不适用；PVA-Phantom 令四类语义均有效。有效类别进一步区分前景阳性与已确认不存在，后者作为可信阴性而不是缺失标注。最终像素级监督由画刷、精细多边形、时序传播或模型辅助候选经过一致性检查与冲突消解形成，不能笼统表述为每帧四类均为纯人工阳性标注。
当前规范化发布中，NeckScan 包含 1,534 帧训练图像和 383 帧验证图像，PVA-Phantom 包含 2,575 帧训练图像和 645 帧验证图像。两者均按扫查视图分层后逐帧随机划分，验证比例为 20%，随机种子为 2026。二维分割使用像素级有效监督；只有具备同步位姿、标定关系和充分空间覆盖的 PVA-Phantom 序列进入三维语义场与针体几何评价，避免用单帧分割性能替代空间重建质量。', 'neckscan pva-phantom 534 383 575 645 20 2026 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 集 据集 集构 空 间 同 步 空间 间同 同步 语 义 标 注 划 分 语义 义标 标注 注与 与数 据划 划分 二 维 图 像 进 入 三 场 之 前 依 次 经 过 时 关 联 二维 维图 图像 像进 进入 入三 三维 维语 义场 场之 之前 前依 依次 次经 经过 过时 时间 间关 关联 探 头 定 位 姿 修 正 探头 头空 间标 标定 定和 和多 多次 次扫 查位 位姿 姿修 修正 该 链 路 把 素 该链 链路 路把 把图 像像 像素 参 考 架 头参 参考 考架 外 部 世 界 坐 规 范 连 接 起 来 外部 部定 定位 位世 世界 界坐 坐标 标和 和规 规范 范空 间连 连接 接起 起来 使 概 率 能 够 投 影 到 一 致 物 理 置 使二 义概 概率 率能 能够 够投 投影 影到 到一 一致 致的 的物 物理 理位 位置 对 于 缺 少 有 效 对于 于缺 缺少 少有 有效 效位 或 覆 盖 定关 关系 系或 或空 间覆 覆盖 盖的 的数 只 用 观 析 只能 能用 用于 于二 维外 外观 观分 分析 不 作 监 督 不能 能作 作为 为三 场的 的有 效监 监督 围 绕 集标 注围 围绕 绕甲 结 节 结节 血 管 针 四 类 组 织 血管 管和 和穿 刺针 针四 四类 类导 航语 义组 组织 但 两 个 采 契 约 但两 两个 个来 来源 源采 采用 用不 不同 同契 契约 仅 令 仅令 令甲 腺和 和血 管有 记 失 节与 与穿 针标 标记 记为 为缺 缺失 适 不适 适用 均 令四 类语 义均 均有 别 区 景 阳 性 已 确 认 存 效类 类别 别进 进一 一步 步区 区分 分前 前景 景阳 阳性 性与 与已 已确 确认 认不 不存 存在 后 者 可 信 阴 而 后者 者作 为可 可信 信阴 阴性 性而 而不 不是 是缺 失标 最 终 级 由 画 刷 最终 终像 素级 级监 督由 由画 画刷 精 细 边 形 精细 细多 多边 边形 序 传 播 模 型 辅 助 候 选 检 冲 突 消 解 成 时序 序传 传播 播或 或模 模型 型辅 辅助 助候 候选 选经 过一 致性 性检 检查 查与 与冲 冲突 突消 消解 解形 形成 笼 表 述 每 帧 纯 人 工 能笼 笼统 统表 表述 述为 为每 每帧 帧四 类均 均为 为纯 纯人 人工 工阳 性标 当 化 发 布 当前 前规 范化 化发 发布 布中 包 含 包含 训 练 帧训 训练 练图 像和 帧验 证图 按 视 层 逐 随 机 两者 者均 均按 按扫 查视 视图 图分 分层 层后 后逐 逐帧 帧随 随机 机划 比 例 证比 比例 例为 种 子 机种 种子 子为 割 维分 分割 割使 使用 用像 级有 具 备 只有 有具 具备 备同 步位 充 系和 和充 充分 分空 列 几 何 评 价 序列 列进 场与 与针 针体 体几 几何 何评 评价 避 免 单 替 代 重 质 量 避免 免用 用单 单帧 帧分 割性 性能 能替 替代 代空 间重 重建 建质 质量', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd6232d05de48b2ecdc970d0abec2d9adb99f57d1d7d4605adcd01acef0bedccd') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=