INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-668932ffb6248a60', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / NeckScan 与 PVA-Phantom 数据集构建 / 数据质量检查与可追溯记录', '数据质量检查在图 5.9 中按 NeckScan 和 PVA-Phantom 分别汇总记录来源、图像数量、扫查视图、类别有效性、阳性/已确认不存在状态和可训练样本索引，并逐帧关联 B-mode、标注、位姿与质量状态。界面提供最少有效帧、位姿要求和类别覆盖等参数，使数据准入规则能够在运行前配置并在结果面板中核对。
图 5.9对应02工作台的数据完整性检查页面。中央区域以代表样本、类别分布和标注概况呈现输入，右侧参数与结果面板用于设置检查条件并反馈有效帧、类别覆盖和数据规模。', 'neckscan pva-phantom 5.9 b-mode 02 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 集 据集 集构 质 量 检 可 追 溯 记 录 据质 质量 量检 检查 查与 与可 可追 追溯 溯记 记录 图 查在 在图 按 中按 分 别 汇 总 来 分别 别汇 汇总 总记 录来 来源 像 图像 像数 数量 视 查视 视图 类 有 效 性 类别 别有 有效 效性 阳 阳性 已 确 认 不 存 态 训 练 样 本 索 引 已确 确认 认不 不存 存在 在状 状态 态和 和可 可训 训练 练样 样本 本索 索引 并 逐 帧 关 联 并逐 逐帧 帧关 关联 标 注 标注 位 姿 位姿 姿与 与质 量状 界 面 提 供 最 少 界面 面提 提供 供最 最少 少有 效帧 要 求 覆 盖 等 参 姿要 要求 求和 和类 别覆 覆盖 盖等 等参 参数 使 准 入 规 则 能 够 运 行 前 配 置 结 果 板 核 对 使数 据准 准入 入规 规则 则能 能够 够在 在运 运行 行前 前配 配置 置并 并在 在结 结果 果面 面板 板中 中核 核对 应 对应 工 作 台 完 整 页 工作 作台 台的 的数 据完 完整 整性 性检 查页 页面 央 区 域 以 代 表 中央 央区 区域 域以 以代 代表 表样 布 概 况 呈 现 输 别分 分布 布和 和标 注概 概况 况呈 呈现 现输 输入 右 侧 用 于 设 条 件 反 馈 右侧 侧参 数与 与结 板用 用于 于设 设置 置检 查条 条件 件并 并反 反馈 馈有 模 盖和 和数 据规 规模', '/#research', 'doctoral-thesis', 1, '2026-08-04', '668932ffb6248a6019d0282b0d017615151e6b6038376ae2363e78232f0b1b33') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-dc8d7d91cdffff92', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 甲状腺假体与多源扫查数据构建 / NeckScan 与 PVA-Phantom 数据集构建 / 数据用途与适用边界', '两个自制数据源在系统中承担三项作用。第一，NeckScan 用于补充颈部真实扫查外观下的甲状腺—血管联合分割，PVA-Phantom 用于验证四类语义与解剖—器械结构一致性；第二，PVA-Phantom 中带位姿的横切、纵切和多区域扫查用于构建方向无关的三维语义后验；第三，针体概率与器械标定结果共同用于分析针轴、端点候选与解剖结构之间的空间关系。
NeckScan 与 PVA-Phantom 的优势分别是补充颈部联合外观和提供几何可控、可重复的空间观测，但其对象规模、材料回声、组织变形和操作复杂度不能覆盖真实临床场景。因而，两者用于评价系统模块在统一数据契约和坐标链中的表现，不替代公开临床数据上的外观泛化实验，也不据此推断临床穿刺安全性。
图 .9 假体扫查数据完整性检查工作台
Figure . Data-integrity inspection workbench for thyroid-phantom scanning
图 5.9使操作者能够在一个页面内完成扫查记录选择、代表样本浏览、类别覆盖核对、数据准入参数配置和完整性结果读取。该环节输出有效B-mode、同步位姿和语义标注索引，并分别流向二维语义、序列配准和三维重建。
本节构建了 NeckScan 与 PVA-Phantom 两个独立自制数据源，并将设备状态、扫查视图、同步位姿和类别有效性组织为可追溯数据单元。二者分别承担颈部甲状腺—血管联合外观与可控四类导航语义验证，均不能替代临床数据。5.5—5.7 节依次验证二维语义、序列配准、三维重建与针体定位模块。', 'neckscan pva-phantom figure data-integrity inspection workbench for thyroid-phantom scanning 5.9 b-mode 5.5 5.7 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 多 源 扫 查 数 据 腺假 体与 与多 多源 源扫 扫查 查数 数据 据构 集 据集 集构 用 途 适 边 界 据用 用途 途与 与适 适用 用边 边界 两 个 自 制 承 担 三 项 作 两个 个自 自制 制数 据源 源在 在系 统中 中承 承担 担三 三项 项作 作用 一 第一 于 补 充 颈 部 真 实 外 观 下 用于 于补 补充 充颈 颈部 部真 真实 实扫 查外 外观 观下 下的 的甲 血 管 联 合 分 割 血管 管联 联合 合分 分割 四 类 语 义 解 剖 于验 证四 四类 类语 语义 义与 与解 解剖 器 械 结 致 性 器械 械结 结构 构一 一致 致性 二 第二 带 位 姿 横 切 中带 带位 位姿 姿的 的横 横切 纵 区 域 方 向 无 关 维 后 纵切 切和 和多 多区 区域 域扫 查用 于构 建方 方向 向无 无关 关的 的三 三维 维语 义后 后验 第三 针 概 率 标 定 果 共 同 析 轴 针体 体概 概率 率与 与器 械标 标定 定结 结果 果共 共同 同用 于分 分析 析针 针轴 端 点 候 选 之 间 空 端点 点候 候选 选与 剖结 构之 之间 间的 的空 空间 间关 关系 优 势 别 提 供 几 何 可 控 的优 优势 势分 分别 别是 是补 部联 合外 观和 和提 提供 供几 几何 何可 可控 重 复 测 可重 重复 复的 间观 观测 但 其 对 象 规 模 但其 其对 对象 象规 规模 材 料 回 材料 料回 回声 组 织 变 形 操 杂 度 不 能 覆 盖 临 床 场 景 组织 织变 变形 形和 和操 操作 作复 复杂 杂度 度不 不能 能覆 覆盖 盖真 实临 临床 床场 场景 因 而 因而 者 评 价 块 契 约 坐 链 表 现 两者 者用 于评 评价 价系 统模 模块 块在 在统 统一 一数 据契 契约 约和 和坐 坐标 标链 链中 中的 的表 表现 替 代 公 开 上 泛 化 不替 替代 代公 公开 开临 床数 据上 上的 的外 观泛 泛化 化实 实验 也 此 推 断 安 全 也不 不据 据此 此推 推断 断临 床穿 刺安 安全 全性 图 完 整 检 工 台 体扫 据完 完整 整性 性检 检查 查工 工作 作台 使 够 页 面 内 成 记 录 择 使操 作者 者能 能够 够在 在一 一个 个页 页面 面内 内完 完成 成扫 查记 记录 录选 选择 样 本 浏 览 代表 表样 样本 本浏 浏览 核 类别 别覆 盖核 核对 准 入 参 配 置 读 取 据准 准入 入参 参数 数配 配置 置和 和完 性结 果读 读取 该 环 节 输 出 有 效 该环 环节 节输 输出 出有 有效 步 注 索 引 同步 步位 姿和 和语 义标 标注 注索 索引 并 流 并分 别流 流向 向二 二维 序 列 序列 列配 配准 准和 和三 维重 重建 本节 节构 建了 独 立 个独 独立 立自 将 设 备 态 并将 将设 设备 备状 状态 视 查视 视图 追 溯 单 元 和类 别有 效性 性组 织为 为可 可追 追溯 溯数 据单 单元 二者 者分 别承 担颈 部甲 观与 与可 控四 类导 航语 义验 均 均不 能替 代临 依 次 节依 依次 次验 证二 与针 体定 定位 位模', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'dc8d7d91cdffff922ab13d2cdab7b2278b77b57babe66d391558db1b578376a7') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=ex