INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-d9c9fbcdce7bc506', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 超声扫查与二维语义分割系统集成与假体验证', '本节对应02超声扫查与二维语义分割工作台，将第4章的输入域规范化、冻结教师引导和结构化解剖几何约束接入假体数据链。操作者依次完成数据检查、有效接触筛选和多任务分割，系统输出甲状腺、结节、血管和针体概率，并以区域与结构指标判断结果是否满足三维任务的输入条件。', '02 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 扫 查 二 维 语 义 分 割 集 成 声扫 扫查 查与 与二 二维 维语 语义 义分 分割 割系 统集 集成 成与 本 节 对 应 本节 节对 对应 工 作 台 割工 工作 作台 将 将第 输 入 域 规 范 化 章的 的输 输入 入域 域规 规范 范化 冻 结 教 师 引 解 剖 几 何 约 束 接 数 据 链 冻结 结教 教师 师引 引导 导和 和结 结构 构化 化解 解剖 剖几 几何 何约 约束 束接 接入 入假 体数 数据 据链 操 者 依 次 完 检 操作 作者 者依 依次 次完 完成 成数 据检 检查 有 效 触 筛 选 多 任 务 有效 效接 接触 触筛 筛选 选和 和多 多任 任务 务分 出 统输 输出 出甲 结节 血 管 针 概 率 血管 管和 和针 针体 体概 概率 并 以 区 指 标 判 断 果 否 满 足 三 条 件 并以 以区 区域 域与 与结 构指 指标 标判 判断 断结 结果 果是 是否 否满 满足 足三 三维 维任 务的 入条 条件', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'd9c9fbcdce7bc506668451167502ea5110fb364f6b2fedef15244f2955b1decd') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-9341d737432d81fa', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 超声扫查与二维语义分割系统集成与假体验证 / 扫查输入、有效观测与二维语义接入', '操作者首先选择扫查记录并核对来源与类别，随后在图 5.10中检查列级接触概率、有效成像区域、边界连续性及不同表征投影下的筛选结果。通过接触门控的B-mode再进入输入域规范化和四类二维语义推理。设解剖分支输出为三类单纯形概率，针体分支允许与解剖语义重叠，则有效像素上的统一输出与掩膜定义如下。
其中，π_(A,i)表示甲状腺、结节和血管的解剖分支概率，q_(N,i)表示允许与解剖类别重叠的针体概率，m_i控制接触有效性与标签可用性。该定义与04工作台中的解剖—器械双分支保持一致。
EIDC用于减小采集条件造成的显示差异，多任务网络输出甲状腺、结节、血管和穿刺针概率；冻结教师语义引导与结构化解剖几何约束分别提供低标注表征和结构约束。02工作台把接触范围、概率与轮廓、区域指标和结构违反率分层显示，使输入质量、类别响应与结构合理性能够分别判断。
阶段输出分为两路：合格B-mode及同步位姿送入03工作台并参与三维强度重建，四类概率保留来源与坐标信息后送入04工作台，与修正位姿汇合形成三维语义和针体概率。二维概率不是序列配准的前置输入，两条路径在三维阶段汇合。
02工作台以统一任务记录连接数据完整性检查、有效接触推理、输入域规范化和多任务分割。页面提供可直接调整的模型、阈值、平滑尺度与连续区间参数，中央区域展示逐样本中间结果，结果面板同步反馈区域指标和结构一致性，使二维实验能够从输入检查连续执行至结果导出。', '5.10 b-mode 04 eidc 02 03 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 扫 查 二 维 语 义 分 割 集 成 声扫 扫查 查与 与二 二维 维语 语义 义分 分割 割系 统集 集成 成与 输 入 查输 输入 有 效 观 测 接 有效 效观 观测 测与 义接 接入 操 作 者 首 先 选 择 记 录 并 核 对 来 源 类 别 操作 作者 者首 首先 先选 选择 择扫 查记 记录 录并 并核 核对 对来 来源 源与 与类 类别 随 后 图 随后 后在 在图 检 列 级 触 概 率 中检 检查 查列 列级 级接 接触 触概 概率 像 区 域 效成 成像 像区 区域 边 界 连 续 性 不 同 表 征 投 影 下 筛 结 果 边界 界连 连续 续性 性及 及不 不同 同表 表征 征投 投影 影下 下的 的筛 筛选 选结 结果 通 过 门 控 通过 过接 触门 门控 控的 再 进 规 范 化 四 推 理 再进 进入 入输 入域 域规 规范 范化 化和 和四 四类 类二 义推 推理 设 解 剖 支 出 三 单 纯 形 设解 解剖 剖分 分支 支输 输出 出为 为三 三类 类单 单纯 纯形 形概 针 允 许 重 叠 针体 体分 支允 允许 许与 与解 剖语 义重 重叠 则 素 上 一 掩 膜 定 如 则有 效像 像素 素上 上的 的统 统一 一输 出与 与掩 掩膜 膜定 定义 义如 如下 其 其中 示 表示 示甲 节 血 管 结节 节和 和血 血管 管的 的解 支概 示允 剖类 别重 叠的 的针 体概 制 标 签 可 用 控制 制接 触有 效性 性与 与标 标签 签可 可用 用性 该 该定 义与 工 台 工作 作台 台中 中的 器 械 双 保 持 致 器械 械双 双分 支保 保持 持一 一致 于 减 小 采 条 件 造 显 差 异 用于 于减 减小 小采 采集 集条 条件 件造 造成 成的 的显 显示 示差 差异 多 任 务 网 络 多任 任务 务网 网络 络输 出甲 管和 和穿 刺针 针概 冻 教 师 引 几 何 约 束 提 供 低 注 冻结 结教 教师 师语 义引 引导 导与 与结 结构 构化 化解 剖几 几何 何约 约束 束分 分别 别提 提供 供低 低标 标注 注表 征和 和结 构约 把 围 台把 把接 触范 范围 轮 廓 率与 与轮 轮廓 指 违 反 层 域指 指标 标和 构违 违反 反率 率分 分层 层显 使 质 量 使输 入质 质量 响 应 合 能 够 判 断 别响 响应 应与 构合 合理 理性 性能 能够 够分 别判 判断 阶 段 两 路 阶段 段输 出分 分为 为两 两路 格 合格 步 位 姿 送 及同 同步 步位 位姿 姿送 送入 参 强 度 台并 并参 参与 与三 三维 维强 强度 度重 重建 留 坐 信 息 类概 率保 保留 留来 与坐 坐标 标信 信息 息后 后送 修 正 汇 与修 修正 正位 姿汇 汇合 合形 形成 成三 义和 和针 序 配 准 前 置 维概 率不 不是 是序 序列 列配 配准 准的 的前 前置 置输 径 两条 条路 路径 径在 在三 维阶 段汇 以 数 据 完 整 台以 以统 一任 务记 录连 连接 接数 数据 据完 完整 整性 性检 效接 触推 和多 务分 页 面 直 调 模 型 页面 面提 供可 可直 直接 接调 调整 整的 的模 模型 阈 值 阈值 平 滑 尺 间 平滑 滑尺 尺度 度与 与连 续区 区间 间参 参数 央 展 逐 样 本 中央 央区 域展 展示 示逐 逐样 样本 本中 中间 间结 板 馈 果面 面板 板同 步反 反馈 馈区 构一 致性 实 从 执 行 至 使二 维实 实验 验能 够从 从输 入检 查连 续执 执行 行至 至结 果导 导出', '/#research', 'doctoral-thesis', 1, '2026-08-04', '9341d737432d81fa5fba06da5e6a471b17b5693bf0b447872df1d20e8aa0ba50') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_titl