INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-66c6f50b09676c44', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 三维重建与穿刺针定位系统集成与假体验证 / 多视角三维语义重建与三维参考', '设I、P、W、N和R分别表示超声图像平面、探头参考架、外部定位世界坐标、语义规范空间和穿刺针参考架。二维类别概率依次通过N线探头标定、外部位姿和扫查修正映射至N；多视角输入、连续三维输出与三维参考分别保存，其坐标链由下式概括。
三维参考评价表明，连续位置场的复合前景Dice和解剖宏平均Dice分别为0.7722和0.7457，在本实验中优于体素概率融合及简单方向边缘化条件场。图 5.12(b)同时反馈三维指标和语义体状态，输入点云作为多视角观测，连续语义场作为最终空间输出。令z汇总二维概率、位姿、标定和融合不确定性，其一阶传播由下式表示。', 'dice 0.7722 0.7457 5.12 第 章 甲 状 腺 超 声 穿 刺 导 航 系 统 构 建 假 体 验 证 甲状 状腺 腺超 超声 声穿 穿刺 刺导 导航 航系 系统 统构 构建 建与 与假 假体 体验 验证 三 维 重 针 定 位 集 成 三维 维重 重建 与穿 刺针 针定 定位 位系 统集 集成 成与 多 视 角 语 义 参 考 多视 视角 角三 维语 语义 义重 与三 维参 参考 设 分 别 表 示 图 像 平 面 分别 别表 表示 示超 声图 图像 像平 平面 探 头 架 探头 头参 考架 外 部 世 界 坐 标 外部 部定 位世 世界 界坐 坐标 规 范 空 间 义规 规范 范空 空间 间和 和穿 针参 二 类 概 率 依 次 通 过 二维 维类 类别 别概 概率 率依 依次 次通 通过 线 线探 头标 标定 姿 扫 查 修 正 映 射 至 部位 位姿 姿和 和扫 扫查 查修 修正 正映 映射 射至 输 入 角输 输入 连 续 出 保 存 连续 续三 维输 输出 出与 考分 别保 保存 其 链 由 下 式 括 其坐 标链 链由 由下 下式 式概 概括 评 价 明 考评 评价 价表 表明 置 场 复 合 前 景 续位 位置 置场 场的 的复 复合 合前 前景 解 剖 宏 均 和解 解剖 剖宏 宏平 平均 别为 本 实 优 于 素 融 简 单 方 向 边 缘 化 条 件 在本 本实 实验 验中 中优 优于 于体 体素 素概 率融 融合 合及 及简 简单 单方 方向 向边 边缘 缘化 化条 条件 件场 同 时 反 馈 指 态 同时 时反 反馈 馈三 维指 指标 标和 和语 义体 体状 状态 点 云 作 观 测 入点 点云 云作 作为 为多 角观 观测 最 终 续语 义场 场作 为最 最终 终空 间输 令 汇 总 汇总 总二 维概 不 确 性 定和 和融 合不 不确 确定 定性 一 阶 传 播 其一 一阶 阶传 传播 播由 式表', '/#research', 'doctoral-thesis', 1, '2026-08-04', '66c6f50b09676c448c6474d1e87ec8cc088646b3a66d40f1c088694abba8235c') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-4cdedca2e8d64c9e', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第5章 甲状腺超声穿刺导航系统构建与假体验证 / 三维重建与穿刺针定位系统集成与假体验证 / 穿刺针概率场与几何定位', '穿刺针分支将多视角二维针体概率映射到统一空间，并以解剖—器械双分支、距离和拓扑连续性约束处理细长、断裂与类别不均衡。图 5.12(c)用于调节概率阈值并观察高置信种子、弱支持碎片和无支撑间隔，图 5.12(d)通过双阈值迟滞与碎片均衡稳健拟合输出轴线、有限线段和端点候选。针体几何是否可接受由覆盖率、最大间隔、中心线残差和物理来源共同决定。
其中，ρ_cov为轴向覆盖率，g_max为最大无支撑间隔，e_line为中心线残差，s_src表示物理来源与单位是否可核对。几何质量通过并不自动意味着物理针尖已知；端点候选与物理针尖在界面和论文中分别表述。
假体实验中，碎片均衡使轴向误差由0.191°降至0.100°，中心线误差由0.3429 mm降至0.3327 mm；双阈值迟滞恢复进一步使覆盖率达到1、最大无支撑间隔降至0、中心线误差降至0.3225 mm。上述结果在图 5.12(c)—(d)中对应概率支持、几何输出和质量状态，红色端点表示模型端点候选。
图 .13 针体几何参数配置与定位任务评价
