INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-2958c97908dd4912', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第6章 总结与展望 / 主要结论', 'CBAM冻结教师语义引导较无语义引导提高0.0341。三维组织GT评价中，连续位置场略优于体素概率融合，而成像平面条件场未保持二维观测域优势，说明方向条件观测与方向无关后验必须分开评价。针体无向中心线结果限于单病例，不作为一般针尖精度结论。
（4）完成了甲状腺穿刺导航原理样机及关键几何链路验证。双目标定、连续轨迹、探头N线标定和针尖枢轴标定分别给出相机、工具、成像平面与器械工作点的误差边界，其中轨迹平移RMSE为0.7963 mm，探头两条链路的三维有效RMSE为1.550 mm和1.654 mm，针尖枢轴标定内点RMSE为3.0118 mm。结果支持固定变换的可估计性和模块间坐标连接，不等同于端到端穿刺精度。
综上，本文建立了由可信二维观测、连续三维表征、多次扫查空间统一、组织—器械语义接口到物理坐标链的连续技术路线。实验分别验证了三维强度重建、扫查序列配准、二维语义观测、三维组织GT语义评价、单病例针体几何和关键标定环节，并揭示了成像平面条件场与针体端点候选的适用边界。上述证据支持方法、模块和原理样机层面的结论；端到端穿刺精度和临床安全性不在本研究的实测范围内。', 'cbam 0.0341 gt rmse 0.7963 mm 1.550 1.654 3.0118 第 章 总 结 展 望 总结 结与 与展 展望 主 要 论 主要 要结 结论 冻 教 师 语 义 引 导 较 无 提 高 冻结 结教 教师 师语 语义 义引 引导 导较 较无 无语 导提 提高 三 维 组 织 三维 维组 组织 评 价 评价 价中 连 续 位 置 场 略 优 于 体 素 概 率 融 合 连续 续位 位置 置场 场略 略优 优于 于体 体素 素概 概率 率融 融合 而 成 像 平 面 条 件 未 保 持 二 观 测 域 势 而成 成像 像平 平面 面条 条件 件场 场未 未保 保持 持二 二维 维观 观测 测域 域优 优势 说 明 方 向 关 后 验 必 须 分 开 说明 明方 方向 向条 件观 测与 与方 向无 无关 关后 后验 验必 必须 须分 分开 开评 针 心 线 果 限 单 病 例 针体 体无 无向 向中 中心 心线 线结 结果 果限 限于 于单 单病 病例 不 作 一 般 尖 精 度 不作 作为 为一 一般 般针 针尖 尖精 精度 度结 完 甲 状 腺 穿 刺 航 原 理 样 机 键 几 何 链 路 证 完成 成了 了甲 甲状 状腺 腺穿 穿刺 刺导 导航 航原 原理 理样 样机 机及 及关 关键 键几 几何 何链 链路 路验 验证 双 目 标 定 双目 目标 标定 轨 迹 续轨 轨迹 探 头 探头 枢 轴 别 给 出 相 线标 定和 和针 尖枢 枢轴 轴标 定分 分别 别给 给出 出相 相机 工 具 工具 器 械 点 误 差 边 界 面与 与器 器械 械工 工作 作点 点的 的误 误差 差边 边界 其 移 其中 中轨 迹平 平移 两 有 效 头两 两条 条链 路的 的三 维有 有效 内 定内 内点 支 固 变 换 可 估 计 性 模 块 间 坐 接 果支 支持 持固 固定 定变 变换 换的 的可 可估 估计 计性 性和 和模 模块 块间 间坐 坐标 标连 连接 等 同 端 到 不等 等同 同于 于端 端到 到端 端穿 刺精 综 上 综上 本 文 建 立 由 信 本文 文建 建立 立了 了由 由可 可信 信二 表 征 续三 维表 表征 多 次 扫 查 空 统 多次 次扫 扫查 查空 空间 间统 统一 口 物 技 术 械语 义接 接口 口到 到物 物理 理坐 标链 链的 的连 续技 技术 术路 路线 实 强 重 实验 验分 别验 证了 了三 维强 强度 度重 重建 序 列 配 准 查序 序列 列配 配准 维语 义观 义评 环 节 例针 体几 何和 和关 键标 定环 环节 并 揭 示 候 选 适 用 并揭 揭示 示了 了成 场与 与针 体端 端点 点候 候选 选的 的适 适用 用边 述 据 法 上述 述证 证据 据支 持方 方法 层 块和 和原 机层 层面 面的 的结 临 床 安 全 研 究 范 围 度和 和临 临床 床安 安全 全性 性不 不在 在本 本研 研究 究的 的实 实测 测范 范围 围内', '/#research', 'doctoral-thesis', 1, '2026-08-04', '2958c97908dd491252e09a6377acd346507c70f92d2b3c60f3421a70994365c7') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-562dee40c03fc926', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第6章 总结与展望 / 创新点总结', '本文的主要创新点体现在以下五个方面。
（1）提出观测质量控制与超声物理约束神经场重建相耦合的三维表征方法。该方法将列级接触状态纳入射线筛选，并在连续表示中联合描述瑞利背散射和方向参数化反射，使观测可信度、散斑统计与界面角度响应进入同一可微重建过程，区别于直接堆叠全部切片或仅采用通用辐射场。
（2）提出面向多组超声扫查序列的位姿—表征协同优化框架。该框架以外观与几何证据建立扫查级可辨识性，以不确定性权重抑制不可靠匹配，再以统计噪声先验和Lie群B样条恢复帧级连续轨迹，使不同尺度的位姿误差与场景表示在同一规范空间中相互提供监督。
（3）构建面向跨域与低标注条件的二维超声语义观测方法。规范回声强度表征用于缓解设备显示差异，源任务迁移与冻结教师语义引导用于提高有限标注下的特征利用率，结构化解剖几何约束则把血管邻近关系和针体形态转化为可优化的结构量，为多视角三维估计提供较稳定的概率观测。
（4）提出区分方向条件观测与方向无关输出的三维组织—器械语义建模与评价方法。连续位置场、成像平面条件场和解剖—器械双分支分别处理坐标共享、切面相关性与语义重叠，距离—拓扑约束进一步服务细长针体；同时以三维组织GT检验方向边缘化，避免用二维重投影指标替代三维结论。', 'lie gt 第 章 总 结 展 望 总结 结与 与展 展望 创 新 点 创新 新点 点总 本 文 主 要 体 现 以 下 五 个 方 面 本文 文的 的主 主要 要创 点体 体现 现在 在以 以下 下五 五个 个方 方面 提 出 观 测 质 量 控 制 超 声 物 理 约 束 神 经 场 重 建 相 耦 合 三 维 表 征 法 提出 出观 观测 测质 质量 量控 控制 制与 与超 超声 声物 物理 理约 约束 束神 神经 经场 场重 重建 建相 相耦 耦合 合的 的三 三维 维表 表征 征方 方法 该 将 列 级 接 触 状 态 纳 入 射 线 筛 选 该方 法将 将列 列级 级接 接触 触状 状态 态纳 纳入 入射 射线 线筛 筛选 并 连 续 示 联 描 述 瑞 利 背 散 向 参 数 化 反 并在 在连 连续 续表 表示 示中 中联 联合 合描 描述 述瑞 瑞利 利背 背散 散射 射和 和方 方向 向参 参数 数化 化反 反射 使 可 信 度 使观 测可 可信 信度 斑 统 计 界 角 响 应 进 同 一 微 过 程 散斑 斑统 统计 计与 与界 界面 面角 角度 度响 响应 应进 进入 入同 同一 一可 可微 微重 建过 过程 区 别 于 直 堆 叠 全 部 切 片 或 仅 采 用 通 辐 区别 别于 于直 直接 接堆 堆叠 叠全 全部 部切 切片 片或 或仅 仅采 采用 用通 通用 用辐 辐射 射场 多 组 扫 查 序 位 姿 出面 面向 向多 多组 组超 声扫 扫查 查序 序列 列的 的位 位姿 协 优 框 架 征协 协同 同优 优化 化框 框架 外 几 何 证 据 立 辨 识 性 该框 架以 以外 外观 观与 与几 几何 何证 证据 据建 建立 立扫 查级 级可 可辨 辨识 识性 不 确 定 权 抑 靠 匹 配 以不 不确 确定 定性 性权 权重 重抑 抑制 制不 不可 可靠 靠匹 匹配 再 噪 先 验 再以 以统 计噪 噪声 声先 先验 验和 群 样 条 恢 复 帧 轨 迹 样条 条恢 恢复 复帧 帧级 级连 续轨 轨迹 尺 误 差 景 规 范 空 间 互 供 监 督 使不 不同 同尺 尺度 度的 姿误 误差 差与 与场 场景 景表 示在 在同 一规 规范 范空 空间 间中 中相 相互 互提 提供 供监 监督 构 跨 域 低 标 注 件 二 语 义 构建 建面 向跨 跨域 域与 与低 低标 标注 注条 条件 件的 的二 二维 维超 声语 语义 义观 测方 回 强 缓 解 设 备 显 异 范回 回声 声强 强度 度表 征用 用于 于缓 缓解 解设 设备 备显 显示 示差 差异 源 任 务 迁 移 冻 教 师 引 导 高 有 限 特 率 源任 任务 务迁 迁移 移与 与冻 冻结 结教 教师 师语 义引 引导 导用 于提 提高 高有 有限 限标 注下 下的 的特 特征 征利 利用 用率 剖 则 把 血 管 邻 近 关 系 针 形 转 结构 构化 化解 解剖 剖几 何约 束则 则把 把血 血管 管邻 邻近 近关 关系 系和 和针 针体 体形 形态 态转 转化 化为 为可 可优 化的 的结 构量 视 估 较 稳 概 为多 多视 视角 角三 维估 估计 计提 供较 较稳 稳定 定的 的概 概率 率观 分 无 输 织 出区 区分 分方 向条 件观 测与 与方 向无 无关 关输 输出 出的 维组 组织 器 械 模 评 价 器械 械语 义建 建模 模与 与评 评价 价方 置 续位 位置 置场 成 像 平 成像 像平 平面 面条 件场 场和 和解 双 支 处 坐 共 享 械双 双分 分支 支分 分别 别处 处理 理坐 坐标 标共 共享 切面 面相 相关 关性 性与 与语 义重 重叠 距 离 距离 拓 扑 步 服 细 长 拓扑 扑约 束进 进一 一步 步服 服务 务细 细长 长针 时 同时 时以 以三 检 边 缘 检验 验方 向边 边缘 缘化 避 免 投 影 指 替 代 论 避免 免用 用二 维重 重投 投影 影指 指标 标替 替代 代三 维结 结论', '/#research', 'doctoral-thesis', 1, '2026-08-04', '562dee40c03fc926dea857d412c7f8be3b3bc85e8542176ccdf2724cb641beaf') ON CONFLICT(`id`) DO UPDATE SET `locale`