INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-dcdf3487a928f441', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第6章 总结与展望 / 创新点总结', '观测与方向无关输出的三维组织—器械语义建模与评价方法。连续位置场、成像平面条件场和解剖—器械双分支分别处理坐标共享、切面相关性与语义重叠，距离—拓扑约束进一步服务细长针体；同时以三维组织GT检验方向边缘化，避免用二维重投影指标替代三维结论。
（5）构建基于物理坐标链和分层证据的甲状腺穿刺导航原理样机。多组织假体、双目近红外定位、探头N线标定和针尖枢轴标定将二维图像、修正位姿、三维场与器械几何置于统一坐标语义下；跟踪、成像平面和器械工作点误差分别报告，从而使模块结果可追溯，并避免以单项残差替代端到端精度。', 'gt 第 章 总 结 展 望 总结 结与 与展 展望 创 新 点 创新 新点 点总 观 测 方 向 无 关 输 出 三 维 组 织 观测 测与 与方 方向 向无 无关 关输 输出 出的 的三 三维 维组 组织 器 械 语 义 建 模 评 价 法 器械 械语 语义 义建 建模 模与 与评 评价 价方 方法 连 续 位 置 场 连续 续位 位置 置场 成 像 平 面 条 件 解 剖 成像 像平 平面 面条 条件 件场 场和 和解 解剖 双 分 支 别 处 理 坐 标 共 享 械双 双分 分支 支分 分别 别处 处理 理坐 坐标 标共 共享 切 相 性 重 叠 切面 面相 相关 关性 性与 与语 义重 重叠 距 离 距离 拓 扑 约 束 进 一 步 服 务 细 长 针 体 拓扑 扑约 约束 束进 进一 一步 步服 服务 务细 细长 长针 针体 同 时 以 同时 时以 以三 检 验 边 缘 化 检验 验方 向边 边缘 缘化 避 免 用 二 投 影 指 替 代 论 避免 免用 用二 二维 维重 重投 投影 影指 指标 标替 替代 代三 维结 结论 构 基 于 物 链 层 证 据 甲 状 腺 穿 刺 导 航 原 样 机 构建 建基 基于 于物 物理 标链 链和 和分 分层 层证 证据 据的 的甲 甲状 状腺 腺穿 穿刺 刺导 导航 航原 原理 理样 样机 多 假 多组 织假 假体 目 近 红 外 定 双目 目近 近红 红外 外定 定位 探 头 探头 线 尖 枢 轴 将 图 线标 标定 定和 和针 针尖 尖枢 枢轴 轴标 定将 将二 维图 图像 修 正 姿 修正 正位 位姿 几 何 统 下 维场 场与 与器 械几 几何 何置 置于 于统 统一 一坐 标语 义下 跟 踪 跟踪 工 作 误 差 报 告 面和 和器 械工 工作 作点 点误 误差 差分 别报 报告 从 而 使 块 果 可 追 溯 从而 而使 使模 模块 块结 结果 果可 可追 追溯 并 单 项 残 端 到 精 度 并避 免以 以单 单项 项残 残差 差替 代端 端到 到端 端精 精度', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'dcdf3487a928f44134101ef624eafdab12cb58073eae7d50f828b9c5348615d9') ON CONFLICT(`id`) DO UPDATE SET `locale`=excluded.`locale`, `source_title`=excluded.`source_title`, `title_path`=excluded.`title_path`, `content`=excluded.`content`, `search_text`=excluded.`search_text`, `url`=excluded.`url`, `evidence_level`=excluded.`evidence_level`, `public`=excluded.`public`, `index_version`=excluded.`index_version`, `hash`=excluded.`hash`;--> statement-breakpoint
INSERT INTO `knowledge_chunks` (`id`, `locale`, `source_title`, `title_path`, `content`, `search_text`, `url`, `evidence_level`, `public`, `index_version`, `hash`) VALUES ('thesis-dcd8bf3d531e9cf6', 'zh', '博士论文：甲状腺超声穿刺导航系统构建与假体验证', '第6章 总结与展望 / 研究展望', '本文已在刚性或近刚性假体、离线计算和模块级评价条件下完成既定方法与原理样机研究。面向更复杂的术中环境，可从以下方向深化。
（1）研究动态术中场景中的组织—器械关系表达。可将静态三维语义和无向针体几何扩展为随时间变化的靶区、风险结构、针轴与针尖关系，形成面向术中决策的动态空间表示与交互反馈。
（2）研究在线增量建模与低时延计算。可通过关键帧选择、稀疏更新、轻量网络、混合精度和并行流水线降低重建、配准与语义推理开销，并建立采集、跟踪、计算和显示各阶段的统一时间模型。
（3）引入组织形变与针—组织交互模型。本文的规范空间主要描述刚性或近刚性关系；复杂临床场景还包含探头压力、呼吸、吞咽和进针造成的局部非刚性变化。可结合可变形神经场、生物力学先验或时空运动模型，联合估计组织形变、针体偏转与语义变化。
（4）开展不确定性传播与安全约束研究。可将分割置信度、位姿协方差、标定误差和针体拟合残差传播到靶区距离、风险间隙与路径可行性，形成可解释的置信区间、异常观测拒绝和保守反馈机制，使系统输出与证据强度一致。
（5）推进多中心临床数据与应用拓展。在伦理审批和标准化采集协议下，可研究不同受试者、设备与操作者条件下的跨中心泛化、重复性和人机交互。本文方法也可在重新标定成像模型与解剖先验后拓展至乳腺、肝脏等自由手超声介入场景，但需要针对具体器官重新界定模型假设与应用范围。', '第 章 总 结 展 望 总结 结与 与展 展望 研 究 研究 究展 本 文 已 刚 性 或 近 假 体 本文 文已 已在 在刚 刚性 性或 或近 近刚 性假 假体 离 线 计 算 模 块 级 评 价 条 件 下 完 成 既 定 方 法 原 理 样 机 离线 线计 计算 算和 和模 模块 块级 级评 评价 价条 条件 件下 下完 完成 成既 既定 定方 方法 法与 与原 原理 理样 样机 机研 面 向 更 复 杂 术 环 境 面向 向更 更复 复杂 杂的 的术 术中 中环 环境 可 从 以 深 化 可从 从以 以下 下方 方向 向深 深化 动 态 场 景 组 织 究动 动态 态术 中场 场景 景中 中的 的组 组织 器 械 关 系 表 达 器械 械关 关系 系表 表达 将 静 三 维 语 义 无 针 几 何 扩 随 时 间 变 靶 区 可将 将静 静态 态三 三维 维语 语义 义和 和无 无向 向针 针体 体几 几何 何扩 扩展 展为 为随 随时 时间 间变 变化 化的 的靶 靶区 风 险 构 风险 险结 结构 轴 尖 针轴 轴与 与针 针尖 尖关 形 决 策 空 示 交 互 反 馈 形成 成面 向术 中决 决策 策的 的动 态空 空间 间表 表示 示与 与交 交互 互反 反馈 增 量 建 低 延 究在 在线 线增 增量 量建 建模 模与 与低 低时 时延 延计 通 过 键 帧 选 择 可通 通过 过关 关键 键帧 帧选 选择 稀 疏 新 稀疏 疏更 更新 轻 网 络 轻量 量网 网络 混 合 精 度 并 行 流 水 降 重 混合 合精 精度 度和 和并 并行 行流 流水 水线 线降 降低 低重 重建 配 准 推 开 销 配准 准与 与语 义推 推理 理开 开销 立 采 集 并建 建立 立采 采集 跟 踪 跟踪 显 各 阶 段 统 一 型 和显 显示 示各 各阶 阶段 段的 的统 统一 一时 间模 模型 引 入 引入 入组 织形 形变 变与 织交 互模 规 范 主 要 描 述 文的 的规 规范 范空 间主 主要 要描 描述 述刚 性关 临 床 还 包 含 探 头 压 力 杂临 临床 床场 景还 还包 包含 含探 探头 头压 压力 呼 吸 呼吸 吞 咽 进 造 局 部 非 吞咽 咽和 和进 进针 针造 造成 成的 的局 局部 部非 非刚 性变 神 经 可结 结合 合可 可变 变形 形神 神经 经场 生 物 学 先 验 运 生物 物力 力学 学先 先验 验或 或时 时空 空运 运动 动模 联 估 联合 合估 估计 计组 偏 转 体偏 偏转 转与 义变 不 确 传 播 安 全 约 束 开展 展不 不确 确定 定性 性传 传播 播与 与安 安全 全约 约束 束研 分 割 置 信 将分 分割 割置 置信 信度 位 姿 协 差 位姿 姿协 协方 方差 标 误 拟 残 到 距 标定 定误 误差 差和 和针 体拟 拟合 合残 残差 差传 播到 到靶 区距 距离 隙 路 径 险间 间隙 隙与 与路 路径 径可 可行 行性 解 释 成可 可解 解释 释的 的置 信区 区间 异 常 观 测 拒 绝 保 守 制 异常 常观 观测 测拒 拒绝 绝和 和保 保守 守反 馈机 机制 使 输 出 证 据 强 致 使系 系统 统输 输出 出与 与证 证据 据强 强度 度一 一致 多 心 数 应 用 拓 推进 进多 多中 中心 心临 床数 数据 据与 与应 应用 用拓 拓展 伦 审 批 议 在伦 伦理 理审 审批 批和 和标 标准 准化 化采 集协 协议 议下 同 受 试 者 可研 究不 不同 同受 受试 试者 设 备 操 作 跨 泛 设备 备与 与操 操作 作者 者条 下的 的跨 跨中 心泛 泛化 人 重复 复性 性和 和人 人机 机交 也 像 剖 后 至 乳 腺 文方 法也 也可 可在 在重 重新 新标 定成 成像 像模 型与 与解 解剖 剖先 验后 后拓 展至 至乳 乳腺 肝 脏 等 自 由 手 超 声 介 肝脏 脏等 等自 自由 由手 手超 超声 声介 介入 入场 但 需 对 具 官 界 围 但需 需要 要针 针对 对具 具体 体器 器官 官重 新界 界定 定模 型假 假设 设与 用范 范围', '/#research', 'doctoral-thesis', 1, '2026-08-04', 'dcd8bf3d531e9cf638c69a80a4f17098bdfb4c42b8919d8de